// ===== M9. Operaciones: procesos diarios, inventarios y calidad =====
Object.assign(window.LECC, {
"M9-1": {
s: `Un cliente le dice a Lupita: «Sus tortas son las mejores, pero a veces tardan 3 minutos y a veces 12». Toño se da cuenta de que el problema no es la receta, sino la forma en que se hace el trabajo. Es un problema de operaciones.`,
o: ["Definir qué son las operaciones de un negocio.","Describir el modelo de insumos, transformación y resultados.","Medir la productividad de una operación."],
x: `## ¿Qué son las operaciones?
Las **operaciones** son todas las actividades que convierten **insumos** (materiales, trabajo, energía, información) en **productos o servicios** para el cliente. Es la parte del negocio que «hace» lo que se vende: la cocina de un restaurante, la línea de producción de una fábrica, el mostrador y el almacén de una tienda, el taller de un mecánico, las aulas de una escuela. En casi todos los negocios, operaciones es el área con más personas, más costos y más impacto directo en lo que vive el cliente.

## El modelo de transformación
Una forma sencilla de entender cualquier operación es verla como un proceso de transformación:

**Insumos → Transformación → Resultados**

| Negocio | Insumos | Transformación | Resultados |
|---|---|---|---|
| Tortas Lupita | Pan, carne, verduras, gas, cocineros, recetas | Preparar, armar, empacar | Tortas listas para el cliente |
| Taller mecánico | Auto descompuesto, refacciones, mecánicos, herramientas | Diagnosticar y reparar | Auto funcionando |
| Escuela | Alumnos, maestros, materiales, aulas | Enseñar | Alumnos que aprendieron |
| Fábrica de muebles | Madera, tornillos, barniz, máquinas, carpinteros | Cortar, ensamblar, barnizar | Muebles terminados |

En los servicios, el cliente muchas veces **participa** en la transformación (el paciente en la consulta, el comensal en el restaurante), lo que hace que la operación sea más variable y difícil de controlar.

## Las cuatro grandes preguntas de operaciones
Quien dirige operaciones se ocupa, sobre todo, de cuatro cosas:
1. **Calidad:** ¿el producto o servicio cumple lo prometido, siempre?
2. **Rapidez:** ¿cuánto tarda el cliente en recibirlo?
3. **Costo:** ¿cuánto cuesta producir cada unidad?
4. **Flexibilidad:** ¿qué tan fácil es cambiar el producto, el volumen o los tiempos?

Mejorar una suele afectar a otra: hacer todo a la medida aumenta la flexibilidad, pero también el costo y el tiempo; producir en grandes cantidades baja el costo, pero reduce la flexibilidad. Cada negocio elige en qué destacar según su propuesta de valor. Tortas Lupita prometió **rapidez** y **sabor constante** (calidad), con un costo razonable.

## Las cuatro «V» de una operación
Los profesores británicos Nigel Slack y sus colegas propusieron comparar operaciones con cuatro dimensiones:
- **Volumen:** cuántas unidades se producen. Más volumen permite especializar y bajar costos.
- **Variedad:** cuántos productos distintos se ofrecen. Más variedad exige más flexibilidad.
- **Variación de la demanda:** qué tanto cambia la demanda entre horas, días o temporadas. Más variación complica planear el personal y el inventario.
- **Visibilidad:** qué tanto ve el cliente la operación. Más visibilidad exige cuidar la imagen, el trato y la limpieza en todo momento.

Tortas Lupita tiene volumen medio, variedad baja (5 tipos de torta), variación alta (hora pico de 13:00 a 14:30) y visibilidad alta (el cliente ve la cocina). Por eso sus retos principales son la hora pico y la limpieza visible.

## La productividad
La **productividad** mide cuánto resultado se obtiene con los recursos usados:

**Productividad = resultados ÷ insumos**

Se puede medir de muchas formas:
- **Tortas por hora de trabajo:** si 4 personas trabajan 8 horas (32 horas) y preparan 480 tortas, la productividad es 15 tortas por hora-persona.
- **Ventas por metro cuadrado:** útil en tiendas.
- **Clientes atendidos por mesero:** útil en restaurantes.
- **Unidades por máquina por hora:** útil en fábricas.

Aumentar la productividad significa producir más con lo mismo o lo mismo con menos. Se logra con mejores procesos, mejor capacitación, mejores herramientas y menos desperdicio, no con «trabajar más duro» sin cambiar nada.

## La variabilidad: el enemigo silencioso
El cliente del inicio se quejaba de que las tortas tardaban «a veces 3 minutos y a veces 12». Ese es un problema de **variabilidad**: el proceso no da siempre el mismo resultado. La variabilidad tiene muchas causas: cocineros que trabajan distinto, ingredientes que se acaban a mitad del turno, pedidos que llegan todos juntos, la plancha que no calienta igual en todas partes. Reducir la variabilidad es uno de los grandes objetivos de operaciones, porque un cliente prefiere un servicio confiable a uno a veces excelente y a veces malo. Gran parte de este módulo trata de cómo lograrlo: procesos claros, rutinas, inventario controlado, estándares de calidad y procedimientos escritos.

## Operaciones en una empresa gigante
En una empresa grande, operaciones puede incluir decenas de plantas, centros de distribución y miles de personas, con áreas especializadas: planeación de la producción, ingeniería de procesos, calidad, mantenimiento, logística, seguridad industrial. Toyota, por ejemplo, desarrolló a lo largo de décadas un sistema de producción que se volvió referencia mundial por su forma de reducir desperdicios y variabilidad. Pero las preguntas son las mismas que en Tortas Lupita: ¿sale siempre bien?, ¿sale rápido?, ¿cuánto cuesta?, ¿podemos adaptarnos?

## El diagnóstico de Toño
Toño cronometra 50 tortas durante una semana: el tiempo promedio es de 5.4 minutos, pero va de 2.5 a 12. Descubre que los tiempos largos ocurren cuando falta un ingrediente en la estación, cuando entran muchos pedidos de WhatsApp al mismo tiempo que la fila y cuando el cocinero nuevo está solo. Ahora sabe qué atacar en las siguientes lecciones.`,
k: `**Operaciones:** actividades que transforman **insumos** en **productos o servicios**. Se gestionan cuatro objetivos: **calidad, rapidez, costo y flexibilidad**. Las **cuatro V**: volumen, variedad, variación y visibilidad. **Productividad = resultados ÷ insumos.** La **variabilidad** es el enemigo de la confianza del cliente.`,
ch: `En una lavandería, los insumos son ropa sucia, agua, jabón, energía y trabajo; la transformación es lavar, secar y doblar; el resultado, ropa limpia entregada a tiempo.`,
gi: `Toyota desarrolló el Sistema de Producción Toyota para fabricar autos con alta calidad y poco desperdicio; su forma de trabajar se estudia en todo el mundo bajo el nombre de «manufactura esbelta» (lean).`,
e: `Toño mide la productividad de la cocina en dos turnos:

| Turno | Personas | Horas | Horas-persona | Tortas | Tortas por hora-persona |
|---|---|---|---|---|---|
| Matutino | 3 | 8 | 24 | 360 | 15 |
| Vespertino | 2 | 6 | 12 | 120 | 10 |

El turno vespertino es menos productivo: hay menos clientes y las personas esperan sin trabajo. Toño decide que el turno vespertino prepare la salsa y porcione ingredientes para el día siguiente en las horas flojas.`,
r: `El Sistema de Producción Toyota, desarrollado por Taiichi Ohno y otros en las décadas posteriores a la Segunda Guerra Mundial, buscaba eliminar desperdicios (inventario de más, esperas, movimientos innecesarios, defectos) para producir con calidad y bajo costo. Su difusión en Occidente se aceleró con el libro «La máquina que cambió el mundo» (1990).`,
f: `Taiichi Ohno, «El sistema de producción Toyota»; James Womack, Daniel Jones y Daniel Roos, «La máquina que cambió el mundo» (1990); Nigel Slack y otros, «Administración de operaciones».`,
err: ["Creer que operaciones es solo «la cocina» y no un sistema.","Querer ser el mejor en calidad, rapidez, costo y flexibilidad al mismo tiempo.","Medir productividad sin considerar la calidad.","Ignorar la variabilidad y mirar solo promedios."],
a: `Describe la operación del negocio que observas con el modelo insumos → transformación → resultados. Clasifícala con las cuatro V y mide un indicador de productividad sencillo durante un día.`,
sol: `Si la variación de la demanda es alta (hora pico), el reto principal suele ser ajustar el personal y tener todo listo antes del pico.`,
q: [["Las operaciones de un negocio son…",["Las actividades que transforman insumos en productos o servicios","Solo las ventas","Los impuestos"],0,"Es la parte que «hace» lo que se vende."],
["¿Cuál NO es uno de los cuatro objetivos de operaciones?",["Popularidad en redes","Calidad","Costo"],0,"Son calidad, rapidez, costo y flexibilidad."],
["Si 4 personas trabajan 8 horas y preparan 480 tortas, la productividad es…",["15 tortas por hora-persona","60 tortas por hora-persona","120 tortas por persona"],0,"480 ÷ 32 = 15."],
["La variabilidad en un proceso significa que…",["El resultado no es siempre el mismo","El proceso es muy rápido","No hay clientes"],0,"Es enemiga de la confianza del cliente."]],
t: ["Operaciones", "Productividad"]
},
"M9-2": {
s: `Toño intenta explicarle al nuevo cocinero cómo se atiende un pedido, pero cada vez lo cuenta distinto. Decide dibujarlo en una hoja: del cliente que pide al cliente que recibe. Al terminar, encuentra tres pasos que nadie había notado.`,
o: ["Definir qué es un proceso y sus partes.","Dibujar un diagrama de flujo con los símbolos básicos.","Usar el diagrama para encontrar mejoras."],
x: `## ¿Qué es un proceso?
Un **proceso** es una secuencia de actividades que convierte una entrada en un resultado para un cliente (interno o externo). Atender un pedido, cobrar, comprar insumos, contratar a una persona, cerrar la caja: todo es un proceso. Cada proceso tiene:
- **Un inicio:** lo que lo dispara (el cliente pide una torta).
- **Entradas:** lo que se necesita (ingredientes, la comanda, el cocinero).
- **Actividades:** los pasos que se siguen.
- **Decisiones:** puntos en los que el camino cambia (¿hay ingredientes?, ¿paga en efectivo o con tarjeta?).
- **Salidas:** el resultado (la torta entregada y cobrada).
- **Un responsable** (o varios).
- **Un cliente:** quien recibe el resultado.

## ¿Por qué dibujar los procesos?
Un proceso que solo existe en la cabeza de las personas es invisible: nadie puede ver dónde se atora, dónde se repiten pasos o dónde se cometen errores. Dibujarlo lo vuelve visible y permite:
- **Entenderlo:** todos ven el mismo proceso.
- **Enseñarlo:** el diagrama sirve para capacitar.
- **Mejorarlo:** se ven pasos innecesarios, esperas y riesgos.
- **Estandarizarlo:** se define una sola forma de hacer las cosas.

## El diagrama de flujo
El **diagrama de flujo** es la herramienta más común para dibujar un proceso. Usa unos cuantos símbolos:

| Símbolo | Forma | Significado |
|---|---|---|
| Inicio o fin | Óvalo | Dónde empieza y dónde termina el proceso |
| Actividad | Rectángulo | Un paso que alguien hace |
| Decisión | Rombo | Una pregunta con respuestas (sí/no) que cambian el camino |
| Documento | Rectángulo con base ondulada | Un papel o registro (comanda, factura) |
| Espera | Forma de «D» | Un tiempo en que no pasa nada |
| Flecha | Línea con punta | El orden de los pasos |

No hace falta un programa especial: se puede dibujar en una hoja, en un pizarrón o con notas adhesivas en la pared.

## El proceso de un pedido en mostrador
Así quedó el diagrama de Toño, escrito como lista de pasos:
1. **Inicio:** el cliente llega al mostrador.
2. La cajera saluda y toma el pedido.
3. **Decisión:** ¿el cliente paga ahora? Sí → cobra. No (pedido de oficina a crédito) → registra en la libreta.
4. La cajera escribe la comanda y la pasa a la cocina.
5. **Espera:** la comanda espera en la barra hasta que un cocinero la toma.
6. El cocinero revisa la comanda.
7. **Decisión:** ¿hay todos los ingredientes en la estación? No → va a la bodega por ellos (paso que nadie había notado).
8. El cocinero prepara la torta.
9. El cocinero la deja en la barra de salida.
10. **Espera:** la torta espera a que la cajera la vea.
11. La cajera llama al cliente y entrega.
12. **Fin:** el cliente se va con su torta.

Al dibujarlo, Toño vio tres problemas que nadie había notado:
- **Espera en la barra (paso 5):** a veces la comanda tardaba un minuto en ser tomada porque los cocineros no la veían.
- **Ir a la bodega (paso 7):** cuando faltaba un ingrediente, el cocinero dejaba la estación hasta dos minutos.
- **Espera en la salida (paso 10):** la torta lista se enfriaba porque la cajera estaba cobrando a otro cliente.

## Mejoras a partir del diagrama
- Un **timbre** o una pantalla para avisar a la cocina de cada comanda nueva.
- **Reabastecer la estación** antes de la hora pico, con una lista de verificación (lección M9-3), y una persona encargada de traer ingredientes de la bodega durante el pico.
- **Separar** la caja de la entrega en la hora pico: una persona cobra y otra entrega.

Con estos cambios, el tiempo promedio baja de 5.4 a 3.5 minutos.

## Una herramienta complementaria: SIPOC
Antes de dibujar el detalle, a veces conviene ver el proceso «desde lejos» con una tabla llamada **SIPOC** (por las siglas en inglés de proveedores, entradas, proceso, salidas y clientes):

| Proveedores | Entradas | Proceso (5 a 7 pasos) | Salidas | Clientes |
|---|---|---|---|---|
| Panadería, carnicería, cajera | Pan, carne, comanda | Tomar pedido → cobrar → preparar → empacar → entregar | Torta entregada, ticket | Cliente de mostrador |

Sirve para que todos tengan claro el alcance del proceso antes de entrar al detalle.

## Los procesos que cruzan áreas
Los procesos más importantes de un negocio suelen cruzar varias áreas. El pedido de una oficina pasa por ventas (lo toma), cocina (lo prepara), reparto (lo entrega) y administración (lo factura y lo cobra). Cuando cada área solo ve su parte, el proceso se atora en los cambios de mano. Una práctica útil es dibujar el diagrama en **carriles** (como una alberca): una columna por área, para ver claramente en qué momento el trabajo pasa de una a otra.

## Las grandes empresas y sus procesos
En una empresa grande hay cientos de procesos documentados, a veces con áreas dedicadas a su mejora. Uno de los ejemplos históricos más famosos es la **línea de ensamble móvil** de Ford en 1913: al rediseñar el proceso de armado del Modelo T, de modo que el auto avanzara por una línea y cada trabajador hiciera una tarea, el tiempo para ensamblar un chasis se redujo drásticamente, de más de doce horas a alrededor de hora y media. El producto no cambió; cambió el proceso.`,
k: `**Proceso:** secuencia de actividades que convierte entradas en un resultado para un cliente. **Diagrama de flujo:** óvalo (inicio/fin), rectángulo (actividad), rombo (decisión), flechas (orden). Dibujar el proceso revela **esperas, pasos innecesarios y riesgos**. **SIPOC** da la vista general; los **carriles** muestran los cambios de mano entre áreas.`,
ch: `Una estética dibuja el proceso de una cita: agendar, recibir, lavar, cortar, cobrar. Descubre que las clientas esperan 15 minutos entre el lavado y el corte porque solo hay una estilista libre.`,
gi: `Ford introdujo en 1913 la línea de ensamble móvil para el Modelo T: el rediseño del proceso redujo de forma enorme el tiempo de ensamble y permitió bajar el precio del auto.`,
e: `Toño mide el tiempo de cada paso antes y después de las mejoras:

| Paso | Antes (min) | Después (min) |
|---|---|---|
| Tomar pedido y cobrar | 0.8 | 0.8 |
| Espera de la comanda | 1.0 | 0.1 |
| Ir por ingredientes | 0.6 (promedio) | 0 |
| Preparar | 2.5 | 2.5 |
| Espera en la salida | 0.5 | 0.1 |
| **Total** | **5.4** | **3.5** |

Sin cambiar la receta ni contratar a nadie, el tiempo baja 35 %.`,
r: `Ford Motor Company introdujo en 1913, en su planta de Highland Park, la línea de ensamble móvil. La empresa ha documentado cómo el tiempo para ensamblar un chasis del Modelo T bajó de más de 12 horas a alrededor de hora y media, lo que permitió bajar el precio del auto y venderlo a millones de personas.`,
f: `Ford Motor Company, historia corporativa (corporate.ford.com); The Henry Ford Museum, «Moving assembly line».`,
err: ["Dibujar el proceso «como debería ser» y no como es en realidad.","Hacer diagramas tan detallados que nadie los entiende.","Olvidar las decisiones y las esperas.","Mejorar un paso sin ver el proceso completo."],
a: `Dibuja el diagrama de flujo de un proceso del negocio que observas (atender a un cliente, recibir mercancía, cerrar la caja). Marca las esperas y los pasos que no agregan valor, y propón dos mejoras.`,
sol: `Para encontrar las esperas, observa el proceso real con un reloj. Las mejoras más baratas suelen ser reordenar pasos, preparar antes y quitar traslados.`,
q: [["En un diagrama de flujo, el rombo representa…",["Una decisión","Una actividad","El inicio"],0,"Una pregunta que cambia el camino."],
["¿Por qué conviene dibujar un proceso?",["Para verlo, enseñarlo, mejorarlo y estandarizarlo","Para decorar la oficina","Porque lo pide el SAT"],0,"Lo invisible no se puede mejorar."],
["SIPOC sirve para…",["Ver el proceso completo desde lejos: proveedores, entradas, proceso, salidas y clientes","Calcular impuestos","Dibujar el organigrama"],0,"Define el alcance antes del detalle."],
["La línea de ensamble móvil de Ford (1913) es un ejemplo de…",["Mejora del proceso","Nuevo producto","Publicidad"],0,"El producto era el mismo; cambió el proceso."]],
t: ["Proceso", "Diagrama de flujo"]
},
"M9-3": {
s: `Un martes, el local abrió con la plancha fría, sin salsa preparada y sin cambio en la caja. El jueves, alguien dejó el refrigerador mal cerrado y se perdió la carne. Toño concluye: «Necesitamos una lista para abrir y otra para cerrar».`,
o: ["Organizar la rutina diaria en apertura, operación y cierre.","Diseñar listas de verificación (checklists).","Usar la rutina para reducir errores y olvidos."],
x: `## La rutina diaria
Todo negocio tiene una rutina que se repite cada día: abrir, operar y cerrar. Parece obvio, pero muchos problemas nacen de olvidos en esa rutina: la plancha que no se encendió a tiempo, el refrigerador mal cerrado, la caja sin cambio, la luz que se quedó prendida, la puerta sin candado. Cuando la rutina depende de la memoria de las personas, tarde o temprano alguien olvida algo, sobre todo en los días de prisa o cuando falta alguien.

## Las tres fases del día
**1. Apertura:** todo lo necesario para empezar a atender bien.
- Revisar que el local esté seguro (cerraduras, gas, luz).
- Encender equipos (plancha, refrigeradores, terminal de pago).
- Recibir y revisar la mercancía del día.
- Preparar ingredientes (porcionar, picar, preparar salsas).
- Revisar la limpieza.
- Preparar la caja con fondo de cambio.
- Junta diaria de 10 minutos (lección M7-5).

**2. Operación:** atender a los clientes y mantener todo funcionando.
- Atender pedidos según el proceso (lección M9-2).
- Reabastecer las estaciones antes de la hora pico.
- Limpiar sobre la marcha.
- Registrar faltantes y problemas en la bitácora.
- Hacer cortes parciales de caja si hay mucho efectivo.

**3. Cierre:** dejar todo listo y seguro para el día siguiente.
- Corte de caja y depósito o resguardo del efectivo.
- Inventario rápido de insumos clave y lista de compras.
- Guardar y etiquetar alimentos con fecha.
- Limpieza profunda de equipos y área.
- Apagar equipos que no deben quedarse encendidos; revisar gas.
- Revisar refrigeradores (temperatura y puertas cerradas).
- Sacar la basura.
- Cerrar con llave y revisar alarmas.
- Anotar en la bitácora los pendientes para el turno siguiente.

## La lista de verificación (checklist)
Una **lista de verificación** es una lista breve de pasos que alguien marca conforme los cumple. Su objetivo no es enseñar a hacer el trabajo (para eso están los procedimientos), sino **evitar olvidos** en tareas que se hacen muchas veces y en las que un descuido puede costar caro.

Las listas de verificación se volvieron famosas en la aviación. En 1935, durante una demostración, se estrelló un prototipo del bombardero B-17 de Boeing porque los pilotos, muy experimentados, olvidaron quitar un seguro de los controles. En lugar de concluir que el avión era «demasiado complicado», los pilotos crearon una lista de verificación para el despegue, el vuelo y el aterrizaje. Desde entonces, las listas son parte esencial de la seguridad aérea. El cirujano Atul Gawande contó esta historia en su libro «El efecto checklist», donde también mostró cómo una lista de verificación quirúrgica ayudó a reducir complicaciones en hospitales.

## Cómo diseñar una buena lista de verificación
1. **Corta:** de 5 a 10 puntos por fase; si es muy larga, nadie la usa.
2. **Con lo importante:** incluye lo que, si se olvida, causa problemas graves o caros (el gas, el refrigerador, la caja).
3. **Clara y concreta:** «Refrigerador a menos de 5 °C y puerta cerrada», no «revisar refrigeración».
4. **En orden:** en la secuencia en que se hacen las cosas.
5. **Visible:** pegada donde se usa (en la puerta, junto a la caja).
6. **Con responsable y firma:** quién la hizo, a qué hora.
7. **Revisada:** se actualiza cuando cambia algo o cuando un olvido muestra que falta un punto.

## La lista de apertura de Tortas Lupita
| # | Punto | Hora | ✓ | Iniciales |
|---|---|---|---|---|
| 1 | Revisar cerraduras y que no huela a gas | 6:45 | | |
| 2 | Encender plancha y extractor | 6:50 | | |
| 3 | Refrigeradores a menos de 5 °C | 6:50 | | |
| 4 | Recibir y revisar pan y carne (cantidad y frescura) | 7:00 | | |
| 5 | Preparar salsa y porcionar jamón y queso | 7:00–7:40 | | |
| 6 | Caja con 1,000 pesos de cambio | 7:40 | | |
| 7 | Terminal de pago encendida y con batería | 7:40 | | |
| 8 | Barra y mostrador limpios | 7:45 | | |
| 9 | Junta de 10 minutos | 7:50 | | |
| 10 | Abrir puerta | 8:00 | | |

## La bitácora de turno
Además de las listas, la **bitácora** es un cuaderno (o un documento compartido) donde cada turno anota lo importante: faltantes, problemas con equipos, quejas de clientes, pedidos especiales para el día siguiente. Es la memoria del negocio y la forma de que la información no se pierda entre turnos o cuando cambia el personal.

## Rutinas y supervisión
Las listas ayudan, pero hay que revisarlas. El encargado o el gerente debe revisar de vez en cuando que se llenen con honestidad (no marcando todo al final del día sin hacerlo). Una forma sencilla es hacer verificaciones sorpresa: medir la temperatura del refrigerador y compararla con lo anotado.

## En empresas grandes
Las cadenas de restaurantes, hoteles, hospitales, aerolíneas y fábricas tienen listas de verificación para casi todo: apertura, cierre, cambios de turno, mantenimiento, seguridad, limpieza. En muchas, el sistema registra automáticamente quién hizo cada verificación y a qué hora. La lógica es la misma que en Tortas Lupita: que las cosas importantes no dependan de la memoria.

## El resultado
Con las listas de apertura y cierre y la bitácora, en dos meses no se repite ningún olvido grave. Y cuando Toño falta un día, el turno abre igual que siempre.`,
k: `La rutina diaria tiene **apertura, operación y cierre**. Una **lista de verificación** (checklist) evita olvidos: corta, concreta, en orden, visible, con responsable y revisada. La **bitácora de turno** es la memoria del negocio. Ejemplo histórico: las listas de la aviación tras el accidente del prototipo B-17 (1935).`,
ch: `Una farmacia de barrio usa una lista de cierre: revisar la temperatura del refrigerador de vacunas, corte de caja, cerrar la cortina y activar la alarma. Desde que la usa, no se ha perdido ningún medicamento por temperatura.`,
gi: `Las aerolíneas usan listas de verificación en cada fase del vuelo, y los hospitales que adoptaron la lista de verificación de seguridad quirúrgica de la Organización Mundial de la Salud reportaron menos complicaciones en estudios publicados.`,
e: `Toño calcula lo que costaron los olvidos en un mes antes de las listas:

| Olvido | Veces | Costo por vez | Costo total |
|---|---|---|---|
| Carne perdida por refrigerador mal cerrado | 1 | 3,500 | 3,500 |
| Apertura tarde (plancha fría) | 3 | 600 de ventas perdidas | 1,800 |
| Sin cambio en caja (clientes que se van) | 4 | 200 | 800 |
| **Total** | | | **6,100** |

Las listas cuestan unos minutos al día y evitan unos 6,000 pesos al mes de pérdidas.`,
r: `Atul Gawande, cirujano y escritor, narró en «The Checklist Manifesto» (2009) la historia del prototipo del B-17 y explicó cómo la Organización Mundial de la Salud desarrolló una lista de verificación de seguridad quirúrgica que, en un estudio en ocho hospitales de distintos países publicado en 2009, se asoció con una reducción importante de complicaciones y muertes.`,
f: `Atul Gawande, «The Checklist Manifesto» (2009); Haynes y otros, New England Journal of Medicine (2009), sobre la lista de verificación quirúrgica de la OMS.`,
err: ["Hacer listas tan largas que nadie las usa.","Marcar todo al final del día sin haberlo hecho.","Confundir la lista con el procedimiento completo.","No actualizar la lista cuando ocurre un olvido nuevo."],
a: `Diseña la lista de apertura y la lista de cierre del negocio que observas (o de tu casa al salir de viaje), con un máximo de 10 puntos cada una. Úsala una semana y anota qué cambiarías.`,
sol: `Si en la semana encontraste un olvido que no estaba en la lista, agrégalo. Si un punto nunca se olvida y no es crítico, quizá puedes quitarlo para mantener la lista corta.`,
q: [["El objetivo principal de una lista de verificación es…",["Evitar olvidos en tareas repetidas","Enseñar todo el oficio","Decorar"],0,"Para enseñar están los procedimientos."],
["¿Cuál es una buena práctica al diseñar una lista?",["Que sea corta y concreta","Que tenga 80 puntos","Que esté guardada en un cajón"],0,"De 5 a 10 puntos por fase."],
["La bitácora de turno sirve para…",["Pasar la información importante entre turnos","Calcular impuestos","Contratar"],0,"Es la memoria del negocio."],
["Las listas de verificación se popularizaron en la aviación tras…",["El accidente de un prototipo del B-17 en 1935","La invención del teléfono","La Revolución francesa"],0,"Los pilotos olvidaron quitar un seguro de los controles."]],
t: ["Lista de verificación (checklist)", "Bitácora de turno"]
},
"M9-4": {
s: `En la hora pico, la fila llega a la calle. Lupita quiere contratar a otro cocinero. Toño cronometra cada paso y descubre que el problema no está en la cocina, sino en la caja: los cocineros esperan las comandas. ¿Dónde está realmente el atorón?`,
o: ["Calcular la capacidad de un proceso.","Identificar el cuello de botella.","Aplicar los pasos de la teoría de las restricciones."],
x: `## ¿Qué es la capacidad?
La **capacidad** es la cantidad máxima de producto o servicio que un proceso puede producir en un tiempo determinado. Se expresa, por ejemplo, en tortas por hora, clientes por día, autos reparados por semana o piezas por turno. Conocer la capacidad permite saber si el negocio puede atender la demanda, cuándo se van a formar filas y dónde conviene invertir.

## La capacidad de cada paso
Un proceso tiene varios pasos, y cada uno tiene su propia capacidad. Para calcularla:

**Capacidad de un paso (unidades por hora) = (60 ÷ minutos por unidad) × número de personas o máquinas en ese paso**

En el proceso de mostrador de Tortas Lupita en hora pico:

| Paso | Minutos por pedido | Personas | Capacidad (pedidos por hora) |
|---|---|---|---|
| Tomar pedido y cobrar | 1.5 | 1 cajera | 60 ÷ 1.5 × 1 = 40 |
| Preparar la torta | 2.5 | 3 cocineros | 60 ÷ 2.5 × 3 = 72 |
| Empacar y entregar | 0.5 | 1 ayudante | 60 ÷ 0.5 × 1 = 120 |

## El cuello de botella
La capacidad de todo el proceso **es igual a la del paso más lento**. Ese paso se llama **cuello de botella** (o restricción): como el cuello estrecho de una botella, limita cuánto puede pasar en total. En el ejemplo, aunque la cocina puede preparar 72 tortas por hora y la entrega 120, la caja solo procesa 40 pedidos por hora. El proceso completo atiende, como máximo, **40 pedidos por hora**. Contratar otro cocinero no serviría de nada: la cocina ya está esperando comandas.

Si en la hora pico llegan 55 clientes por hora, la fila crece en 15 personas cada hora. Al cabo de hora y media, hay más de 20 personas esperando, y muchas se van.

## La teoría de las restricciones
El físico israelí Eliyahu Goldratt popularizó estas ideas en su novela de negocios «La meta» (1984), en la que el gerente de una fábrica descubre que su planta está limitada por unas pocas máquinas y que mejorar cualquier otra parte no sirve. De ahí surgió la **teoría de las restricciones**, que propone cinco pasos:
1. **Identificar** la restricción (el cuello de botella).
2. **Explotarla:** sacarle el máximo provecho sin invertir (que nunca esté parada ni haga trabajo que no le corresponde).
3. **Subordinar** todo lo demás a la restricción: el resto del proceso trabaja al ritmo del cuello de botella y lo apoya.
4. **Elevar** la restricción: si después de los pasos anteriores sigue siendo insuficiente, invertir para aumentar su capacidad (otra persona, otra máquina).
5. **Repetir:** al resolver un cuello de botella, aparece otro; volver al paso 1.

## Aplicando los cinco pasos en Tortas Lupita
1. **Identificar:** la caja (40 pedidos por hora).
2. **Explotar:** que la cajera solo cobre y tome pedidos; quitarle tareas como entregar tortas o contestar WhatsApp en la hora pico. Tener cambio suficiente y la terminal lista. Con esto, el tiempo baja a 1.2 minutos: capacidad de 50.
3. **Subordinar:** el ayudante de entrega ayuda a tomar pedidos de la fila con una libreta mientras esperan; los cocineros preparan por adelantado las tortas más pedidas en los 10 minutos antes del pico.
4. **Elevar:** si aún no alcanza, abrir una segunda caja en la hora pico (con el ayudante) o aceptar pedidos anticipados por WhatsApp para recoger. Con dos puntos de cobro, la capacidad de la caja sube a 100, y el nuevo cuello de botella es la cocina (72).
5. **Repetir:** ahora la restricción es la cocina; si la demanda crece, ahí se invertirá.

## Utilización y esperas
La **utilización** es el porcentaje de su capacidad que realmente usa un recurso:

**Utilización = demanda ÷ capacidad**

Si llegan 55 clientes por hora y la caja puede atender 60, su utilización es 92 %. Parece bien, pero en la práctica, cuando la utilización se acerca al 100 %, las filas crecen muchísimo, porque los clientes no llegan de forma pareja: llegan en grupos. Por eso los negocios de servicio suelen planear capacidad por encima de la demanda promedio en la hora pico.

## Capacidad y demanda en el tiempo
La demanda cambia a lo largo del día, la semana y el año. Hay dos estrategias básicas:
- **Ajustar la capacidad a la demanda:** más personal en la hora pico, turnos escalonados, personal de medio tiempo, abrir una segunda caja.
- **Ajustar la demanda a la capacidad:** promociones en horas flojas, pedidos anticipados, citas, precios distintos por horario.

## En empresas grandes
Las fábricas planean su producción alrededor de sus máquinas cuello de botella; los aeropuertos, alrededor de sus pistas; los hospitales, alrededor de sus quirófanos. Las empresas de logística calculan la capacidad de cada centro de distribución hora por hora. Y todas aprenden lo mismo que Toño: **mejorar un paso que no es el cuello de botella no mejora el resultado total**.`,
k: `**Capacidad:** máximo que produce un proceso por unidad de tiempo; por paso = (60 ÷ minutos por unidad) × personas. El **cuello de botella** (el paso más lento) limita todo el proceso. **Teoría de las restricciones** (Goldratt, «La meta», 1984): identificar, explotar, subordinar, elevar y repetir. Utilización = demanda ÷ capacidad; cerca de 100 %, las filas crecen.`,
ch: `En una barbería con dos barberos y una sola silla de lavado, la silla de lavado es el cuello de botella: comprar una tercera silla de corte no reduce la espera.`,
gi: `Los aeropuertos con mucho tráfico están limitados por el número de despegues y aterrizajes por hora que permiten sus pistas; por eso se asignan horarios a las aerolíneas y se construyen pistas nuevas cuando la demanda crece.`,
e: `Toño calcula la fila en la hora pico antes y después:

| Situación | Capacidad del proceso | Clientes por hora | Fila después de 1.5 h |
|---|---|---|---|
| Antes (una caja, 1.5 min) | 40 | 55 | (55 − 40) × 1.5 = 22.5 personas |
| Explotar la caja (1.2 min) | 50 | 55 | (55 − 50) × 1.5 = 7.5 personas |
| Elevar (dos cajas, cocina como límite) | 72 | 55 | Sin fila acumulada |

Con dos puntos de cobro en el pico, la fila deja de crecer sin contratar otro cocinero.`,
r: `Eliyahu Goldratt publicó «La meta» en 1984 junto con Jeff Cox. La novela, que narra cómo un gerente salva su fábrica identificando sus cuellos de botella, se convirtió en uno de los libros de negocios más vendidos y dio origen a la teoría de las restricciones, aplicada en fábricas, hospitales y empresas de servicios.`,
f: `Eliyahu M. Goldratt y Jeff Cox, «La meta» (1984).`,
err: ["Invertir en un paso que no es el cuello de botella.","Calcular la capacidad con el mejor tiempo y no con el promedio real.","Planear la capacidad para la demanda promedio y no para la hora pico.","Creer que una utilización de 100 % es eficiente en un servicio."],
a: `Cronometra los pasos de un proceso del negocio que observas en su hora pico. Calcula la capacidad de cada paso, identifica el cuello de botella y propón una acción para explotarlo y otra para elevarlo.`,
sol: `Explotar casi siempre es más barato que elevar: quitar tareas al cuello de botella, preparar antes y evitar que se detenga.`,
q: [["El cuello de botella de un proceso es…",["El paso más lento, que limita a todo el proceso","El paso más rápido","El primer paso"],0,"Determina la capacidad total."],
["Si un paso tarda 2 minutos por unidad y hay 2 personas, su capacidad es…",["60 unidades por hora","30 unidades por hora","120 unidades por hora"],0,"60 ÷ 2 × 2 = 60."],
["Según la teoría de las restricciones, después de identificar la restricción hay que…",["Explotarla: sacarle el máximo provecho sin invertir","Contratar en todas las áreas","Ignorarla"],0,"Elevar viene después."],
["Si la demanda es de 50 por hora y la capacidad de 40, cada hora la fila…",["Crece en 10 personas","Se reduce","Se mantiene"],0,"50 − 40 = 10."]],
t: ["Capacidad", "Cuello de botella"]
},
"M9-5": {
s: `En la bodega de Tortas Lupita hay cajas de servilletas para seis meses, pero el viernes se acabó el aguacate a las 12:00. Toño se pregunta cómo puede sobrar lo que no importa y faltar lo que más se vende.`,
o: ["Explicar para qué sirve el inventario y cuánto cuesta.","Clasificar el inventario con el método ABC.","Aplicar el método de primeras entradas, primeras salidas (PEPS)."],
x: `## ¿Qué es el inventario?
El **inventario** es todo lo que el negocio tiene guardado para usar o vender: insumos y materias primas (pan, carne, verduras), productos en proceso (salsa a medio preparar), productos terminados (salsas envasadas) y materiales de apoyo (servilletas, bolsas, artículos de limpieza). En una tienda, el inventario es la mercancía en los anaqueles y en la bodega.

## ¿Para qué sirve?
El inventario cumple funciones importantes:
- **Atender la demanda** sin hacer esperar al cliente.
- **Protegerse de imprevistos:** retrasos del proveedor, ventas más altas de lo normal.
- **Aprovechar compras por volumen** o precios bajos.
- **Separar etapas** del proceso (preparar salsa en la tarde para usarla en la mañana).

## ¿Cuánto cuesta?
Pero el inventario también cuesta, y mucho:
- **Dinero detenido:** lo que está en la bodega es efectivo que no está en la caja (lección M8-5).
- **Espacio:** bodega, refrigeración, estantes.
- **Merma y caducidad:** los alimentos se echan a perder; los productos pasan de moda.
- **Robo y pérdida.**
- **Manejo:** el tiempo de acomodar, contar y mover.
- **Obsolescencia:** productos que ya nadie quiere.

El reto de operaciones es tener **suficiente inventario para no quedarse sin lo importante, pero no tanto que se desperdicie dinero**. Ni de más ni de menos.

## La clasificación ABC
No todos los artículos merecen la misma atención. El método **ABC** aplica el principio de Pareto (lección M5-2) al inventario: se ordenan los artículos según su **valor de consumo** (cuánto dinero representan en un periodo: cantidad usada × costo unitario) y se dividen en tres grupos:
- **A:** pocos artículos (alrededor del 10 % al 20 %) que representan la mayor parte del valor (alrededor del 70 % al 80 %). Requieren control estricto: conteo frecuente, pedidos cuidadosos, proveedores de respaldo.
- **B:** un grupo intermedio, con control moderado.
- **C:** muchos artículos (alrededor del 50 % o más) que representan poco valor (alrededor del 5 % al 10 %). Control sencillo: se pueden comprar en mayor cantidad y revisar con menos frecuencia.

Clasificación ABC de Tortas Lupita (consumo mensual):

| Artículo | Valor mensual | % del total | % acumulado | Clase |
|---|---|---|---|---|
| Carne y jamón | 28,000 | 32 % | 32 % | A |
| Pan | 18,000 | 21 % | 53 % | A |
| Queso | 13,000 | 15 % | 68 % | A |
| Aguacate | 10,000 | 12 % | 80 % | B |
| Refrescos | 7,000 | 8 % | 88 % | B |
| Verduras | 4,500 | 5 % | 93 % | C |
| Frijoles, mayonesa, chiles | 3,000 | 3 % | 96 % | C |
| Bolsas y servilletas | 2,000 | 2 % | 98 % | C |
| Limpieza | 1,500 | 2 % | 100 % | C |
| **Total** | **87,000** | **100 %** | | |

Cuatro artículos (carne, pan, queso y aguacate) suman el 80 % del valor. Ahí debe estar la atención de Toño, no en las servilletas. Nota que el aguacate, aunque es B por valor, es **crítico** para el cliente (sin él, no hay torta completa); por eso algunos negocios combinan el ABC con una clasificación por importancia.

## Primeras entradas, primeras salidas (PEPS)
Para productos perecederos o con caducidad, se usa el método **PEPS** (primeras entradas, primeras salidas; en inglés, FIFO): lo primero que llegó es lo primero que se usa. En la práctica:
- Se **etiqueta** cada producto con su fecha de entrada (y de caducidad).
- Al acomodar, lo nuevo se pone **atrás** y lo viejo **adelante**.
- Se revisan las fechas con regularidad.

Sin PEPS, el producto nuevo se usa primero y el viejo se queda en el fondo hasta echarse a perder. Es una de las causas más comunes de merma en restaurantes y tiendas.

(En contabilidad también existen métodos para valorar el inventario, como PEPS o costo promedio, que afectan cómo se calcula el costo de ventas; esos los define el contador.)

## Contar el inventario
Para controlar el inventario hay que contarlo:
- **Conteo diario** de los artículos A al cierre (carne, pan, queso).
- **Conteo semanal** de los B.
- **Conteo mensual** completo de todo.
- **Comparar** lo contado con lo que debería haber (compras − consumo según ventas): la diferencia es merma, desperdicio, error o robo.

## Rotación de inventario
La **rotación** indica cuántas veces se renueva el inventario en un periodo:

**Rotación = costo de ventas del periodo ÷ inventario promedio**

Si Tortas Lupita consume 87,000 pesos al mes y tiene en promedio 8,700 pesos de inventario, su rotación es de 10 veces al mes (el inventario dura unos 3 días). Una rotación alta es buena para perecederos; una baja indica dinero detenido o productos que no se venden.

## La solución de Toño
Toño aplica ABC: cuenta todos los días carne, pan, queso y aguacate; compra aguacate cada dos días según la venta esperada (y no una vez por semana); etiqueta todo con la fecha y aplica PEPS en el refrigerador. Las servilletas se compran una vez al mes en la cantidad necesaria, no para seis meses. Resultado: el aguacate ya no se acaba y la bodega libera dinero y espacio.`,
k: `**Inventario:** lo que el negocio guarda para usar o vender. Sirve, pero **cuesta** (dinero detenido, espacio, merma). **ABC:** pocos artículos A concentran la mayor parte del valor y requieren control estricto. **PEPS:** lo primero que entra es lo primero que sale. **Rotación = costo de ventas ÷ inventario promedio.**`,
ch: `Una tienda de abarrotes descubre que los refrescos, la leche y el pan son sus artículos A: los cuenta cada día y nunca se queda sin ellos, mientras revisa una vez al mes los productos de limpieza.`,
gi: `El código de barras transformó el control de inventarios: el primer producto con código universal (UPC) se escaneó en 1974 en un supermercado de Ohio, en Estados Unidos. Hoy las grandes cadenas saben en tiempo real cuántas piezas de cada producto hay en cada tienda.`,
e: `Toño calcula cuánto dinero libera al reducir el inventario de servilletas y bolsas:

| Concepto | Antes | Después |
|---|---|---|
| Inventario de bolsas y servilletas | 12,000 (6 meses) | 2,000 (1 mes) |
| Dinero liberado | — | 10,000 |
| Espacio en bodega | 2 estantes | Medio estante |

Ese dinero ahora sirve para comprar más seguido los artículos A frescos.`,
r: `El 26 de junio de 1974, en un supermercado Marsh en Troy, Ohio, se escaneó por primera vez un producto con código de barras UPC: un paquete de chicles Wrigley. La adopción del código de barras permitió a los comercios llevar un control de inventario mucho más preciso y rápido.`,
f: `GS1, historia del código de barras (gs1.org); Smithsonian, National Museum of American History.`,
err: ["Controlar igual todos los artículos.","No etiquetar fechas ni aplicar PEPS.","Comprar de más «porque está barato».","No comparar el inventario contado con el esperado."],
a: `Haz la clasificación ABC de 8 a 10 artículos del negocio que observas (o de tu despensa): estima cuánto se gasta en cada uno al mes, ordénalos y clasifícalos. Propón cómo controlar los A.`,
sol: `Para estimar el valor mensual, multiplica la cantidad que se usa al mes por su precio. Los artículos A suelen ser pocos y caros o muy usados.`,
q: [["En la clasificación ABC, los artículos A son…",["Pocos artículos que representan la mayor parte del valor","Los más baratos","Los que nunca se usan"],0,"Requieren control estricto."],
["PEPS significa…",["Primeras entradas, primeras salidas","Pagar en partes semanales","Pedir en pocas semanas"],0,"Lo primero que llega es lo primero que se usa."],
["Un costo del inventario es…",["El dinero detenido que no está en la caja","Las ventas","Los clientes"],0,"También el espacio, la merma y el robo."],
["Si el costo de ventas mensual es 60,000 y el inventario promedio 6,000, la rotación es…",["10 veces al mes","6 veces","100 veces"],0,"60,000 ÷ 6,000."]],
t: ["Inventario", "Clasificación ABC"]
},
"M9-6": {
s: `Toño ya sabe qué artículos cuidar. Ahora la pregunta es otra: ¿cuándo pedir el pan para no quedarse sin él, sin llenar la bodega de bolillos duros? La panadería tarda un día en entregar y algunos días se vende más de lo normal.`,
o: ["Calcular el punto de reorden.","Calcular el inventario de seguridad.","Entender la idea del lote económico de compra."],
x: `## La pregunta de cuándo pedir
Para cada artículo importante hay dos preguntas: **¿cuándo pedir?** y **¿cuánto pedir?** Si se pide tarde, se acaba antes de que llegue el pedido; si se pide muy pronto o mucho, se acumula inventario, se inmoviliza dinero y, en perecederos, se desperdicia. Esta lección responde la primera pregunta con una herramienta sencilla: el **punto de reorden**.

## El tiempo de entrega
El **tiempo de entrega** (o tiempo de reposición) es lo que tarda en llegar un pedido desde que se hace. Si la panadería entrega al día siguiente, el tiempo de entrega es de 1 día. Si un proveedor de empaques tarda una semana, es de 7 días. Durante ese tiempo, el negocio sigue vendiendo y consumiendo, así que hay que pedir **antes** de quedarse sin nada.

## El punto de reorden
El **punto de reorden** es el nivel de inventario en el que hay que hacer un nuevo pedido. La fórmula básica es:

**Punto de reorden = consumo diario × días de entrega + inventario de seguridad**

- **Consumo diario × días de entrega:** lo que se va a usar mientras llega el pedido.
- **Inventario de seguridad:** una reserva extra para protegerse si se vende más de lo normal o si el proveedor se retrasa.

## El inventario de seguridad
El **inventario de seguridad** (o stock de seguridad) es un colchón. Sin él, cualquier variación (un día con más clientes, un retraso del proveedor) deja al negocio sin producto. Una forma práctica de calcularlo en negocios pequeños es en **días de consumo**:

**Inventario de seguridad = consumo diario × días de seguridad**

¿Cuántos días de seguridad? Depende de:
- **Qué tan variable es la demanda:** si un día se venden 150 tortas y otro 260, hace falta más colchón.
- **Qué tan confiable es el proveedor:** si suele llegar tarde, más colchón.
- **Qué tan grave es quedarse sin el producto:** sin pan no hay tortas (muy grave); sin servilletas de color, poco grave.
- **Qué tan perecedero es:** el pan no puede guardarse muchos días; el colchón debe ser pequeño o resolverse de otra forma (un segundo proveedor cercano).

Un método más preciso, usado en empresas grandes, calcula el inventario de seguridad con estadística: a partir de la variación histórica de la demanda y del tiempo de entrega, y del nivel de servicio deseado (por ejemplo, no quedarse sin producto en el 95 % de los casos).

## Ejemplo con el pan
- Consumo promedio de bolillos: 300 al día.
- Días de entrega: 1.
- Días de seguridad: 1 (porque algunos días se venden hasta 380 y la panadería a veces se retrasa unas horas).

Punto de reorden = 300 × 1 + 300 × 1 = **600 bolillos**. Cuando el inventario baje a 600 bolillos, Toño debe pedir. En la práctica, como el pan se compra cada día, esto significa pedir cada mañana lo que se espera usar al día siguiente, y mantener siempre unos 300 de reserva (que se usan primero con PEPS para que no se pongan duros, o se congelan según la receta).

## Ejemplo con los empaques
- Consumo de bolsas: 250 al día.
- Días de entrega del proveedor: 5.
- Días de seguridad: 3.

Punto de reorden = 250 × 5 + 250 × 3 = 1,250 + 750 = **2,000 bolsas**. Cuando queden 2,000 bolsas, se hace el pedido. Puedes calcularlo con la calculadora «Punto de reorden».

## ¿Cuánto pedir? El lote económico
La segunda pregunta, cuánto pedir, tiene una respuesta clásica: el **lote económico de compra** (en inglés, EOQ, *economic order quantity*), propuesto por el ingeniero Ford W. Harris en 1913. Busca el equilibrio entre dos costos:
- **Costo de pedir:** cada pedido cuesta (tiempo, envío, trámite). Pedir pocas veces y en grandes cantidades reduce este costo.
- **Costo de mantener:** cada unidad guardada cuesta (dinero detenido, espacio, merma). Pedir muchas veces en cantidades pequeñas reduce este costo.

La fórmula es:

**Lote económico = raíz cuadrada de (2 × demanda anual × costo por pedido ÷ costo anual de mantener una unidad)**

Por ejemplo, si se usan 90,000 bolsas al año, cada pedido cuesta 200 pesos (envío y tiempo) y mantener una bolsa guardada un año cuesta 0.10 pesos, el lote económico es la raíz de (2 × 90,000 × 200 ÷ 0.10) = raíz de 360,000,000 ≈ **18,974 bolsas**, unos dos meses y medio de consumo. En la práctica se redondea al tamaño de caja del proveedor y se ajusta si hay descuentos por volumen o si el espacio es limitado.

Para perecederos como el pan, el lote económico no se aplica igual: manda la frescura.

## El sistema de revisión
Hay dos formas de aplicar estas ideas:
- **Revisión continua:** se vigila el inventario todo el tiempo y se pide cuando llega al punto de reorden (con un sistema o con una marca en el estante: «cuando llegues a esta línea, avisa»).
- **Revisión periódica:** se revisa en fechas fijas (cada lunes, cada día al cierre) y se pide lo necesario para llegar a un nivel objetivo.

En negocios pequeños, una técnica muy práctica es el **sistema de dos contenedores**: el producto se guarda en dos cajas; cuando se vacía la primera, se hace el pedido y se empieza a usar la segunda, que funciona como el inventario hasta que llegue el pedido.

## En empresas grandes
Las grandes cadenas tienen sistemas que calculan automáticamente el punto de reorden de cada producto en cada tienda, con base en las ventas recientes, la temporada, las promociones y los tiempos de entrega de cada proveedor. Muchas comparten esta información directamente con sus proveedores para que ellos repongan el producto sin que nadie haga un pedido. Pero la fórmula base es la misma que usa Toño para el pan.`,
hr: "reorden",
k: `**Punto de reorden = consumo diario × días de entrega + inventario de seguridad.** **Inventario de seguridad** = consumo diario × días de seguridad (más días si la demanda varía mucho, el proveedor falla o quedarse sin producto es grave). **Lote económico** (Harris, 1913) equilibra el costo de pedir y el de mantener. Truco práctico: **dos contenedores**.`,
ch: `Una papelería pega en el estante de hojas blancas una etiqueta: «Cuando queden 5 paquetes, pedir». Como el proveedor tarda 3 días y vende 1 paquete al día, tiene 2 de reserva.`,
gi: `Las grandes cadenas y sus proveedores usan sistemas de reposición automática que calculan, con las ventas diarias de cada tienda, cuándo y cuánto reponer de cada producto.`,
e: `Toño calcula el punto de reorden de tres insumos:

| Insumo | Consumo diario | Días de entrega | Días de seguridad | Punto de reorden |
|---|---|---|---|---|
| Bolillos | 300 | 1 | 1 | 600 |
| Bolsas | 250 | 5 | 3 | 2,000 |
| Queso (kg) | 12 | 2 | 1 | 36 kg |

Pega las cifras en la bodega y en el refrigerador. Desde entonces, no se ha acabado ningún insumo clave.`,
r: `Ford W. Harris publicó en 1913, en la revista «Factory, The Magazine of Management», el artículo «How Many Parts to Make at Once», en el que presentó el modelo del lote económico. Más de un siglo después, sigue enseñándose en todos los cursos de administración de operaciones.`,
f: `Ford W. Harris, «How Many Parts to Make at Once», Factory, The Magazine of Management (1913).`,
err: ["Pedir solo cuando el producto ya se acabó.","No considerar el tiempo de entrega.","Usar el mismo inventario de seguridad para todo.","Aplicar el lote económico a productos muy perecederos."],
a: `Elige tres insumos del negocio que observas. Estima su consumo diario, el tiempo de entrega y los días de seguridad, y calcula el punto de reorden con la calculadora del curso. Propón cómo marcarlo físicamente en la bodega.`,
sol: `Una línea en el estante, una etiqueta en el refrigerador o el sistema de dos contenedores son formas baratas de que todos sepan cuándo pedir.`,
q: [["El punto de reorden se calcula como…",["Consumo diario × días de entrega + inventario de seguridad","Ventas − costos","Inventario ÷ ventas"],0,"Es el nivel en el que hay que pedir."],
["Si se usan 100 piezas al día, la entrega tarda 3 días y hay 2 días de seguridad, el punto de reorden es…",["500 piezas","300 piezas","200 piezas"],0,"100 × 3 + 100 × 2 = 500."],
["El inventario de seguridad sirve para…",["Protegerse si se vende más de lo normal o el proveedor se retrasa","Vender más caro","Pagar impuestos"],0,"Es un colchón."],
["El lote económico de compra equilibra…",["El costo de pedir y el costo de mantener inventario","Ventas y gastos","Precios y salarios"],0,"Propuesto por Ford W. Harris en 1913."]],
t: ["Punto de reorden", "Inventario de seguridad"]
},
"M9-7": {
s: `Un cliente encuentra un pelo en su torta. Otro dice que hoy estaba «más chica». Un tercero se queja de que la salsa estaba distinta. Lupita entiende que la calidad no puede depender del humor del día: necesita estándares y una forma de mejorar siempre.`,
o: ["Definir calidad desde el punto de vista del cliente.","Distinguir estándares, control y mejora continua.","Aplicar Kaizen, las 5S y los sistemas a prueba de errores."],
x: `## ¿Qué es la calidad?
Para un negocio, la **calidad** es cumplir, de forma **constante**, lo que el cliente espera y lo que el negocio promete. No se trata de hacer el producto más lujoso posible, sino de que sea **igual de bueno cada vez**. Una torta sencilla que siempre sale igual, rápida y limpia tiene más calidad (para su cliente) que una torta gourmet que a veces sale perfecta y a veces quemada.

El experto en calidad Joseph Juran la definió como «adecuación al uso»; Philip Crosby, como «cumplimiento de los requisitos». En la práctica, la calidad tiene varias dimensiones: el producto en sí (sabor, tamaño, temperatura), la higiene, la rapidez, el trato y la consistencia.

## Tres niveles de trabajo en calidad
1. **Estándares:** definir con precisión qué es «bien hecho».
2. **Control:** verificar que se cumpla el estándar y corregir cuando no.
3. **Mejora continua:** elevar el estándar poco a poco, siempre.

## 1. Estándares
Un **estándar** es una especificación clara y medible de cómo debe ser el producto o el servicio. Sin estándar, cada persona tiene su propia idea de «bien hecho». Ejemplos de estándares de Tortas Lupita:
- Bolillo del día, sin partes quemadas.
- 60 gramos de jamón, 40 de queso, un cuarto de aguacate.
- Preparación en un máximo de 3 minutos.
- Temperatura del refrigerador por debajo de 5 °C.
- Cofia, cubrebocas en preparación y manos lavadas cada vez que se cobra.
- Saludo y despedida a cada cliente.

Los estándares se escriben en las recetas y procedimientos (lección M9-9) y se enseñan a todos.

## 2. Control de calidad
El **control** verifica que el estándar se cumpla:
- **Revisión en el momento:** el cocinero revisa la torta antes de entregarla; la cajera mira que vaya completa.
- **Muestreo:** el encargado pesa al azar 5 tortas al día para revisar las porciones.
- **Registros:** temperaturas del refrigerador, quejas de clientes, devoluciones.
- **Indicadores:** porcentaje de tortas rehechas, quejas por cada 1,000 tortas, calificación en reseñas.

Cuando algo falla, no basta con corregir el caso: hay que buscar la **causa raíz**. Una técnica sencilla son los **cinco porqués**: preguntar «¿por qué?» varias veces hasta llegar al origen. Ejemplo:
- ¿Por qué la torta salió chica? Porque tenía menos jamón.
- ¿Por qué? Porque el cocinero no pesó la porción.
- ¿Por qué? Porque la báscula estaba descompuesta.
- ¿Por qué? Porque se mojó y nadie la revisó.
- ¿Por qué? Porque no estaba en la lista de verificación de apertura.
- **Acción:** agregar «báscula funcionando» a la lista de apertura y tener una de repuesto.

## 3. Mejora continua: Kaizen
**Kaizen** es una palabra japonesa que significa, aproximadamente, «cambio para mejor». En administración designa la filosofía de **mejorar un poco todos los días, con la participación de todos**. En lugar de esperar grandes inversiones o grandes cambios, se buscan pequeñas mejoras constantes: reacomodar una estación para ahorrar pasos, cambiar el orden de una tarea, eliminar una espera. El consultor Masaaki Imai difundió el concepto en Occidente con su libro «Kaizen» (1986).

Prácticas de Kaizen en un negocio pequeño:
- Una **caja o pizarrón de ideas** donde cualquiera propone mejoras.
- Una **reunión breve** cada semana para revisar una idea y probarla (con el ciclo PHVA de la lección M7-3).
- **Reconocer** a quien propone mejoras que funcionan.

## Las 5S: orden y limpieza
Las **5S** son una metodología japonesa para organizar el lugar de trabajo. Su nombre viene de cinco palabras japonesas que empiezan con «s»:

| S | Palabra | Significado | En la cocina de Tortas Lupita |
|---|---|---|---|
| 1 | Seiri | Clasificar: quitar lo que no sirve | Sacar utensilios rotos y cosas que no se usan |
| 2 | Seiton | Ordenar: un lugar para cada cosa | Cada ingrediente en su contenedor, siempre en el mismo lugar |
| 3 | Seiso | Limpiar | Limpiar la estación durante y después del turno |
| 4 | Seiketsu | Estandarizar | Fotos de cómo debe verse cada estación |
| 5 | Shitsuke | Disciplina | Revisar cada día que se mantenga el orden |

Un lugar de trabajo ordenado reduce errores, tiempos de búsqueda, accidentes y contaminación de alimentos.

## A prueba de errores: poka-yoke
Otra idea japonesa, desarrollada por el ingeniero Shigeo Shingo en Toyota, es el **poka-yoke** («a prueba de errores»): diseñar el proceso para que sea difícil equivocarse. Ejemplos:
- Contenedores con el tamaño exacto de una porción (no se puede servir de más).
- Colores distintos para tablas de picar de carne cruda y de verduras.
- Un temporizador que suena si la torta lleva más de 3 minutos.
- La terminal que no deja cerrar la venta sin elegir el tipo de torta.

En lugar de culpar a las personas por los errores, se mejora el diseño del proceso.

## La calidad cuesta, pero la falta de calidad cuesta más
Prevenir errores tiene un costo (capacitación, revisiones, básculas), pero los errores cuestan más: tortas rehechas, ingredientes desperdiciados, clientes que no regresan, reseñas negativas y, en alimentos, riesgos para la salud. Philip Crosby resumió la idea en el título de su libro «La calidad no cuesta» (1979): lo caro es no tenerla.

## En las empresas gigantes
Las grandes empresas tienen sistemas formales de gestión de la calidad, muchas veces certificados con normas internacionales como **ISO 9001**, que exigen procesos documentados, control y mejora continua. Toyota, con su sistema de producción, y otras empresas japonesas mostraron al mundo, desde los años setenta y ochenta, que la calidad constante podía ser una ventaja competitiva enorme.`,
k: `**Calidad:** cumplir de forma **constante** lo que el cliente espera y el negocio promete. Tres niveles: **estándares**, **control** (con causa raíz y los **cinco porqués**) y **mejora continua** (**Kaizen**). **5S:** clasificar, ordenar, limpiar, estandarizar, disciplina. **Poka-yoke:** diseñar el proceso para evitar errores. Norma internacional: ISO 9001.`,
ch: `Un taller de costura usa contenedores marcados por talla y una foto de cómo debe quedar cada prenda terminada. Las devoluciones por errores de talla bajan a casi cero.`,
gi: `Toyota permite que cualquier trabajador de la línea detenga la producción si detecta un defecto (tirando de una cuerda llamada andon), para que el problema se resuelva en su origen en lugar de pasar al siguiente paso.`,
e: `Lupita mide el costo de la mala calidad en un mes antes y después de estándares, 5S y poka-yoke:

| Concepto | Antes | Después |
|---|---|---|
| Tortas rehechas | 180 (× 16 = 2,880) | 40 (× 16 = 640) |
| Quejas | 45 | 12 |
| Clientes perdidos estimados | 20 (× 46 × 8 visitas al mes = 7,360 de ventas) | 5 (1,840) |
| Costo de básculas, contenedores y capacitación | 0 | 1,200 |

La calidad dejó de costar miles de pesos al mes en desperdicio y ventas perdidas.`,
r: `Masaaki Imai fundó el Kaizen Institute y publicó en 1986 «Kaizen: la clave de la ventaja competitiva japonesa», que difundió en Occidente la idea de la mejora continua con la participación de todos los empleados, inspirada en prácticas de empresas japonesas como Toyota.`,
f: `Masaaki Imai, «Kaizen» (1986); Philip Crosby, «La calidad no cuesta» (1979); ISO, norma ISO 9001.`,
err: ["Definir calidad como lujo en lugar de consistencia.","Corregir el caso sin buscar la causa raíz.","Culpar a las personas en lugar de mejorar el proceso.","Hacer una limpieza general una vez y no mantenerla."],
a: `Aplica las 5S a un espacio de trabajo (una estación del negocio, tu escritorio, tu cocina). Toma una foto antes y después. Después, elige un error frecuente y aplica los cinco porqués para encontrar su causa raíz.`,
sol: `La S más difícil es la quinta (disciplina): define quién revisa el orden y cada cuánto, o en un mes estarás como al principio.`,
q: [["Para un negocio, calidad significa sobre todo…",["Cumplir de forma constante lo que el cliente espera","Ser lo más lujoso posible","Ser lo más barato"],0,"La consistencia es clave."],
["Kaizen significa…",["Mejora continua con la participación de todos","Un tipo de sushi","Una norma fiscal"],0,"Pequeñas mejoras constantes."],
["La técnica de los cinco porqués sirve para…",["Encontrar la causa raíz de un problema","Calcular el precio","Dibujar el organigrama"],0,"Se pregunta «¿por qué?» varias veces."],
["Un contenedor del tamaño exacto de una porción es un ejemplo de…",["Poka-yoke (a prueba de errores)","Publicidad","Factoraje"],0,"Hace difícil equivocarse."]],
t: ["Calidad", "Estándar"]
},
"M9-8": {
s: `Los pedidos a oficinas crecen, pero el repartidor llega tarde: sale con un pedido, regresa, sale con otro y cruza la ciudad dos veces. Una oficina se queja de que las tortas llegaron frías. Toño se da cuenta de que entregar también es una operación que se puede planear.`,
o: ["Explicar qué es la logística y la «última milla».","Planear rutas, tiempos y capacidad de reparto.","Cuidar la calidad del producto durante la entrega."],
x: `## ¿Qué es la logística?
La **logística** es la parte de las operaciones que se encarga de **mover y guardar** cosas: traer los insumos de los proveedores, almacenarlos, moverlos dentro del negocio y llevar los productos al cliente, en el momento y el lugar correctos, al menor costo posible y en buenas condiciones. En una empresa grande hay áreas completas de logística con flotas, centros de distribución y sistemas. En Tortas Lupita, la logística es el repartidor, su moto, una mochila térmica y un cuaderno de pedidos.

## Logística de entrada y de salida
- **Logística de entrada:** cómo llegan los insumos al negocio (quién los trae, a qué hora, cómo se reciben, dónde se guardan).
- **Logística interna:** cómo se mueven dentro (de la bodega a la cocina, de la cocina al mostrador).
- **Logística de salida:** cómo llega el producto al cliente (entrega en mostrador, a domicilio, por paquetería).

## La última milla
La **última milla** es el tramo final de la entrega, desde el negocio (o el centro de distribución) hasta el cliente. Suele ser la parte **más cara y difícil** de toda la cadena: muchas paradas, tráfico, direcciones confusas, clientes que no están. Para las tiendas en línea y las plataformas de reparto, la última milla es uno de sus mayores costos.

## Planear las entregas
Para que las entregas sean puntuales y eficientes hay que planear:
1. **Horario de corte:** hasta qué hora se reciben pedidos para cada horario de entrega («pedidos antes de las 11:00 se entregan a las 13:00»).
2. **Agrupar pedidos:** juntar los pedidos de oficinas cercanas en una misma salida.
3. **Rutas:** ordenar las entregas para recorrer la menor distancia (un mapa en el celular ayuda).
4. **Tiempos:** estimar cuánto tarda cada ruta, incluido estacionarse y subir a la oficina.
5. **Capacidad:** cuántos pedidos puede llevar el repartidor en cada viaje (tamaño de la mochila, peso) y cuántos viajes puede hacer en el horario de entrega.
6. **Comunicación:** avisar al cliente cuando el pedido sale y confirmar la entrega.

## La calidad durante la entrega
El producto puede salir perfecto de la cocina y llegar mal al cliente. En alimentos, hay que cuidar:
- **Temperatura:** mochilas térmicas; preparar lo más cerca posible de la salida.
- **Empaque:** que no se aplaste ni se derrame; separar lo frío de lo caliente.
- **Higiene:** empaques cerrados y limpios.
- **Tiempo:** cada minuto cuenta para que llegue caliente.
- **Exactitud:** que llegue lo que se pidió (una lista de verificación por pedido).

## Medir el reparto
Indicadores útiles:
- **Entregas a tiempo:** porcentaje de pedidos que llegan dentro del horario prometido.
- **Tiempo promedio de entrega.**
- **Pedidos con error** (faltó algo, llegó otro producto).
- **Costo por entrega:** sueldo del repartidor, gasolina, mantenimiento, dividido entre el número de entregas.
- **Quejas por temperatura o estado del producto.**

## ¿Repartidor propio o externo?
| Opción | Ventajas | Desventajas |
|---|---|---|
| Repartidor propio | Control del trato y la calidad; costo fijo predecible | Costo aunque haya pocos pedidos; hay que administrar vehículo y seguro |
| Mensajería o repartidores por pedido | Pagas solo cuando hay entregas | Menos control; costo por entrega más alto |
| Plataforma de reparto | Acceso a nuevos clientes; ellos ponen al repartidor | Comisiones altas; poco control de la experiencia (lección M4-4) |

Muchos negocios combinan: repartidor propio para los pedidos programados de oficinas y plataforma para pedidos individuales.

## Logística en las empresas gigantes
Las grandes empresas tratan la logística como una ventaja competitiva:
- **Centros de distribución:** grandes almacenes desde donde se surten las tiendas o los clientes de una región (Módulo 20).
- **Optimización de rutas:** programas que calculan las mejores rutas para miles de vehículos. La empresa de paquetería UPS es conocida por su sistema de optimización de rutas, llamado ORION, y por su práctica de evitar en lo posible las vueltas a la izquierda en países donde se maneja por la derecha (que obligan a esperar el tráfico contrario), lo que, según la empresa, ahorra millones de litros de combustible al año.
- **Seguimiento en tiempo real:** el cliente ve dónde va su pedido.
- **Logística inversa:** recoger devoluciones, envases o productos para reciclar.

## El nuevo plan de reparto de Tortas Lupita
Toño organiza:
- Horario de corte: pedidos de oficinas hasta las 11:00 para entregar entre 12:30 y 13:30.
- Dos rutas fijas (zona norte y zona sur), cada una con 6 a 8 oficinas.
- Preparación escalonada: primero los pedidos de la ruta más lejana.
- Mochila térmica grande y empaques que no se aplastan.
- Mensaje al cliente: «Su pedido salió; llega en 15 minutos».

Resultado: el repartidor hace dos viajes en lugar de seis, las entregas a tiempo pasan de 70 % a 96 % y no ha vuelto a haber quejas por tortas frías.

## La logística de entrada también cuenta
No hay que olvidar el otro extremo: pedir a los proveedores que entreguen en un horario fijo, antes de la apertura, evita recibir mercancía en plena hora pico.`,
k: `**Logística:** mover y guardar cosas (de entrada, interna y de salida), a tiempo, al menor costo y en buen estado. La **última milla** suele ser la parte más cara de la entrega. Planea **horario de corte, agrupación, rutas, tiempos y capacidad**; cuida la **calidad en el traslado** y mide entregas a tiempo y costo por entrega.`,
ch: `Una tortillería que surte a cinco fondas organiza una sola ruta a las 12:00 en lugar de cinco viajes separados, y ahorra gasolina y tiempo.`,
gi: `UPS desarrolló el sistema ORION para optimizar las rutas de sus repartidores; la empresa ha informado que su política de reducir las vueltas a la izquierda le ahorra millones de litros de combustible y reduce emisiones cada año.`,
e: `Toño compara el costo por entrega antes y después de las rutas:

| Concepto | Antes | Después |
|---|---|---|
| Viajes al día | 6 | 2 |
| Kilómetros al día | 48 | 22 |
| Gasolina al mes | 3,600 | 1,650 |
| Pedidos al día | 14 | 14 |
| Costo de gasolina por entrega | 9.9 | 4.5 |
| Entregas a tiempo | 70 % | 96 % |

Agrupar y planear rutas reduce el costo por entrega a menos de la mitad.`,
r: `UPS ha descrito públicamente su sistema de optimización de rutas ORION (On-Road Integrated Optimization and Navigation) y su política de minimizar las vueltas a la izquierda, con la que estima ahorros de millones de galones de combustible al año en su red de Estados Unidos.`,
f: `UPS, comunicados y notas corporativas sobre ORION y la política de vueltas a la izquierda (about.ups.com).`,
err: ["Salir con cada pedido por separado.","No definir un horario de corte para los pedidos.","Olvidar la temperatura y el empaque durante la entrega.","No medir el costo por entrega."],
a: `Planea las entregas de un día para un negocio con 10 pedidos en distintas direcciones (puedes inventarlas en un mapa de tu ciudad): agrupa en rutas, ordena las paradas y estima tiempos. Calcula el costo por entrega.`,
sol: `Agrupa por zona y empieza por la parada más lejana del punto de salida, o recorre en círculo para no regresar sobre el mismo camino.`,
q: [["La logística se encarga de…",["Mover y guardar cosas a tiempo, al menor costo y en buen estado","Contratar personal","Fijar precios"],0,"Entrada, interna y salida."],
["La «última milla» es…",["El tramo final de la entrega hasta el cliente","El primer proveedor","La bodega"],0,"Suele ser la parte más cara."],
["Un horario de corte sirve para…",["Agrupar pedidos y planear las entregas","Cortar el pan","Cerrar el negocio"],0,"Define hasta qué hora se reciben pedidos para cada entrega."],
["UPS es conocida por optimizar rutas y…",["Evitar en lo posible las vueltas a la izquierda","Entregar solo de noche","No usar vehículos"],0,"Para ahorrar tiempo y combustible."]],
t: ["Logística", "Última milla"]
},
"M9-9": {
s: `Tortas Lupita va a abrir su segunda sucursal. Lupita se preocupa: «¿Cómo voy a lograr que allá sepan igual que aquí?». Toño responde: «Escribiendo cómo se hace cada cosa, para que no dependa de nosotros».`,
o: ["Explicar qué es un procedimiento estándar de operación.","Escribir un procedimiento claro y útil.","Usar los procedimientos para capacitar, controlar y replicar el negocio."],
x: `## ¿Qué es un procedimiento estándar?
Un **procedimiento estándar de operación** (en inglés, SOP, *standard operating procedure*) es un documento que describe, paso a paso, **cómo se hace una tarea** de la forma acordada como la mejor hasta ahora. Responde: ¿qué se hace?, ¿quién lo hace?, ¿cuándo?, ¿con qué?, ¿cómo?, y ¿cómo se sabe que quedó bien?

Mientras la descripción de puesto (lección M6-8) dice qué responsabilidades tiene una persona, el procedimiento dice cómo se ejecuta una tarea concreta, la haga quien la haga.

## ¿Para qué sirven?
1. **Consistencia:** el producto sale igual, sin importar quién lo haga ni en qué sucursal.
2. **Capacitación:** una persona nueva aprende más rápido y con menos errores.
3. **Independencia del dueño:** el conocimiento deja de estar solo en la cabeza de una persona.
4. **Control:** permite revisar si la tarea se hizo como se debía.
5. **Mejora:** el procedimiento escrito es la base para mejorarlo (Kaizen): si se encuentra una mejor forma, se actualiza.
6. **Replicar el negocio:** es indispensable para abrir sucursales o franquicias (Módulos 20 y 21).
7. **Seguridad e higiene:** asegura que se sigan las reglas importantes.

## ¿Qué tareas merecen un procedimiento?
No todo necesita un procedimiento escrito. Conviene empezar por las tareas que:
- **Afectan directamente al cliente** (preparar el producto estrella, atender una queja).
- **Tienen riesgo** (manejo de gas, de efectivo, de alimentos crudos).
- **Se hacen con frecuencia** y por distintas personas.
- **Generan errores frecuentes.**
- **Son difíciles de aprender** solo observando.

## Las partes de un buen procedimiento
| Parte | Contenido |
|---|---|
| Nombre y código | «PR-COC-01 Preparación de torta de jamón» |
| Objetivo | Para qué sirve el procedimiento |
| Alcance | A qué puestos y lugares aplica |
| Responsable | Quién lo ejecuta y quién lo supervisa |
| Materiales y equipo | Lo que se necesita |
| Pasos | Numerados, en orden, uno por renglón, con verbos de acción |
| Puntos críticos | Lo que nunca debe fallar (higiene, cantidades, tiempos) |
| Criterio de terminado | Cómo se sabe que quedó bien |
| Fotos o dibujos | Cómo debe verse el resultado |
| Fecha y versión | Para saber si es la versión vigente |

## Ejemplo: preparación de la torta de jamón
**Objetivo:** preparar la torta de jamón con el sabor, tamaño y tiempo estándar.
**Responsable:** cocinero de turno; supervisa el jefe de cocina.
**Materiales:** bolillo del día, 60 g de jamón, 40 g de queso, 1/4 de aguacate, jitomate, cebolla, frijoles, mayonesa, salsa de la casa, báscula, contenedores de porción, plancha a temperatura media.

**Pasos:**
1. Lavarse las manos y ponerse guantes.
2. Abrir el bolillo a lo largo sin separar las mitades.
3. Calentar el bolillo en la plancha 40 segundos, por dentro.
4. Untar una cucharada de frijoles en la base y una de mayonesa en la tapa.
5. Colocar el jamón (contenedor de 60 g) y calentar 30 segundos.
6. Agregar el queso (contenedor de 40 g).
7. Agregar 2 rebanadas de jitomate, cebolla y el aguacate en rebanadas.
8. Agregar salsa según la comanda (normal, poca o sin salsa).
9. Cerrar, cortar en diagonal y envolver en papel.
10. Dejar en la barra de salida con la comanda.

**Puntos críticos:** manos limpias; porciones exactas; sin partes quemadas; menos de 3 minutos.
**Criterio de terminado:** se ve como la foto estándar; peso total entre 280 y 300 gramos.

## Cómo escribir procedimientos que se usen
- **Escríbelos con quien hace la tarea:** la persona que la realiza conoce los detalles.
- **Usa verbos de acción:** «abrir», «calentar», «colocar».
- **Un paso por renglón**, en orden.
- **Lenguaje sencillo**, sin palabras técnicas innecesarias.
- **Agrega fotos:** una imagen vale más que muchas palabras, sobre todo en cocina y manufactura.
- **Pruébalo:** pide a una persona nueva que lo siga sin ayuda; donde se atore, el procedimiento no está claro.
- **Ponlo donde se usa:** una hoja plastificada junto a la estación.
- **Actualízalo** cuando el proceso cambie, y retira las versiones viejas.

## Del procedimiento al manual de operación
El conjunto de procedimientos de un negocio forma su **manual de operación**: recetas, apertura y cierre, atención al cliente, manejo de caja, recepción de mercancía, limpieza, seguridad. Es uno de los activos más valiosos de un negocio que quiere crecer, porque contiene **cómo funciona**. Las franquicias venden, en buena medida, el derecho a usar su manual (Módulo 21).

## En empresas grandes
Las grandes empresas tienen miles de procedimientos, muchas veces en sistemas digitales con videos y evaluaciones. Las cadenas de hoteles de lujo, como Ritz-Carlton, son conocidas por sus estándares escritos de servicio, que todos los empleados aprenden y repasan con frecuencia. Las fábricas tienen instrucciones de trabajo en cada estación. Los hospitales tienen protocolos para cada tipo de atención. En todos los casos, la idea es la misma que en Tortas Lupita: **que la calidad no dependa de quién esté ese día**.

## La segunda sucursal
Antes de abrir la segunda sucursal, Toño y el jefe de cocina escriben 15 procedimientos clave: las 5 recetas, apertura, cierre, caja, recepción de mercancía, limpieza, manejo de quejas, pedidos de oficinas, uso de la plancha y del gas, manejo higiénico de alimentos y entrega a domicilio. El nuevo equipo se capacita con ellos durante una semana en la primera sucursal. El día de la apertura, las tortas saben igual.`,
k: `**Procedimiento estándar (SOP):** cómo se hace una tarea, paso a paso, la haga quien la haga. Partes: objetivo, responsable, materiales, **pasos numerados**, **puntos críticos**, criterio de terminado, fotos y versión. Empieza por las tareas que afectan al cliente, tienen riesgo o generan errores. El conjunto forma el **manual de operación**, clave para crecer.`,
ch: `Una paletería escribe la receta exacta de cada sabor con fotos y gramos. Cuando la dueña se enferma, su sobrino produce las paletas igual que siempre.`,
gi: `Las cadenas hoteleras de lujo, como Ritz-Carlton, son conocidas por sus estándares de servicio escritos, que los empleados aprenden y repasan con frecuencia para ofrecer la misma experiencia en hoteles de todo el mundo.`,
e: `Toño mide el efecto de los procedimientos en la capacitación del equipo de la segunda sucursal:

| Indicador | Primera sucursal (sin procedimientos) | Segunda sucursal (con procedimientos) |
|---|---|---|
| Días de capacitación por cocinero | 15 | 5 |
| Variación en el peso de las tortas | ± 60 g | ± 15 g |
| Quejas en el primer mes | 52 | 14 |
| Tiempo promedio de preparación en el primer mes | 4.8 min | 3.4 min |

Los procedimientos permitieron replicar el negocio con calidad desde el primer día.`,
r: `Ritz-Carlton es conocida por sus «Gold Standards», un conjunto de estándares escritos de servicio que incluyen su credo y sus valores de servicio, que la cadena usa en la capacitación de sus empleados y en reuniones diarias de cada hotel.`,
f: `The Ritz-Carlton Hotel Company, «Gold Standards» (ritzcarlton.com).`,
err: ["Escribir procedimientos que nadie puede seguir sin preguntar.","Hacerlos sin consultar a quien hace la tarea.","Guardarlos en una carpeta lejos de donde se trabaja.","No actualizarlos cuando el proceso cambia."],
a: `Escribe el procedimiento de una tarea importante del negocio que observas (o de una tarea de tu casa, como preparar un platillo), con la estructura de esta lección. Pide a alguien que lo siga sin ayuda y anota dónde se atoró.`,
sol: `Donde la otra persona se atoró, falta un paso, una cantidad o una foto. Corrige y vuelve a probar.`,
q: [["Un procedimiento estándar de operación describe…",["Cómo se hace una tarea, paso a paso","Las ventas del mes","El organigrama"],0,"La haga quien la haga."],
["¿Qué tareas conviene documentar primero?",["Las que afectan al cliente, tienen riesgo o generan errores","Las que nunca se hacen","Ninguna"],0,"Son las de mayor impacto."],
["¿Cómo se comprueba que un procedimiento es claro?",["Pidiendo a una persona nueva que lo siga sin ayuda","Leyéndolo el dueño","Guardándolo"],0,"Donde se atore, falta claridad."],
["El conjunto de procedimientos de un negocio forma su…",["Manual de operación","Estado de resultados","Acta constitutiva"],0,"Es clave para abrir sucursales o franquicias."]],
t: ["Procedimiento estándar de operación (SOP)", "Manual de operación"]
}
});
// ===== M10. Compras y proveedores =====
Object.assign(window.LECC, {
"M10-1": {
s: `Toño compra «a ojo»: va al mercado, ve qué está barato y regresa con lo que cree que hace falta. Algunos días sobra queso y falta jamón; otros paga más caro porque se le olvidó pedir a tiempo. Lupita le propone convertir las compras en un proceso.`,
o: ["Describir la función de compras y su impacto en la utilidad.","Conocer los cinco «correctos» de una buena compra.","Seguir el ciclo de compra, de la necesidad al pago."],
x: `## ¿Qué hace el área de compras?
El área de **compras** (también llamada abastecimiento o adquisiciones) se encarga de conseguir todo lo que el negocio necesita para operar: insumos, mercancía, empaques, equipo, servicios. Su trabajo no es solo «ir a comprar», sino **comprar bien**: lo correcto, en la cantidad, el momento y el precio adecuados, al proveedor adecuado.

En un changarro, compra el dueño. En una pyme, un encargado de compras o el gerente de operaciones. En una gran empresa, una dirección de compras con compradores especializados por categoría (carnes, empaques, tecnología, servicios) que negocian contratos por millones.

## Por qué las compras importan tanto
En muchos negocios, lo que se compra es el **costo más grande**. En Tortas Lupita, los ingredientes y empaques son el 40 % de las ventas; en un supermercado, la mercancía es alrededor de tres cuartas partes. Por eso, un pequeño ahorro en compras tiene un efecto enorme en la utilidad.

Ejemplo: Tortas Lupita vende 216,000 pesos al mes y su utilidad de operación es de 39,600 (lección M8-2). Si compras logra un ahorro de 5 % en ingredientes (86,400 × 5 % = 4,320 pesos), la utilidad de operación sube 11 %. Para lograr lo mismo vendiendo más, tendría que vender unas 180 tortas extra al mes. A veces es más fácil ahorrar que vender.

## Los cinco «correctos» de una buena compra
Una forma clásica de resumir el trabajo de compras es que debe lograr:
1. **El producto correcto:** con la calidad y especificaciones necesarias (ni más caro de lo necesario, ni de menor calidad).
2. **La cantidad correcta:** ni tanto que sobre y se desperdicie, ni tan poco que falte (lecciones M9-5 y M9-6).
3. **El momento correcto:** que llegue cuando se necesita, ni antes ni después.
4. **El precio correcto:** el mejor costo total, no solo el precio más bajo (lección M10-3).
5. **El proveedor correcto:** confiable, que cumpla y con quien se pueda trabajar a largo plazo (lección M10-2).

## El ciclo de compra
Aunque en un negocio pequeño todo pase en una llamada, una compra tiene siempre los mismos pasos:
1. **Necesidad (requisición):** alguien detecta que falta algo (el inventario llegó al punto de reorden) y lo pide.
2. **Búsqueda y cotización:** se consulta a uno o varios proveedores (precio, plazo, condiciones).
3. **Selección:** se elige al proveedor.
4. **Orden de compra:** se confirma por escrito qué se compra, cuánto, a qué precio y cuándo se entrega (lección M10-5).
5. **Recepción:** se recibe la mercancía y se revisa que esté completa y en buen estado.
6. **Factura:** el proveedor entrega su factura.
7. **Pago:** se paga según lo acordado.
8. **Evaluación:** se registra si el proveedor cumplió (para futuras decisiones).

Saltarse pasos es la causa de muchos problemas: compras duplicadas, mercancía que llega incompleta y se paga completa, precios distintos a los acordados, facturas que nadie revisa.

## Separar funciones: control y honestidad
En un negocio que crece, conviene que **no sea la misma persona** la que pide, compra, recibe y paga. Si una sola persona hace todo, es fácil que se cometan errores sin que nadie los note (o que alguien pague mercancía que nunca llegó). Una práctica básica de control interno (Módulo 17) es separar:
- Quien **pide** (el jefe de cocina).
- Quien **compra** (el encargado de compras).
- Quien **recibe** (el encargado del turno).
- Quien **autoriza el pago** (la administradora o Lupita).

En un negocio muy pequeño no siempre es posible, pero al menos el dueño debe revisar periódicamente las compras.

## Tipos de compras
- **Compras recurrentes:** lo que se compra todos los días o semanas (pan, carne, verduras). Se negocian condiciones fijas con proveedores estables.
- **Compras ocasionales:** lo que se compra de vez en cuando (un ventilador, uniformes). Se cotiza cada vez.
- **Compras de inversión:** equipo y mejoras grandes (un horno, una remodelación). Se comparan varias opciones con cuidado y se piensa en el costo total durante su vida útil.
- **Servicios:** contador, mantenimiento, limpieza, fumigación, seguridad.

## Compras en una empresa gigante
Las grandes empresas tienen un enorme **poder de compra**: como compran volúmenes gigantes, consiguen precios y condiciones que un negocio pequeño no puede obtener. Walmart, por ejemplo, es conocido por usar su escala para negociar precios bajos con sus proveedores, que luego traslada en parte a sus clientes. También tienen sistemas que generan órdenes de compra automáticas, contratos anuales con proveedores, auditorías de calidad en las fábricas de sus proveedores y políticas de ética para evitar sobornos. Pero hacen lo mismo que debería hacer Tortas Lupita: comprar lo correcto, en la cantidad, el momento y el precio adecuados, al proveedor adecuado.

## Cómo pueden comprar mejor los negocios chicos
Aunque no tengan el poder de una cadena, los negocios pequeños pueden mejorar sus compras:
- **Planear** con base en las ventas esperadas, no «a ojo».
- **Concentrar** compras en menos proveedores para tener más volumen con cada uno.
- **Comprar en grupo** con otros negocios (algunas asociaciones y cámaras organizan compras conjuntas).
- **Negociar** condiciones, no solo precio: plazo de pago, entregas, devoluciones.
- **Revisar** cada entrega y cada factura.

## El nuevo proceso de Toño
Toño crea una lista semanal de compras basada en las ventas esperadas y los puntos de reorden, pide cotización a dos proveedores por insumo importante, confirma cada pedido por WhatsApp con cantidades y precios (como orden de compra sencilla), revisa cada entrega con la lista y entrega las facturas a la administradora, que paga solo lo recibido. En el primer mes, el gasto en ingredientes baja 4 % sin cambiar las recetas.`,
k: `**Compras:** conseguir lo que el negocio necesita, **comprando bien**. Cinco correctos: **producto, cantidad, momento, precio y proveedor**. Ciclo: necesidad → cotización → selección → **orden de compra** → recepción → factura → pago → evaluación. **Separa funciones** (quien pide, compra, recibe y paga). Un pequeño ahorro en compras puede valer más que muchas ventas.`,
ch: `Tres fondas de un mercado se ponen de acuerdo para comprar juntas el aceite y el gas; al pedir el triple, consiguen un mejor precio y entregas a domicilio.`,
gi: `Walmart es conocido por su capacidad de negociación con proveedores gracias a su escala; su área de compras negocia con miles de empresas en todo el mundo.`,
e: `Lupita compara el efecto en la utilidad de ahorrar en compras frente a vender más:

| Acción | Cálculo | Efecto en la utilidad de operación |
|---|---|---|
| Ahorrar 5 % en ingredientes | 86,400 × 5 % | +4,320 al mes |
| Vender más con el mismo margen de 24 pesos | 4,320 ÷ 24 | Haría falta vender 180 tortas extra al mes |

Ahorrar 5 % en compras equivale a vender 180 tortas más. Ambas cosas valen la pena, pero la primera suele ser más rápida.`,
r: `En la literatura sobre comercio minorista se ha estudiado cómo grandes cadenas como Walmart usan su volumen de compra para obtener mejores condiciones de sus proveedores. Libros como «The Wal-Mart Effect» (Charles Fishman, 2006) describen el impacto de este poder de compra en proveedores e industrias enteras.`,
f: `Charles Fishman, «The Wal-Mart Effect» (2006); Walmart Inc., informe anual.`,
err: ["Comprar «a ojo», sin planear.","Elegir siempre el precio más bajo sin mirar el costo total.","Que una sola persona pida, compre, reciba y pague sin revisión.","No revisar las entregas ni las facturas."],
a: `Dibuja el ciclo de compra de un insumo importante del negocio que observas. Identifica qué pasos se saltan y propón cómo incluirlos sin complicar el día a día.`,
sol: `En negocios pequeños, una orden de compra puede ser un mensaje con cantidad, precio y fecha; la revisión de la entrega, una lista firmada por quien recibe.`,
q: [["¿Cuál de estos NO es uno de los cinco «correctos» de una compra?",["El color correcto del local","La cantidad correcta","El proveedor correcto"],0,"Son producto, cantidad, momento, precio y proveedor."],
["Si los ingredientes son 86,400 al mes, un ahorro de 5 % equivale a…",["4,320 pesos","8,640 pesos","432 pesos"],0,"86,400 × 0.05."],
["¿Por qué conviene separar quién compra y quién paga?",["Para tener control y evitar errores o fraudes","Para tardar más","Porque lo exige el cliente"],0,"Es una práctica de control interno."],
["La orden de compra sirve para…",["Confirmar por escrito qué se compra, cuánto, a qué precio y cuándo","Cobrar a los clientes","Contratar personal"],0,"Evita malentendidos con el proveedor."]],
t: ["Compras", "Ciclo de compra"]
},
"M10-2": {
s: `La panadería de siempre a veces llega tarde y el pan sale duro algunos días. Dos panaderías nuevas ofrecen surtirle a Tortas Lupita. Una es más barata; la otra, más cara pero muy puntual. ¿Cómo elegir sin dejarse llevar solo por el precio?`,
o: ["Definir los criterios para elegir proveedores.","Construir una matriz de evaluación ponderada.","Evaluar a los proveedores de forma periódica."],
x: `## Elegir proveedores: una decisión importante
Un proveedor es, en la práctica, una extensión del negocio: si falla, el negocio falla frente a su cliente. Si el pan llega tarde, la torta llega tarde; si la carne no es buena, la torta no es buena. Por eso elegir proveedores es una de las decisiones más importantes de operaciones, y no debería basarse solo en el precio.

## Los criterios más comunes
| Criterio | Pregunta |
|---|---|
| Precio | ¿Cuánto cuesta? ¿Hay descuentos por volumen? |
| Calidad | ¿El producto cumple las especificaciones siempre? |
| Puntualidad | ¿Entrega a tiempo y completo? |
| Condiciones de pago | ¿Da crédito? ¿A cuántos días? |
| Servicio | ¿Responde rápido? ¿Resuelve problemas? ¿Acepta devoluciones? |
| Capacidad | ¿Puede surtir si el negocio crece? |
| Ubicación | ¿Qué tan cerca está? ¿Cuánto cuesta el flete? |
| Estabilidad | ¿Es un negocio sólido? ¿Lleva años operando? |
| Cumplimiento | ¿Factura? ¿Cumple normas sanitarias y fiscales? |
| Valores | ¿Trata bien a sus trabajadores? ¿Cuida el ambiente? |

No todos los criterios pesan igual para todos los insumos. Para el pan, la puntualidad y la frescura son críticas; para las servilletas, el precio pesa más.

## La matriz de evaluación ponderada
Para comparar proveedores de forma objetiva, se usa una **matriz de evaluación ponderada**:
1. **Elige los criterios** importantes para ese insumo.
2. **Asigna un peso** a cada criterio según su importancia; los pesos suman 100 %.
3. **Califica** a cada proveedor en cada criterio (por ejemplo, del 1 al 5).
4. **Multiplica** cada calificación por su peso.
5. **Suma** los resultados: el proveedor con el puntaje más alto es, en principio, el mejor.

Matriz para elegir panadería:

| Criterio | Peso | Panadería actual | Panadería A (barata) | Panadería B (puntual) |
|---|---|---|---|---|
| Precio | 25 % | 3 | 5 | 3 |
| Calidad y frescura | 30 % | 3 | 3 | 5 |
| Puntualidad | 25 % | 2 | 3 | 5 |
| Crédito | 10 % | 4 | 2 | 3 |
| Servicio | 10 % | 3 | 3 | 4 |
| **Puntaje ponderado** | **100 %** | **2.85** | **3.40** | **4.20** |

Cálculo para la Panadería B: 3 × 0.25 + 5 × 0.30 + 5 × 0.25 + 3 × 0.10 + 4 × 0.10 = 0.75 + 1.50 + 1.25 + 0.30 + 0.40 = **4.20**.

Aunque la Panadería A es la más barata, la B obtiene el mejor puntaje porque gana en lo que más importa para el pan: calidad y puntualidad.

## Cómo obtener la información
- **Pide muestras** y pruébalas.
- **Haz una prueba** de una o dos semanas antes de cambiar del todo.
- **Pide referencias** a otros clientes del proveedor.
- **Visita sus instalaciones** si es posible (limpieza, organización).
- **Revisa su formalidad:** constancia de situación fiscal, permisos sanitarios.
- **Consulta tu historial:** si ya es tu proveedor, revisa cuántas veces llegó tarde o con faltantes.

## Evaluar a los proveedores con regularidad
Elegir no es una decisión de una sola vez. Conviene evaluar a los proveedores principales **cada cierto tiempo** (cada mes o trimestre) con indicadores sencillos:
- Porcentaje de entregas a tiempo.
- Porcentaje de entregas completas.
- Número de rechazos por calidad.
- Cambios de precio.
- Tiempo de respuesta ante problemas.

Y compartir los resultados con el proveedor: un buen proveedor quiere saber cómo mejorar.

## ¿Cuántos proveedores?
Hay un equilibrio:
- **Un solo proveedor por insumo:** más volumen, mejor relación y a veces mejor precio, pero mucho riesgo si falla (lección M10-6).
- **Muchos proveedores:** menos riesgo, pero menos volumen con cada uno, más trabajo administrativo y relaciones más débiles.

Para insumos críticos, muchas empresas eligen un **proveedor principal** (que recibe la mayor parte de los pedidos) y un **proveedor de respaldo** (que recibe una parte pequeña, para mantener la relación activa y poder crecer si el principal falla).

## Proveedores en empresas gigantes
Las grandes empresas tienen procesos formales para **calificar** a sus proveedores antes de comprarles: cuestionarios, auditorías de calidad, revisión financiera, cumplimiento de normas laborales y ambientales. Algunas, como las armadoras de autos, clasifican a sus proveedores por niveles y les exigen certificaciones de calidad. Toyota, por ejemplo, es conocida por trabajar con sus proveedores a largo plazo y ayudarles a mejorar sus procesos, en lugar de cambiarlos a la primera falla.

## La decisión de Lupita
Con la matriz, Lupita elige a la Panadería B como proveedor principal (80 % del pan) y mantiene a la panadería actual como respaldo (20 %). Además, acuerda con la Panadería B revisar cada mes la puntualidad y la frescura. El pan cuesta un poco más que con la Panadería A, pero las quejas por pan duro desaparecen y la cocina deja de esperar por las mañanas.

## Cómo despedirse de un proveedor
A veces la evaluación muestra que hay que dejar a un proveedor. Conviene hacerlo con orden y respeto: hablar primero de los problemas y dar una oportunidad de mejorar; si no mejora, avisar con tiempo, pagar todo lo pendiente y terminar en buenos términos. El mundo de los negocios es pequeño, y un proveedor que hoy no conviene puede ser el respaldo de mañana. Además, cambiar de proveedor de golpe, sin una prueba previa del nuevo, es uno de los errores más comunes: primero se prueba al nuevo con una parte de las compras y, cuando cumple, se aumenta su participación.`,
k: `Elige proveedores con varios criterios: **precio, calidad, puntualidad, crédito, servicio, capacidad**, etc. **Matriz ponderada:** pesos que suman 100 %, calificación de 1 a 5, multiplicar y sumar. Pide muestras, haz pruebas y **evalúa periódicamente** (entregas a tiempo, completas, rechazos). Para insumos críticos: **principal + respaldo**.`,
ch: `Una estética elige proveedor de tintes con una matriz: calidad 40 %, precio 30 %, entrega 20 %, crédito 10 %. Gana el distribuidor que no es el más barato, pero cuyos tintes dan resultados constantes.`,
gi: `Las armadoras de autos califican a sus proveedores con auditorías y certificaciones de calidad, y muchas trabajan con ellos durante años, ayudándoles a mejorar sus procesos.`,
e: `Toño verifica el puntaje de cada panadería, criterio por criterio:

| Criterio | Peso | Actual | A (barata) | B (puntual) |
|---|---|---|---|---|
| Precio | 0.25 | 3 × 0.25 = 0.75 | 5 × 0.25 = 1.25 | 3 × 0.25 = 0.75 |
| Calidad | 0.30 | 3 × 0.30 = 0.90 | 3 × 0.30 = 0.90 | 5 × 0.30 = 1.50 |
| Puntualidad | 0.25 | 2 × 0.25 = 0.50 | 3 × 0.25 = 0.75 | 5 × 0.25 = 1.25 |
| Crédito | 0.10 | 4 × 0.10 = 0.40 | 2 × 0.10 = 0.20 | 3 × 0.10 = 0.30 |
| Servicio | 0.10 | 3 × 0.10 = 0.30 | 3 × 0.10 = 0.30 | 4 × 0.10 = 0.40 |
| **Total** | **1.00** | **2.85** | **3.40** | **4.20** |

La Panadería B gana con claridad. Repetir las cuentas antes de decidir evita que un error de suma cambie la elección.`,
r: `Toyota es conocida por su relación de largo plazo con sus proveedores principales, a quienes apoya con mejora de procesos. Jeffrey Liker, en «Las claves del éxito de Toyota», describe cómo la empresa evalúa y desarrolla a sus proveedores en lugar de cambiarlos solo por precio.`,
f: `Jeffrey K. Liker, «The Toyota Way» (2004).`,
err: ["Elegir solo por precio.","Usar los mismos pesos para todos los insumos.","Cambiar de proveedor sin una prueba.","No volver a evaluar al proveedor después de elegirlo."],
a: `Haz una matriz de evaluación ponderada para elegir un proveedor de un insumo del negocio que observas (o un servicio para tu casa, como internet). Usa al menos cuatro criterios y tres opciones.`,
sol: `Revisa que los pesos sumen 100 % y repite el cálculo de cada proveedor dos veces; un error de suma puede cambiar la decisión.`,
q: [["En una matriz de evaluación ponderada, los pesos deben sumar…",["100 %","50 %","Lo que sea"],0,"Representan la importancia relativa de cada criterio."],
["Si un proveedor obtiene 4 en un criterio con peso de 30 %, su resultado en ese criterio es…",["1.2","4.3","0.4"],0,"4 × 0.30."],
["Para insumos críticos, muchas empresas eligen…",["Un proveedor principal y uno de respaldo","Siempre el más barato","Diez proveedores iguales"],0,"Equilibra relación y riesgo."],
["Un indicador para evaluar proveedores es…",["Porcentaje de entregas a tiempo","Número de empleados del cliente","Color del camión"],0,"Mide su puntualidad."]],
t: ["Proveedor", "Matriz de evaluación ponderada"]
},
"M10-3": {
s: `Un proveedor de carne ofrece el kilo de jamón a 140 pesos; otro, a 150. Toño elige el de 140. A fin de mes descubre que el barato cobra flete, exige comprar 30 kilos mínimo y su jamón rinde menos porque tiene más agua. ¿Cuál era realmente más barato?`,
o: ["Pedir cotizaciones comparables.","Calcular el costo total de una compra.","Comparar ofertas con distintas condiciones."],
x: `## El precio no es el costo
El **precio** es lo que dice la cotización. El **costo total** es lo que realmente le cuesta al negocio tener ese producto listo para usar. Muchas veces, el proveedor con el precio más bajo no es el más barato cuando se suman todos los costos. Comprar bien exige comparar **costos totales**, no solo precios.

## Pedir cotizaciones comparables
Para comparar, las cotizaciones deben referirse a lo mismo. Comparar «manzanas con manzanas» significa pedir a todos los proveedores:
- La **misma especificación:** tipo de producto, marca o calidad, presentación, tamaño.
- La **misma cantidad** o la misma frecuencia de compra.
- El **precio con y sin IVA**.
- El **costo de flete** o si la entrega está incluida.
- El **pedido mínimo**.
- El **plazo de entrega**.
- Las **condiciones de pago** (contado, crédito a cuántos días).
- La **política de devoluciones** y garantía.
- La **vigencia** de la cotización (cuánto tiempo respeta el precio).

Una tabla sencilla con estas columnas permite ver las diferencias de un vistazo.

## Los componentes del costo total
Además del precio, el costo total puede incluir:
1. **Flete o envío.**
2. **Rendimiento:** cuánto del producto realmente se usa (un jamón con más agua rinde menos porciones; una fruta con más merma deja menos producto útil).
3. **Pedido mínimo:** si obliga a comprar más de lo necesario, hay más dinero detenido y riesgo de merma.
4. **Costo financiero:** pagar de contado frente a pagar a 15 o 30 días tiene un valor (el dinero cuesta).
5. **Calidad:** rechazos, devoluciones, productos defectuosos, quejas de clientes.
6. **Tiempo administrativo:** ir a recogerlo, hacer más pedidos, resolver problemas.
7. **Confiabilidad:** el costo de quedarse sin producto si el proveedor falla.

## El caso del jamón
Toño rehace la comparación con todos los costos, por cada kilo **útil** de jamón:

| Concepto | Proveedor barato | Proveedor caro |
|---|---|---|
| Precio por kilo | 140 | 150 |
| Flete (500 pesos por pedido de 30 kg) | 16.67 | Incluido (0) |
| Rendimiento (porciones útiles por kilo) | 15 | 16.5 |
| Pedido mínimo | 30 kg | 10 kg |
| Merma por exceso de pedido (estimada) | 3 % → 4.70 | 0 |
| Crédito | Contado | 15 días |
| **Costo por kilo entregado y con merma** | **161.37** | **150.00** |
| **Costo por porción** | **10.76** | **9.09** |

El jamón «barato» en realidad cuesta **18 % más por porción**. Además, el proveedor caro da 15 días de crédito, lo que ayuda al flujo de efectivo.

## El costo total de propiedad
Para compras de equipo, el concepto equivalente es el **costo total de propiedad**: lo que cuesta un equipo durante toda su vida útil, no solo su precio de compra. Incluye:
- Precio de compra e instalación.
- Consumo de energía (gas, luz).
- Mantenimiento y refacciones.
- Tiempo sin funcionar por descomposturas.
- Vida útil.
- Valor de reventa al final.

Una plancha barata que consume más gas y se descompone cada año puede salir mucho más cara que una plancha de mejor calidad.

Ejemplo de dos planchas a 5 años:

| Concepto | Plancha A | Plancha B |
|---|---|---|
| Precio | 9,000 | 15,000 |
| Gas al año | 18,000 | 14,400 |
| Mantenimiento al año | 1,500 | 600 |
| Vida útil | 3 años (hay que comprar otra) | 6 años |
| Costo en 5 años | 9,000 × 2 + (18,000 + 1,500) × 5 = 115,500 | 15,000 + (14,400 + 600) × 5 = 90,000 |

La plancha B, aunque cuesta 6,000 pesos más, ahorra 25,500 pesos en cinco años.

## Cuidado con el valor del dinero en el tiempo
Cuando una opción se paga de contado y otra a plazo, o cuando los ahorros llegan durante varios años, conviene recordar que **un peso hoy vale más que un peso dentro de un año** (porque se puede invertir o porque evita pedir prestado). Para decisiones grandes se usan herramientas como el valor presente (Módulo 17); para compras del día a día, basta con considerar el beneficio del crédito.

## Las compras públicas y grandes
En las empresas grandes y en el gobierno, las compras importantes se hacen mediante **licitaciones** o concursos: se publican las especificaciones, varios proveedores presentan propuestas y se elige con criterios definidos de antemano (precio, calidad, experiencia, plazo). Esto busca comparar de forma justa y transparente y reducir el riesgo de corrupción. La lógica es la misma que la de Toño: especificaciones iguales para todos y comparación del costo total.

## La lección
Toño ahora usa una hoja de comparación con todas las condiciones para cada insumo importante y calcula el **costo por porción útil**, no solo el precio por kilo. Regresa con el proveedor de 150 pesos y negocia: si le compra también el queso, le deja el jamón en 146.

## Una hoja de comparación sencilla
Para el día a día, basta con una hoja de cálculo con una fila por proveedor y columnas para precio, flete, pedido mínimo, rendimiento, crédito, calidad y costo por unidad útil. Actualizarla cada vez que llega una cotización nueva evita decidir de memoria y permite ver cómo cambian los costos de cada proveedor con el tiempo.`,
k: `**Precio ≠ costo total.** Pide cotizaciones **comparables** (misma especificación, cantidad, IVA, flete, mínimo, plazo, crédito). El costo total incluye flete, **rendimiento**, pedido mínimo y merma, costo financiero, calidad y confiabilidad. En equipos: **costo total de propiedad** durante su vida útil.`,
ch: `Una fonda compara dos proveedores de tortillas: el más barato entrega tortillas que se rompen y obliga a usar 15 % más. El más caro sale más barato por taco servido.`,
gi: `Las empresas grandes y los gobiernos usan licitaciones con especificaciones iguales para todos los proveedores y criterios de evaluación definidos antes de recibir las propuestas.`,
e: `Toño verifica el cálculo del costo por porción del jamón barato:

| Paso | Cálculo | Resultado |
|---|---|---|
| Flete por kilo | 500 ÷ 30 | 16.67 |
| Precio + flete | 140 + 16.67 | 156.67 |
| Merma de 3 % | 156.67 × 0.03 | 4.70 |
| Costo por kilo | 156.67 + 4.70 | 161.37 |
| Costo por porción | 161.37 ÷ 15 | 10.76 |

Y del jamón caro: 150 ÷ 16.5 = 9.09 por porción. Con 5,400 tortas al mes, la diferencia es de unos 9,000 pesos mensuales.`,
r: `En México, las compras del gobierno federal se rigen por la Ley de Adquisiciones, Arrendamientos y Servicios del Sector Público, que establece procedimientos como la licitación pública para promover la competencia y la transparencia entre proveedores.`,
f: `Ley de Adquisiciones, Arrendamientos y Servicios del Sector Público (México); plataforma de compras públicas del gobierno federal.`,
err: ["Comparar precios con condiciones distintas.","Olvidar el flete, el pedido mínimo o el rendimiento.","Comprar equipo barato sin considerar su consumo y su vida útil.","No considerar el valor del crédito del proveedor."],
a: `Pide (o investiga en internet) el precio de un mismo producto en tres lugares distintos, con sus condiciones (envío, mínimo, forma de pago). Calcula el costo total por unidad útil y decide cuál conviene.`,
sol: `Si un lugar tiene envío gratis solo por encima de cierto monto, calcula cuánto tendrías que comprar y si te sobraría producto.`,
q: [["¿Por qué el precio más bajo puede no ser el más barato?",["Porque hay costos adicionales: flete, merma, rendimiento, mínimos","Porque el IVA es distinto siempre","Porque los proveedores mienten"],0,"Hay que comparar el costo total."],
["Comparar «manzanas con manzanas» significa…",["Pedir cotizaciones con la misma especificación y condiciones","Comprar solo manzanas","Elegir al azar"],0,"Así las ofertas son comparables."],
["El costo total de propiedad de un equipo incluye…",["Precio, energía, mantenimiento, vida útil y reventa","Solo el precio","Solo el IVA"],0,"Todo lo que cuesta durante su vida útil."],
["Si un kilo cuesta 150 y rinde 15 porciones, cada porción cuesta…",["10 pesos","15 pesos","150 pesos"],0,"150 ÷ 15."]],
t: ["Cotización", "Costo total"]
},
"M10-4": {
s: `El proveedor de pan anuncia que subirá el precio 15 %. Toño está molesto y quiere amenazarlo con cambiarse. Lupita lo detiene: «Antes de pelear, preparemos la negociación». ¿Cómo se negocia bien con un proveedor?`,
o: ["Preparar una negociación con información, objetivos y alternativas.","Usar los conceptos de MAAN y zona de acuerdo.","Negociar por intereses y buscar acuerdos de beneficio mutuo."],
x: `## Negociar: una habilidad de todos los días
**Negociar** es buscar un acuerdo entre dos o más partes que tienen intereses en parte comunes y en parte distintos. En un negocio se negocia todo el tiempo: precios con proveedores, plazos de pago, condiciones con clientes, sueldos, rentas, créditos. Negociar bien no es «ganarle» al otro, sino lograr un acuerdo que convenga y que se pueda sostener en el tiempo.

## El enfoque de Harvard
En 1981, Roger Fisher y William Ury, del Proyecto de Negociación de la Universidad de Harvard, publicaron «Obtenga el sí», uno de los libros de negociación más influyentes. Propusieron la **negociación basada en principios**, con cuatro ideas:
1. **Separar a las personas del problema:** se puede ser firme con el problema y respetuoso con la persona.
2. **Concentrarse en los intereses, no en las posiciones:** la posición es lo que alguien pide («quiero subir 15 %»); el interés es por qué lo pide («subió la harina y mi margen ya no alcanza»). Atender los intereses abre más soluciones.
3. **Inventar opciones de beneficio mutuo:** antes de decidir, buscar varias soluciones que ayuden a ambos.
4. **Usar criterios objetivos:** precios de mercado, índices de inflación, costos documentados, en lugar de «porque sí».

## La preparación: la mitad de la negociación
La mayor parte del éxito de una negociación se decide **antes** de sentarse a hablar. Prepararse significa responder:
1. **¿Qué quiero lograr?** (objetivo ideal y mínimo aceptable).
2. **¿Qué quiere el otro y por qué?** (sus intereses).
3. **¿Qué información tengo?** (precios de mercado, mi historial de compras, cuánto represento para él).
4. **¿Qué puedo ofrecer que me cueste poco y a él le valga mucho?** (pagar antes, comprar más, comprometerme a largo plazo).
5. **¿Cuál es mi alternativa si no hay acuerdo?** (MAAN).

## El MAAN: tu mejor alternativa
El **MAAN** (mejor alternativa a un acuerdo negociado; en inglés, BATNA) es lo que harías si no llegas a un acuerdo. Es la fuente principal de **poder** en una negociación:
- Si tu MAAN es buena (otra panadería que te surte a buen precio), puedes negociar con más firmeza.
- Si tu MAAN es mala (no hay otra panadería en la zona), tienes menos poder y conviene ser más flexible.

Regla de oro: **nunca aceptes un acuerdo peor que tu MAAN**, y **mejora tu MAAN antes de negociar** (por ejemplo, pidiendo cotización a otros proveedores). También conviene pensar en el MAAN del otro: si a la panadería le costaría mucho perder a Tortas Lupita como cliente, su MAAN es débil.

## La zona de posible acuerdo
Cada parte tiene un límite:
- Para Lupita, el **precio máximo** que está dispuesta a pagar (por arriba de él, le conviene su MAAN).
- Para la panadería, el **precio mínimo** que está dispuesta a aceptar (por debajo, prefiere no venderle).

Si el mínimo del vendedor es menor que el máximo del comprador, existe una **zona de posible acuerdo**. Cualquier precio dentro de esa zona es mejor para ambos que no llegar a un acuerdo. La negociación decide en qué punto de esa zona se cierra.

## Las concesiones
En casi toda negociación hay concesiones (cosas que cada parte cede). Algunas reglas útiles:
- **No cedas sin recibir algo a cambio:** «Puedo aceptar un aumento si me das 15 días de crédito».
- **Empieza con margen:** si empiezas pidiendo exactamente lo que quieres, no tienes espacio para ceder.
- **Cede en lo que te importa menos** y defiende lo que te importa más.
- **Haz concesiones cada vez más pequeñas:** muestran que te acercas a tu límite.
- **Pon todo sobre la mesa:** precio, plazo, cantidad, entregas, calidad, duración del acuerdo. Negociar varias variables a la vez permite intercambios de beneficio mutuo.

## Variables que se pueden negociar con un proveedor
- Precio por unidad.
- Descuento por volumen.
- Plazo de pago (crédito).
- Descuento por pronto pago.
- Frecuencia y horario de entrega.
- Pedido mínimo.
- Calidad y especificaciones.
- Devoluciones y garantías.
- Duración del acuerdo y congelamiento de precios.
- Préstamo de equipo (refrigeradores, exhibidores).

## La negociación con la panadería
**Preparación de Lupita:**
- Objetivo ideal: aumento de 5 %; máximo aceptable: 10 %.
- Interés de la panadería: subió la harina 12 % y el gas; su margen bajó.
- Información: Tortas Lupita le compra 9,000 bolillos al mes, es uno de sus clientes más grandes y siempre paga puntual. Otra panadería ofrece un precio 8 % mayor al actual, con buena calidad (ese es el MAAN de Lupita).
- Qué puede ofrecer: un acuerdo de seis meses y pago semanal en lugar de quincenal.

**La conversación:** Lupita reconoce que los costos subieron (separa a la persona del problema), pregunta cuánto subió exactamente la harina (criterio objetivo) y propone: aumento de 7 % hoy, sin más aumentos durante seis meses, y pago semanal. La panadería acepta, porque asegura a un buen cliente y cobra más rápido.

Resultado: en lugar de 15 %, el aumento es de 7 %, la relación sigue fuerte y ambos saben qué esperar.

## Negociación en empresas gigantes
Las grandes empresas negocian contratos con proveedores por montos enormes y durante años. Usan equipos de compradores especializados, información de mercado, subastas en línea y contratos con cláusulas detalladas (ajustes por inflación, penalizaciones por incumplimiento). Pero los principios son los mismos: prepararse, conocer el MAAN, entender los intereses del otro y buscar acuerdos que se puedan sostener.`,
k: `**Negociación basada en principios** (Fisher y Ury, «Obtenga el sí», 1981): separar personas y problema, **intereses** sobre posiciones, opciones de beneficio mutuo, **criterios objetivos**. **MAAN** (mejor alternativa a un acuerdo negociado): tu fuente de poder; no aceptes nada peor. **Zona de posible acuerdo** entre los límites de ambos. **No cedas sin recibir algo a cambio.**`,
ch: `Un dueño de taller negocia con su proveedor de refacciones: en lugar de pedir descuento, ofrece pagar de contado a cambio de 4 % menos. El proveedor acepta porque mejora su flujo.`,
gi: `Las grandes cadenas negocian cada año con sus proveedores condiciones como precios, descuentos por volumen, espacio en anaqueles y aportaciones para promociones, en contratos muy detallados.`,
e: `Lupita calcula el efecto de la negociación (9,000 bolillos al mes a 3 pesos):

| Escenario | Precio por bolillo | Costo mensual | Diferencia frente al actual |
|---|---|---|---|
| Actual | 3.00 | 27,000 | — |
| Propuesta del proveedor (+15 %) | 3.45 | 31,050 | +4,050 |
| MAAN (otra panadería, +8 %) | 3.24 | 29,160 | +2,160 |
| Acuerdo (+7 %, fijo 6 meses) | 3.21 | 28,890 | +1,890 |

El acuerdo es mejor que su MAAN y le ahorra 2,160 pesos al mes frente a la propuesta inicial, además de la estabilidad de precio por seis meses.`,
r: `«Getting to Yes» («Obtenga el sí»), de Roger Fisher y William Ury (con Bruce Patton en ediciones posteriores), se publicó en 1981 como resultado del trabajo del Proyecto de Negociación de Harvard. El libro introdujo conceptos como el BATNA (en español, MAAN) y la negociación basada en intereses, hoy usados en negocios, diplomacia y mediación.`,
f: `Roger Fisher, William Ury y Bruce Patton, «Obtenga el sí: el arte de negociar sin ceder» (1981).`,
err: ["Negociar sin prepararse.","Pelear con la persona en lugar de resolver el problema.","No conocer tu MAAN ni mejorarlo antes de negociar.","Ceder sin recibir nada a cambio."],
a: `Prepara una negociación real o simulada (con un proveedor, un arrendador o un cliente): escribe tu objetivo ideal y mínimo, los intereses del otro, tu MAAN, el MAAN del otro y tres cosas que podrías ofrecer. Practícala con alguien que haga el otro papel.`,
sol: `Si no tienes MAAN (no hay alternativa), dedica tiempo a crear una antes de negociar: pide otras cotizaciones o piensa cómo podrías prescindir del producto.`,
q: [["Según Fisher y Ury, conviene concentrarse en…",["Los intereses, no en las posiciones","Ganar a toda costa","Las emociones del otro"],0,"El interés explica por qué se pide algo."],
["El MAAN es…",["Tu mejor alternativa si no hay acuerdo","El precio máximo del proveedor","Un impuesto"],0,"Es tu principal fuente de poder."],
["Una buena regla al hacer concesiones es…",["No ceder sin recibir algo a cambio","Ceder todo al principio","Nunca ceder"],0,"Así se construyen intercambios de beneficio mutuo."],
["Existe una zona de posible acuerdo cuando…",["El mínimo del vendedor es menor que el máximo del comprador","Ambos quieren lo mismo exactamente","No hay proveedores"],0,"Cualquier precio en esa zona es mejor que no acordar."]],
t: ["Negociación", "MAAN"]
},
"M10-5": {
s: `La carnicería entregó 25 kilos de jamón, pero facturó 30. Nadie lo notó y se pagó completo. Otra vez, el proveedor de empaques dijo que el precio «acordado» era otro. Lupita decide que todo debe quedar por escrito.`,
o: ["Usar órdenes de compra y contratos con proveedores.","Revisar entregas y facturas con la comparación de tres documentos.","Aprovechar y cuidar el crédito de los proveedores."],
x: `## Los papeles que te protegen
En los negocios pequeños, muchos acuerdos se hacen de palabra: «tráeme lo de siempre». Funciona mientras todo va bien, pero cuando hay un error o un desacuerdo, no hay forma de probar qué se acordó. Los documentos de compra no son burocracia: son una forma de **evitar errores, aclarar expectativas y protegerse**.

## La orden de compra
La **orden de compra** es un documento (puede ser un formato, un correo o un mensaje) que el comprador envía al proveedor para confirmar un pedido. Debe incluir:
- Fecha y número de orden.
- Datos del comprador y del proveedor.
- Producto (descripción clara), cantidad y unidad.
- Precio unitario y total (con y sin IVA).
- Fecha y lugar de entrega.
- Condiciones de pago.
- Datos para la factura.

En Tortas Lupita, la orden de compra puede ser un mensaje de WhatsApp con un formato fijo: «Orden 145 – 30 kg jamón de pierna a 146 + IVA – entrega martes 7:00 – pago a 15 días». Lo importante es que quede escrito y que el proveedor lo confirme.

## El contrato con proveedores
Para proveedores importantes y relaciones de largo plazo, conviene un **contrato** (o al menos un acuerdo escrito) que establezca:
- Productos y especificaciones de calidad.
- Precios y cómo se ajustan (por ejemplo, cada seis meses según la inflación).
- Volúmenes esperados.
- Plazos y horarios de entrega.
- Condiciones de pago y crédito.
- Qué pasa si hay faltantes, retrasos o productos defectuosos (devoluciones, descuentos, penalizaciones).
- Duración del acuerdo y cómo se termina.
- Confidencialidad (si aplica, por ejemplo, de una receta).

Para contratos importantes, conviene la revisión de un abogado (Módulo 14).

## La recepción de mercancía
Al recibir, alguien debe revisar **en el momento**, antes de firmar:
1. **Cantidad:** contar o pesar lo que llegó y compararlo con la orden de compra.
2. **Calidad:** frescura, temperatura (en carnes y lácteos), empaques sin daños, fechas de caducidad.
3. **Producto correcto:** que sea lo pedido y no un sustituto.
4. **Anotar diferencias** en la nota de remisión y en la bitácora; rechazar lo que no cumpla.
5. **Firmar** solo lo recibido realmente.

Una buena práctica es tener una **báscula en la recepción** y un horario fijo para recibir, fuera de la hora pico.

## La comparación de tres documentos
Antes de pagar, se comparan tres documentos:
1. **La orden de compra** (lo que se pidió y a qué precio).
2. **El comprobante de recepción** (lo que llegó realmente).
3. **La factura** (lo que cobra el proveedor).

Solo se paga si los tres coinciden. Si no coinciden, se aclara con el proveedor antes de pagar. A esta práctica se le conoce en inglés como *three-way match* y es una de las formas más sencillas y eficaces de evitar pagar de más, ya sea por error o por abuso.

En el caso del jamón: orden de 30 kg, recepción de 25 kg, factura de 30 kg. La comparación habría detectado la diferencia de 5 kg (unos 730 pesos) antes de pagar.

## El crédito de proveedores
El **crédito de proveedores** (pagar a 7, 15 o 30 días) es una de las fuentes de financiamiento más baratas y útiles para un negocio pequeño, porque normalmente no cobra intereses explícitos (lecciones M8-5 y M8-8). Para conseguirlo y conservarlo:
- **Paga siempre en la fecha acordada:** tu historial es tu mejor carta.
- **Concentra compras** con proveedores clave para ser un cliente importante.
- **Pide crédito** después de un periodo de compras de contado puntuales.
- **Avisa antes** si vas a tener un retraso; nunca desaparezcas.
- **No abuses:** pagar siempre tarde daña la relación y puede costar el crédito o un aumento de precio.

## Cuidado con el descuento por pronto pago
Si un proveedor ofrece, por ejemplo, 2 % de descuento por pagar de contado en lugar de a 30 días, conviene calcular si vale la pena: como viste en la lección M8-6, no aprovechar ese descuento equivale a pagar un costo anual muy alto por el crédito. Si tienes el efectivo, suele convenir tomar el descuento.

## Documentos y control interno
Los documentos de compra también sirven para el **control interno** (Módulo 17): permiten revisar quién pidió, quién autorizó, quién recibió y quién pagó, y detectar compras duplicadas, precios fuera de lo acordado o pagos por mercancía no recibida. En las empresas grandes, el sistema no permite pagar una factura que no coincida con una orden de compra y una recepción registradas.

## Lo que hace Tortas Lupita ahora
- Cada pedido se confirma con una orden por WhatsApp con formato fijo.
- La panadería, la carnicería y el proveedor de empaques firmaron un acuerdo de una página con precios, entregas y devoluciones.
- La recepción se hace de 6:30 a 7:15, con báscula y una lista.
- La administradora solo paga si coinciden la orden, la recepción firmada y la factura.
- Los pagos se hacen siempre el día acordado.

En el primer mes detectan dos diferencias en facturas por un total de 1,200 pesos, y el proveedor de empaques ya no puede «cambiar» el precio acordado.`,
k: `**Orden de compra:** confirma por escrito producto, cantidad, precio, entrega y pago. **Contrato** para proveedores importantes. **Recepción:** contar, pesar y revisar antes de firmar. **Comparación de tres documentos:** orden, recepción y factura deben coincidir antes de pagar. El **crédito de proveedores** se gana pagando siempre a tiempo.`,
ch: `Una tienda de abarrotes revisa cada entrega del repartidor de refrescos contra su pedido antes de firmar; una vez descubrió que le cobraban dos cajas que no le dejaron.`,
gi: `En las grandes empresas, los sistemas de compras no permiten liberar el pago de una factura si no coincide con la orden de compra y con la recepción registrada en el almacén.`,
e: `La administradora revisa tres facturas del mes:

| Proveedor | Orden de compra | Recepción | Factura | ¿Coinciden? | Acción |
|---|---|---|---|---|---|
| Panadería | 9,000 bolillos × 3.21 | 9,000 | 28,890 | Sí | Pagar |
| Carnicería | 30 kg × 146 | 25 kg | 30 kg (4,380) | No | Pedir nota de crédito por 5 kg (730) |
| Empaques | 5,000 bolsas × 0.40 | 5,000 | 5,000 × 0.49 (2,450) | No | Reclamar el precio acordado (2,000) |

Ahorro detectado en el mes: 730 + 450 = 1,180 pesos.`,
r: `La comparación de tres documentos (orden de compra, recepción y factura) es una práctica estándar de control en cuentas por pagar, recomendada en guías de control interno como el marco COSO, que muchas empresas usan para diseñar sus controles.`,
f: `COSO, «Control interno – Marco integrado» (2013); guías de auditoría sobre cuentas por pagar.`,
err: ["Hacer pedidos importantes solo de palabra.","Firmar la recepción sin contar ni revisar.","Pagar facturas sin compararlas con lo pedido y lo recibido.","Pagar tarde y perder el crédito del proveedor."],
a: `Diseña un formato de orden de compra para el negocio que observas (puede ser un mensaje con campos fijos) y una lista de verificación para recibir mercancía. Si tienes facturas reales, compara tres con lo pedido y lo recibido.`,
sol: `El formato debe caber en un mensaje: número, producto, cantidad, precio, fecha de entrega y condiciones de pago. La lista de recepción debe incluir cantidad, calidad y fechas.`,
q: [["La comparación de tres documentos revisa…",["Orden de compra, recepción y factura","Precio, IVA e ISR","Nombre, RFC y domicilio"],0,"Solo se paga si coinciden."],
["Al recibir mercancía, se debe firmar…",["Solo lo que realmente se recibió y revisó","Todo lo que dice la factura","Nada"],0,"Firmar sin revisar quita la posibilidad de reclamar."],
["¿Cómo se gana el crédito de un proveedor?",["Pagando siempre en la fecha acordada","Pagando tarde","Cambiando de proveedor cada mes"],0,"Tu historial es tu mejor carta."],
["Un contrato con un proveedor debe incluir…",["Precios, entregas, pagos y qué pasa si hay faltantes","Solo el nombre","El organigrama del cliente"],0,"Así se evitan malentendidos."]],
t: ["Orden de compra", "Recepción de mercancía"]
},
"M10-6": {
s: `Un lunes, la carnicería de siempre cierra por una inspección sanitaria. Tortas Lupita no tiene otro proveedor de jamón y pasa dos días vendiendo solo tortas de huevo y frijoles. Las ventas caen a la mitad. Lupita aprende la lección del proveedor único.`,
o: ["Identificar el riesgo de depender de un solo proveedor.","Evaluar qué tan crítico es cada insumo.","Diseñar estrategias para diversificar y reducir el riesgo."],
x: `## El riesgo del proveedor único
Depender de un **solo proveedor** para un insumo importante tiene ventajas: más volumen con él, mejor precio, relación cercana, menos trabajo administrativo. Pero también un gran riesgo: si ese proveedor falla (cierra, se retrasa, sube mucho el precio, tiene problemas de calidad, sufre un desastre), el negocio se queda sin el insumo. Y si el insumo es crítico, el negocio se detiene.

## Las causas de falla de un proveedor
- Problemas sanitarios o legales (una clausura).
- Problemas financieros (quiebra, falta de liquidez para producir).
- Desastres naturales o accidentes (incendio, inundación, sismo).
- Problemas de transporte (bloqueos, huelgas, falta de combustible).
- Escasez de su propia materia prima.
- Cambios de dueño o de política (deja de vender a clientes pequeños).
- Conflictos con el cliente (un desacuerdo que termina la relación).

## ¿Qué tan crítico es cada insumo?
No todos los insumos tienen el mismo riesgo. Una herramienta útil, inspirada en la **matriz de Kraljic** (propuesta por Peter Kraljic en Harvard Business Review en 1983), clasifica los insumos según dos preguntas:
1. **¿Qué tan importante es para el negocio?** (impacto en ventas, costo, calidad).
2. **¿Qué tan difícil es conseguirlo?** (pocos proveedores, productos especiales, tiempos de entrega largos).

| | Fácil de conseguir | Difícil de conseguir |
|---|---|---|
| **Muy importante** | **Apalancamiento:** negociar buen precio entre varios proveedores (pan, verduras) | **Estratégico:** relación cercana de largo plazo y plan de respaldo (jamón de cierta calidad, la receta del chile) |
| **Poco importante** | **Rutina:** simplificar y comprar fácil (servilletas, limpieza) | **Cuello de botella:** asegurar el abasto aunque cueste un poco más (una refacción especial de la plancha) |

Esta matriz ayuda a decidir dónde dedicar más atención: los insumos **estratégicos** y de **cuello de botella** necesitan planes de respaldo.

## Estrategias para reducir el riesgo
1. **Proveedor de respaldo:** tener un segundo proveedor aprobado al que se le compre una parte pequeña con regularidad, para que conozca el producto y esté listo si el principal falla (lección M10-2).
2. **Inventario de seguridad mayor** para los insumos más críticos y difíciles de conseguir (lección M9-6), siempre que no sean muy perecederos.
3. **Proveedores en distintas zonas:** si uno tiene un problema local, el otro puede seguir.
4. **Contratos con compromisos de abasto** y avisos anticipados de problemas.
5. **Especificaciones flexibles:** recetas o productos que permitan sustituir un insumo por otro parecido sin afectar mucho la calidad.
6. **Conocer a tus proveedores:** su salud financiera, sus permisos, sus propios proveedores.
7. **Plan de contingencia escrito:** qué hacer y a quién llamar si falla cada insumo crítico.

## Diversificar tiene un costo
Tener dos o tres proveedores para cada insumo crítico cuesta: menos volumen con cada uno (quizá un precio un poco mayor), más trabajo para administrar, más pruebas de calidad. Por eso la decisión es un **equilibrio** entre costo y riesgo. Para un insumo crítico, pagar un poco más por tener respaldo es como pagar un seguro.

## Un ejemplo clásico: el incendio de Aisin
En febrero de 1997, un incendio destruyó una fábrica de Aisin Seiki, el proveedor principal de una pequeña válvula de frenos que Toyota usaba en casi todos sus autos. Como Toyota trabajaba con muy poco inventario, sus líneas de producción en Japón se detuvieron en pocos días. Sin embargo, en cuestión de días, decenas de empresas de su red de proveedores, coordinadas con Aisin y Toyota, empezaron a fabricar la válvula con los planos de Aisin, y la producción se recuperó con relativa rapidez. El caso mostró dos cosas: el riesgo de depender de una sola fábrica y el valor de tener relaciones de confianza con una red de proveedores.

## La escasez de chips de 2021
Otro ejemplo reciente: en 2021, una escasez mundial de semiconductores (chips), provocada por una combinación de factores (la pandemia, el aumento de la demanda de aparatos electrónicos y problemas en algunas fábricas), obligó a muchas armadoras de autos en el mundo, incluidas plantas en México, a detener o reducir su producción. Muchas empresas revisaron después su dependencia de unos pocos proveedores y regiones.

## El plan de Tortas Lupita
Después de los dos días sin jamón, Lupita hace un plan:

| Insumo | Tipo (matriz) | Proveedor principal | Respaldo | Acción |
|---|---|---|---|---|
| Jamón y carnes | Estratégico | Carnicería A (80 %) | Carnicería B (20 %) | Comprar cada semana a ambas |
| Pan | Apalancamiento | Panadería B (80 %) | Panadería actual (20 %) | Ya implementado |
| Aguacate | Apalancamiento | Mercado | Dos puestos distintos | Comprar cada dos días |
| Gas | Cuello de botella | Gasera A | Gasera B con número a la mano | Tanque de reserva |
| Servilletas | Rutina | Distribuidor | Cualquier tienda mayorista | Compra mensual |

Además, escribe un plan de contingencia de una página que está pegado en la oficina. La próxima vez que la carnicería principal falla, al día siguiente llega el jamón de la carnicería B y nadie se entera.

## Revisar el riesgo cada año
La matriz no es fija: un insumo fácil de conseguir hoy puede volverse difícil mañana. Conviene revisarla al menos una vez al año.`,
k: `Depender de un **proveedor único** para un insumo crítico es un gran riesgo. Clasifica insumos por **importancia** y **dificultad para conseguirlos** (matriz de Kraljic: estratégico, apalancamiento, cuello de botella, rutina). Reduce el riesgo con **proveedor de respaldo**, inventario de seguridad, proveedores en distintas zonas, contratos y un **plan de contingencia**.`,
ch: `Una cafetería que dependía de un solo tostador de café se quedó sin grano una semana. Ahora compra el 70 % a su tostador principal y el 30 % a otro, y tiene una semana de inventario.`,
gi: `En 1997, un incendio en una fábrica de Aisin Seiki detuvo la producción de Toyota en Japón por falta de una válvula de frenos; la red de proveedores de Toyota se coordinó para fabricarla y la producción se recuperó en pocos días.`,
e: `Lupita estima el costo de quedarse sin jamón frente al costo del respaldo:

| Concepto | Cálculo | Resultado |
|---|---|---|
| Ventas perdidas en 2 días sin jamón | 2 × 4,000 | 8,000 |
| Margen perdido (60 %) | 8,000 × 0.6 | 4,800 |
| Clientes molestos que no regresan (estimado) | — | difícil de medir |
| Costo extra de comprar el 20 % a la carnicería B (precio 3 % mayor) | 28,000 × 20 % × 3 % | 168 al mes |

Pagar unos 170 pesos al mes por tener respaldo evita pérdidas de miles de pesos en un solo evento.`,
r: `El caso del incendio de Aisin Seiki en 1997 fue analizado por Toshihiro Nishiguchi y Alexandre Beaudet en el artículo «The Toyota Group and the Aisin Fire» (Sloan Management Review, 1998), como ejemplo de la capacidad de recuperación de una red de proveedores con relaciones de confianza.`,
f: `T. Nishiguchi y A. Beaudet, «The Toyota Group and the Aisin Fire», Sloan Management Review (1998); P. Kraljic, «Purchasing Must Become Supply Management», Harvard Business Review (1983).`,
err: ["Tener un solo proveedor para un insumo crítico.","Tener un proveedor de respaldo al que nunca se le compra.","No tener un plan escrito para emergencias.","Diversificar todo sin pensar en el costo."],
a: `Clasifica 8 insumos del negocio que observas con la matriz de importancia y dificultad. Para los insumos estratégicos o de cuello de botella, escribe quién es el proveedor principal, quién sería el respaldo y qué harías si el principal falla mañana.`,
sol: `Un plan de contingencia útil cabe en una hoja: insumo, proveedor de respaldo con teléfono, cantidad mínima y quién llama.`,
q: [["¿Cuál es el principal riesgo de un proveedor único?",["Quedarse sin el insumo si falla","Pagar menos","Tener demasiada calidad"],0,"El negocio puede detenerse."],
["En la matriz de Kraljic, un insumo muy importante y difícil de conseguir es…",["Estratégico","De rutina","De apalancamiento"],0,"Requiere relación cercana y respaldo."],
["¿Por qué conviene comprarle regularmente al proveedor de respaldo?",["Para que conozca el producto y esté listo si el principal falla","Para pagar más","No conviene"],0,"Un respaldo que nunca se usa no sirve en una emergencia."],
["El incendio de Aisin en 1997 afectó a…",["Toyota","Bimbo","Netflix"],0,"Detuvo su producción por falta de una válvula de frenos."]],
t: ["Proveedor único", "Matriz de Kraljic"]
},
"M10-7": {
s: `La panadería B le propone a Lupita algo nuevo: «Si me compartes cada semana cuántas tortas esperas vender, puedo planear mi producción y garantizarte el pan más fresco». Lupita descubre que con sus proveedores no solo compra: forma una cadena.`,
o: ["Explicar qué es la cadena de suministro.","Reconocer el valor de las relaciones de largo plazo con proveedores.","Entender el efecto látigo y cómo compartir información lo reduce."],
x: `## De comprar a gestionar la cadena
Hasta ahora vimos cómo comprar bien, elegir proveedores, negociar y reducir riesgos. Pero hay una mirada más amplia: un negocio no está solo; forma parte de una **cadena de suministro**, que es la red de empresas y actividades que llevan un producto desde las materias primas hasta el cliente final.

La cadena de una torta de Tortas Lupita, por ejemplo:
**Agricultores de trigo → molino → panadería → Tortas Lupita → cliente**
**Ganaderos → rastro → empacadora → carnicería → Tortas Lupita → cliente**
**Productores de aguacate → empacadora → central de abasto → mercado → Tortas Lupita → cliente**

Cada eslabón depende de los demás. Si el molino tiene problemas, la panadería no hornea; si la panadería falla, Tortas Lupita no vende. La **gestión de la cadena de suministro** busca que toda la cadena funcione bien: que el producto llegue al cliente con la calidad, el costo y la rapidez adecuados.

## Del campo a la mesa
En alimentos, la cadena es especialmente importante por la frescura, la higiene y la trazabilidad. La **trazabilidad** es la capacidad de saber de dónde viene cada producto y por dónde pasó. Si un lote de carne tiene un problema sanitario, la trazabilidad permite saber qué otros productos se hicieron con él y retirarlos. Las grandes empresas de alimentos llevan registros detallados de cada lote; un negocio pequeño puede, al menos, anotar la fecha y el proveedor de cada compra.

## Relaciones de largo plazo
Hay dos formas de relacionarse con los proveedores:
- **Transaccional:** cada compra es una operación aislada; se busca el mejor precio en cada momento y se cambia de proveedor con facilidad.
- **Colaborativa (de largo plazo):** se construye una relación de confianza, con información compartida, objetivos comunes y mejora conjunta.

La relación transaccional funciona bien para insumos de rutina, fáciles de conseguir. Para insumos estratégicos, la relación de largo plazo suele dar mejores resultados: mejor calidad, prioridad en momentos de escasez, ideas de mejora, precios más estables y menos tiempo dedicado a buscar y negociar.

## Qué se gana colaborando
- **Planeación conjunta:** si el proveedor conoce la demanda esperada, produce lo justo y a tiempo.
- **Mejor calidad:** el proveedor entiende exactamente lo que el negocio necesita.
- **Innovación:** el proveedor propone productos o procesos nuevos (un pan especial para tortas, un empaque mejor).
- **Prioridad:** en una escasez, el proveedor atiende primero a sus clientes de confianza.
- **Costos menores para ambos:** menos desperdicio, menos urgencias, menos devoluciones.

## El efecto látigo
Un fenómeno muy conocido en las cadenas de suministro es el **efecto látigo**: pequeñas variaciones en la demanda del cliente final se convierten en variaciones cada vez mayores a medida que se sube por la cadena. Ocurre porque cada eslabón, sin información completa, se protege pidiendo de más cuando ve que la demanda sube, y pidiendo de menos cuando baja.

Ejemplo: un lunes Tortas Lupita vende 10 % más. Toño, preocupado, pide 20 % más pan para el martes. La panadería ve que su cliente grande pidió 20 % más y, para no quedarse corta, pide 30 % más harina. El molino ve el pedido grande y aumenta su producción. Si la venta del martes vuelve a la normalidad, toda la cadena queda con exceso de inventario.

El fenómeno fue estudiado por Hau Lee y otros investigadores de la Universidad de Stanford en 1997, quienes describieron, entre otros ejemplos, cómo Procter & Gamble observó grandes variaciones en los pedidos de sus pañales a pesar de que el consumo de los bebés era bastante estable.

## Cómo reducir el efecto látigo
- **Compartir información** de ventas reales y pronósticos con los proveedores.
- **Pedir con más frecuencia y en cantidades más pequeñas**, en lugar de grandes pedidos esporádicos.
- **Evitar pedidos de pánico:** basarse en datos, no en reacciones.
- **Estabilizar precios:** las promociones agresivas generan picos de compra artificiales.
- **Acortar los tiempos de entrega.**

## La información compartida en las empresas gigantes
Las grandes cadenas comparten datos con sus proveedores para que planeen mejor. Walmart desarrolló desde hace décadas un sistema llamado **Retail Link**, mediante el cual muchos de sus proveedores pueden consultar las ventas e inventarios de sus productos en las tiendas, para planear su producción y su reposición. En algunos casos, los proveedores administran directamente el inventario de sus productos en el cliente (**inventario administrado por el proveedor**).

## Desarrollo de proveedores
Algunas empresas van más allá y ayudan a sus proveedores a mejorar: capacitación, asesoría en calidad, apoyo para certificarse, incluso financiamiento. Lo hacen porque un proveedor más fuerte es un eslabón más confiable en su cadena. Las armadoras de autos y las grandes cadenas de alimentos tienen programas de este tipo con proveedores locales.

## La nueva relación de Tortas Lupita
Lupita acepta la propuesta de la panadería B:
- Cada viernes le envía el pronóstico de tortas de la semana siguiente, por día.
- La panadería hornea de acuerdo con el pronóstico y ajusta cada mañana según el pedido del día anterior.
- Revisan juntos cada mes la frescura y la puntualidad.
- Prueban juntos un bolillo especial para tortas, más resistente.

Resultado: el pan sobrante baja a casi cero, la panadería produce con menos desperdicio y ambos negocios ganan. Lupita entiende que sus proveedores no son adversarios a los que hay que «exprimir», sino socios de una misma cadena que llega al cliente.

## Cierre del módulo
Comprar bien es mucho más que encontrar el precio más bajo: es elegir con criterios, comparar costos totales, negociar con preparación, documentar, reducir riesgos y construir relaciones que hagan fuerte a toda la cadena.`,
k: `**Cadena de suministro:** red de empresas que llevan un producto de las materias primas al cliente. **Trazabilidad:** saber de dónde viene cada producto. Relación **transaccional** o **colaborativa** de largo plazo. **Efecto látigo:** pequeñas variaciones de demanda se amplifican al subir por la cadena; se reduce **compartiendo información** y pidiendo con frecuencia.`,
ch: `Una frutería comparte cada semana con su proveedor de la central de abasto qué frutas vendió más; el proveedor le aparta lo mejor y le avisa de temporadas y precios.`,
gi: `Walmart comparte información de ventas e inventarios con sus proveedores mediante su sistema Retail Link, para que planeen su producción y reposición.`,
e: `Toño mide el pan sobrante antes y después de compartir pronósticos:

| Indicador | Antes | Después |
|---|---|---|
| Bolillos sobrantes por semana | 420 | 60 |
| Costo del pan sobrante al mes (× 3.21) | 5,393 | 770 |
| Faltantes de pan al mes | 3 días | 0 |
| Tiempo de Toño en llamadas de urgencia | 4 horas | 0 |

Compartir información ahorra más de 4,600 pesos al mes en pan y elimina los faltantes.`,
r: `Hau Lee, V. Padmanabhan y Seungjin Whang publicaron en 1997 «The Bullwhip Effect in Supply Chains» (Sloan Management Review), donde analizaron el efecto látigo y mencionaron casos como el de Procter & Gamble con los pañales Pampers, cuyos pedidos variaban mucho más que el consumo real.`,
f: `H. Lee, V. Padmanabhan y S. Whang, «The Bullwhip Effect in Supply Chains», Sloan Management Review (1997); Walmart, información sobre Retail Link.`,
err: ["Tratar a todos los proveedores como adversarios.","Hacer pedidos de pánico ante un pequeño cambio en las ventas.","No compartir información útil con los proveedores clave.","No registrar el origen de los productos (trazabilidad)."],
a: `Dibuja la cadena de suministro de un producto que vende el negocio que observas, desde la materia prima hasta el cliente. Identifica un eslabón débil y propón una forma de colaborar con un proveedor para fortalecerlo.`,
sol: `La forma más sencilla de colaborar es compartir un pronóstico semanal de ventas y revisar juntos cada mes la calidad y la puntualidad.`,
q: [["La cadena de suministro es…",["La red de empresas que llevan un producto de la materia prima al cliente","El organigrama","Una cadena de restaurantes"],0,"Cada eslabón depende de los demás."],
["El efecto látigo consiste en que…",["Pequeñas variaciones de demanda se amplifican al subir por la cadena","Los precios bajan siempre","Los clientes se van"],0,"Cada eslabón se protege pidiendo de más o de menos."],
["¿Qué ayuda a reducir el efecto látigo?",["Compartir información de ventas reales con los proveedores","Hacer pedidos de pánico","Cambiar de proveedor cada semana"],0,"Así todos planean con datos."],
["La trazabilidad permite…",["Saber de dónde viene cada producto y por dónde pasó","Vender más caro","Evitar impuestos"],0,"Es clave en alimentos."]],
t: ["Cadena de suministro", "Trazabilidad"]
}
});
// ===== M11. Ventas y clientes =====
Object.assign(window.LECC, {
"M11-1": {
s: `Lupita contrata a Karla como ejecutiva de ventas para conseguir oficinas. Al mes, Karla pregunta: «¿Cuál es mi meta? ¿Cómo me van a pagar si consigo clientes? ¿A quién le reporto lo que vendo?». Lupita no lo había pensado.`,
o: ["Describir qué hace el área de ventas.","Distinguir los tipos de puestos de ventas.","Diseñar metas y esquemas de comisiones sencillos."],
x: `## El área que trae el dinero
El área de **ventas** se encarga de convertir a personas interesadas en clientes que compran, y de que los clientes actuales sigan comprando. Es la parte del negocio que **trae el dinero**: sin ventas, ninguna otra área tiene sentido. En un changarro, vende el dueño en el mostrador; en una pyme, puede haber vendedores de mostrador, ejecutivos que visitan empresas y un gerente de ventas; en una empresa grande, una dirección comercial con cientos o miles de vendedores organizados por región, canal o tipo de cliente.

## Ventas y marketing: hermanos distintos
Ventas y marketing trabajan juntos, pero no son lo mismo (lección M12-1):
- **Marketing** atrae y prepara: hace que el cliente conozca el negocio, se interese y quiera comprar.
- **Ventas** convierte y cierra: atiende al cliente interesado, resuelve dudas y concreta la compra.

En un negocio pequeño, ambas cosas las hace la misma persona. Al crecer, se separan, y conviene que se coordinen bien.

## Tipos de puestos de ventas
| Puesto | Qué hace | Ejemplo |
|---|---|---|
| Vendedor de mostrador o piso | Atiende al cliente que llega | La cajera de Tortas Lupita |
| Vendedor de ruta | Visita a clientes con una ruta fija y levanta pedidos | El vendedor de refrescos que visita tienditas |
| Ejecutivo de cuenta | Busca y atiende a clientes empresas | Karla, que consigue oficinas |
| Vendedor telefónico o digital | Vende por teléfono, chat o en línea | Quien atiende los pedidos de WhatsApp |
| Gerente de ventas | Dirige al equipo, fija metas, da seguimiento | En una pyme, el dueño o un gerente |
| Gerente de cuentas clave | Atiende a los clientes más grandes e importantes | El responsable de un supermercado como cliente |

## Las funciones del área de ventas
1. **Prospectar:** buscar posibles clientes (prospectos).
2. **Calificar:** identificar cuáles tienen necesidad, capacidad de pago y poder de decisión.
3. **Vender:** presentar la oferta, resolver dudas y cerrar (lección M11-5).
4. **Atender y retener:** dar seguimiento, resolver problemas, lograr que vuelvan a comprar (lecciones M11-7 y M11-8).
5. **Pronosticar:** estimar cuánto se venderá en las próximas semanas o meses; ese pronóstico es el punto de partida del presupuesto (lección M8-7) y de las compras.
6. **Informar:** contar a la dirección qué piden los clientes, qué hace la competencia y qué problemas hay.

## Las metas de ventas
Un vendedor necesita saber qué se espera de él. Las metas deben ser SMART (lección M7-2) y pueden ser de varios tipos:
- **De resultado:** ventas en pesos, número de clientes nuevos, margen generado.
- **De actividad:** número de visitas, llamadas o propuestas enviadas (son indicadores adelantados: anticipan resultados).
- **De calidad:** clientes que repiten, quejas, cobranza a tiempo.

Combinar metas de actividad y de resultado ayuda: si un vendedor no llega a su meta de ventas, las metas de actividad permiten ver si el problema es que no visita suficientes clientes o que no logra convertirlos.

## Cómo pagar a los vendedores
Hay tres esquemas básicos:
- **Sueldo fijo:** da estabilidad; conviene cuando las ventas dependen de muchos factores que el vendedor no controla o cuando el trabajo incluye mucho servicio.
- **Comisión pura:** el vendedor gana un porcentaje de lo que vende; motiva mucho, pero puede llevar a vender a cualquier precio o a clientes que no pagan.
- **Mixto:** sueldo base más comisión o bonos por metas. Es el más común.

Algunas reglas para diseñar comisiones:
- **Paga sobre lo cobrado, no solo sobre lo vendido**, para que al vendedor le importe que el cliente pague.
- **Considera el margen:** si un producto deja más margen, puede pagar una comisión mayor; evita premiar descuentos excesivos.
- **Que sea sencillo:** el vendedor debe poder calcular su comisión.
- **Revisa que sea rentable:** la comisión debe salir del margen extra que genera la venta.
- **Respeta la ley laboral:** en México, las comisiones forman parte del salario y tienen efectos en prestaciones y cuotas; conviene revisarlo con el contador.

## El ejemplo de Karla
Lupita diseña el esquema de Karla:
- Sueldo base: 9,000 pesos al mes.
- Comisión: 3 % de las ventas **cobradas** a oficinas nuevas durante sus primeros seis meses como clientes.
- Meta de actividad: 40 visitas o llamadas a oficinas por mes.
- Meta de resultado: 3 oficinas nuevas al mes, con un pedido mínimo de 4,000 pesos mensuales cada una.
- Reporta a Lupita cada lunes en la junta semanal.

Si Karla consigue 3 oficinas de 6,000 pesos al mes, al sexto mes estará generando 18 oficinas × 6,000 = 108,000 pesos al mes en ventas nuevas (si ninguna se va), con una comisión de 3,240 pesos. El margen de esas ventas (60 %, unos 64,800 pesos) cubre de sobra su costo.

## El pronóstico de ventas
Un buen equipo de ventas ayuda a todo el negocio porque **anticipa**. Un pronóstico sencillo combina:
- Lo que se vendió en el mismo periodo del año anterior.
- La tendencia de los últimos meses.
- Los pedidos ya confirmados.
- Las oportunidades en proceso, multiplicadas por su probabilidad de cerrarse.
- Los cambios conocidos (una nueva sucursal, una promoción, un competidor).

## Ventas en las empresas gigantes
Las grandes empresas organizan a sus vendedores por territorio, canal o tipo de cliente; usan sistemas para registrar cada oportunidad (Módulo 15) y gerentes que revisan metas y avances semana a semana. Las empresas de consumo, como las embotelladoras, tienen miles de vendedores de ruta que visitan tienditas con una frecuencia planeada. Pero los fundamentos son los mismos que los de Karla: saber a quién vender, con qué metas, cómo se paga y cómo se reporta.`,
k: `**Ventas:** convertir interesados en clientes y lograr que sigan comprando. Funciones: **prospectar, calificar, vender, retener, pronosticar e informar**. Metas de **actividad**, **resultado** y **calidad**. Pago: fijo, comisión o **mixto**; comisiona sobre lo **cobrado** y cuida el margen.`,
ch: `Un vendedor de una distribuidora de dulces visita 40 tienditas por semana con una ruta fija; gana un sueldo base más 2 % de lo que cobra, y su meta incluye no tener clientes con más de 15 días de atraso.`,
gi: `Las embotelladoras de refrescos tienen miles de vendedores y repartidores que visitan cientos de miles de tiendas con una frecuencia planeada, apoyados por sistemas que sugieren qué pedido levantar en cada punto de venta.`,
e: `Lupita verifica que el esquema de Karla sea rentable al sexto mes:

| Concepto | Cálculo | Pesos al mes |
|---|---|---|
| Ventas nuevas (18 oficinas × 6,000) | — | 108,000 |
| Margen (60 %) | 108,000 × 0.6 | 64,800 |
| Sueldo de Karla | — | 9,000 |
| Comisión (3 %) | 108,000 × 0.03 | 3,240 |
| Margen después del costo de ventas | 64,800 − 12,240 | 52,560 |

Aunque solo la mitad de las oficinas se quedara, el esquema seguiría siendo muy rentable.`,
r: `En el sector de bebidas, empresas como Coca-Cola FEMSA describen en sus informes un modelo de servicio a clientes del canal tradicional (tienditas) basado en visitas frecuentes de vendedores, herramientas digitales para levantar pedidos y segmentación de clientes.`,
f: `Coca-Cola FEMSA, informe anual integrado (coca-colafemsa.com).`,
err: ["Contratar vendedores sin metas claras.","Pagar comisiones sobre ventas que nunca se cobran.","Premiar el volumen aunque se venda con descuentos que destruyen el margen.","No pedir al área de ventas un pronóstico."],
a: `Diseña el puesto de un vendedor para el negocio que observas: tipo de puesto, metas de actividad y de resultado, esquema de pago y cómo reportará. Calcula si su costo se paga con el margen que generaría.`,
sol: `Para revisar la rentabilidad, multiplica las ventas esperadas por el margen y resta sueldo y comisiones; debe quedar un excedente claro.`,
q: [["La principal función del área de ventas es…",["Convertir interesados en clientes y lograr que sigan comprando","Llevar la contabilidad","Hacer el organigrama"],0,"Es la que trae el dinero."],
["Una meta de actividad para un vendedor es…",["Número de visitas o llamadas al mes","Utilidad neta de la empresa","Número de empleados"],0,"Anticipa los resultados."],
["¿Por qué conviene pagar comisión sobre lo cobrado?",["Para que al vendedor le importe que el cliente pague","Para pagar menos siempre","Porque lo prohíbe la ley"],0,"Evita vender a quien no paga."],
["El esquema de pago más común para vendedores es…",["Mixto: sueldo base más comisión o bonos","Solo propinas","Ninguno"],0,"Combina estabilidad y motivación."]],
t: ["Ventas", "Prospecto"]
},
"M11-2": {
s: `Karla visita una oficina y ofrece «las mejores tortas de la zona». La encargada responde: «Lo que necesito es que llegue a tiempo para la junta de las 13:00, con factura y sin que yo tenga que organizar nada». Karla aprende que no se vende un producto: se resuelve el problema de alguien.`,
o: ["Describir al cliente con un perfil concreto.","Identificar necesidades y motivos de compra racionales y emocionales.","Reconocer quién usa, quién decide, quién influye y quién paga."],
x: `## Conocer al cliente
Vender empieza por **entender al cliente**: quién es, qué necesita, qué le preocupa, cómo decide y qué valora. Un vendedor que conoce bien a su cliente no «empuja» un producto: ayuda a resolver un problema. Por eso, antes de hablar del producto, conviene escuchar y preguntar.

## El perfil del cliente
Un **perfil del cliente** (a veces llamado *buyer persona* en el lenguaje del marketing) es una descripción concreta de un cliente típico de un segmento (lección M4-3). No es un promedio estadístico, sino un retrato útil para decidir. Incluye:
- **Datos generales:** edad, ocupación, ubicación, nivel de ingresos (si es persona); giro, tamaño, número de empleados (si es empresa).
- **Necesidades:** qué problema quiere resolver.
- **Objetivos:** qué quiere lograr.
- **Frustraciones:** qué le molesta o preocupa.
- **Cómo compra:** dónde se informa, cuándo compra, cómo paga, con qué frecuencia.
- **Qué valora:** precio, rapidez, calidad, trato, seguridad, prestigio.
- **Objeciones típicas:** por qué podría no comprar.

## Ejemplo: el perfil de «Mariana, encargada de oficina»
| Elemento | Descripción |
|---|---|
| Quién es | Mariana, 35 años, asistente de dirección en un despacho de 25 personas en la colonia Centro |
| Necesidad | Comida para juntas y para el personal los viernes |
| Objetivo | Que todo salga bien sin que su jefe se queje y sin dedicarle mucho tiempo |
| Frustraciones | Pedidos que llegan tarde o incompletos; proveedores que no dan factura; tener que perseguir a varios proveedores |
| Cómo compra | Por WhatsApp; pide cotización; necesita autorización de su jefe para gastos mayores a 3,000 pesos; paga con transferencia contra factura |
| Qué valora | Puntualidad, que no haya errores, factura correcta, buen sabor |
| Objeciones | «Ya tenemos un proveedor», «Es más caro que la fonda» |

Con este perfil, Karla cambia su discurso: en lugar de «las mejores tortas», ofrece «su pedido listo a las 12:45, con factura, y usted solo me escribe una vez a la semana».

## Necesidades y motivos de compra
La gente compra por **motivos** que pueden ser:
- **Racionales:** precio, ahorro de tiempo, calidad, durabilidad, garantía, conveniencia.
- **Emocionales:** tranquilidad, prestigio, pertenencia, placer, miedo a equivocarse, quedar bien con otros.

En la práctica, casi todas las compras combinan ambos. Mariana compra tortas por razones racionales (precio, puntualidad, factura) y emocionales (quedar bien con su jefe, no estresarse). Un buen vendedor atiende a los dos tipos de motivos.

Una idea útil es la de los **trabajos por hacer** (en inglés, *jobs to be done*), popularizada por Clayton Christensen: el cliente «contrata» un producto para hacer un trabajo en su vida. Mariana no contrata tortas: contrata «que la junta salga bien sin que yo me preocupe».

## Quién participa en la compra
En muchas compras, especialmente entre empresas, participan varias personas con papeles distintos:
- **Usuario:** quien usa el producto (los empleados que comen las tortas).
- **Influenciador:** quien opina e influye (el jefe que comentó que la fonda tardaba).
- **Decisor:** quien elige (Mariana, para pedidos pequeños; su jefe, para los grandes).
- **Comprador:** quien hace la compra formal (Mariana).
- **Pagador:** quien paga (el área de administración del despacho).
- **Guardián:** quien controla el acceso a los demás (la recepcionista que contesta el teléfono).

Un vendedor que solo habla con una persona puede perder la venta porque otra se opone. Conviene saber quién es quién y qué le importa a cada uno.

## Cómo conocer mejor a los clientes
- **Pregunta:** «¿Qué es lo más importante para usted cuando pide comida para su oficina?», «¿Qué le ha fallado con otros proveedores?».
- **Escucha más de lo que hablas.**
- **Observa:** qué piden, cuándo, cuánto, cómo pagan.
- **Registra:** anota lo que aprendes de cada cliente (Módulo 15, CRM).
- **Pide retroalimentación** después de cada pedido.
- **Revisa las quejas:** dicen mucho de lo que el cliente valora.

## El cliente cambia
Los clientes cambian: de necesidades, de presupuesto, de persona encargada. Lo que valoraban hace un año puede no ser lo que valoran hoy. Por eso conocer al cliente no es un ejercicio de una vez, sino una práctica continua.

## En empresas gigantes
Las grandes empresas invierten mucho en conocer a sus clientes: estudios de mercado, encuestas, análisis de datos de compras, programas de lealtad que registran qué compra cada persona, grupos de enfoque. Pero la pregunta central es la misma que se hizo Karla: ¿qué problema le estoy resolviendo a esta persona y qué le importa realmente?

## El viaje del cliente
Otra herramienta útil es el **mapa del viaje del cliente**: una línea de tiempo con todos los momentos en que el cliente tiene contacto con el negocio, desde que siente la necesidad hasta después de la compra. Para Mariana serían: darse cuenta de que hay junta el viernes, buscar opciones, pedir cotización, pedir autorización a su jefe, hacer el pedido, recibirlo, pagar la factura y comentar cómo salió. En cada momento conviene preguntarse qué siente el cliente, qué le preocupa y qué podría hacer el negocio para facilitarle las cosas. Muchas veces, la diferencia entre ganar o perder a un cliente no está en el producto, sino en uno de esos momentos: una cotización que tardó dos días, una factura con errores o un repartidor que no encontró la oficina. Dibujar el viaje permite descubrir esos momentos y mejorarlos uno por uno.`,
k: `Conocer al cliente: **perfil** concreto (necesidades, objetivos, frustraciones, cómo compra, qué valora, objeciones). Motivos **racionales y emocionales**; el cliente «contrata» un producto para hacer un **trabajo** (Christensen). En la compra participan **usuario, influenciador, decisor, comprador, pagador y guardián**.`,
ch: `En una papelería, la mamá que compra útiles en agosto quiere terminar rápido la lista escolar y no gastar de más: la papelería que le arma la lista completa en una bolsa resuelve su «trabajo».`,
gi: `Clayton Christensen y su equipo contaron el caso de una cadena de comida rápida que descubrió que muchas personas compraban malteadas por la mañana para hacer más llevadero un trayecto largo en auto; entender ese «trabajo» cambió la forma de pensar el producto.`,
e: `Karla mapea quién participa en la compra del despacho de Mariana:

| Papel | Persona | Qué le importa | Qué hace Karla |
|---|---|---|---|
| Usuario | Empleados | Sabor y cantidad | Degustación gratis el primer viernes |
| Influenciador | El jefe | Que no haya retrasos en las juntas | Garantía: si llega tarde, el pedido es gratis |
| Decisor y comprador | Mariana | Puntualidad, factura, poco trabajo | Pedido fijo semanal por WhatsApp |
| Pagador | Administración | Factura correcta y precio claro | Factura con los datos exactos y precio fijo |
| Guardián | Recepcionista | No ser molestada | Solo escribir a Mariana, no llamar a recepción |

Con el mapa, el despacho firma un pedido semanal de 25 tortas.`,
r: `Clayton Christensen, profesor de la Escuela de Negocios de Harvard, desarrolló la teoría de los «trabajos por hacer» y la explicó en el libro «Competing Against Luck» (2016) y en artículos de Harvard Business Review, donde cuenta, entre otros, el ejemplo de las malteadas compradas para acompañar trayectos matutinos.`,
f: `Clayton M. Christensen y otros, «Competing Against Luck» (2016); «Know Your Customers' Jobs to Be Done», Harvard Business Review (2016).`,
err: ["Hablar del producto antes de entender al cliente.","Describir al cliente como «todo el mundo».","Hablar solo con una persona en una compra de empresa.","Ignorar los motivos emocionales de compra."],
a: `Escribe el perfil de un cliente típico del negocio que observas con los siete elementos de la lección. Después identifica qué «trabajo» contrata ese cliente y quién participa en su decisión de compra.`,
sol: `Si no sabes algo del perfil, es una señal para preguntar a clientes reales. Las mejores respuestas salen de conversaciones, no de suposiciones.`,
q: [["Un perfil del cliente sirve para…",["Entender a un cliente típico y decidir cómo atenderlo","Calcular impuestos","Elegir proveedores"],0,"Es un retrato concreto y útil."],
["«Quedar bien con su jefe» es un motivo de compra…",["Emocional","Racional","Fiscal"],0,"Se relaciona con emociones y relaciones."],
["En una compra de empresa, quien autoriza el gasto suele ser el…",["Decisor","Usuario","Guardián"],0,"El usuario usa el producto; el decisor elige."],
["La idea de los «trabajos por hacer» se asocia con…",["Clayton Christensen","Henri Fayol","Adam Smith"],0,"El cliente «contrata» un producto para hacer un trabajo."]],
t: ["Perfil del cliente", "Motivos de compra"]
},
"M11-3": {
s: `Cada día pasan unas 1,000 personas frente a Tortas Lupita, pero solo 120 compran. Toño se pregunta: ¿dónde se quedan las otras 880? ¿No nos ven, no les interesa, no les convence el precio o se van por la fila?`,
o: ["Describir las etapas del embudo de ventas.","Calcular la conversión entre etapas.","Identificar en qué etapa conviene mejorar."],
x: `## El embudo de ventas
El **embudo de ventas** es una forma de representar el camino que recorren las personas desde que se enteran de que un negocio existe hasta que se vuelven clientes frecuentes. Se llama embudo porque en cada etapa **se van quedando** personas: muchas entran arriba y pocas salen abajo.

Una de las primeras versiones de esta idea es el modelo **AIDA** (atención, interés, deseo, acción), atribuido al publicista estadounidense Elias St. Elmo Lewis a finales del siglo XIX. Hoy se usan muchas variantes. Una versión práctica para un negocio es:

| Etapa | Qué pasa | Ejemplo en Tortas Lupita |
|---|---|---|
| 1. Alcance | La persona se entera de que existes | Pasa frente al local, ve una publicación, alguien le cuenta |
| 2. Interés | Pone atención | Se detiene a ver el menú o el letrero |
| 3. Consideración | Evalúa si le conviene | Revisa precios, ve la fila, compara con otras opciones |
| 4. Compra | Compra por primera vez | Pide una torta |
| 5. Recompra | Vuelve a comprar | Regresa al día siguiente o a la semana |
| 6. Lealtad y recomendación | Se vuelve cliente frecuente y recomienda | Viene varias veces por semana y trae a sus compañeros |

## La conversión
La **tasa de conversión** es el porcentaje de personas que pasan de una etapa a la siguiente:

**Conversión = personas que pasan a la siguiente etapa ÷ personas en la etapa actual × 100**

También se usa la conversión total: **compradores ÷ personas alcanzadas × 100**.

## El embudo de Tortas Lupita
Toño observa un día normal en la acera y cuenta:

| Etapa | Personas | Conversión desde la etapa anterior |
|---|---|---|
| Pasan frente al local (alcance) | 1,000 | — |
| Miran el menú o el letrero (interés) | 400 | 40 % |
| Se acercan al mostrador o a la fila (consideración) | 180 | 45 % |
| Compran | 120 | 67 % |

**Conversión total:** 120 ÷ 1,000 = **12 %**. Si el ticket promedio es de 85 pesos (con refresco y alguna torta extra en pedidos de oficina), las ventas de mostrador de ese día son 120 × 85 = **10,200 pesos**.

## ¿Dónde se pierden más personas?
Al mirar cada etapa:
- **De alcance a interés (40 %):** 600 personas pasan sin mirar. Quizá el letrero es pequeño, el menú no se ve desde la calle o muchas no buscan comida a esa hora.
- **De interés a consideración (45 %):** de las 400 que miran, 220 no se acercan. Quizá los precios no están visibles, el local no se ve limpio o no hay algo que llame la atención.
- **De consideración a compra (67 %):** de las 180 que se acercan, 60 se van. Quizá por la fila o porque no aceptan tarjeta.

Cada pérdida sugiere una acción distinta:
- Mejorar el **alcance e interés:** letrero más visible, menú grande en la calle, olor a pan tostado, promoción visible.
- Mejorar la **consideración:** precios claros, foto de las tortas, local limpio y ordenado.
- Mejorar la **compra:** fila más rápida (lección M9-4), pago con tarjeta y transferencia.

## El efecto de mejorar una etapa
Una mejora pequeña en una etapa se multiplica en el resultado final. Si Toño logra que la conversión de consideración a compra suba de 67 % a 80 % (agilizando la fila y aceptando tarjeta):
- 180 × 80 % = 144 compradores en lugar de 120.
- 24 compradores más al día × 85 pesos = 2,040 pesos más al día.
- Al mes (26 días): unos 53,000 pesos más en ventas, sin traer a nadie nuevo a la calle.

## El embudo en ventas a empresas
Para clientes empresa, el embudo suele tener etapas como:
1. **Prospecto:** una empresa que podría ser cliente.
2. **Contacto:** se habló con la persona adecuada.
3. **Calificado:** tiene necesidad, presupuesto y poder de decisión.
4. **Propuesta:** se envió una cotización.
5. **Negociación.**
6. **Cierre:** firma o primer pedido.
7. **Cliente activo y recurrente.**

Karla registra a cada oficina en la etapa en que está. Si ve que muchas se quedan en «propuesta», el problema puede ser el precio o la forma de presentarla; si se quedan en «contacto», quizá no habla con quien decide.

## El embudo digital
En internet, el embudo es aún más fácil de medir: impresiones de una publicación (alcance), clics (interés), visitas al menú o al perfil (consideración), mensajes o pedidos (compra). Las herramientas digitales muestran estas cifras automáticamente (Módulo 12).

## Más allá de la primera compra
El embudo no termina en la compra. Para muchos negocios, la parte más valiosa son las etapas de **recompra** y **lealtad**: un cliente que regresa cada semana vale mucho más que uno que compra una sola vez (lección M11-8). Por eso, algunos autores prefieren hablar de un ciclo en lugar de un embudo: los clientes leales recomiendan y traen a nuevos clientes a la parte de arriba.

## En las empresas gigantes
Las empresas grandes miden su embudo con enorme detalle: cuántas personas ven un anuncio, cuántas entran a la tienda o al sitio web, cuántas agregan un producto al carrito, cuántas pagan y cuántas regresan. Las tiendas en línea, por ejemplo, analizan en qué paso del proceso de pago se van los clientes y lo simplifican. La lógica es exactamente la del conteo de Toño en la acera.`,
k: `**Embudo de ventas:** alcance → interés → consideración → compra → recompra → lealtad (basado en el modelo **AIDA**). **Conversión** = los que pasan ÷ los que estaban. Conversión total = compradores ÷ alcanzados. Encuentra la etapa donde se pierde más gente; una mejora pequeña en una etapa se **multiplica** en el resultado.`,
ch: `Una estética mide: 300 personas ven su publicación, 60 le escriben, 25 agendan y 20 llegan. Descubre que muchas no agendan porque no ven precios; al publicarlos, sube la conversión.`,
gi: `Las tiendas en línea grandes analizan cada paso de su proceso de compra (ver producto, agregar al carrito, pagar) y prueban cambios para reducir el número de clientes que abandonan el carrito.`,
e: `Toño calcula el efecto de dos mejoras en el embudo:

| Escenario | Interés | Consideración | Compra | Compradores | Ventas del día (× 85) |
|---|---|---|---|---|---|
| Actual | 400 (40 %) | 180 (45 %) | 120 (67 %) | 120 | 10,200 |
| Mejor compra (80 %) | 400 | 180 | 144 | 144 | 12,240 |
| Mejor interés (50 %) + mejor compra | 500 | 225 | 180 | 180 | 15,300 |

Mejorar dos etapas aumenta las ventas de mostrador 50 % con la misma gente pasando por la calle.`,
r: `El modelo AIDA se atribuye a Elias St. Elmo Lewis, publicista estadounidense que a finales del siglo XIX describió las etapas que una buena venta o un buen anuncio debía lograr: atraer la atención, despertar el interés, crear deseo y llevar a la acción.`,
f: `Historia del modelo AIDA en textos de marketing, por ejemplo, Philip Kotler y Gary Armstrong, «Fundamentos de marketing».`,
err: ["Mirar solo las ventas finales sin medir las etapas.","Gastar en atraer más gente cuando el problema está en la compra (fila, pagos).","Olvidar las etapas de recompra y lealtad.","No registrar en qué etapa está cada cliente empresa."],
a: `Observa durante una hora el negocio que estudias (o uno de tu colonia) y cuenta cuántas personas pasan, cuántas miran, cuántas se acercan y cuántas compran. Calcula las conversiones y propón una mejora para la etapa más débil.`,
sol: `Si la etapa más débil es la compra, revisa la fila, las formas de pago y la atención; si es el interés, revisa el letrero, el menú visible y la vitrina.`,
q: [["Si 1,000 personas pasan y 120 compran, la conversión total es…",["12 %","120 %","1.2 %"],0,"120 ÷ 1,000."],
["El modelo AIDA significa…",["Atención, interés, deseo, acción","Ahorro, inversión, deuda, activo","Análisis, ideas, diseño, ajuste"],0,"Atribuido a Elias St. Elmo Lewis."],
["Si 180 personas se acercan y la conversión a compra sube de 67 % a 80 %, compran…",["144","120","180"],0,"180 × 0.8."],
["¿Por qué conviene medir cada etapa del embudo?",["Para saber dónde se pierden más personas y qué mejorar","Para pagar menos impuestos","Para despedir vendedores"],0,"Cada pérdida sugiere una acción distinta."]],
t: ["Embudo de ventas", "Modelo AIDA"]
},
"M11-4": {
s: `Lupita quiere más clientes, pero no sabe dónde buscarlos. Toño propone anuncios en redes, Karla quiere visitar oficinas, un vecino sugiere repartir volantes y un cliente fiel dice: «Yo ya les traje a cinco compañeros». ¿Cuál es el mejor camino?`,
o: ["Conocer los principales canales para conseguir clientes.","Comparar su costo y su efectividad.","Diseñar un plan sencillo de adquisición de clientes."],
x: `## Muchas formas de llegar
Conseguir clientes nuevos (la **adquisición de clientes**) puede hacerse por muchos caminos. No todos sirven igual para todos los negocios, y cada uno tiene un costo distinto. La clave es elegir los que usan tus clientes y medir cuánto cuesta cada cliente que llega por cada camino.

## 1. La ubicación
Para un negocio de calle, la **ubicación** es el primer canal de adquisición: el local mismo «se anuncia» a quienes pasan. Un buen letrero, una vitrina atractiva, un menú visible desde la calle y un local limpio convierten a los transeúntes en clientes (lección M11-3). Elegir dónde abrir es una de las decisiones más importantes de un negocio físico (lección M20-2).

## 2. La recomendación (boca a boca)
Un cliente satisfecho que recomienda el negocio es el canal más **creíble** y **barato** que existe: la gente confía más en un amigo que en un anuncio. Para estimularlo:
- **Dar una experiencia que valga la pena contar.**
- **Pedirlo:** «Si te gustó, recomiéndanos».
- **Premiarlo:** programas de referidos («trae a un amigo y ambos tienen 10 % de descuento»).
- **Facilitarlo:** tarjetas para compartir, número de WhatsApp fácil de pasar.

Una forma de medir qué tan dispuestos están los clientes a recomendar es el **Net Promoter Score (NPS)**, propuesto por Fred Reichheld en 2003: se pregunta «Del 0 al 10, ¿qué tan probable es que nos recomiendes?» y se resta el porcentaje de quienes responden 0 a 6 (detractores) al de quienes responden 9 o 10 (promotores).

## 3. Las reseñas y los mapas en internet
Hoy muchas personas buscan «tortas cerca de mí» en un mapa o un buscador. Tener un perfil completo en Google Maps (con fotos, horario, menú y teléfono) y buenas reseñas es, para un negocio local, casi tan importante como el letrero. Pedir a los clientes satisfechos que dejen una reseña y responder con amabilidad a todas (incluidas las negativas) ayuda mucho.

## 4. Las redes sociales
Publicar fotos y videos del producto, promociones y la vida del negocio en redes sociales puede atraer clientes con poco costo. Funciona mejor cuando es **constante**, **local** (dirigido a la zona) y **auténtico**. También se pueden pagar anuncios dirigidos a personas de cierta zona y edad (Módulo 12).

## 5. La venta directa (vendedores)
Para clientes empresa, como las oficinas, lo más efectivo suele ser la **venta directa**: un vendedor que identifica empresas, contacta a la persona adecuada, presenta una propuesta y da seguimiento (lección M11-5). Es más caro por cliente, pero cada cliente empresa puede valer mucho.

## 6. Alianzas
Asociarse con otros negocios que tienen los mismos clientes: un gimnasio que recomienda la torta saludable, una escuela que ofrece las tortas en sus eventos, un edificio de oficinas que incluye un descuento en su bienvenida a inquilinos.

## 7. Distribuidores e intermediarios
Vender a través de otros: plataformas de reparto, tiendas que revenden la salsa, cafeterías que ofrecen las tortas. Permiten llegar a muchos clientes, pero se comparte el margen (lección M4-4).

## 8. Promociones, eventos y degustaciones
Dejar probar el producto es una de las formas más efectivas de convencer: degustaciones en oficinas, participación en ferias o eventos de la colonia, promociones de bienvenida.

## 9. Publicidad tradicional
Volantes, lonas, anuncios en radio local o periódicos de la zona. Pueden funcionar, pero son difíciles de medir; conviene usar un código o una promoción específica para saber cuántos clientes llegan por ahí.

## Comparar canales: el costo por cliente
Para elegir, hay que medir el **costo de adquisición por cliente (CAC)** de cada canal: lo que se gastó en el canal ÷ los clientes nuevos que trajo (lección M11-9).

| Canal | Gasto al mes | Clientes nuevos | Costo por cliente |
|---|---|---|---|
| Volantes | 1,500 | 15 | 100 |
| Anuncios en redes | 2,000 | 40 | 50 |
| Programa de referidos (descuentos) | 1,200 | 60 | 20 |
| Visitas de Karla (parte de su sueldo y comisión) | 6,000 | 3 oficinas | 2,000 por oficina |

A simple vista, las visitas de Karla parecen carísimas. Pero cada oficina compra unos 6,000 pesos al mes durante muchos meses, mientras que un cliente de volante quizá compra 45 pesos un par de veces. El costo por cliente hay que compararlo con **lo que deja cada cliente** durante su relación con el negocio (valor de vida, lección M11-8).

## El plan de adquisición
Un plan sencillo responde:
1. ¿Qué **segmentos** quiero atraer? (oficinistas, oficinas, estudiantes).
2. ¿Qué **canales** usan esos segmentos?
3. ¿Cuánto puedo **gastar** en cada canal?
4. ¿Cómo voy a **medir** cuántos clientes llegan por cada canal? (preguntar «¿cómo nos conociste?», códigos de promoción, enlaces distintos).
5. ¿Cuándo voy a **revisar** y ajustar?

## El plan de Tortas Lupita
- **Oficinistas de la zona:** letrero y menú visibles, perfil en mapas con fotos y reseñas, anuncios en redes dirigidos a 1 kilómetro alrededor.
- **Oficinas:** visitas de Karla con degustación gratis.
- **Estudiantes:** promoción visible a la hora de salida.
- **Todos:** programa de referidos y tarjeta de sellos.

Toño agrega una pregunta en la caja: «¿Cómo nos conociste?». Al mes descubren que la mitad de los clientes nuevos llegaron por recomendación de otro cliente. Deciden reforzar el programa de referidos y dejar los volantes.`,
k: `Canales de **adquisición**: ubicación, **recomendación** (el más creíble y barato; se mide con el **NPS**), reseñas y mapas, redes sociales, venta directa, alianzas, distribuidores, degustaciones y publicidad tradicional. Compara canales por su **costo por cliente (CAC)** frente a lo que deja cada cliente. Pregunta siempre «¿cómo nos conociste?».`,
ch: `Una tintorería deja tarjetas en los edificios cercanos con un código de descuento distinto para cada edificio; así sabe qué edificios le traen más clientes.`,
gi: `Muchas empresas grandes miden su Net Promoter Score, la métrica propuesta por Fred Reichheld en 2003, para seguir qué tan dispuestos están sus clientes a recomendarlas.`,
e: `Toño calcula el NPS de Tortas Lupita con 100 respuestas:

| Respuesta | Clientes | Tipo |
|---|---|---|
| 9 o 10 | 62 | Promotores |
| 7 u 8 | 26 | Pasivos |
| 0 a 6 | 12 | Detractores |

NPS = % promotores − % detractores = 62 − 12 = **50**. Es un buen resultado. Llama a los detractores para entender qué falló.`,
r: `Fred Reichheld presentó el Net Promoter Score en el artículo «The One Number You Need to Grow» (Harvard Business Review, 2003). Desde entonces, muchas empresas lo usan como indicador de lealtad, aunque también ha recibido críticas por simplificar demasiado la satisfacción del cliente.`,
f: `Frederick F. Reichheld, «The One Number You Need to Grow», Harvard Business Review (2003).`,
err: ["Usar todos los canales sin medir cuál funciona.","Comparar canales solo por costo por cliente sin ver cuánto deja cada cliente.","Olvidar pedir recomendaciones y reseñas.","No preguntar a los clientes cómo conocieron el negocio."],
a: `Durante una semana, pregunta (o imagina que preguntas) a los clientes nuevos del negocio que observas cómo lo conocieron. Calcula qué porcentaje llega por cada canal y propón en cuál invertir más.`,
sol: `Si la recomendación es el canal principal, conviene reforzarla con un programa de referidos y cuidando la experiencia; es más barato que la publicidad.`,
q: [["El canal de adquisición más creíble suele ser…",["La recomendación de otro cliente","Un volante","Un anuncio en la radio"],0,"La gente confía en sus conocidos."],
["El NPS se calcula como…",["% de promotores − % de detractores","Ventas − costos","Clientes ÷ empleados"],0,"Propuesto por Fred Reichheld en 2003."],
["Si gastas 2,000 en un canal y llegan 40 clientes nuevos, el costo por cliente es…",["50","80","2,040"],0,"2,000 ÷ 40."],
["¿Por qué un costo por cliente alto puede convenir?",["Si cada cliente deja mucho dinero durante su relación con el negocio","Nunca conviene","Porque se paga menos impuesto"],0,"Hay que comparar con su valor de vida."]],
t: ["Adquisición de clientes", "Recomendación (boca a boca)"]
},
"M11-5": {
s: `Karla visita una oficina, habla diez minutos de lo ricas que son las tortas, deja un menú y se va. Nunca le llaman. En otra visita, pregunta, escucha, propone una solución a la medida y cierra un pedido semanal. ¿Qué hizo distinto?`,
o: ["Seguir las etapas del proceso de venta.","Hacer preguntas que descubran necesidades.","Manejar objeciones y cerrar la venta de forma ética."],
x: `## Vender es ayudar a decidir
Vender bien no es convencer a alguien de comprar algo que no necesita, sino **ayudarle a decidir** si lo que ofreces resuelve su problema. Un buen vendedor escucha más de lo que habla, pregunta antes de proponer y es honesto cuando su producto no es lo adecuado. A largo plazo, esa forma de vender genera confianza, recompra y recomendaciones.

## Las etapas del proceso de venta
Aunque cambia según el tipo de negocio, una venta suele seguir estas etapas:
1. **Preparación:** conocer al cliente antes del contacto (a qué se dedica, cuántas personas tiene, qué compra hoy).
2. **Apertura:** presentarse, generar confianza, explicar el motivo de la visita en pocas palabras.
3. **Descubrimiento:** hacer preguntas para entender sus necesidades, problemas y forma de decidir.
4. **Presentación:** mostrar cómo el producto resuelve **su** problema (beneficios, no solo características).
5. **Manejo de objeciones:** escuchar las dudas y responderlas con honestidad.
6. **Cierre:** pedir la decisión o el siguiente paso concreto.
7. **Seguimiento:** cumplir lo prometido y mantener la relación.

## Preguntar para descubrir
La etapa más importante (y la que más se salta) es el **descubrimiento**. El investigador Neil Rackham estudió miles de visitas de ventas y publicó en 1988 el libro «SPIN Selling», donde propuso cuatro tipos de preguntas:
- **De situación:** para entender el contexto. «¿Cuántas personas trabajan aquí? ¿Cómo resuelven hoy la comida de las juntas?».
- **De problema:** para descubrir dificultades. «¿Qué es lo que más le complica de pedir comida? ¿Ha tenido retrasos?».
- **De implicación:** para entender las consecuencias del problema. «¿Qué pasa cuando la comida llega tarde a una junta con clientes?».
- **De necesidad-beneficio:** para que el cliente diga el valor de resolverlo. «¿Qué tan útil le sería tener el pedido listo cada viernes sin tener que organizarlo?».

Cuando el cliente expresa con sus propias palabras el problema y el valor de la solución, la venta deja de ser «convencer» y se vuelve «ayudar».

## Beneficios, no solo características
- **Característica:** lo que el producto es o tiene. «Usamos pan de panadería».
- **Ventaja:** lo que permite. «El pan está fresco cada mañana».
- **Beneficio:** lo que gana el cliente. «Sus empleados comen bien y usted queda bien con su jefe».

Los clientes compran beneficios. Una forma práctica de pasar de características a beneficios es preguntarse después de cada característica: «¿Y eso qué le da al cliente?».

## Manejar objeciones
Una **objeción** es una duda o una razón para no comprar. No es un ataque: es información. Las objeciones más comunes son de precio, de confianza, de necesidad («no lo necesitamos»), de tiempo («ahora no») o de competencia («ya tenemos proveedor»). Un método sencillo:
1. **Escuchar completo** sin interrumpir.
2. **Reconocer:** «Entiendo, es importante cuidar el presupuesto».
3. **Preguntar para entender:** «¿Más caro comparado con qué?».
4. **Responder** con información concreta.
5. **Confirmar:** «¿Eso resuelve su duda?».

Ejemplo:
- Objeción: «Es más caro que la fonda».
- Respuesta: «Entiendo. La fonda cobra 10 pesos menos por persona. Nosotros entregamos a tiempo garantizado, con factura y armado por persona, y usted no tiene que ir por él. ¿Cuánto tiempo le dedica hoy a organizar la comida de cada viernes?».

## Cerrar
Muchos vendedores hacen todo bien y no cierran porque **no piden la decisión**. Cerrar es simplemente proponer el siguiente paso concreto:
- «¿Le parece si empezamos este viernes con 20 tortas?».
- «¿Le envío la cotización hoy y la revisamos el lunes?».
- «¿Qué necesitaría para tomar la decisión?».

Si el cliente no está listo, el cierre puede ser un paso intermedio: una degustación, una cita con el jefe, un pedido de prueba.

## El seguimiento
La venta no termina con el sí. El seguimiento incluye:
- **Cumplir** exactamente lo prometido (la hora, la factura, el pedido completo).
- **Preguntar** cómo salió el primer pedido.
- **Resolver** rápido cualquier problema.
- **Mantener el contacto** sin ser invasivo.

Muchas ventas a empresas se pierden después del primer pedido por un mal seguimiento.

## Vender con ética
Algunas prácticas destruyen la confianza y, en muchos casos, son ilegales o abusivas:
- Prometer lo que no se puede cumplir.
- Ocultar costos («la entrega es gratis», y luego se cobra).
- Presionar con urgencias falsas («solo hoy»).
- Hablar mal de la competencia sin fundamento.
- Ofrecer regalos o pagos a quien decide para que elija tu producto (en empresas y gobierno, esto puede ser corrupción; Módulo 27).

La ética no es un lujo: un cliente engañado no regresa y lo cuenta a otros.

## La visita exitosa de Karla
En la segunda oficina, Karla:
1. Investigó antes: un despacho de 30 personas con juntas frecuentes.
2. Se presentó en 30 segundos.
3. Preguntó cómo resolvían la comida de las juntas, qué les fallaba y qué pasaba cuando algo salía mal.
4. Propuso un pedido fijo cada viernes, con factura y entrega garantizada.
5. Respondió la objeción de precio mostrando el ahorro de tiempo y la garantía.
6. Cerró con una degustación el viernes siguiente.
7. Llamó el lunes para preguntar cómo les fue. El despacho firmó un pedido semanal.`,
k: `Proceso de venta: **preparación, apertura, descubrimiento, presentación, objeciones, cierre y seguimiento**. Pregunta antes de proponer (**SPIN**: situación, problema, implicación, necesidad-beneficio; Neil Rackham, 1988). Vende **beneficios**, no solo características. Trata las **objeciones** como información. **Pide la decisión.** Vende con **ética**.`,
ch: `Un vendedor de una tienda de colchones pregunta cómo duerme el cliente, si le duele la espalda y con quién comparte la cama antes de mostrar un modelo; vende menos colchones caros innecesarios y recibe más recomendaciones.`,
gi: `Muchas empresas que venden a otras empresas capacitan a sus vendedores en métodos basados en preguntas, como SPIN, que surgieron de investigaciones con miles de visitas de ventas reales.`,
e: `Karla compara sus resultados antes y después de cambiar su forma de vender:

| Indicador | Antes (hablar del producto) | Después (preguntar y proponer) |
|---|---|---|
| Visitas al mes | 40 | 40 |
| Propuestas enviadas | 8 | 15 |
| Oficinas nuevas | 1 | 4 |
| Conversión de visita a cliente | 2.5 % | 10 % |

Con el mismo número de visitas, cuadruplicó los clientes nuevos.`,
r: `Neil Rackham y su equipo de Huthwaite analizaron más de 35,000 llamadas de ventas en varios países durante los años setenta y ochenta; sus resultados, publicados en «SPIN Selling» (1988), mostraron que en las ventas grandes las preguntas sobre problemas e implicaciones se asociaban con más éxito que las técnicas de cierre agresivas.`,
f: `Neil Rackham, «SPIN Selling» (1988).`,
err: ["Hablar del producto sin preguntar nada.","Responder una objeción antes de entenderla.","No pedir la decisión.","Prometer lo que no se puede cumplir para cerrar."],
a: `Prepara una visita de ventas para un posible cliente del negocio que observas: escribe dos preguntas de cada tipo SPIN, tres beneficios (no características) y tus respuestas a dos objeciones probables. Practícala con alguien.`,
sol: `Si tus beneficios suenan a características, pregúntate «¿y eso qué le da al cliente?» hasta llegar a algo que le importe a la persona.`,
q: [["¿Cuál es la etapa del proceso de venta que más se salta?",["El descubrimiento (preguntar)","El saludo","La despedida"],0,"Preguntar antes de proponer."],
["En SPIN, «¿Qué pasa cuando la comida llega tarde a una junta?» es una pregunta de…",["Implicación","Situación","Cierre"],0,"Explora las consecuencias del problema."],
["«Sus empleados comen bien y usted queda bien con su jefe» es…",["Un beneficio","Una característica","Una objeción"],0,"Es lo que gana el cliente."],
["Cerrar una venta significa…",["Proponer el siguiente paso concreto o pedir la decisión","Presionar con urgencias falsas","Despedirse"],0,"Muchos vendedores no lo hacen."]],
t: ["Proceso de venta", "Método SPIN"]
},
"M11-6": {
s: `En el mostrador, una persona decide en segundos si compra una torta. Con las oficinas, Karla tarda semanas: cotizaciones, autorizaciones, facturas, crédito. Toño se da cuenta de que vender a personas y vender a empresas son dos mundos distintos.`,
o: ["Distinguir la venta a consumidores (B2C) de la venta a empresas (B2B).","Comparar su ciclo de venta, decisión y condiciones.","Adaptar la forma de vender a cada tipo de cliente."],
x: `## Dos tipos de clientes
- **B2C** (del inglés *business to consumer*, de negocio a consumidor): el negocio vende a **personas** que compran para sí mismas o su familia. La tortería con el cliente de mostrador, la tienda de ropa, el cine, la farmacia.
- **B2B** (*business to business*, de negocio a negocio): el negocio vende a **otras empresas** u organizaciones, que compran para usar en su operación o para revender. Tortas Lupita con las oficinas, el proveedor de pan con Tortas Lupita, el fabricante de empaques, el despacho contable.

Muchos negocios hacen ambas cosas. Y también existe la venta al gobierno (a veces llamada **B2G**), que tiene reglas propias, como las licitaciones.

## Las grandes diferencias
| Aspecto | Venta a personas (B2C) | Venta a empresas (B2B) |
|---|---|---|
| Número de clientes | Muchos | Pocos |
| Monto por compra | Bajo | Alto |
| Quién decide | Una persona o una familia | Varias personas (usuario, decisor, pagador) |
| Tiempo para decidir | Minutos u horas | Días, semanas o meses |
| Motivos | Más emocionales e inmediatos | Más racionales: costo, confiabilidad, riesgo |
| Relación | A veces breve | Normalmente de largo plazo |
| Precio | De lista, igual para todos | Negociado, con descuentos por volumen |
| Pago | De contado | A crédito, contra factura |
| Documentos | Ticket o factura simple | Cotización, orden de compra, contrato, factura, complemento de pago |
| Cómo se llega | Ubicación, publicidad, redes, recomendación | Venta directa, referencias, ferias del sector, licitaciones |
| Riesgo de perder un cliente | Bajo (es uno de muchos) | Alto (puede ser una parte grande de las ventas) |

## Vender a personas
En B2C, el reto es atraer a muchas personas, convencerlas rápido y lograr que regresen. Las claves:
- **Visibilidad y conveniencia:** estar donde está el cliente.
- **Experiencia:** trato, rapidez, ambiente, limpieza.
- **Precio claro** y formas de pago fáciles.
- **Marca:** que el cliente recuerde y confíe.
- **Lealtad:** programas, promociones, trato personal.

## Vender a empresas
En B2B, el reto es entender a la organización, ganarse su confianza y cumplir de forma impecable. Las claves:
- **Conocer el proceso de compra** de la empresa: quién decide, quién autoriza, qué documentos piden (lección M11-2).
- **Formalidad:** estar registrado ante el SAT, emitir facturas correctas (CFDI 4.0 con los datos exactos), tener la opinión de cumplimiento al día, a veces estar dado de alta como proveedor en su sistema.
- **Confiabilidad:** cumplir siempre en tiempo, cantidad y calidad; un error puede costar el cliente.
- **Propuestas por escrito:** cotizaciones claras con precio, condiciones, vigencia y entregas.
- **Crédito y cobranza:** las empresas suelen pagar a 15, 30 o más días; hay que planear el flujo (lecciones M8-5 y M8-6).
- **Relación de largo plazo:** atender, dar seguimiento, proponer mejoras.

## El riesgo de la concentración
En B2B, unos pocos clientes pueden representar una gran parte de las ventas. Si el cliente más grande se va, el golpe es enorme. Una regla de prudencia común es vigilar que **ningún cliente represente más de una cierta proporción de las ventas** (por ejemplo, un 20 % o 30 %, según el negocio). Si Tortas Lupita llegara a depender de una sola empresa grande para la mitad de sus ventas, estaría en una situación muy frágil.

## Requisitos de los clientes grandes
Cuando se le vende a una empresa grande, es común que pida:
- Constancia de situación fiscal y opinión de cumplimiento.
- Alta en su portal de proveedores.
- Contrato con condiciones (penalizaciones por retraso, confidencialidad).
- Seguro de responsabilidad civil.
- Certificaciones (de higiene, de calidad).
- Plazos de pago largos (30, 60 o más días).
- Precios fijos por un periodo.

Estos requisitos pueden ser una barrera para un negocio pequeño, pero también una oportunidad: quien los cumple tiene menos competencia (lección M18-7).

## Vender al gobierno
La venta al gobierno suele hacerse por **licitaciones** o procedimientos de compra regulados (lección M10-3). Exige cumplir requisitos formales estrictos, presentar documentos en tiempo y forma, y aceptar plazos de pago que a veces son largos. Puede ser una fuente importante de ventas, pero hay que conocer bien las reglas.

## Tortas Lupita en los dos mundos
Tortas Lupita vende B2C en el mostrador y B2B a oficinas. Para cada uno organiza distinto:
- **B2C:** precios en el menú, pago de contado o con tarjeta, tarjeta de sellos, rapidez en el mostrador.
- **B2B:** Karla como ejecutiva, cotización por escrito, pedido fijo semanal, factura con datos exactos, crédito de 7 días, reporte mensual a cada oficina y una garantía de puntualidad.

Además, Lupita se pone una regla: ninguna oficina puede representar más del 10 % de las ventas totales, para no depender de un solo cliente.

## Las empresas gigantes
Muchas empresas gigantes son principalmente B2B: fabricantes de autopartes, empresas de software para corporaciones, constructoras, proveedores de maquinaria. Otras son principalmente B2C: cadenas de tiendas, bancos de consumo, marcas de alimentos. Y muchas hacen ambas: un banco atiende personas y empresas con áreas distintas, cada una con su propia forma de vender.`,
k: `**B2C:** venta a personas: muchos clientes, montos bajos, decisión rápida y más emocional, pago de contado. **B2B:** venta a empresas: pocos clientes, montos altos, varios decisores, ciclo largo, precio negociado, crédito y documentos formales. En B2B cuida la **formalidad**, la **confiabilidad** y la **concentración** de clientes.`,
ch: `Una panadería vende a personas en su mostrador (B2C) y a tres cafeterías por pedido con factura y crédito de 15 días (B2B); para las cafeterías tiene precios por volumen y entrega a domicilio.`,
gi: `Los bancos grandes tienen áreas separadas para banca de personas (cuentas, tarjetas, créditos de consumo) y banca de empresas (créditos corporativos, servicios de tesorería), con vendedores, productos y procesos distintos.`,
e: `Toño revisa la concentración de las ventas a oficinas:

| Cliente | Ventas al mes | % de las ventas totales (236,000) |
|---|---|---|
| Despacho A | 24,000 | 10.2 % |
| Oficina B | 12,000 | 5.1 % |
| Oficina C | 8,000 | 3.4 % |
| Otras 6 oficinas | 20,000 | 8.5 % |
| **Total oficinas** | **64,000** | **27.1 %** |

El Despacho A ya supera ligeramente el límite de 10 %. No le van a vender menos, pero Karla se enfoca en conseguir más oficinas para reducir la dependencia.`,
r: `Las grandes empresas en México suelen pedir a sus proveedores darse de alta en un portal de proveedores y presentar la opinión de cumplimiento de obligaciones fiscales emitida por el SAT, documento que acredita que el proveedor está al corriente con sus obligaciones.`,
f: `SAT, opinión del cumplimiento de obligaciones fiscales (sat.gob.mx).`,
err: ["Vender a empresas con la misma informalidad que en el mostrador.","Depender de uno o dos clientes grandes.","No planear el flujo de efectivo al vender a crédito a empresas.","Emitir facturas con datos incorrectos del cliente."],
a: `Si el negocio que observas vende a personas y a empresas, haz una tabla con las diferencias en cómo vende a cada uno. Si solo vende a personas, describe qué requisitos tendría que cumplir para empezar a vender a empresas.`,
sol: `Los requisitos más comunes para vender a empresas son: registro fiscal, facturación correcta, opinión de cumplimiento, cotizaciones por escrito y capacidad de dar crédito.`,
q: [["B2B significa…",["Venta de negocio a negocio","Venta a personas","Venta al gobierno"],0,"Business to business."],
["En la venta B2B, normalmente…",["Participan varias personas en la decisión","Decide una persona en segundos","No hay facturas"],0,"Usuario, decisor, pagador, etc."],
["¿Cuál es un riesgo típico de la venta B2B?",["Depender de pocos clientes grandes","Tener demasiados clientes pequeños","No poder vender"],0,"Si se va uno grande, el golpe es enorme."],
["Para vender a una empresa grande suele pedirse…",["Opinión de cumplimiento y facturas correctas","Nada","Solo un menú"],0,"La formalidad es indispensable."]],
t: ["B2C", "B2B"]
},
"M11-7": {
s: `Un cliente reclama a gritos que su torta llegó sin aguacate. La cajera se defiende: «No fue mi culpa». El cliente se va furioso y escribe una reseña de una estrella. Otro día, con un error parecido, Toño se disculpa, le prepara otra torta y le regala un agua. Ese cliente se vuelve uno de los más fieles.`,
o: ["Explicar por qué el servicio al cliente es parte del producto.","Aplicar un protocolo para atender quejas.","Convertir las quejas en mejoras y en lealtad."],
x: `## El servicio también se vende
El **servicio al cliente** es todo lo que hace un negocio para atender a sus clientes antes, durante y después de la compra: el trato, la rapidez, la información, la solución de problemas. Para el cliente, el servicio es parte del producto: una torta excelente servida con mala cara se recuerda como una mala experiencia.

## Las quejas son un regalo
Cuando algo sale mal, la mayoría de los clientes **no se queja**: simplemente se va y no regresa (y a veces lo cuenta a otros). Por eso, cuando un cliente se queja, está dando al negocio una **segunda oportunidad** y una información valiosa: dice qué está fallando. Un negocio que aprende de sus quejas mejora más rápido que uno que no las escucha.

## La paradoja de la recuperación del servicio
Algunos estudios han observado un fenómeno llamado **paradoja de la recuperación del servicio**: un cliente que tuvo un problema y fue atendido de forma excelente puede quedar **más satisfecho y leal** que un cliente que nunca tuvo problemas. La razón es que la buena respuesta demuestra que el negocio se preocupa por él. No significa que convenga cometer errores, sino que **cómo se responde a un error** puede convertirlo en una oportunidad.

## Un protocolo para atender quejas
Un método sencillo, con cinco pasos, que todo el equipo puede aprender:
1. **Escuchar sin interrumpir:** dejar que el cliente explique, mirarlo, no defenderse.
2. **Reconocer y disculparse:** «Tiene razón, lo siento mucho, eso no debió pasar». Disculparse no es aceptar culpas legales; es mostrar empatía.
3. **Resolver rápido:** preparar otra torta, devolver el dinero, corregir el pedido. Mientras más rápido, mejor.
4. **Compensar cuando corresponde:** un detalle que muestre que el negocio valora al cliente (un agua, un descuento en la siguiente compra).
5. **Registrar y aprender:** anotar la queja, su causa y la solución, para que no se repita.

Algunas cosas que **nunca** deben hacerse: discutir con el cliente, culpar a otro empleado frente a él, minimizar el problema («no es para tanto») o pedirle que regrese otro día para resolverlo.

## Dar poder al equipo
Para resolver rápido, las personas que atienden deben tener **autoridad** para hacerlo sin pedir permiso (lección M6-7). En Tortas Lupita, cualquier empleado puede rehacer una torta o regalar una bebida por una queja; los encargados pueden devolver el dinero. La cadena de hoteles Ritz-Carlton es conocida por permitir que sus empleados gasten hasta una cantidad determinada (se ha citado la cifra de 2,000 dólares por huésped) para resolver el problema de un cliente sin pedir autorización.

## Las quejas en internet
Hoy muchas quejas llegan como **reseñas** en mapas, redes o plataformas de reparto. Algunas recomendaciones:
- **Responder siempre**, con amabilidad y rapidez, aunque la reseña sea injusta.
- **Agradecer** la retroalimentación.
- **Disculparse** y ofrecer una solución por un canal privado (WhatsApp, teléfono).
- **No discutir en público** ni revelar datos del cliente.
- **Corregir** el problema real; si se repiten las mismas quejas, hay un problema de proceso.

Las personas que leen las reseñas suelen fijarse tanto en la respuesta del negocio como en la queja.

## Medir el servicio
Indicadores útiles:
- **Número de quejas** (por cada 1,000 ventas, para comparar meses).
- **Tipos de queja:** tiempo, calidad, error en el pedido, trato, precio.
- **Tiempo de respuesta** a quejas y reseñas.
- **Calificación promedio** en reseñas.
- **NPS** (lección M11-4).
- **Clientes recuperados:** quienes se quejaron y volvieron.

## Del caso a la mejora
Cada queja debe llevar a una pregunta: **¿por qué pasó y cómo evitamos que vuelva a pasar?** Si varios clientes se quejan de tortas sin aguacate, el problema no es un cocinero distraído: quizá el aguacate se acaba a cierta hora (inventario, lección M9-6) o la comanda no indica bien los ingredientes (proceso, lección M9-2). Aplicar los cinco porqués (lección M9-7) a las quejas frecuentes es una de las formas más efectivas de mejorar un negocio.

## La protección al consumidor
En México, la **Procuraduría Federal del Consumidor (Profeco)** atiende las quejas de los consumidores contra los negocios y vigila que se respeten sus derechos: precios exhibidos, información veraz, garantías, cumplimiento de lo prometido, cobros correctos. Un negocio que atiende bien las quejas rara vez llega a la Profeco. El Módulo 14 trata estos temas con más detalle.

## El cambio en Tortas Lupita
Lupita capacita a todo el equipo en el protocolo de cinco pasos y en la regla de autoridad. Además, crea una hoja de quejas: cada semana revisan las más frecuentes en la junta. En dos meses, las quejas por errores en el pedido bajan a la mitad y la calificación en mapas sube de 4.2 a 4.6.

## Prevenir es mejor que remediar
El mejor servicio es el que evita que haya quejas: confirmar el pedido antes de entregarlo, avisar si habrá un retraso y preguntar «¿todo bien?» antes de que el cliente se vaya.`,
k: `El **servicio** es parte del producto. Las **quejas son un regalo**: la mayoría de los clientes insatisfechos no se queja, se va. **Paradoja de la recuperación:** una buena respuesta a un error puede aumentar la lealtad. Protocolo: **escuchar, disculparse, resolver rápido, compensar, registrar y aprender**. Da **autoridad** al equipo para resolver. Responde siempre las reseñas.`,
ch: `Una zapatería que cambia sin discutir un par defectuoso, aunque el cliente no traiga el ticket, gana un cliente fiel y una reseña de cinco estrellas.`,
gi: `Ritz-Carlton es conocida por permitir a sus empleados gastar una cantidad determinada por huésped para resolver problemas sin pedir autorización, como parte de su cultura de servicio.`,
e: `Toño compara el costo de atender bien una queja con el valor del cliente:

| Concepto | Pesos |
|---|---|
| Costo de rehacer la torta y regalar un agua | 16 + 3 = 19 |
| Gasto del cliente por visita | 46 |
| Visitas al mes de un cliente frecuente | 8 |
| Valor del cliente en un año (46 × 8 × 12) | 4,416 |

Gastar 19 pesos para conservar a un cliente que deja más de 4,000 pesos al año (y que además recomienda) es una de las mejores inversiones del negocio.`,
r: `La paradoja de la recuperación del servicio fue descrita por Michael McCollough y Sundar Bharadwaj en 1992. Estudios posteriores han encontrado que el efecto existe en algunos casos, sobre todo cuando el problema no es grave y la respuesta es rápida y generosa, aunque no se presenta siempre.`,
f: `M. McCollough y S. Bharadwaj (1992); The Ritz-Carlton Leadership Center, materiales sobre empoderamiento de empleados; Profeco (gob.mx/profeco).`,
err: ["Discutir con el cliente o culpar a otros frente a él.","No dar autoridad al equipo para resolver.","Ignorar las reseñas negativas.","Resolver el caso y no buscar la causa."],
a: `Escribe el protocolo de atención de quejas del negocio que observas (cinco pasos, qué puede hacer cada puesto sin pedir permiso). Busca tres reseñas negativas reales de un negocio cualquiera y redacta una respuesta para cada una.`,
sol: `Una buena respuesta a una reseña agradece, se disculpa, no discute, ofrece una solución por un canal privado y es breve.`,
q: [["¿Qué hace la mayoría de los clientes insatisfechos?",["Se va sin quejarse","Se queja siempre","Pide hablar con el gerente"],0,"Por eso las quejas son valiosas."],
["El primer paso para atender una queja es…",["Escuchar sin interrumpir","Defenderse","Pedirle que regrese otro día"],0,"Dejar que el cliente explique."],
["La paradoja de la recuperación del servicio dice que…",["Una buena respuesta a un error puede aumentar la lealtad","Equivocarse siempre es bueno","Las quejas no importan"],0,"Depende de cómo se responda."],
["¿Por qué dar autoridad al equipo para resolver quejas?",["Para resolver rápido sin esperar autorización","Para gastar más","Para no capacitar"],0,"La rapidez es clave."]],
t: ["Servicio al cliente", "Queja"]
},
"M11-8": {
s: `Toño hace cuentas: conseguir un cliente nuevo con anuncios cuesta unos 50 pesos, pero un cliente que viene dos veces por semana durante un año deja miles. «Entonces», dice, «lo más rentable no es conseguir clientes, sino conservarlos».`,
o: ["Explicar por qué retener clientes es tan valioso.","Calcular el valor de vida del cliente.","Diseñar acciones para aumentar la lealtad y la recompra."],
x: `## Conseguir no basta: hay que conservar
Muchos negocios dedican casi todo su esfuerzo a conseguir clientes nuevos y muy poco a conservar a los que ya tienen. Pero un cliente que regresa es mucho más valioso: ya conoce el negocio, compra con más frecuencia, gasta más con el tiempo, cuesta menos atenderlo y recomienda a otros. Conservarlo suele costar menos que conseguir uno nuevo.

En 1990, Frederick Reichheld y W. Earl Sasser publicaron en Harvard Business Review un estudio, «Zero Defections», en el que estimaron, para varias industrias de servicios, que reducir en 5 puntos la tasa de clientes que se van podía aumentar las utilidades de forma muy importante (en sus ejemplos, entre 25 % y 85 %, según la industria). Las cifras exactas dependen del negocio, pero la idea se volvió central en la administración: **la lealtad de los clientes es una fuente enorme de utilidades**.

## La retención y el abandono
- **Tasa de retención:** porcentaje de clientes que siguen comprando después de un periodo.
- **Tasa de abandono** (en inglés, *churn*): porcentaje de clientes que dejan de comprar en un periodo.

Retención + abandono = 100 %. Si de 100 oficinas clientes, al cabo de un año siguen 80, la retención anual es 80 % y el abandono 20 %.

En negocios de mostrador es más difícil medirlo, porque no siempre se sabe quién es cada cliente. Por eso ayudan los programas de lealtad, las tarjetas de sellos y los registros de clientes frecuentes.

## El valor de vida del cliente
El **valor de vida del cliente** (en inglés, LTV, *lifetime value*) es una estimación de cuánto deja un cliente durante todo el tiempo que compra en el negocio. Una forma sencilla de calcularlo en **margen** (lo que realmente le queda al negocio):

**Valor de vida = ticket promedio × compras por periodo × margen × número de periodos que dura el cliente**

Ejemplo, un oficinista frecuente de Tortas Lupita:
- Ticket promedio: 85 pesos (torta más refresco y, a veces, una torta para llevar).
- Compras al mes: 4.
- Margen bruto: 55 %.
- Meses que dura como cliente: 12.

Valor de vida = 85 × 4 × 0.55 × 12 = **2,244 pesos** de margen.

Para una oficina con pedido semanal de 6,000 pesos al mes, con margen de 60 % y una duración de 18 meses: 6,000 × 0.6 × 18 = **64,800 pesos**.

Saber esto cambia las decisiones: vale la pena regalar una bebida para conservar al oficinista, y vale mucho la pena que Karla visite cada mes a la oficina para asegurarse de que está contenta.

## Por qué se van los clientes
Los clientes se van por muchas razones:
- **Una mala experiencia** que no se resolvió.
- **Indiferencia:** sienten que al negocio no le importa si regresan.
- **Mejor oferta** de la competencia (precio, conveniencia, calidad).
- **Cambio en su vida:** se mudan, cambian de trabajo, cambian de hábitos.
- **Errores repetidos.**
- **Falta de novedad:** se aburren del mismo producto.

Algunas causas no se pueden controlar (una mudanza), pero muchas sí.

## Cómo aumentar la lealtad
1. **Cumplir siempre:** la base de la lealtad es la confianza; un servicio constante es más importante que los regalos.
2. **Reconocer al cliente:** saludarlo por su nombre, recordar su pedido.
3. **Programas de lealtad:** tarjeta de sellos, puntos, beneficios para clientes frecuentes.
4. **Comunicación oportuna:** avisar de novedades, sin saturar.
5. **Pedir opinión** y actuar sobre ella.
6. **Atender bien las quejas** (lección M11-7).
7. **Sorprender de vez en cuando:** un detalle inesperado.
8. **Facilitar la recompra:** pedido fijo semanal, «lo de siempre» por WhatsApp, suscripción (lección M4-5).
9. **Detectar a tiempo a quien se está yendo:** la oficina que bajó sus pedidos, el cliente que dejó de venir.

## Programas de lealtad: cuidado con los costos
Un programa de lealtad cuesta: descuentos, productos gratis, administración. Funciona si:
- Premia la **frecuencia** (lo que el negocio quiere).
- Es **sencillo** de entender y usar.
- Su costo es **menor** que el margen adicional que genera.
- Da **información** sobre los clientes (en los programas digitales).

La tarjeta de sellos de Tortas Lupita (la décima torta gratis) cuesta, en ingredientes, 16 pesos por cada 9 tortas vendidas a un cliente frecuente: alrededor de 4 % del precio. Si gracias a ella el cliente viene una vez más al mes, el programa se paga solo.

## Hacer crecer al cliente
Además de conservarlo, se puede lograr que el cliente compre más:
- **Venta cruzada:** ofrecer otros productos (agua fresca, postre, la salsa en frasco).
- **Venta de mayor valor:** ofrecer una opción más completa (torta grande, combo).
- **Ampliar el uso:** que la oficina que pide los viernes también pida para las juntas del martes.

## La lealtad en empresas gigantes
Las grandes empresas tienen programas de lealtad muy elaborados. **Starbucks Rewards**, por ejemplo, combina puntos, pedidos anticipados desde una aplicación y ofertas personalizadas, y la empresa ha informado que sus miembros representan una parte muy importante de sus ventas en Estados Unidos. Las aerolíneas tienen programas de viajero frecuente; los supermercados, tarjetas de puntos. Todos buscan lo mismo que la tarjeta de sellos de Lupita: que el cliente regrese.`,
k: `Conservar clientes suele ser más rentable que conseguirlos (Reichheld y Sasser, 1990). **Retención** + **abandono** = 100 %. **Valor de vida (LTV) = ticket × compras por periodo × margen × periodos.** Aumenta la lealtad cumpliendo siempre, reconociendo al cliente, con **programas de lealtad** rentables y **facilitando la recompra**. Haz crecer al cliente con **venta cruzada**.`,
ch: `Una tintorería llama a los clientes que no han venido en dos meses con un descuento de regreso; recupera a uno de cada cuatro.`,
gi: `Starbucks ha informado que los miembros de su programa Starbucks Rewards generan una proporción muy importante de sus ventas en Estados Unidos; el programa combina puntos, pedidos por la aplicación y ofertas personalizadas.`,
e: `Toño calcula cuánto vale reducir el abandono de oficinas de 30 % a 15 % al año (con 20 oficinas que compran 6,000 al mes cada una, margen de 60 %):

| Escenario | Oficinas al final del año (sin nuevas) | Margen mensual al final del año |
|---|---|---|
| Abandono de 30 % | 14 | 14 × 6,000 × 0.6 = 50,400 |
| Abandono de 15 % | 17 | 17 × 6,000 × 0.6 = 61,200 |

Reducir el abandono a la mitad deja 10,800 pesos más de margen al mes, sin conseguir ni una oficina nueva.`,
r: `Frederick Reichheld y W. Earl Sasser Jr. publicaron «Zero Defections: Quality Comes to Services» en Harvard Business Review en 1990, donde mostraron con ejemplos de varias industrias que pequeñas reducciones en el abandono de clientes podían aumentar mucho las utilidades. Starbucks informa sobre su programa de lealtad en sus reportes a inversionistas.`,
f: `F. Reichheld y W. E. Sasser, «Zero Defections», Harvard Business Review (1990); Starbucks Corporation, reportes trimestrales y Form 10-K.`,
err: ["Dedicar todo el esfuerzo a conseguir clientes y olvidar a los actuales.","Crear un programa de lealtad que cuesta más de lo que genera.","No detectar a tiempo a los clientes que se están yendo.","Creer que los regalos sustituyen a un buen servicio constante."],
a: `Calcula el valor de vida de dos tipos de cliente del negocio que observas (uno ocasional y uno frecuente) con la calculadora CAC/LTV. Propón dos acciones para aumentar la retención del cliente frecuente.`,
sol: `Compara el valor de vida con lo que cuesta conseguir a cada cliente: si el frecuente vale 20 veces más, conviene invertir en conservarlo.`,
q: [["La tasa de abandono (churn) es…",["El porcentaje de clientes que dejan de comprar en un periodo","El número de quejas","El margen"],0,"Retención + abandono = 100 %."],
["Con ticket de 50, 4 compras al mes, margen de 50 % y 10 meses, el valor de vida es…",["1,000 pesos","2,000 pesos","200 pesos"],0,"50 × 4 × 0.5 × 10."],
["¿Por qué suele ser rentable retener clientes?",["Compran más con el tiempo, cuestan menos de atender y recomiendan","Porque no pagan","Porque no hay competencia"],0,"La lealtad es fuente de utilidades."],
["La venta cruzada consiste en…",["Ofrecer otros productos al mismo cliente","Vender a la competencia","Bajar precios"],0,"Por ejemplo, el agua fresca con la torta."]],
t: ["Retención de clientes", "Tasa de abandono (churn)"]
},
"M11-9": {
s: `Lupita quiere saber, con números, si su negocio atrae, convierte y conserva bien a sus clientes. Toño prepara un tablero de ventas con seis indicadores y la calculadora del curso. Por primera vez, las ventas dejan de ser «buenas» o «malas» y se vuelven números que se pueden mejorar.`,
o: ["Calcular las principales métricas de ventas.","Relacionar el costo de adquirir un cliente con su valor de vida.","Construir un tablero de ventas sencillo."],
x: `## Medir las ventas
Las ventas totales dicen cuánto se vendió, pero no por qué ni cómo mejorar. Las **métricas de ventas** descomponen el resultado en piezas que se pueden entender y mejorar. Las más útiles para un negocio son seis.

## 1. Ticket promedio
**Ticket promedio = ventas ÷ número de tickets (compras)**

Indica cuánto gasta cada cliente en cada compra (lección M5-2). Se mejora con combos, venta cruzada y productos de mayor valor.

## 2. Tasa de conversión
**Conversión = compradores ÷ personas que tuvieron contacto con el negocio × 100**

Indica qué porcentaje de las personas que pasan, entran, preguntan o reciben una propuesta termina comprando (lección M11-3).

Ejemplo del plan del curso: si 1,000 personas pasan frente al local y 120 compran, la conversión es **12 %**. Con un ticket promedio de 85 pesos, las ventas son 120 × 85 = **10,200 pesos**.

## 3. Costo de adquisición de clientes (CAC)
**CAC = gasto en marketing y ventas ÷ número de clientes nuevos**

Indica cuánto cuesta, en promedio, conseguir un cliente nuevo. Incluye publicidad, promociones de bienvenida, sueldos y comisiones de vendedores dedicados a conseguir clientes, degustaciones, etc. Ejemplo: si en un mes se gastan 6,000 pesos y llegan 120 clientes nuevos, el CAC es **50 pesos**.

## 4. Valor de vida del cliente (LTV)
**LTV = ticket promedio × compras por periodo × margen × periodos que dura el cliente**

Indica cuánto margen deja un cliente durante toda su relación con el negocio (lección M11-8). Ejemplo: 85 × 4 × 0.55 × 12 = **2,244 pesos**.

## 5. La relación LTV / CAC
**Relación = LTV ÷ CAC**

Es una de las métricas más importantes para decidir cuánto invertir en conseguir clientes:
- **Menor que 1:** cada cliente cuesta más de lo que deja. El negocio pierde dinero al crecer.
- **Entre 1 y 3:** se recupera la inversión, pero con poco margen para otros gastos.
- **Mayor que 3:** relación sana; muchas empresas usan 3 como referencia mínima deseable, aunque depende del negocio.
- **Mucho mayor (por ejemplo, 40):** quizá se está invirtiendo muy poco en crecer; podría convenir gastar más en atraer clientes.

En el ejemplo: 2,244 ÷ 50 = **44.9**. Tortas Lupita gasta muy poco para conseguir clientes en relación con lo que valen. Le conviene invertir más en atraer oficinistas de la zona.

Otra métrica relacionada es el **tiempo de recuperación del CAC**: cuántos meses tarda un cliente en dejar suficiente margen para pagar lo que costó conseguirlo. Con 85 × 4 × 0.55 = 187 pesos de margen al mes y un CAC de 50, se recupera en menos de un mes.

## 6. Retención y abandono
**Retención = clientes que siguen al final del periodo ÷ clientes al inicio × 100** (sin contar a los nuevos).

Indica qué tan bien se conservan los clientes. En negocios de suscripción, contratos o pedidos fijos (como las oficinas), es fácil de medir; en el mostrador, se estima con la tarjeta de sellos o con registros de clientes frecuentes.

## Otras métricas útiles
- **Clientes nuevos por mes** y por canal.
- **Frecuencia de compra:** cuántas veces compra un cliente en un periodo.
- **Ventas por vendedor** y conversión por vendedor.
- **Ciclo de venta:** cuánto tarda en cerrarse una venta a empresas.
- **NPS** y calificación en reseñas (lecciones M11-4 y M11-7).
- **Participación de los productos** en las ventas (mezcla).

## El tablero de ventas de Tortas Lupita
| Métrica | Fórmula | Mes actual | Meta | Estado |
|---|---|---|---|---|
| Ventas totales | — | 236,000 | 250,000 | Amarillo |
| Ticket promedio de mostrador | Ventas ÷ tickets | 46 | 48 | Amarillo |
| Conversión de mostrador | Compradores ÷ personas que pasan | 12 % | 14 % | Amarillo |
| Clientes nuevos de mostrador | Pregunta «¿es su primera vez?» | 120 | 150 | Amarillo |
| CAC | Gasto ÷ clientes nuevos | 50 | Menos de 80 | Verde |
| Oficinas activas | Conteo | 9 | 12 | Rojo |
| Retención de oficinas (trimestral) | Oficinas que siguen ÷ oficinas al inicio | 89 % | 90 % | Amarillo |

Con este tablero, en la junta semanal se ve de inmediato dónde actuar: este mes, conseguir más oficinas.

## Cuidado con las métricas
- **Las métricas se pueden manipular:** si se premia la conversión, alguien podría dejar de contar a quienes no compran. Hay que revisar cómo se mide.
- **Los promedios esconden diferencias:** el ticket promedio puede subir porque llegó un pedido enorme de una oficina, no porque los clientes de mostrador gasten más.
- **El LTV es una estimación:** depende de supuestos (¿cuánto dura un cliente?); conviene ser conservador.
- **No todo se mide en números:** las conversaciones con clientes siguen siendo indispensables.

## En las empresas gigantes
Las empresas de suscripción y de tecnología siguen con mucha atención el CAC, el LTV y el abandono, porque de ellos depende si su crecimiento es rentable. Los inversionistas de empresas emergentes suelen pedir estas métricas antes de invertir (Módulo 19). Las cadenas de tiendas, por su parte, siguen el tráfico de clientes, la conversión y el ticket promedio por tienda, cada día. Con la calculadora «Costo por cliente (CAC) y valor de vida (LTV)» del curso puedes hacer estos cálculos con tus propios números.`,
hr: "caclt",
k: `Métricas clave: **ticket promedio**, **conversión** (compradores ÷ contactos), **CAC** (gasto ÷ clientes nuevos), **LTV** (ticket × frecuencia × margen × duración), **LTV/CAC** (más de 3 se considera sano) y **retención**. Ejemplo del plan: 1,000 pasan, 120 compran, ticket 85 → **conversión 12 %** y **ventas 10,200**. Cuidado con promedios y manipulación.`,
ch: `Un gimnasio de barrio calcula que conseguir un socio le cuesta 400 pesos en publicidad y que cada socio deja 300 pesos de margen al mes durante 8 meses (2,400): su relación LTV/CAC es 6.`,
gi: `Las empresas de suscripción, como las plataformas de video o de software, informan o siguen de cerca métricas como el número de suscriptores, el ingreso promedio por usuario y el abandono, porque determinan si su crecimiento es rentable.`,
e: `Toño calcula las métricas de un mes con la calculadora:

| Dato | Valor |
|---|---|
| Gasto en marketing y ventas | 6,000 |
| Clientes nuevos | 120 |
| Ticket promedio | 85 |
| Compras por cliente al mes | 4 |
| Margen bruto | 55 % |
| Meses que dura un cliente | 12 |
| **CAC** | 6,000 ÷ 120 = **50** |
| **LTV** | 85 × 4 × 0.55 × 12 = **2,244** |
| **LTV / CAC** | **44.9** |

Conclusión: puede aumentar con confianza su inversión en atraer clientes de la zona.`,
r: `Los inversionistas de capital emprendedor suelen analizar la relación entre el valor de vida del cliente y el costo de adquisición para evaluar si una empresa emergente crece de forma rentable; una referencia que aparece con frecuencia en la industria es que el LTV sea al menos tres veces el CAC.`,
f: `David Skok, «SaaS Metrics 2.0» (forEntrepreneurs); materiales de capital emprendedor sobre métricas de unidad.`,
err: ["Mirar solo las ventas totales.","Calcular el LTV con ventas en lugar de margen.","Olvidar incluir sueldos de vendedores en el CAC.","Confiar en un LTV con supuestos demasiado optimistas."],
a: `Con la calculadora «CAC y LTV», calcula las métricas del negocio que observas (estima los datos que no tengas). Arma un tablero de ventas con cinco métricas, su meta y su estado.`,
sol: `Si tu LTV/CAC es menor que 1, revisa primero la retención y el margen antes de gastar más en publicidad.`,
q: [["Si 1,000 personas pasan y 120 compran con ticket de 85, las ventas son…",["10,200 pesos","8,500 pesos","120,000 pesos"],0,"120 × 85."],
["El CAC se calcula como…",["Gasto en marketing y ventas ÷ clientes nuevos","Ventas ÷ clientes","Margen × clientes"],0,"Costo de adquisición de clientes."],
["Una relación LTV/CAC menor que 1 significa que…",["Cada cliente cuesta más de lo que deja","El negocio es muy rentable","No hay clientes"],0,"Crecer así pierde dinero."],
["¿Por qué el LTV debe calcularse con margen?",["Porque lo que importa es lo que le queda al negocio, no lo que vende","Porque es más grande","Porque lo pide el SAT"],0,"Las ventas incluyen costos."]],
t: ["Métricas de ventas", "Costo de adquisición de clientes (CAC)"]
}
});
// ===== M12. Marketing =====
Object.assign(window.LECC, {
"M12-1": {
s: `Toño cree que marketing es «hacer anuncios». Karla dice que su trabajo de ventas se facilita cuando la gente ya conoce Tortas Lupita. Lupita se pregunta dónde termina una cosa y empieza la otra.`,
o: ["Definir qué es el marketing.","Distinguir marketing y ventas, y cómo se complementan.","Reconocer las tareas del área de marketing en negocios de distinto tamaño."],
x: `## ¿Qué es el marketing?
El **marketing** (o mercadotecnia) es el conjunto de actividades para **entender a los clientes**, **crear una oferta** que les dé valor, **comunicarla** y **llevarla** hasta ellos, de forma que el negocio gane y el cliente quede satisfecho. Philip Kotler, uno de los autores más influyentes en la materia, lo resume como el proceso de crear, comunicar y entregar valor a los clientes y de construir relaciones rentables con ellos.

Muchas personas creen que marketing es solo publicidad. La publicidad es una parte pequeña. El marketing empieza **antes** de tener el producto (¿qué necesita el cliente?, ¿qué ofrece la competencia?) y continúa **después** de la venta (¿quedó contento?, ¿regresará?).

## Marketing y ventas
| Aspecto | Marketing | Ventas |
|---|---|---|
| Pregunta central | ¿A quién le vendemos, qué y por qué nos elegirían? | ¿Cómo convertimos a este cliente en comprador? |
| Horizonte | Mediano y largo plazo | Corto plazo |
| Alcance | Muchos clientes (segmentos) | Clientes individuales |
| Tareas | Investigar, segmentar, posicionar, diseñar oferta, fijar precio, comunicar, construir marca | Prospectar, presentar, negociar, cerrar, dar seguimiento |
| Resultado | Clientes que conocen, prefieren y buscan al negocio | Pedidos y cobros |

Peter Drucker escribió que el objetivo del marketing es hacer **innecesaria** la venta: conocer tan bien al cliente que el producto «se venda solo». En la práctica, casi siempre hacen falta ambas cosas, pero la idea muestra la relación: un buen marketing hace mucho más fácil el trabajo de ventas.

## Las tareas del marketing
1. **Investigar el mercado:** quiénes son los clientes, qué necesitan, qué ofrece la competencia (lección M12-2).
2. **Segmentar y elegir a quién atender** (lección M12-3).
3. **Posicionar:** decidir qué lugar se quiere ocupar en la mente del cliente.
4. **Diseñar la oferta** con las 4P: producto, precio, plaza y promoción (lección M12-4).
5. **Construir y cuidar la marca** (lección M12-5).
6. **Comunicar:** publicidad, redes sociales, relaciones públicas, promociones (lecciones M12-6 y M12-7).
7. **Medir** los resultados y ajustar (lección M12-8).
8. **Cuidar la relación** con los clientes (con ventas y servicio al cliente).

## Marketing según el tamaño del negocio
- **Changarro:** el marketing es intuitivo: el dueño conoce a sus clientes, cuida su letrero y su trato, y depende del boca a boca.
- **Pyme:** alguien se encarga (a veces el dueño) de las redes sociales, las promociones, el diseño de menús y letreros, y quizá se contrata a una agencia o a un independiente.
- **Empresa grande:** una dirección de marketing con áreas de investigación de mercado, gerentes de marca, publicidad, medios digitales, promociones, comunicación, y presupuestos de millones.

## El marketing como forma de pensar
Más que un área, el marketing es una **forma de pensar el negocio desde el cliente**. Las empresas que la adoptan se preguntan primero «¿qué necesita el cliente?» y después «¿qué podemos ofrecerle?». Las que no la adoptan empiezan por «¿qué sabemos hacer?» y luego buscan a quién vendérselo.

Theodore Levitt, profesor de Harvard, publicó en 1960 un artículo famoso, «Miopía en el marketing», en el que advertía que muchas empresas fracasan porque se definen por su producto y no por la necesidad que satisfacen. Su ejemplo: los ferrocarriles de Estados Unidos perdieron terreno porque se veían como empresas «de trenes» y no «de transporte», y dejaron que los autos, camiones y aviones se quedaran con sus clientes. Para Tortas Lupita, la pregunta sería: ¿somos un negocio «de tortas» o un negocio que resuelve «comer bien y rápido cerca del trabajo»? La segunda definición abre más posibilidades (desayunos, ensaladas, comida para juntas).

## Marketing ético
El marketing tiene un enorme poder para influir en las decisiones de las personas. Por eso conlleva responsabilidades:
- **Decir la verdad:** no prometer lo que el producto no cumple.
- **Respetar a los clientes vulnerables:** niños, personas mayores.
- **Cuidar los datos personales** de los clientes (Módulo 14).
- **Cumplir las reglas** de publicidad y etiquetado.

En México, la Ley Federal de Protección al Consumidor y la Profeco vigilan la publicidad engañosa, y existen normas específicas de etiquetado de alimentos y bebidas.

## El plan de Lupita
Lupita decide que el marketing de Tortas Lupita tendrá tres objetivos para el año: que más oficinistas de la zona conozcan el local, que los clientes de mostrador vengan con más frecuencia y que las oficinas encuentren fácil hacer pedidos. Asigna a Toño la responsabilidad de marketing (con apoyo de una diseñadora independiente) y le pide coordinarse cada semana con Karla, que se ocupa de las ventas a oficinas. En las siguientes lecciones construirán juntos el plan.

## El marketing en números
Para el negocio, el marketing es una inversión que debe dar resultados medibles: más clientes que conocen la marca, más clientes que la eligen, más clientes que regresan y un costo razonable por cada cliente conseguido. Por eso, aunque tiene mucho de creatividad, el buen marketing también tiene mucho de disciplina: objetivos claros, presupuesto, calendario y medición. Un error frecuente en negocios pequeños es hacer marketing «cuando hay tiempo» o «cuando las ventas bajan»; los resultados suelen ser mejores cuando se hace de forma constante, con un plan sencillo y revisado cada mes. En la lección M12-8 verás cómo medir si el marketing está funcionando y cuánto devuelve cada peso invertido.`,
k: `**Marketing:** entender al cliente, crear una oferta con valor, comunicarla y entregarla, con relaciones rentables (Kotler). No es solo publicidad. **Marketing** piensa en segmentos y en el largo plazo; **ventas**, en clientes concretos y el cierre. Drucker: el marketing busca hacer **innecesaria** la venta. **Miopía en el marketing** (Levitt, 1960): definirse por el producto y no por la necesidad.`,
ch: `Una estética de barrio hace marketing sin saberlo: pregunta a sus clientas qué servicios quieren, pone fotos de sus trabajos en redes, tiene precios visibles y manda un mensaje de cumpleaños con un descuento.`,
gi: `Las grandes empresas de consumo, como Procter & Gamble, se hicieron famosas por organizarse alrededor de gerentes de marca responsables de entender a los consumidores y de toda la estrategia de cada producto.`,
e: `Toño distribuye las tareas de marketing y ventas en Tortas Lupita:

| Tarea | Marketing (Toño) | Ventas (Karla) |
|---|---|---|
| Encuesta a clientes de la zona | ✓ | |
| Menú, fotos y letreros | ✓ | |
| Redes sociales y perfil en mapas | ✓ | |
| Promoción de la tarjeta de sellos | ✓ | |
| Lista de oficinas por visitar | Apoya con datos | ✓ |
| Visitas, propuestas y cierres | | ✓ |
| Material para las oficinas (folleto, menú de paquetes) | ✓ | Usa |
| Revisión semanal de resultados | ✓ | ✓ |`,
r: `Theodore Levitt publicó «Marketing Myopia» en Harvard Business Review en 1960. El artículo, uno de los más reproducidos de la revista, usó el caso de los ferrocarriles estadounidenses para argumentar que las empresas deben definirse por las necesidades de sus clientes y no por sus productos.`,
f: `Theodore Levitt, «Marketing Myopia», Harvard Business Review (1960); Philip Kotler y Gary Armstrong, «Fundamentos de marketing»; Peter Drucker, «Management: Tasks, Responsibilities, Practices» (1973).`,
err: ["Creer que marketing es solo hacer anuncios.","Que marketing y ventas no se hablen.","Definir el negocio por el producto y no por la necesidad.","Hacer publicidad engañosa."],
a: `Describe el negocio que observas de dos formas: por su producto («vendemos…») y por la necesidad que resuelve («ayudamos a… a…»). Después lista tres tareas de marketing que hoy no hace y que podría empezar.`,
sol: `Si la definición por necesidad te abre ideas de nuevos productos o clientes, evitaste la miopía de marketing.`,
q: [["El marketing incluye…",["Entender al cliente, diseñar la oferta, comunicarla y entregarla","Solo poner anuncios","Solo cobrar"],0,"Es mucho más que publicidad."],
["La diferencia principal entre marketing y ventas es que…",["Marketing piensa en segmentos y en el largo plazo; ventas, en el cierre con cada cliente","Son exactamente lo mismo","Ventas hace los anuncios"],0,"Se complementan."],
["La «miopía en el marketing» consiste en…",["Definirse por el producto y no por la necesidad del cliente","Ver mal los anuncios","Gastar mucho en publicidad"],0,"Según Theodore Levitt (1960)."],
["¿Qué autor dijo que el objetivo del marketing es hacer innecesaria la venta?",["Peter Drucker","Adam Smith","Henri Fayol"],0,"La idea: conocer tan bien al cliente que el producto se venda solo."]],
t: ["Marketing", "Miopía en el marketing"]
},
"M12-2": {
s: `Lupita quiere lanzar desayunos, pero no sabe si habría clientes. Toño propone una encuesta. Karla sugiere contar cuánta gente pasa a las 8:00. Un amigo dice: «Contrata a una empresa de estudios de mercado». Eso cuesta decenas de miles de pesos. ¿Se puede investigar sin gastar tanto?`,
o: ["Distinguir fuentes de información secundarias y primarias.","Diseñar una investigación de mercado barata.","Evitar errores comunes al preguntar a los clientes."],
x: `## ¿Para qué investigar el mercado?
La **investigación de mercado** busca información para tomar mejores decisiones: ¿hay suficientes clientes?, ¿qué quieren?, ¿cuánto pagarían?, ¿qué ofrece la competencia?, ¿funcionará este producto nuevo? Sin investigación, las decisiones se basan en suposiciones o en lo que «le parece» al dueño. Con ella, se reduce el riesgo de gastar dinero en algo que nadie quiere.

No hace falta contratar a una empresa grande. Muchos negocios pequeños pueden obtener información muy útil con poco dinero, si saben qué preguntar y a quién.

## Fuentes secundarias: lo que ya existe
Las **fuentes secundarias** son datos que otros ya recolectaron. Son baratas o gratuitas y conviene revisarlas primero:
- **INEGI:** los Censos Económicos y de Población, la Encuesta Nacional de Ingresos y Gastos de los Hogares (ENIGH), la Encuesta Nacional de Ocupación y Empleo y, muy útil para negocios locales, el **DENUE** (Directorio Estadístico Nacional de Unidades Económicas), un mapa en línea donde se pueden ver los negocios registrados en una zona por tipo de actividad. Con él, Lupita puede saber cuántas oficinas, escuelas y restaurantes hay a un kilómetro de su local.
- **Cámaras y asociaciones empresariales:** publican estudios de su sector.
- **Informes de empresas en bolsa:** describen tendencias de su industria.
- **Prensa económica y estudios universitarios.**
- **Internet:** las páginas, menús, precios y reseñas de la competencia.

## Fuentes primarias: lo que tú recolectas
Las **fuentes primarias** son datos que el negocio obtiene directamente para su pregunta. Las formas más baratas:
1. **Observación:** contar cuántas personas pasan a cierta hora, cuántas entran a la competencia, qué compran, cuánto esperan. Es barata y muy confiable, porque mide lo que la gente **hace**, no lo que **dice**.
2. **Entrevistas:** conversaciones de 10 a 15 minutos con clientes o posibles clientes, con preguntas abiertas («¿Dónde desayunas los días de trabajo? ¿Qué te gustaría que hubiera?»).
3. **Encuestas:** cuestionarios breves en papel o en línea, con preguntas cerradas para contar respuestas («¿Cuántos días a la semana desayunas fuera de casa? 0 / 1–2 / 3–4 / 5»).
4. **Cliente misterioso:** visitar a la competencia (o el propio negocio) como cliente para evaluar la experiencia.
5. **Prueba piloto:** vender el producto nuevo durante una o dos semanas en pequeño y medir cuánto se vende. Es la forma más confiable de saber si algo funciona.
6. **Datos propios:** las ventas por producto, hora y día que registra el sistema de punto de venta (Módulo 15).

## Lo que la gente dice y lo que la gente hace
Un problema conocido de las encuestas es que **la gente dice una cosa y hace otra**. Muchas personas responden «sí, compraría desayunos saludables» y luego siguen comprando tamales. Por eso:
- Prefiere preguntar por el **comportamiento pasado** («¿qué desayunaste ayer y dónde?») que por el futuro («¿comprarías…?»).
- Combina la encuesta con **observación** y con una **prueba piloto**.
- Desconfía de las respuestas «de cortesía»: a nadie le gusta decirle a la dueña que su idea no le interesa.

## Cómo hacer una buena encuesta
- **Define primero la decisión** que quieres tomar («¿lanzo desayunos?, ¿a qué precio?»).
- **Pocas preguntas:** de 5 a 10; una encuesta larga se abandona.
- **Preguntas claras y neutrales:** «¿Qué tan probable es que…?» y no «¿Verdad que te encantaría…?».
- **Una idea por pregunta.**
- **Opciones de respuesta completas** que no se traslapen.
- **Pregunta a las personas adecuadas:** si quieres vender desayunos a oficinistas, encuesta a oficinistas a las 8:00, no a estudiantes a las 14:00.
- **Suficientes respuestas:** para tener una idea general en un negocio local, varias decenas de respuestas bien elegidas suelen dar una orientación útil; para conclusiones más precisas, hacen falta más y un muestreo cuidadoso.

## La investigación de Tortas Lupita para los desayunos
| Método | Qué hicieron | Qué encontraron |
|---|---|---|
| DENUE (INEGI) | Contaron oficinas y escuelas en 1 km | 85 oficinas y 3 escuelas |
| Observación | Contaron personas de 7:30 a 9:30 frente al local, 3 días | 600 personas por mañana; 1 de cada 3 con café o pan en la mano |
| Cliente misterioso | Visitaron dos cafeterías cercanas | Desayunos de 70 a 95 pesos; filas largas a las 8:30 |
| Encuesta | 60 oficinistas, 6 preguntas | 45 % desayuna fuera 3 o más días; precio aceptable: 50 a 65 pesos; quieren rapidez |
| Prueba piloto | Dos semanas con 3 desayunos a 55 pesos | Promedio de 70 desayunos diarios a partir de la segunda semana |

Con esta información, gastando muy poco, Lupita decide lanzar los desayunos.

## Investigar de forma continua
La investigación no es solo para grandes decisiones. Un negocio que pregunta con regularidad a sus clientes, observa a su competencia y revisa sus propios datos se entera antes que nadie de los cambios del mercado. Una caja de sugerencias, una pregunta en la caja («¿qué le gustaría que tuviéramos?») y una visita trimestral a la competencia ya son investigación de mercado.

## En las empresas gigantes
Las grandes empresas invierten mucho en investigación: estudios de consumidores en varios países, grupos de enfoque, paneles de hogares que registran sus compras, pruebas de productos en tiendas seleccionadas antes de lanzarlos a todo el país, análisis de millones de transacciones. Pero también usan los métodos sencillos: muchas cadenas prueban un producto nuevo en unas cuantas tiendas antes de llevarlo a todas, exactamente como hizo Lupita con sus desayunos.`,
k: `**Investigación de mercado:** información para decidir mejor. **Fuentes secundarias:** lo que ya existe (INEGI y su **DENUE**, cámaras, informes, competencia en internet). **Primarias:** observación, entrevistas, encuestas, **cliente misterioso**, **prueba piloto** y datos propios. La gente dice una cosa y hace otra: pregunta por el **comportamiento pasado** y prueba en pequeño.`,
ch: `Antes de abrir una lavandería, una emprendedora cuenta los edificios de departamentos de la zona en el DENUE, observa cuántas personas usan la lavandería más cercana un sábado y pregunta a 30 vecinos cuánto pagan hoy.`,
gi: `Las grandes cadenas suelen probar productos nuevos en un grupo de tiendas antes de lanzarlos a todo el país, y empresas de consumo usan paneles de hogares que registran sus compras para medir el mercado.`,
e: `Toño estima la demanda de desayunos con la observación y la encuesta:

| Paso | Cálculo | Resultado |
|---|---|---|
| Personas que pasan en la mañana | — | 600 |
| Oficinistas (estimado por observación) | 600 × 60 % | 360 |
| Desayunan fuera 3 o más días (encuesta) | 360 × 45 % | 162 |
| Podrían elegir Tortas Lupita (supuesto conservador) | 162 × 35 % | 57 desayunos al día |
| Resultado real de la prueba piloto | — | 70 desayunos al día |

La prueba piloto confirmó (y superó) la estimación.`,
r: `El INEGI ofrece en línea el DENUE, un directorio con la ubicación y la actividad de millones de establecimientos del país, que se puede consultar en un mapa y filtrar por tipo de negocio y zona. Es una herramienta gratuita muy usada para estudios de mercado y de ubicación.`,
f: `INEGI, Directorio Estadístico Nacional de Unidades Económicas (DENUE) (inegi.org.mx/app/mapa/denue).`,
err: ["Decidir sin ninguna información.","Hacer encuestas largas y con preguntas que inducen la respuesta.","Creer todo lo que la gente dice en una encuesta.","Preguntar a las personas equivocadas."],
a: `Elige una decisión del negocio que observas (un producto nuevo, un horario, un precio). Diseña una investigación barata con al menos tres métodos (por ejemplo, DENUE, observación y encuesta de 6 preguntas). Si puedes, aplícala.`,
sol: `Revisa que tus preguntas pregunten por lo que la gente hizo y no solo por lo que haría. Siempre que puedas, termina con una prueba piloto.`,
q: [["El DENUE del INEGI sirve para…",["Ver los negocios registrados en una zona por actividad","Calcular impuestos","Pagar la nómina"],0,"Es un directorio en línea con mapa."],
["Contar cuántas personas pasan frente al local es un método de…",["Observación","Encuesta","Fuente secundaria"],0,"Mide lo que la gente hace."],
["¿Cuál es una pregunta mejor para una encuesta?",["«¿Qué desayunaste ayer y dónde?»","«¿Verdad que te encantaría desayunar aquí?»","«¿Comprarías todo lo que te ofrezca?»"],0,"Pregunta por el comportamiento pasado y es neutral."],
["La forma más confiable de saber si un producto nuevo funciona suele ser…",["Una prueba piloto","Preguntarle a un amigo","Adivinar"],0,"Se mide lo que realmente se vende."]],
t: ["Investigación de mercado", "Fuentes secundarias"]
},
"M12-3": {
s: `En la misma cuadra hay una cadena de comida rápida, una cafetería de especialidad y la fonda de Doña Tere. Lupita se pregunta: ¿cómo quiere que la recuerden sus clientes? ¿Como la más barata, la más rápida, la más sabrosa o la más «de casa»?`,
o: ["Aplicar el proceso de segmentación, mercado meta y posicionamiento.","Construir un mapa de posicionamiento.","Redactar una declaración de posicionamiento."],
x: `## Tres pasos para decidir a quién y cómo
El marketing suele organizar sus decisiones estratégicas en tres pasos:
1. **Segmentar:** dividir el mercado en grupos de clientes con necesidades parecidas (lección M4-3).
2. **Elegir el mercado meta:** decidir a qué segmento o segmentos se va a atender.
3. **Posicionar:** definir qué lugar quiere ocupar el negocio en la mente de esos clientes, frente a la competencia.

## 1. Segmentar
Los criterios más comunes para segmentar son:
- **Geográficos:** dónde viven o trabajan (zona, ciudad, región).
- **Demográficos:** edad, sexo, ingreso, ocupación, tamaño de la familia.
- **Psicográficos:** estilo de vida, valores, intereses (personas que cuidan su salud, que buscan experiencias, que priorizan el ahorro).
- **Conductuales:** cómo y cuándo compran, cuánto, con qué frecuencia, qué beneficio buscan (rapidez, precio, calidad).
- **Para empresas:** giro, tamaño, ubicación, forma de comprar.

Un buen segmento es **medible** (se puede estimar su tamaño), **accesible** (se puede llegar a él), **suficientemente grande** (para que valga la pena), **distinto** (responde de forma diferente a otros) y **atendible** (el negocio puede ofrecerle algo).

## 2. Elegir el mercado meta
No se puede ser todo para todos. Hay varias estrategias:
- **Masiva:** una sola oferta para todo el mercado (pocos negocios pueden hacerlo).
- **Diferenciada:** ofertas distintas para varios segmentos (una cadena con marcas para distintos niveles de precio).
- **Concentrada (de nicho):** una oferta para un solo segmento, atendido muy bien. Es la estrategia más común en negocios pequeños.
- **Local o individual:** ofertas muy personalizadas.

Tortas Lupita elige una estrategia concentrada: **oficinistas y trabajadores de la zona Centro que necesitan comer bien, rápido y a un precio accesible**, con un segmento secundario (estudiantes en la tarde) y un canal especial para oficinas.

## 3. Posicionar
El **posicionamiento** es el lugar que una marca ocupa en la mente de los clientes en comparación con la competencia. Al Ries y Jack Trout popularizaron la idea en su libro «Posicionamiento: la batalla por su mente» (1981): como los clientes reciben miles de mensajes, recuerdan a las marcas por **una idea simple y distinta**. Algunos ejemplos clásicos: una marca de autos asociada con la seguridad, una tienda asociada con los precios bajos, una cafetería asociada con la experiencia.

Un buen posicionamiento es:
- **Claro:** se puede decir en una frase.
- **Distinto:** no lo puede decir cualquier competidor.
- **Relevante:** le importa al cliente meta.
- **Creíble y sostenible:** el negocio puede cumplirlo siempre.

## El mapa de posicionamiento
Una herramienta visual es el **mapa de posicionamiento** (o mapa perceptual): un plano con dos ejes que representan atributos importantes para el cliente, donde se ubica a cada competidor. Para la cuadra de Lupita, con los ejes «precio» y «rapidez»:

| Competidor | Precio | Rapidez | Lugar en el mapa |
|---|---|---|---|
| Cadena de comida rápida | Medio | Muy alta | Rápido y estándar |
| Cafetería de especialidad | Alto | Baja | Experiencia, para sentarse |
| Fonda de Doña Tere | Bajo | Baja | Comida de casa, sin prisa |
| Tortas Lupita | Bajo-medio | Alta | **Comida sabrosa y rápida a buen precio** |

El mapa muestra un espacio libre: nadie ofrece al mismo tiempo **sabor «de casa»** y **rapidez** a **precio accesible**. Ese es el lugar que Tortas Lupita quiere ocupar.

## La declaración de posicionamiento
Una forma de escribir el posicionamiento (para uso interno, no como eslogan) es:

**«Para [mercado meta], [marca] es [categoría] que [beneficio principal], porque [razón para creer].»**

Para Tortas Lupita:
«Para los trabajadores del Centro que tienen poco tiempo, Tortas Lupita es la tortería que da comida sabrosa como de casa, lista en tres minutos y a buen precio, porque preparamos al momento con ingredientes frescos cada mañana y con un proceso rápido».

Esta frase guía todas las decisiones: el menú (pocas opciones bien hechas), el proceso (rápido), el precio (accesible), la comunicación (fotos de ingredientes frescos y del tiempo de espera) y el trato (cercano, «de casa»).

## Errores de posicionamiento
- **Sin posicionamiento claro:** el cliente no sabe por qué elegirte.
- **Posicionamiento confuso:** prometer «lo más barato» y «lo más gourmet» a la vez.
- **Posicionamiento que no se cumple:** prometer rapidez y tener filas de 20 minutos.
- **Reposicionarse demasiado seguido:** cambiar de idea cada año confunde a los clientes.
- **Copiar el posicionamiento del líder:** es difícil ganarle en su propio terreno.

## Reposicionarse
A veces, una marca necesita **reposicionarse**: cambiar la idea que los clientes tienen de ella, porque el mercado cambió o porque su posicionamiento ya no funciona. Es un proceso lento y caro, que requiere cambiar no solo la publicidad, sino también el producto, el precio, el servicio y la experiencia.

## En las empresas gigantes
Las grandes empresas con muchas marcas posicionan cada una para un segmento distinto. Una empresa de autos puede tener marcas para jóvenes, para familias y de lujo; una cadena de hoteles, marcas económicas, de negocios y de lujo. Cada marca tiene su propio posicionamiento, y la empresa cuida que no se «roben» clientes entre sí.`,
k: `**Segmentar** (geográfico, demográfico, psicográfico, conductual) → **mercado meta** (masivo, diferenciado, **concentrado o de nicho**) → **posicionar**: el lugar que ocupas en la mente del cliente frente a la competencia (Ries y Trout, 1981). Usa un **mapa de posicionamiento** y una declaración: para [meta], [marca] es [categoría] que [beneficio], porque [razón].`,
ch: `Una panadería de barrio se posiciona como «el pan recién salido a las 7:00 y a las 18:00»; sus clientes saben exactamente cuándo ir y por qué elegirla.`,
gi: `Las cadenas hoteleras internacionales manejan varias marcas con posicionamientos distintos (económico, de negocios, de lujo) para atender a segmentos diferentes sin confundirlos.`,
e: `Toño revisa si las acciones de Tortas Lupita son coherentes con su posicionamiento («sabroso como de casa, rápido y a buen precio»):

| Acción propuesta | ¿Coherente? | Decisión |
|---|---|---|
| Agregar 20 tipos de torta al menú | No: hace más lento el proceso | Mantener 5 a 7 tipos |
| Subir el precio a 75 pesos con ingredientes gourmet | No: rompe «buen precio» | Descartar |
| Pedidos por WhatsApp para recoger sin fila | Sí: refuerza «rápido» | Implementar |
| Fotos de Lupita preparando la salsa | Sí: refuerza «de casa» | Implementar |
| Pantalla con el tiempo de espera | Sí: hace visible la rapidez | Implementar |`,
r: `Al Ries y Jack Trout publicaron «Positioning: The Battle for Your Mind» en 1981, después de una serie de artículos en la revista Advertising Age a principios de los setenta. El libro popularizó la idea de que las marcas compiten por ocupar un lugar simple y distinto en la mente de los consumidores.`,
f: `Al Ries y Jack Trout, «Posicionamiento: la batalla por su mente» (1981).`,
err: ["Querer atender a todos los segmentos a la vez.","No tener una idea clara y distinta.","Prometer un posicionamiento que la operación no puede cumplir.","Cambiar de posicionamiento cada poco tiempo."],
a: `Elige dos atributos importantes para los clientes del negocio que observas y dibuja un mapa de posicionamiento con al menos cuatro competidores. Identifica un espacio libre y escribe una declaración de posicionamiento.`,
sol: `Elige atributos que de verdad le importen al cliente (no los que le gustan al dueño). Si todos los competidores están en el mismo lugar, puede haber una oportunidad en otro.`,
q: [["El posicionamiento es…",["El lugar que una marca ocupa en la mente del cliente frente a la competencia","La ubicación del local","El número de sucursales"],0,"Según Ries y Trout."],
["Una estrategia de mercado meta concentrada (de nicho) consiste en…",["Atender muy bien a un solo segmento","Atender a todo el mundo igual","No tener clientes"],0,"Es la más común en negocios pequeños."],
["Un mapa de posicionamiento sirve para…",["Ver visualmente dónde está cada competidor según dos atributos","Calcular impuestos","Dibujar rutas de reparto"],0,"Ayuda a encontrar espacios libres."],
["¿Cuál es un error de posicionamiento?",["Prometer rapidez y tener filas de 20 minutos","Tener una idea clara","Ser distinto a la competencia"],0,"El posicionamiento debe cumplirse."]],
t: ["Segmentación", "Mercado meta"]
},
"M12-4": {
s: `Para lanzar los desayunos, Lupita tiene que decidir qué incluir, a qué precio, dónde y cómo venderlos, y cómo darlos a conocer. Toño le dice que esas cuatro decisiones tienen nombre: las 4P del marketing.`,
o: ["Explicar las 4P del marketing: producto, precio, plaza y promoción.","Conocer las 3P adicionales de los servicios.","Diseñar la mezcla de marketing de un producto concreto."],
x: `## La mezcla de marketing
Una vez que el negocio sabe a quién atiende y cómo quiere posicionarse (lección M12-3), tiene que tomar decisiones concretas sobre su oferta. En 1960, el profesor estadounidense E. Jerome McCarthy propuso agruparlas en cuatro categorías, conocidas como las **4P** (por sus nombres en inglés: *product, price, place, promotion*). Juntas forman la **mezcla de marketing**. Todas deben ser coherentes entre sí y con el posicionamiento.

## 1. Producto
El **producto** es lo que se ofrece al cliente para satisfacer su necesidad: un bien, un servicio o una combinación. Las decisiones de producto incluyen:
- **Características y calidad:** ingredientes, tamaño, sabor, presentación.
- **Variedad:** cuántas opciones (el menú).
- **Marca y empaque:** nombre, imagen, envoltura.
- **Servicios adicionales:** garantía, entrega, atención.

Un producto se puede ver en niveles: el **beneficio central** (calmar el hambre rápido), el **producto básico** (la torta) y el **producto ampliado** (empaque práctico, pedido por WhatsApp, factura, garantía de puntualidad para oficinas).

## 2. Precio
El **precio** es lo que el cliente paga. Las decisiones incluyen:
- **Nivel de precio** (por costo, competencia y valor; lección M5-8).
- **Descuentos y promociones** (lección M5-9).
- **Condiciones de pago:** contado, tarjeta, crédito a oficinas.
- **Precios por volumen** o paquetes.

El precio debe ser coherente con el posicionamiento: un producto que se presenta como «premium» con precio de oferta confunde; uno «accesible» con precio alto aleja a su cliente meta.

## 3. Plaza (distribución)
La **plaza** se refiere a **dónde y cómo** llega el producto al cliente: los canales (lección M4-4), la ubicación, los horarios, la entrega, la cobertura. Decisiones típicas:
- ¿Se vende en el local, por WhatsApp, en plataformas de reparto, en tiendas de terceros?
- ¿En qué horario?
- ¿Con entrega a domicilio o para recoger?
- ¿En cuántos puntos de venta?

## 4. Promoción (comunicación)
La **promoción** es cómo se da a conocer el producto y se motiva la compra. Incluye:
- **Publicidad:** anuncios pagados (lección M12-7).
- **Promoción de ventas:** descuentos, combos, degustaciones, programas de lealtad.
- **Relaciones públicas:** notas en medios, participación en eventos de la comunidad.
- **Venta personal:** la labor de Karla con las oficinas.
- **Marketing digital y redes sociales** (lección M12-6).
- **Comunicación en el punto de venta:** letreros, menú, vitrina.

## Las 3P adicionales de los servicios
Para los servicios, en 1981 Bernard Booms y Mary Jo Bitner propusieron agregar tres P más (las **7P**):
5. **Personas:** quienes atienden son parte del servicio (su trato, su preparación, su aspecto).
6. **Procesos:** cómo se presta el servicio (rapidez, facilidad, pasos para el cliente).
7. **Evidencia física (o ambiente):** lo que el cliente ve y toca (limpieza, decoración, uniformes, empaques, el local).

En un negocio como Tortas Lupita, que es mitad producto y mitad servicio, las 7P son muy útiles: una torta excelente pierde valor si la atiende alguien de mal humor, en un local sucio y con un proceso lento.

## La mezcla de marketing de los desayunos
| P | Decisión |
|---|---|
| Producto | Tres opciones: torta de huevo con chorizo, molletes y yogur con fruta y granola; café de olla incluido; empaque para llevar |
| Precio | 55 pesos con café; 45 sin café; paquete para oficinas de 10 desayunos a 500 pesos |
| Plaza | En el local de 7:30 a 10:30; pedidos por WhatsApp para recoger sin fila; entrega a oficinas a partir de 10 desayunos |
| Promoción | Letrero en la calle desde las 7:00; publicación diaria en redes con foto del desayuno; degustación en 10 oficinas; desayuno de prueba a mitad de precio la primera semana para quien traiga a un compañero |
| Personas | Turno de mañana capacitado en rapidez y trato amable |
| Procesos | Menú corto; tres estaciones; pedido y pago en un solo paso |
| Evidencia física | Local limpio y ventilado; olor a café; vasos con el logo |

## La coherencia
Las P deben reforzarse entre sí. Si el producto es rápido y práctico, la plaza debe facilitar la compra rápida, el precio debe ser accesible y la promoción debe comunicar rapidez. Si una P contradice a las demás (por ejemplo, un desayuno «rápido» que solo se vende en una plataforma de reparto que tarda 40 minutos), la mezcla falla.

## Más allá de las 4P
Algunos autores proponen ver las 4P desde el punto de vista del cliente, con las **4C**: **cliente** (sus necesidades, en lugar del producto), **costo** (todo lo que le cuesta al cliente, no solo el precio), **conveniencia** (en lugar de plaza) y **comunicación** (un diálogo, en lugar de promoción). Es una forma útil de recordar que cada decisión debe pensarse desde quien compra.

## En las empresas gigantes
Las grandes empresas de consumo definen una mezcla de marketing para cada producto y cada país. Una misma bebida puede tener presentaciones, precios, canales y campañas distintas en distintos mercados. Los gerentes de marca son responsables de que las P de su producto sean coherentes y logren sus objetivos de ventas y de participación de mercado.`,
k: `**4P** (McCarthy, 1960): **producto** (qué se ofrece), **precio** (cuánto y cómo se paga), **plaza** (dónde y cómo llega), **promoción** (cómo se comunica). En servicios, **7P**: más **personas, procesos y evidencia física** (Booms y Bitner, 1981). Las P deben ser **coherentes** entre sí y con el posicionamiento. Visto desde el cliente: **4C**.`,
ch: `Una paletería artesanal define su mezcla: paletas de fruta natural (producto), 25 pesos (precio), en su local y en dos tiendas de la colonia (plaza) y una pizarra con el sabor del día y fotos en redes (promoción).`,
gi: `Las grandes marcas de bebidas adaptan su mezcla de marketing a cada país: tamaños de envase, precios, canales (tienditas, supermercados, restaurantes) y campañas publicitarias distintas según el mercado.`,
e: `Lupita calcula los resultados esperados de los desayunos con su mezcla de marketing:

| Concepto | Cálculo | Resultado mensual |
|---|---|---|
| Desayunos en el local | 70 al día × 26 × 55 | 100,100 |
| Paquetes de oficina | 8 paquetes por semana × 4.3 × 500 | 17,200 |
| Ventas totales de desayunos | — | 117,300 |
| Costo de ingredientes (35 %) | 117,300 × 0.35 | 41,055 |
| Costos adicionales del turno de mañana | — | 30,000 |
| Margen después de costos adicionales | 117,300 − 41,055 − 30,000 | 46,245 |

Si la prueba piloto se mantiene, los desayunos agregarían más de 46,000 pesos al mes.`,
r: `E. Jerome McCarthy presentó el marco de las 4P en su libro «Basic Marketing: A Managerial Approach» (1960). En 1981, Bernard Booms y Mary Jo Bitner propusieron ampliar el modelo a 7P para los servicios, agregando personas, procesos y evidencia física.`,
f: `E. J. McCarthy, «Basic Marketing» (1960); B. Booms y M. J. Bitner, «Marketing Strategies and Organization Structures for Service Firms» (1981).`,
err: ["Decidir las P por separado, sin coherencia.","Olvidar las personas, los procesos y el ambiente en un servicio.","Pensar la promoción antes que el producto y el precio.","Copiar la mezcla de un competidor con otro posicionamiento."],
a: `Diseña la mezcla de marketing (7P) de un producto o servicio del negocio que observas, en una tabla. Revisa que las siete P sean coherentes con su posicionamiento.`,
sol: `Una prueba sencilla: lee cada P y pregúntate si refuerza la frase de posicionamiento. Si alguna la contradice, cámbiala.`,
q: [["¿Cuáles son las 4P del marketing?",["Producto, precio, plaza y promoción","Personas, procesos, planta y pago","Planear, presupuestar, pagar y producir"],0,"Propuestas por McCarthy en 1960."],
["La «plaza» se refiere a…",["Dónde y cómo llega el producto al cliente","El precio","La publicidad"],0,"Canales, ubicación, horarios y entrega."],
["Las 3P adicionales de los servicios son…",["Personas, procesos y evidencia física","Precio, plaza y publicidad","Producto, pago y proveedor"],0,"Propuestas por Booms y Bitner."],
["¿Por qué deben ser coherentes las P?",["Porque se refuerzan entre sí; si una contradice a las demás, la mezcla falla","Porque lo pide la ley","No necesitan serlo"],0,"Deben apoyar el mismo posicionamiento."]],
t: ["Mezcla de marketing (4P)", "7P de los servicios"]
},
"M12-5": {
s: `Una agencia ofrece a Lupita «hacerle una marca» con un logo moderno y un nombre en inglés: «Lupi's Gourmet Sandwiches». Sus clientes de años se ríen: «¡Pero si todos te conocemos como Tortas Lupita!». ¿Qué es realmente una marca?`,
o: ["Explicar qué es una marca y qué la compone.","Distinguir entre logo, identidad y experiencia de marca.","Proponer acciones para construir y proteger una marca."],
x: `## Una marca es una promesa
Una **marca** es mucho más que un nombre y un logo. Es el conjunto de ideas, sentimientos y expectativas que una persona asocia con un negocio o un producto. En palabras sencillas, es **una promesa**: lo que el cliente espera recibir cada vez que elige esa marca. Cuando la promesa se cumple una y otra vez, se crea **confianza**; cuando se rompe, la marca se daña.

Una frase atribuida a Jeff Bezos resume la idea: «Tu marca es lo que la gente dice de ti cuando no estás en la habitación».

## Las partes de una marca
1. **Nombre:** cómo se llama. Debe ser fácil de pronunciar, recordar y escribir, y no estar registrado por otro.
2. **Identidad visual:** logo, colores, tipografía, estilo de fotos, uniformes, empaques.
3. **Promesa:** qué beneficio ofrece y en qué es distinta (sale del posicionamiento, lección M12-3).
4. **Personalidad y tono:** cómo «habla» la marca: cercana, formal, divertida, seria.
5. **Experiencia:** lo que el cliente vive en cada contacto con la marca: el trato, el sabor, la rapidez, el local, los mensajes, la entrega.
6. **Reputación:** lo que la gente dice (reseñas, recomendaciones, notas en medios).

El logo es la parte más visible, pero la **experiencia** es la que más construye (o destruye) la marca.

## El valor de una marca
Una marca fuerte tiene **valor**:
- Los clientes la **eligen** sin comparar tanto.
- Están dispuestos a **pagar un poco más**.
- Son más **leales**.
- **Recomiendan**.
- Facilitan **lanzar productos nuevos** con el mismo nombre.
- Hacen que el negocio **valga más** si algún día se vende o se franquicia (Módulo 21).

A este valor se le llama **capital de marca** (en inglés, *brand equity*). Las marcas más conocidas del mundo, como Coca-Cola, Apple o Google, aparecen en clasificaciones de consultoras especializadas (como Interbrand o Kantar) con valores estimados de miles de millones de dólares.

## La marca de un negocio pequeño
Un negocio pequeño no necesita una gran agencia para tener una marca fuerte. Necesita:
- **Coherencia:** el mismo nombre, colores y estilo en el letrero, el menú, las bolsas, las redes y los uniformes.
- **Una promesa clara** que se cumpla siempre.
- **Una historia auténtica:** de dónde viene, quién está detrás, qué la hace especial. La historia de Lupita y su receta de salsa es más poderosa que un nombre en inglés.
- **Consistencia en la experiencia:** que la torta sepa igual cada día y que el trato sea siempre amable.
- **Cuidar la reputación:** responder reseñas, resolver quejas (lección M11-7).

## El error de la agencia
La propuesta de «Lupi's Gourmet Sandwiches» tiene varios problemas:
- **Rompe el reconocimiento** que ya existe: los clientes conocen y buscan «Tortas Lupita».
- **No es coherente con el posicionamiento:** «gourmet» sugiere caro y lento, lo contrario de «sabroso, rápido y a buen precio».
- **Pierde autenticidad:** la marca es la historia de Lupita; un nombre en inglés la borra.
- **Puede confundir:** los clientes podrían creer que es otro negocio.

Cambiar el nombre de una marca que ya tiene reconocimiento es muy costoso y arriesgado; solo se justifica en casos muy concretos (por ejemplo, un problema legal o una mala reputación imposible de recuperar).

## Mejorar sin perder la esencia
Lupita decide **renovar** su identidad sin cambiar su esencia:
- Conserva el nombre «Tortas Lupita».
- Una diseñadora redibuja el logo con un estilo más limpio, pero reconocible, inspirado en el letrero original.
- Define dos colores y los usa en todo: letrero, menú, bolsas, uniformes, redes.
- Escribe su promesa: «Sabor de casa, en tres minutos».
- Agrega una foto de Lupita preparando la salsa en el menú y en las redes.

## Proteger la marca
Una marca es un activo y hay que protegerla:
- **Registrarla** ante el Instituto Mexicano de la Propiedad Industrial (IMPI), para tener el derecho exclusivo de usarla en su giro y poder impedir que otros la copien (lección M14-3). El caso del módulo, «alguien registra la marca Tortas Lupita antes que ella», muestra lo que puede pasar si no se registra a tiempo.
- **Registrar el dominio de internet** y los nombres en redes sociales.
- **Cuidar la calidad** en todas las sucursales o franquicias: una mala experiencia en una sucursal daña a toda la marca.

## Marcas en empresas gigantes
Las grandes empresas pueden tener una sola marca para todo (como una marca corporativa) o un **portafolio de marcas**, cada una dirigida a un segmento distinto. Grupo Bimbo, por ejemplo, maneja muchas marcas de pan y pastelitos en distintos países. Algunas empresas usan una **marca paraguas** para todos sus productos; otras, marcas independientes, para que un problema con un producto no afecte a los demás (Módulo 26).

## La marca como cultura
Una marca fuerte empieza por dentro: si los empleados conocen y creen en la promesa, la cumplen sin que se lo pidan. Por eso la marca está ligada a la cultura (lección M7-6). En Tortas Lupita, «sabor de casa, en tres minutos» se convierte en una frase que todo el equipo repite en la junta diaria.`,
k: `**Marca:** el conjunto de ideas y expectativas que el cliente asocia con un negocio; es una **promesa**. Partes: nombre, identidad visual, promesa, personalidad, **experiencia** y reputación. El **capital de marca** hace que te elijan, paguen más y recomienden. Claves en un negocio pequeño: **coherencia**, promesa clara, historia auténtica y experiencia constante. **Regístrala** ante el IMPI.`,
ch: `Una carnicería de barrio con tres generaciones conserva su nombre familiar, renueva su letrero con los mismos colores de siempre y pone en la pared fotos de la fundación: sus clientes sienten que es «la de siempre, pero mejor».`,
gi: `Consultoras como Interbrand publican cada año clasificaciones de las marcas más valiosas del mundo, en las que aparecen marcas como Apple, Microsoft, Google y Coca-Cola con valores estimados de decenas o cientos de miles de millones de dólares.`,
e: `Lupita compara el costo de cambiar de nombre con el de renovar la identidad:

| Concepto | Cambiar a «Lupi's Gourmet» | Renovar «Tortas Lupita» |
|---|---|---|
| Diseño y letreros | 35,000 | 18,000 |
| Bolsas, menús y uniformes nuevos | 12,000 | 12,000 |
| Pérdida estimada de clientes por confusión (3 meses) | 5 % de ventas ≈ 35,000 | 0 |
| Riesgo legal (nombre nuevo no registrado) | Alto | Bajo (se registra el nombre actual) |
| **Costo total estimado** | **82,000 + riesgo** | **30,000** |

Renovar sin perder la esencia cuesta menos de la mitad y protege lo que ya ganó.`,
r: `Interbrand publica desde 2000 su ranking «Best Global Brands», que estima el valor de las marcas más importantes del mundo con base en su desempeño financiero, su influencia en la decisión de compra y su fortaleza. En las ediciones recientes, marcas de tecnología como Apple, Microsoft y Google ocupan los primeros lugares.`,
f: `Interbrand, «Best Global Brands» (interbrand.com); IMPI, información sobre registro de marcas (gob.mx/impi).`,
err: ["Creer que la marca es solo el logo.","Cambiar un nombre reconocido sin una razón poderosa.","Usar colores, estilos y mensajes distintos en cada lugar.","No registrar la marca."],
a: `Describe la marca del negocio que observas con sus seis partes (nombre, identidad, promesa, personalidad, experiencia, reputación). Revisa si es coherente en el letrero, el menú, los empaques y las redes, y propón tres mejoras que no cambien su esencia.`,
sol: `La mejora más barata y efectiva suele ser la coherencia: usar los mismos colores, logo y tono en todos los puntos de contacto.`,
q: [["Una marca es sobre todo…",["Una promesa: lo que el cliente espera recibir","Solo el logo","El nombre del dueño"],0,"Se construye cumpliendo esa promesa."],
["¿Qué parte de la marca construye más la confianza?",["La experiencia del cliente en cada contacto","El color del logo","El nombre en inglés"],0,"La experiencia es lo que el cliente vive."],
["El capital de marca se refiere a…",["El valor que una marca fuerte aporta al negocio","El dinero en el banco","El capital social de la empresa"],0,"Hace que los clientes elijan, paguen más y recomienden."],
["¿Ante qué institución se registra una marca en México?",["El IMPI","El IMSS","La Profeco"],0,"Instituto Mexicano de la Propiedad Industrial."]],
t: ["Marca", "Identidad de marca"]
},
"M12-6": {
s: `Toño abre una cuenta en redes sociales y publica tres fotos borrosas en un mes. Nadie las ve. Mientras tanto, la cafetería de enfrente aparece primero cuando alguien busca «desayunos cerca de mí» en el mapa del celular. Toño entiende que el marketing digital es más que «tener redes».`,
o: ["Conocer las herramientas básicas del marketing digital para un negocio local.","Usar un perfil en mapas, WhatsApp Business y redes sociales de forma ordenada.","Planear contenido y anuncios segmentados por zona."],
x: `## El cliente busca en el celular
Hoy, una gran parte de las personas busca negocios, compara opciones, lee opiniones y hace pedidos desde su celular. En México, según la encuesta del INEGI sobre disponibilidad y uso de tecnologías de la información en los hogares (ENDUTIH), más de tres cuartas partes de la población de seis años o más usa internet, y la mayoría lo hace desde el teléfono. Para un negocio, estar presente y bien presentado en internet ya no es opcional: es parte de la «vitrina».

El **marketing digital** es el uso de herramientas digitales para atraer, convencer y conservar clientes. Para un negocio local, las herramientas más útiles son cinco.

## 1. El perfil en mapas y buscadores
Cuando alguien busca «tortas cerca de mí» o «desayunos en el Centro», los buscadores y los mapas muestran los negocios cercanos con su calificación, fotos y horario. Tener un **perfil de negocio** completo y actualizado (por ejemplo, en Google Maps) es, para un negocio local, una de las acciones digitales más rentables. Incluye:
- Nombre exacto, dirección y ubicación en el mapa.
- Horarios reales (y días festivos).
- Teléfono y número de WhatsApp.
- Fotos de calidad: fachada, interior, productos, equipo.
- Menú y precios.
- Categoría correcta («tortería», «restaurante de desayunos»).
- **Reseñas:** pedirlas a los clientes satisfechos y responderlas todas.

## 2. WhatsApp Business
Es una aplicación gratuita para negocios que permite:
- Un **perfil de empresa** con horario, dirección y descripción.
- Un **catálogo** con productos y precios.
- **Respuestas rápidas** para preguntas frecuentes («¿Cuál es el menú de hoy?»).
- **Mensaje de bienvenida** y de ausencia (fuera de horario).
- **Etiquetas** para organizar a los clientes (nuevo, oficina, pedido pendiente).
- **Listas de difusión** para enviar avisos a clientes que aceptaron recibirlos.

Para muchos negocios pequeños en México, WhatsApp es el canal principal de pedidos.

## 3. Redes sociales
Las redes sociales sirven para que el negocio se dé a conocer, muestre su producto y su personalidad, y mantenga el contacto con sus clientes. Cada una tiene su estilo y su público; no hace falta estar en todas. Para un negocio de comida, suelen funcionar bien las redes visuales, con fotos y videos cortos.

Lo que funciona en redes para un negocio local:
- **Constancia:** publicar con regularidad (por ejemplo, tres veces por semana) es mejor que publicar mucho una semana y nada en un mes.
- **Fotos y videos reales y de buena calidad:** luz natural, el producto bien presentado, el proceso de preparación.
- **Contenido útil o interesante,** no solo anuncios: la historia del negocio, cómo se prepara la salsa, el equipo, clientes contentos (con su permiso), novedades.
- **Interacción:** responder comentarios y mensajes rápido.
- **Llamado a la acción:** decir qué hacer («pide por WhatsApp», «ven hoy»).

## 4. Anuncios segmentados
Las plataformas digitales permiten pagar anuncios que se muestran solo a ciertas personas: por ubicación (por ejemplo, a un kilómetro del local), edad, intereses y horario. Para un negocio local, la **segmentación geográfica** es lo más valioso: no tiene sentido pagar para que vea el anuncio alguien que vive en otra ciudad. Se puede empezar con presupuestos pequeños, medir resultados (lección M12-8) y ajustar.

## 5. El sitio web o la página propia
Una página web sencilla con menú, ubicación, horarios y forma de pedir da seriedad, sobre todo para clientes empresa. No siempre es indispensable para un negocio pequeño, pero ayuda; y si el negocio crece, permite tener pedidos en línea propios sin depender de plataformas de terceros.

## Un plan de contenido sencillo
| Día | Contenido | Formato |
|---|---|---|
| Lunes | Menú de la semana y promoción | Foto |
| Miércoles | Cómo se prepara algo (la salsa, el pan tostado) | Video corto |
| Viernes | Cliente o equipo (con permiso) o reseña destacada | Foto con texto |
| Diario (historias) | Torta del día, tiempo de espera, avisos | Foto rápida |

Media hora al día, con constancia, suele dar mejores resultados que una gran campaña esporádica.

## Cuidado con los datos y la reputación
- **Pide permiso** antes de enviar mensajes promocionales y respeta a quien no quiera recibirlos.
- **Cuida los datos personales** de los clientes (lección M14-4).
- **No compres seguidores falsos:** no compran tortas.
- **Responde con calma** a las críticas públicas (lección M11-7).
- **No publiques** información privada de clientes ni fotos sin permiso.

## Lo digital y lo físico se complementan
El marketing digital no sustituye al letrero, al trato en el mostrador ni a la recomendación de boca en boca: los **amplifica**. Un cliente satisfecho que deja una reseña con foto convierte la experiencia física en una recomendación que verán cientos de personas.

## El plan digital de Tortas Lupita
- Completan el perfil en mapas con 25 fotos, menú, horarios y WhatsApp; piden reseñas con un letrero en la caja.
- Activan WhatsApp Business con catálogo, respuestas rápidas y etiquetas para oficinas.
- Publican tres veces por semana en una red social visual y suben historias diarias.
- Invierten 1,500 pesos al mes en anuncios dirigidos a personas a 1 kilómetro, entre semana de 7:00 a 13:00.
- Miden cada mes: búsquedas y visitas al perfil, mensajes recibidos, pedidos por WhatsApp y clientes que dicen «los vi en internet».

En tres meses, el perfil en mapas pasa de 200 a 1,800 vistas al mes y los pedidos por WhatsApp se triplican.`,
k: `**Marketing digital local:** perfil completo en **mapas** con fotos, horario y **reseñas**; **WhatsApp Business** (catálogo, respuestas rápidas, etiquetas); **redes sociales** con constancia, contenido real y llamado a la acción; **anuncios segmentados por zona**; página web sencilla. Pide permiso, cuida los datos y mide resultados. Lo digital **amplifica** lo físico.`,
ch: `Un taller mecánico sube a su perfil en mapas fotos de su local limpio y responde cada reseña; pasa a ser el primero que aparece en su colonia cuando alguien busca «taller mecánico».`,
gi: `Las grandes cadenas combinan aplicaciones propias, comercio electrónico, publicidad digital segmentada y programas de lealtad con datos de millones de clientes para personalizar ofertas.`,
e: `Toño mide el efecto del plan digital en tres meses:

| Indicador | Mes 0 | Mes 3 |
|---|---|---|
| Vistas del perfil en mapas | 200 | 1,800 |
| Reseñas (calificación) | 18 (4.2) | 96 (4.6) |
| Mensajes de WhatsApp de clientes nuevos | 20 | 110 |
| Pedidos por WhatsApp al mes | 150 | 460 |
| Gasto en anuncios | 0 | 1,500 |

Con 310 pedidos más al mes y un ticket de 85 pesos, las ventas por WhatsApp suben unos 26,350 pesos al mes.`,
r: `El INEGI publica la Encuesta Nacional sobre Disponibilidad y Uso de Tecnologías de la Información en los Hogares (ENDUTIH). En sus resultados recientes, más de tres cuartas partes de la población de seis años o más en México usaba internet, y el teléfono celular era el dispositivo más usado para conectarse.`,
f: `INEGI, ENDUTIH (inegi.org.mx); Google, ayuda de Perfil de Negocio; Meta, información de WhatsApp Business.`,
err: ["Abrir redes y publicar sin constancia.","Tener el perfil en mapas incompleto o con horarios equivocados.","Pagar anuncios sin segmentar por zona.","Enviar mensajes promocionales a quien no los pidió."],
a: `Revisa la presencia digital del negocio que observas: busca su perfil en mapas, sus redes y su WhatsApp. Haz una lista de lo que falta o está mal, y diseña un plan de contenido de una semana.`,
sol: `Prioriza el perfil en mapas (horario, fotos, reseñas) y el WhatsApp con catálogo: suelen tener más impacto inmediato que las redes para un negocio local.`,
q: [["Para un negocio local, una de las acciones digitales más rentables suele ser…",["Tener un perfil completo en mapas con fotos, horario y reseñas","Comprar seguidores","Publicar una vez al año"],0,"Es la nueva «vitrina»."],
["WhatsApp Business permite…",["Catálogo, respuestas rápidas y etiquetas de clientes","Emitir CFDI","Pagar nómina"],0,"Es gratuito y muy usado por negocios pequeños."],
["En anuncios digitales para un negocio local conviene…",["Segmentar por ubicación cercana al local","Mostrar el anuncio en todo el mundo","No medir"],0,"Así no se paga por personas que no pueden venir."],
["En redes sociales funciona mejor…",["La constancia con contenido real y útil","Publicar mucho una semana y nada después","Solo anuncios"],0,"La regularidad construye audiencia."]],
t: ["Marketing digital", "Perfil de negocio en mapas"]
},
"M12-7": {
s: `Una radio local ofrece a Lupita un paquete de anuncios por 12,000 pesos al mes. Una imprenta, 5,000 volantes por 1,500. Una plataforma digital dice que con 2,000 pesos llega a 50,000 personas. Lupita no sabe cuánto gastar ni dónde. ¿Cómo se decide el presupuesto de marketing?`,
o: ["Conocer métodos para fijar el presupuesto de marketing.","Comparar medios publicitarios según alcance, costo y precisión.","Elegir una combinación de medios para un negocio local."],
x: `## La publicidad: comunicar pagando
La **publicidad** es la comunicación pagada para dar a conocer un negocio, un producto o una promoción a muchas personas. Es una parte de la promoción (lección M12-4), junto con la venta personal, las promociones, las relaciones públicas y el marketing digital orgánico (lo que se publica sin pagar). La pregunta que todo dueño se hace es: **¿cuánto gastar y en qué?**

## Una frase famosa
Al comerciante estadounidense John Wanamaker se le atribuye una frase de finales del siglo XIX: «La mitad del dinero que gasto en publicidad se desperdicia; el problema es que no sé cuál mitad». Aunque no hay certeza de que la haya dicho así, refleja un problema real: la publicidad es difícil de medir. Por eso conviene decidir el presupuesto con un método y medir los resultados (lección M12-8).

## Métodos para fijar el presupuesto
1. **Porcentaje de las ventas:** se destina un porcentaje fijo de las ventas (actuales o esperadas). Es sencillo y controla el gasto. Muchos negocios pequeños destinan un porcentaje de un solo dígito de sus ventas al marketing, pero varía mucho según el giro, la etapa y la competencia. Su defecto: cuando las ventas bajan, se gasta menos, justo cuando quizá haría falta más.
2. **Objetivo y tarea:** se define un objetivo («conseguir 300 clientes nuevos en tres meses»), se estiman las acciones necesarias y se calcula cuánto cuestan. Es el método más lógico, porque conecta el gasto con un resultado.
3. **Paridad con la competencia:** gastar parecido a lo que gastan los competidores. Da una referencia, pero cada negocio tiene objetivos distintos.
4. **Lo que se pueda:** gastar lo que sobre. Es el método más común en negocios pequeños y el menos recomendable, porque no conecta el gasto con un objetivo.

Lo recomendable es combinar: partir del **objetivo y tarea**, verificar que el monto sea razonable como **porcentaje de las ventas** y ajustar con los resultados.

## Los medios publicitarios
| Medio | Alcance | Costo | Precisión (llegar al cliente correcto) | Facilidad para medir |
|---|---|---|---|---|
| Letrero, fachada, vitrina | Local, permanente | Bajo (inversión inicial) | Alta (quien pasa) | Media |
| Volantes | Local | Bajo | Media | Baja (salvo con código) |
| Perifoneo o lonas | Local | Bajo | Baja | Baja |
| Radio local | Ciudad | Medio-alto | Baja-media | Baja |
| Periódico o revista local | Ciudad o zona | Medio | Media | Baja |
| Espectaculares | Ciudad | Alto | Baja | Baja |
| Anuncios digitales segmentados | De muy local a nacional | Bajo a alto (flexible) | Alta | Alta |
| Influenciadores locales | Variable | Variable | Media-alta | Media |
| Patrocinios de eventos locales | Comunidad | Bajo-medio | Media | Baja |

Para un negocio local, los medios con **alta precisión** y **costo bajo** suelen ser los mejores: el propio local, los anuncios digitales segmentados por zona y la presencia en la comunidad.

## Conceptos útiles: alcance y frecuencia
- **Alcance:** cuántas personas distintas ven el anuncio.
- **Frecuencia:** cuántas veces, en promedio, lo ve cada persona.

Una persona suele necesitar ver un mensaje varias veces antes de recordarlo y actuar. Por eso, para un negocio pequeño, suele ser mejor **llegar muchas veces a pocas personas cercanas** (alta frecuencia en la zona) que llegar una vez a muchas personas lejanas.

## El mensaje
Además del medio, importa el mensaje. Un buen anuncio:
- **Llama la atención** (una buena foto del producto).
- **Dice un beneficio claro** («Desayuno completo en 3 minutos, 55 pesos»).
- **Es coherente** con la marca y el posicionamiento.
- **Tiene un llamado a la acción** («Pide por WhatsApp», «Ven antes de las 10:30»).
- **Permite medir** (un código, un número de WhatsApp específico, una promoción exclusiva).
- **Es verdadero:** la publicidad engañosa es ilegal y destruye la confianza.

## El presupuesto de Tortas Lupita
Con el método de objetivo y tarea, Lupita define: «Conseguir 300 clientes nuevos de desayunos en tres meses».

| Acción | Costo mensual |
|---|---|
| Anuncios digitales a 1 km, de 7:00 a 10:00 | 1,500 |
| Lona en la fachada con el desayuno y el precio (costo prorrateado) | 500 |
| Degustaciones en 10 oficinas (ingredientes) | 1,200 |
| Diseño de publicaciones (diseñadora independiente) | 1,000 |
| Promoción «trae a un compañero» (desayunos a mitad de precio) | 800 |
| **Total** | **5,000** |

Con ventas totales de unas 350,000 pesos al mes (incluidos los desayunos), el presupuesto equivale a 1.4 % de las ventas: razonable. Descarta la radio (cara y poco precisa para su zona) y los volantes masivos.

## Cuándo invertir más o menos
- **Más:** al abrir, al lanzar un producto, cuando llega un competidor o cuando la relación entre el costo por cliente y su valor de vida es muy favorable (lección M11-9).
- **Menos:** cuando la capacidad está llena (no tiene sentido atraer clientes que van a hacer fila y irse) o cuando una acción no está dando resultados.

## La publicidad en las empresas gigantes
Las grandes empresas de consumo invierten cantidades enormes en publicidad: campañas en televisión, digitales, patrocinios deportivos, espectaculares. Muchas trabajan con agencias de publicidad y de medios, y miden con estudios de recordación y de ventas. Coca-Cola, por ejemplo, ha informado en sus reportes anuales gastos publicitarios de miles de millones de dólares al año. Pero los principios son los mismos: objetivo claro, mensaje coherente, medio adecuado y medición.`,
k: `**Publicidad:** comunicación pagada. Métodos de presupuesto: **porcentaje de ventas**, **objetivo y tarea** (el más lógico), paridad con la competencia y «lo que se pueda» (el menos recomendable). Elige medios por **alcance, costo, precisión y facilidad para medir**. Mejor **frecuencia alta en la zona** que alcance lejano. Mensaje con beneficio claro, llamado a la acción y forma de medir.`,
ch: `Una lavandería de colonia patrocina las playeras del equipo de futbol infantil del barrio por 3,000 pesos al año; todos los padres del barrio conocen su nombre.`,
gi: `Coca-Cola informa en su reporte anual (Form 10-K) sus gastos de publicidad, que en años recientes han sido de varios miles de millones de dólares; es una de las empresas que más invierte en publicidad en el mundo.`,
e: `Lupita compara el costo por cliente nuevo de dos medios después de un mes:

| Medio | Gasto | Clientes nuevos que llegaron (por código o pregunta) | Costo por cliente |
|---|---|---|---|
| Anuncios digitales a 1 km | 1,500 | 60 | 25 |
| Radio local (prueba de un mes) | 12,000 | 40 | 300 |

Con un valor de vida de unos 2,200 pesos por cliente, ambos medios «se pagan», pero los anuncios digitales son 12 veces más eficientes. Decide no renovar la radio.`,
r: `La frase sobre «la mitad del dinero que gasto en publicidad» se atribuye con frecuencia a John Wanamaker, fundador de grandes almacenes en Filadelfia en el siglo XIX, aunque los historiadores no han encontrado pruebas definitivas de que la haya dicho. Coca-Cola reporta cada año su gasto en publicidad en su informe anual.`,
f: `The Coca-Cola Company, informe anual (Form 10-K), nota sobre gastos de publicidad; historia de la frase atribuida a John Wanamaker en textos de marketing.`,
err: ["Gastar «lo que sobre» sin objetivo.","Elegir un medio por su alcance total y no por su precisión.","Hacer anuncios sin llamado a la acción ni forma de medir.","Seguir pagando un medio que no da resultados."],
a: `Con el método de objetivo y tarea, arma un presupuesto de marketing de un mes para el negocio que observas: define un objetivo concreto, las acciones, su costo y cómo medirás cada una. Calcula qué porcentaje de las ventas representa.`,
sol: `Si el presupuesto supera con mucho lo que el negocio puede pagar, reduce las acciones menos precisas primero y conserva las que permiten medir resultados.`,
q: [["El método de «objetivo y tarea» consiste en…",["Definir un objetivo, las acciones necesarias y su costo","Gastar lo que sobre","Copiar a la competencia"],0,"Conecta el gasto con un resultado."],
["Para un negocio local, suele ser mejor…",["Llegar muchas veces a pocas personas cercanas","Llegar una vez a millones de personas lejanas","No anunciarse"],0,"La frecuencia en la zona ayuda a recordar."],
["Un buen anuncio debe incluir…",["Un beneficio claro y un llamado a la acción","Mucho texto","Información falsa"],0,"Y una forma de medir."],
["¿Cuándo conviene invertir menos en publicidad?",["Cuando la capacidad ya está llena","Al abrir","Al lanzar un producto"],0,"Atraer clientes que harán fila y se irán no ayuda."]],
t: ["Publicidad", "Presupuesto de marketing"]
},
"M12-8": {
s: `Después de tres meses de marketing, Lupita pregunta: «¿Funcionó? ¿Qué parte del dinero sirvió?». Toño tiene muchos datos (vistas, «me gusta», mensajes), pero no sabe cuáles importan. Es hora de medir el marketing en serio.`,
o: ["Distinguir métricas de alcance, interacción y resultado.","Calcular el retorno de la inversión en marketing.","Usar códigos, preguntas y pruebas A/B para saber qué funciona."],
x: `## Medir para no desperdiciar
El marketing cuesta dinero, y como todo gasto, debe medirse por lo que produce. Medir permite saber **qué acciones funcionan**, en cuáles **invertir más** y cuáles **dejar**. Hoy, gracias a las herramientas digitales, se puede medir mucho más que antes; el reto es medir **lo que importa**.

## Tres niveles de métricas
1. **Alcance (exposición):** cuántas personas vieron el mensaje.
   - Impresiones (veces que se mostró un anuncio).
   - Alcance (personas distintas).
   - Vistas del perfil en mapas.
   - Personas que pasaron frente al letrero.
2. **Interacción (interés):** cuántas personas reaccionaron.
   - Clics, «me gusta», comentarios, veces compartido.
   - Mensajes recibidos.
   - Solicitudes de cómo llegar o llamadas desde el perfil en mapas.
   - **Tasa de clics (CTR):** clics ÷ impresiones × 100.
3. **Resultado (negocio):** cuántas ventas y clientes generó.
   - Pedidos y ventas atribuidos a la acción.
   - Clientes nuevos.
   - **Costo por resultado:** gasto ÷ número de resultados (por ejemplo, costo por pedido o por cliente nuevo).
   - **Retorno de la inversión.**

Los «me gusta» y las vistas son útiles para saber si el mensaje llega, pero **no pagan la renta**. Las métricas más importantes son las de resultado. Una publicación con pocos «me gusta» que trae 30 pedidos vale más que una con miles de «me gusta» y ningún pedido.

## El retorno de la inversión en marketing
El **retorno de la inversión** (en inglés, ROI, *return on investment*) compara lo que se ganó con lo que se invirtió:

**ROI = (margen generado − inversión) ÷ inversión × 100**

Es importante usar el **margen** (lo que queda después del costo del producto), no las ventas, porque las ventas incluyen el costo de los ingredientes.

Ejemplo: los anuncios de desayunos costaron 1,500 pesos y generaron 300 desayunos extra en el mes a 55 pesos (16,500 de ventas) con un margen de 65 % (10,725).
ROI = (10,725 − 1,500) ÷ 1,500 × 100 = **615 %**. Por cada peso invertido, se recuperó el peso y se ganaron 6.15 pesos más.

En publicidad digital también se usa el **ROAS** (retorno sobre el gasto publicitario): ventas generadas ÷ gasto en anuncios. En el ejemplo: 16,500 ÷ 1,500 = 11. Es más fácil de calcular, pero no considera el margen.

## El reto de la atribución
La **atribución** es saber qué acción provocó cada venta. Es difícil, porque un cliente puede ver un anuncio, pasar frente al letrero, leer una reseña y luego comprar porque un compañero lo invitó. Algunas formas sencillas de atribuir:
- **Preguntar:** «¿Cómo nos conociste?» en la caja o en el primer mensaje de WhatsApp.
- **Códigos de promoción distintos** por canal («DESAYUNO1» en anuncios, «DESAYUNO2» en volantes).
- **Números o enlaces distintos:** un número de WhatsApp en la lona y otro en los anuncios; un enlace con marca para cada publicación.
- **Comparar antes y después:** ventas de desayunos en las semanas con anuncios contra las semanas sin anuncios (con cuidado de otros factores, como días festivos).
- **Zonas de prueba:** anunciarse en una zona y no en otra, y comparar.

Ningún método es perfecto, pero combinados dan una buena idea.

## Las pruebas A/B
Una **prueba A/B** compara dos versiones de algo para ver cuál funciona mejor: dos anuncios con distinta foto, dos textos para un mensaje, dos precios para un combo, dos diseños de menú. Se muestra la versión A a un grupo y la B a otro, en condiciones parecidas, y se mide cuál genera más resultados. Reglas básicas:
- **Cambiar una sola cosa a la vez** (si cambias la foto y el texto, no sabes cuál hizo la diferencia).
- **Probar con suficientes personas** para que la diferencia no sea casualidad.
- **Medir el resultado que importa** (pedidos, no solo clics).

Las empresas digitales hacen miles de pruebas A/B. Un ejemplo conocido es la campaña presidencial de Barack Obama en 2008, cuyo equipo probó distintas imágenes y botones en su página de registro; su responsable de análisis, Dan Siroker, contó después que la combinación ganadora aumentó notablemente la tasa de registro.

## Un tablero de marketing
| Métrica | Mes 1 | Mes 2 | Mes 3 |
|---|---|---|---|
| Alcance de anuncios | 18,000 | 21,000 | 24,000 |
| Clics o mensajes | 210 | 280 | 330 |
| Pedidos atribuidos (código o pregunta) | 120 | 190 | 300 |
| Gasto | 1,500 | 1,500 | 1,500 |
| Costo por pedido | 12.5 | 7.9 | 5.0 |
| Margen generado (55 × 65 % por pedido) | 4,290 | 6,793 | 10,725 |
| ROI | 186 % | 353 % | 615 % |

La tendencia muestra que los anuncios funcionan cada vez mejor (el público ya conoce la marca y las publicaciones mejoraron).

## Errores comunes al medir
- **Medir vanidad:** seguidores y «me gusta» sin relación con ventas.
- **No tener forma de atribuir:** gastar sin códigos, preguntas ni comparaciones.
- **Calcular el ROI con ventas en lugar de margen.**
- **Sacar conclusiones con pocos datos** (dos días buenos no prueban nada).
- **No considerar el valor de vida:** un cliente nuevo que regresa muchas veces vale mucho más que su primer pedido (lección M11-8).
- **Medir y no actuar.**

## Cierre del módulo
El marketing de Tortas Lupita pasó de «tener redes» a un sistema: entender al cliente con investigación barata, elegir a quién atender, posicionarse con una idea clara, diseñar una mezcla coherente, cuidar la marca, usar las herramientas digitales con constancia, fijar el presupuesto con objetivos y medir lo que importa. Con eso, cada peso de marketing tiene una razón de ser y un resultado que se puede ver.`,
k: `Métricas de **alcance** (impresiones, vistas), **interacción** (clics, mensajes, **CTR**) y **resultado** (pedidos, clientes, **costo por resultado**). **ROI = (margen − inversión) ÷ inversión**; **ROAS** = ventas ÷ gasto publicitario. **Atribución** con preguntas, códigos, números distintos y comparaciones. **Pruebas A/B:** cambia una sola cosa y mide el resultado que importa.`,
ch: `Una pizzería pone un código distinto en sus volantes de cada colonia; descubre que una colonia genera el triple de pedidos y concentra ahí sus volantes.`,
gi: `Las empresas de comercio electrónico hacen constantemente pruebas A/B en sus sitios y aplicaciones (colores de botones, fotos, textos, procesos de pago) y miden cuál versión genera más ventas.`,
e: `Toño calcula el ROI de las degustaciones en oficinas:

| Concepto | Cálculo | Resultado |
|---|---|---|
| Costo (ingredientes y tiempo) | — | 1,200 + 800 = 2,000 |
| Oficinas que firmaron pedido | — | 3 |
| Margen mensual por oficina | 6,000 × 60 % | 3,600 |
| Margen del primer mes (3 oficinas) | 3 × 3,600 | 10,800 |
| ROI del primer mes | (10,800 − 2,000) ÷ 2,000 | 440 % |

Y si las oficinas se quedan 18 meses, el margen total es de 194,400 pesos. Las degustaciones son, con mucho, la mejor inversión de marketing del negocio.`,
r: `Dan Siroker, quien dirigió el área de análisis digital de la campaña de Barack Obama en 2008, describió cómo el equipo probó varias combinaciones de imágenes y botones en la página de registro de la campaña, y cómo la versión ganadora aumentó de forma importante el número de personas que se registraban.`,
f: `Dan Siroker, «How Obama Raised $60 Million by Running a Simple Experiment» (Optimizely, 2010).`,
err: ["Medir solo «me gusta» y seguidores.","Calcular el ROI con ventas en lugar de margen.","Cambiar varias cosas a la vez en una prueba A/B.","Concluir con muy pocos datos."],
a: `Elige una acción de marketing del negocio que observas (o diseña una). Define cómo vas a atribuir sus resultados (código, pregunta o número distinto), qué métricas de los tres niveles medirás y cómo calcularás el ROI. Diseña una prueba A/B sencilla para mejorarla.`,
sol: `Si no hay forma de saber cuántas ventas trajo la acción, todavía no está lista para lanzarse: agrega un código o una pregunta.`,
q: [["¿Qué métrica es de resultado?",["Pedidos generados por la acción","Número de «me gusta»","Impresiones"],0,"Las de resultado se relacionan con ventas y clientes."],
["El ROI de marketing se calcula como…",["(Margen generado − inversión) ÷ inversión","Ventas ÷ clientes","Clics ÷ impresiones"],0,"Usa el margen, no las ventas."],
["En una prueba A/B conviene…",["Cambiar una sola cosa a la vez","Cambiar todo","No medir"],0,"Así se sabe qué hizo la diferencia."],
["Una forma sencilla de atribuir ventas a un canal es…",["Usar un código de promoción distinto por canal","Adivinar","Contar seguidores"],0,"También preguntar «¿cómo nos conociste?»."]],
t: ["Retorno de la inversión (ROI)", "ROAS"]
}
});
// ===== M13. Recursos humanos =====
Object.assign(window.LECC, {
"M13-1": {
s: `En un año, Tortas Lupita contrató a 14 personas y se le fueron 10. Lupita pasa horas buscando reemplazos, enseñando lo mismo una y otra vez y resolviendo pleitos entre empleados. Toño le dice: «Necesitamos ocuparnos de las personas tanto como de las tortas».`,
o: ["Describir qué hace el área de recursos humanos.","Conocer el ciclo de vida del empleado.","Reconocer cómo cambia la función de RH según el tamaño del negocio."],
x: `## Las personas hacen el negocio
Un negocio puede tener el mejor producto, el mejor local y los mejores proveedores, pero si no tiene a las personas adecuadas, bien preparadas y motivadas, no funciona. El área de **recursos humanos** (RH, también llamada gestión de personas, capital humano o talento) se encarga de **atraer, contratar, desarrollar, motivar, pagar y conservar** a las personas que trabajan en el negocio, y de cumplir con las obligaciones laborales.

## El ciclo de vida del empleado
La forma más clara de entender RH es seguir el camino de una persona en el negocio:

| Etapa | Qué incluye | Lección |
|---|---|---|
| 1. Planear | Cuántas personas se necesitan, en qué puestos y cuándo | M13-1 |
| 2. Reclutar | Atraer candidatos | M13-2 |
| 3. Seleccionar | Elegir al mejor candidato | M13-2 |
| 4. Contratar | Contrato, alta en la seguridad social, prestaciones | M13-3 |
| 5. Integrar (inducción) | Bienvenida y primeros días | M13-4 |
| 6. Capacitar y desarrollar | Aprender y crecer | M13-4 |
| 7. Pagar | Sueldo, prestaciones, nómina | M13-5 |
| 8. Evaluar y motivar | Retroalimentación, reconocimiento | M13-6 |
| 9. Conservar | Clima, cultura, oportunidades | M13-7 |
| 10. Salida | Renuncia, despido, jubilación | M13-8 |

En cada etapa, el negocio puede hacerlo bien o mal, y cada error tiene un costo: contratar a la persona equivocada, perder a un buen empleado, tener una demanda laboral.

## Planear: cuántas personas y cuándo
Antes de contratar, conviene preguntarse:
- **¿Qué trabajo hay que hacer?** (con base en las ventas esperadas y en los procesos, Módulo 9).
- **¿Cuántas horas de trabajo hacen falta y cuándo?** (horas pico, días fuertes, temporadas).
- **¿Qué puestos y perfiles?** (descripciones de puesto, lección M6-8).
- **¿Tiempo completo, medio tiempo o por temporada?**
- **¿Cuánto cuesta cada persona y lo paga el negocio?** (lección M13-5).

Una herramienta sencilla es una tabla de horas por día y por puesto: cuántas personas se necesitan en cada hora del día. En Tortas Lupita, la hora de 13:00 a 14:30 necesita cuatro cocineros; de 16:00 a 18:00, solo uno. Planear así evita tener gente de más en horas flojas o de menos en horas pico.

## RH según el tamaño del negocio
- **Changarro:** el dueño contrata a familiares o conocidos, enseña de palabra y paga en efectivo. No hay «área» de RH.
- **Microempresa y pyme:** el dueño o una administradora se ocupa de RH con apoyo del contador (nómina) y, a veces, de un abogado laboral. Empiezan a escribirse descripciones de puesto, contratos y reglas.
- **Empresa mediana:** hay un jefe o gerente de RH que lleva reclutamiento, nómina, capacitación y relaciones laborales.
- **Gran empresa:** una dirección de personas con áreas especializadas: atracción de talento, compensaciones, capacitación y desarrollo, relaciones laborales (incluida la relación con sindicatos), bienestar, cultura, sistemas de RH y análisis de datos de personas.

## RH como socio del negocio
Durante mucho tiempo, RH se vio solo como un área administrativa: hacer la nómina y archivar contratos. En 1997, el profesor Dave Ulrich propuso que RH debe ser también un **socio estratégico**: ayudar al negocio a lograr sus objetivos a través de las personas (tener el talento que la estrategia necesita, construir la cultura adecuada, preparar a los futuros líderes). Para un negocio pequeño, esto significa algo muy concreto: si la estrategia de Tortas Lupita es la **rapidez**, RH debe contratar personas ágiles, capacitarlas en el proceso rápido y premiar el cumplimiento del tiempo.

## El marco legal
En México, la relación de trabajo está regulada principalmente por la **Ley Federal del Trabajo** (LFT), que establece derechos de los trabajadores y obligaciones de los patrones: contrato, salario mínimo, jornada, descanso, vacaciones, aguinaldo, seguridad social, capacitación, reparto de utilidades, seguridad e higiene, y reglas para la terminación de la relación. También participan el IMSS, el Infonavit, el SAT (por la retención de impuestos) y, en caso de conflictos, los centros de conciliación y los tribunales laborales. Este curso explica estos temas de forma educativa; las reglas cambian y cada caso conviene revisarlo con un especialista.

## El costo de no cuidar a las personas
El caso de Tortas Lupita (14 contrataciones y 10 salidas en un año) tiene costos muy concretos:
- **Tiempo del dueño** buscando, entrevistando y enseñando.
- **Errores y lentitud** de las personas nuevas mientras aprenden.
- **Clientes afectados** por el mal servicio.
- **Cansancio y molestia** del equipo que se queda y tiene que cubrir.
- **Riesgos legales** si las salidas no se manejan bien.

En la lección M13-7 verás cómo calcular el costo de la rotación. Por ahora basta con saber que cuidar a las personas no es un lujo: es una decisión de negocio.

## El plan de Lupita
Lupita decide dedicar dos horas a la semana a RH, con apoyo de la administradora: planear las horas por puesto, escribir las descripciones de puesto que faltan, ordenar los contratos y el alta en el IMSS, crear un proceso de bienvenida y hacer una conversación individual al mes con cada empleado. En las siguientes lecciones construirá cada pieza.`,
k: `**Recursos humanos:** atraer, contratar, desarrollar, motivar, pagar y conservar a las personas, y cumplir con las obligaciones laborales. **Ciclo de vida del empleado:** planear → reclutar → seleccionar → contratar → integrar → capacitar → pagar → evaluar → conservar → salida. RH como **socio estratégico** (Dave Ulrich, 1997). Marco legal en México: **Ley Federal del Trabajo**.`,
ch: `En una panadería familiar, la dueña se ocupa de RH: busca panaderos por recomendación, les enseña durante dos semanas, los da de alta en el IMSS con ayuda del contador y les paga cada sábado.`,
gi: `Las grandes empresas tienen direcciones de personas con miles de colaboradores a su cargo, sistemas de gestión del talento, programas de liderazgo y áreas de relaciones laborales que negocian con sindicatos.`,
e: `Toño arma la tabla de horas por puesto de un día entre semana en el local:

| Horario | Cocineros necesarios | Caja | Reparto |
|---|---|---|---|
| 7:00–11:00 (desayunos) | 2 | 1 | 0 |
| 11:00–13:00 | 2 | 1 | 1 |
| 13:00–14:30 (pico) | 4 | 2 | 1 |
| 14:30–16:00 | 2 | 1 | 1 |
| 16:00–18:00 | 1 | 1 | 0 |

Con la tabla, deciden contratar a dos cocineros de medio tiempo (11:00 a 15:00) en lugar de un cocinero más de tiempo completo, y cubren el pico sin pagar horas ociosas.`,
r: `Dave Ulrich propuso en «Human Resource Champions» (1997) que el área de recursos humanos cumpla cuatro papeles: socio estratégico, experto administrativo, defensor de los empleados y agente de cambio. Su modelo influyó en la organización de RH en muchas empresas grandes.`,
f: `Dave Ulrich, «Human Resource Champions» (1997); Ley Federal del Trabajo (México).`,
err: ["Ver RH solo como «hacer la nómina».","Contratar sin planear cuántas personas y en qué horarios se necesitan.","Ignorar las obligaciones laborales.","Creer que la rotación es «normal» y no tiene costo."],
a: `Haz la tabla de horas por puesto de un día típico del negocio que observas. Compárala con el personal que realmente trabaja en cada hora y propón un ajuste.`,
sol: `Si en horas flojas sobra personal y en horas pico falta, considera turnos escalonados o medio tiempo para cubrir el pico.`,
q: [["El área de recursos humanos se encarga de…",["Atraer, contratar, desarrollar, pagar y conservar a las personas","Comprar insumos","Fijar precios"],0,"Y cumplir las obligaciones laborales."],
["¿Cuál es el orden correcto de las primeras etapas del ciclo del empleado?",["Planear, reclutar, seleccionar, contratar","Contratar, planear, despedir","Pagar, reclutar, planear"],0,"Primero se planea qué se necesita."],
["¿Qué propuso Dave Ulrich?",["Que RH sea también un socio estratégico del negocio","Que no haya RH","Que RH solo haga nómina"],0,"Ayudar al negocio a lograr sus objetivos a través de las personas."],
["En México, la relación de trabajo se regula principalmente por…",["La Ley Federal del Trabajo","La Ley del IVA","El Código de Comercio solamente"],0,"Junto con las leyes de seguridad social."]],
t: ["Recursos humanos", "Ciclo de vida del empleado"]
},
"M13-2": {
s: `Lupita contrata a un cocinero porque «le cayó bien» en la entrevista. A las dos semanas descubre que no sabe trabajar bajo presión y que llega tarde. Toño propone otra forma: definir qué se busca, preguntar lo mismo a todos y pedir una prueba práctica.`,
o: ["Diseñar el perfil y la vacante de un puesto.","Elegir fuentes de reclutamiento.","Realizar una selección con entrevista estructurada y prueba práctica."],
x: `## Reclutar y seleccionar: dos pasos distintos
- **Reclutar** es **atraer** candidatos interesados y adecuados para un puesto.
- **Seleccionar** es **elegir**, entre los candidatos, a la persona que mejor encaja.

Ambos pasos empiezan con la misma pregunta: **¿qué buscamos exactamente?**

## 1. El perfil del puesto
El perfil sale de la descripción de puesto (lección M6-8) y define:
- **Funciones principales** del puesto.
- **Conocimientos y experiencia** necesarios (por ejemplo, seis meses en cocina).
- **Habilidades** (rapidez, trabajo bajo presión, atención al detalle, trato con clientes).
- **Actitudes y valores** que encajan con la cultura (puntualidad, trabajo en equipo, honestidad).
- **Condiciones:** horario, sueldo, prestaciones, ubicación.

Conviene separar lo **indispensable** (sin esto, no) de lo **deseable** (suma, pero no es obligatorio).

## 2. La vacante
El anuncio de la vacante debe ser claro y honesto:
- Nombre del puesto.
- Qué hará la persona (en pocas líneas).
- Requisitos indispensables.
- Horario, sueldo (o rango) y prestaciones.
- Cómo postularse.
- Algo atractivo del negocio (buen ambiente, capacitación, crecimiento).

Ser claro sobre el sueldo y el horario ahorra tiempo a todos: evita entrevistar a personas que no aceptarían las condiciones. Y la vacante no debe discriminar (por edad, sexo, apariencia, estado civil, religión u otros motivos); en México, la ley prohíbe la discriminación en el empleo.

## 3. Las fuentes de reclutamiento
| Fuente | Ventaja | Desventaja |
|---|---|---|
| Recomendaciones de empleados | Candidatos confiables, que conocen el negocio | Puede limitar la diversidad; conflictos si no funciona |
| Letrero en el local | Barato, gente de la zona | Alcance limitado |
| Bolsas de trabajo en línea | Muchos candidatos | Muchos no cumplen el perfil |
| Redes sociales y grupos locales | Barato, rápido | Variable |
| Escuelas técnicas y universidades | Jóvenes con formación | Poca experiencia |
| Servicio Nacional de Empleo | Gratuito, apoyo del gobierno | Variable según la zona |
| Promoción interna | Motiva, conoce la cultura | Hay que cubrir el puesto que deja |

## 4. La selección
Un proceso sencillo y eficaz para un negocio pequeño:
1. **Filtro inicial:** revisar solicitudes o hacer una llamada breve para confirmar requisitos indispensables, horario y sueldo.
2. **Entrevista estructurada:** las mismas preguntas para todos, preparadas antes.
3. **Prueba práctica:** que la persona haga una parte real del trabajo.
4. **Referencias:** llamar a uno o dos empleadores anteriores.
5. **Decisión** con base en los criterios definidos.

## La entrevista estructurada
Las investigaciones sobre selección de personal han encontrado que las **entrevistas estructuradas** (preguntas iguales para todos, con criterios para calificar las respuestas) predicen mejor el desempeño que las entrevistas libres, en las que el entrevistador «platica» y decide por la impresión. Google, por ejemplo, después de analizar sus procesos, adoptó entrevistas estructuradas, como contó Laszlo Bock, su director de personas, en el libro «La nueva fórmula del trabajo» (2015).

Tipos de preguntas útiles:
- **De comportamiento pasado:** «Cuéntame de una vez que tuviste que atender a muchos clientes al mismo tiempo. ¿Qué hiciste?». Lo que alguien hizo antes predice lo que hará.
- **De situación:** «Si llega un cliente molesto porque su torta está fría, ¿qué haces?».
- **Sobre el puesto:** horario, transporte, disponibilidad real.

Califica cada respuesta con una escala sencilla (1 a 5) y compara candidatos con la misma tabla.

## La prueba práctica
Para muchos puestos operativos, la mejor prueba es **ver a la persona trabajar**: preparar tres tortas con la receta, atender un cobro simulado, armar un pedido. Una prueba de 30 a 60 minutos dice más que muchas preguntas. (Si la prueba dura más tiempo o se vuelve trabajo real, debe pagarse).

## Los sesgos al seleccionar
Algunos errores comunes:
- **Primera impresión:** decidir en los primeros minutos.
- **Afinidad:** preferir a quien se parece a uno.
- **Efecto halo:** que una cualidad (es simpático) haga ignorar otras (no tiene experiencia).
- **Contratar por urgencia** al primero que llega.
- **Discriminar** por características que no tienen que ver con el trabajo.

La entrevista estructurada, la prueba práctica y la comparación con criterios ayudan a reducirlos.

## El nuevo proceso de Tortas Lupita
| Etapa | Qué hacen |
|---|---|
| Perfil | Cocinero: indispensable 6 meses en cocina, disponibilidad de 7:00 a 15:00; deseable curso de manejo higiénico |
| Vacante | Letrero en el local y publicación en grupos de empleo de la zona, con sueldo y horario |
| Filtro | Llamada de 5 minutos |
| Entrevista estructurada | 6 preguntas iguales, calificadas de 1 a 5 |
| Prueba práctica | Preparar 3 tortas en hora pico simulada (40 minutos) |
| Referencias | Una llamada al empleo anterior |
| Decisión | La persona con mejor puntaje total |

Con este proceso, de las siguientes cinco contrataciones, cuatro siguen en el negocio seis meses después.

## La decisión y el aviso a los candidatos
Al terminar, conviene avisar a todos los candidatos el resultado, también a los que no fueron elegidos. Es una cortesía que habla bien del negocio y deja la puerta abierta: el segundo lugar de hoy puede ser la siguiente contratación. Además, conviene guardar las tablas de selección: si dentro de unos meses la persona elegida no funciona, servirán para revisar qué falló en el proceso (¿el perfil estaba mal definido?, ¿la prueba práctica no reflejaba el trabajo real?) y mejorarlo para la siguiente vez.`,
k: `**Reclutar** = atraer candidatos; **seleccionar** = elegir al mejor. Parte de un **perfil** (indispensable y deseable) y una **vacante** clara y sin discriminación. Selección: filtro, **entrevista estructurada** (mismas preguntas, con criterios), **prueba práctica**, referencias y decisión. Cuida los **sesgos**: primera impresión, afinidad, efecto halo, urgencia.`,
ch: `Una estética pide a cada candidata hacer un corte a una clienta voluntaria y pregunta a todas lo mismo sobre cómo atienden a una clienta inconforme; elige con una tabla de puntajes.`,
gi: `Google analizó sus procesos de contratación y concluyó que las entrevistas estructuradas y las pruebas de trabajo predicen mejor el desempeño que las preguntas de ingenio que usaba antes, según contó Laszlo Bock.`,
e: `Toño compara a tres candidatos con la tabla de selección (1 a 5):

| Criterio | Peso | Candidato A | Candidato B | Candidato C |
|---|---|---|---|---|
| Experiencia en cocina | 25 % | 4 | 3 | 5 |
| Rapidez en la prueba | 30 % | 3 | 5 | 4 |
| Respuestas sobre clientes | 20 % | 4 | 4 | 3 |
| Disponibilidad de horario | 15 % | 5 | 5 | 2 |
| Referencias | 10 % | 3 | 4 | 4 |
| **Puntaje** | | **3.75** | **4.20** | **3.75** |

Aunque C tiene más experiencia, B gana (4.20 frente a 3.75 de A y C) por su rapidez y su disponibilidad, que son críticas para el puesto.`,
r: `Laszlo Bock, quien fue director de personas de Google, describió en «Work Rules!» (2015; en español, «La nueva fórmula del trabajo») cómo la empresa usó datos para mejorar su selección, privilegiando las entrevistas estructuradas y las evaluaciones del trabajo real.`,
f: `Laszlo Bock, «Work Rules!» (2015); Ley Federal para Prevenir y Eliminar la Discriminación (México).`,
err: ["Contratar por simpatía o por urgencia.","Hacer preguntas distintas a cada candidato.","No ver trabajar a la persona antes de contratarla.","Publicar vacantes con requisitos discriminatorios."],
a: `Diseña el proceso de selección para un puesto del negocio que observas: perfil (indispensable y deseable), texto de la vacante, seis preguntas de entrevista estructurada y una prueba práctica. Prepara la tabla para calificar.`,
sol: `Revisa que al menos la mitad de tus preguntas sean de comportamiento pasado («cuéntame de una vez que…») y que la prueba práctica refleje una tarea real del puesto.`,
q: [["Reclutar significa…",["Atraer candidatos","Despedir","Pagar la nómina"],0,"Seleccionar es elegir entre ellos."],
["Una entrevista estructurada consiste en…",["Hacer las mismas preguntas a todos, con criterios para calificar","Platicar libremente","Preguntar lo que se ocurra"],0,"Predice mejor el desempeño."],
["«Cuéntame de una vez que atendiste a muchos clientes a la vez» es una pregunta de…",["Comportamiento pasado","Situación hipotética","Salario"],0,"Lo que alguien hizo antes predice lo que hará."],
["El efecto halo es…",["Que una cualidad haga ignorar otras","Contratar a un familiar","Un tipo de contrato"],0,"Es un sesgo de selección."]],
t: ["Reclutamiento", "Selección de personal"]
},
"M13-3": {
s: `El nuevo cocinero empieza el lunes. Lupita pregunta al contador: «¿Basta con que le pague cada semana?». El contador responde: «No. Necesita contrato por escrito, alta en el IMSS desde el primer día y todas las prestaciones de ley». Lupita toma nota.`,
o: ["Conocer los elementos básicos de un contrato de trabajo en México.","Identificar las prestaciones mínimas de ley.","Cumplir con el alta en la seguridad social y la nómina."],
x: `## La relación de trabajo
En México, cuando una persona trabaja para otra de forma subordinada (sigue sus instrucciones, en un horario, a cambio de un salario), existe una **relación de trabajo**, aunque no haya contrato firmado. La **Ley Federal del Trabajo** (LFT) protege al trabajador en esa relación y le da derechos mínimos que no se pueden renunciar. Esta lección resume los principales de forma educativa; los montos, plazos y reglas cambian (por ejemplo, el salario mínimo cada año, y reformas como la de vacaciones de 2023), así que siempre hay que revisar la norma vigente y asesorarse con un contador o abogado laboral.

## El contrato individual de trabajo
La ley pide que las condiciones de trabajo consten **por escrito**. El contrato debe incluir, entre otros:
- Datos del trabajador y del patrón.
- Si la relación es por **tiempo indeterminado** (la regla general), por **tiempo determinado** o por **obra determinada** (solo cuando la naturaleza del trabajo lo justifica), o de **temporada**.
- El **puesto** y las funciones.
- El **lugar** de trabajo.
- La **jornada** y el horario.
- El **salario**, la forma y el día de pago.
- La **capacitación** que recibirá.
- Los **días de descanso** y las vacaciones.
- Otras condiciones acordadas.

La ley permite un **periodo de prueba** (en los contratos por tiempo indeterminado, en general de hasta 30 días, con más tiempo para ciertos puestos de dirección o técnicos) y un **periodo de capacitación inicial**, siempre por escrito y con todas las prestaciones.

## Las prestaciones mínimas de ley
| Prestación | Idea general |
|---|---|
| Salario mínimo | No se puede pagar menos del salario mínimo vigente que fija la CONASAMI cada año (hay uno general y otro para la zona libre de la frontera norte) |
| Jornada y descanso | Jornada máxima legal y al menos un día de descanso por cada seis de trabajo; tiempo extra pagado con recargo |
| Aguinaldo | Al menos 15 días de salario al año, pagados antes del 20 de diciembre (proporcional si no se trabajó el año completo) |
| Vacaciones | Desde la reforma de 2023, al menos 12 días en el primer año, aumentando con la antigüedad |
| Prima vacacional | Al menos 25 % del salario de los días de vacaciones |
| Días de descanso obligatorio | Ciertos días festivos establecidos por la ley; si se trabajan, se pagan con recargo |
| Seguridad social | Inscripción en el IMSS desde el primer día, con aportaciones del patrón y del trabajador |
| Vivienda | Aportación al Infonavit (5 % del salario base de cotización, pagada por el patrón) |
| Retiro | Aportaciones al Sistema de Ahorro para el Retiro (SAR) en la cuenta del trabajador |
| Reparto de utilidades (PTU) | Participación de los trabajadores en las utilidades de la empresa, según las reglas de la ley |
| Capacitación | Derecho a recibir capacitación para su trabajo |

Además, el patrón **retiene** al trabajador el ISR que corresponda a su salario y lo entrega al SAT, y emite un **recibo de nómina electrónico** (CFDI de nómina, lección M8-10).

## El alta en el IMSS desde el primer día
Inscribir al trabajador en el **IMSS** desde el primer día es una obligación y una protección para ambos:
- El trabajador tiene servicio médico, incapacidades pagadas, guardería para sus hijos, pensión y otros beneficios.
- El patrón queda protegido: si el trabajador sufre un accidente de trabajo y está inscrito, el IMSS atiende y paga; si no está inscrito, el patrón puede tener que pagar todo, además de multas y cuotas atrasadas.

Para inscribir trabajadores, el negocio necesita primero su **registro patronal** (lección M3-8).

## La subcontratación
Desde la reforma de 2021, en México está **prohibida la subcontratación de personal** (que una empresa ponga a sus trabajadores a trabajar para otra en las actividades principales de esta). Solo se permite la subcontratación de **servicios u obras especializados** que no formen parte de la actividad principal del cliente, y las empresas que los prestan deben estar registradas ante la Secretaría del Trabajo (en el registro conocido como REPSE). Para un negocio como Tortas Lupita, esto significa que sus cocineros, cajeros y repartidores deben ser sus propios trabajadores, no personal «prestado» por otra empresa.

## Trabajadores por honorarios: cuidado
Algunos negocios intentan evitar las prestaciones contratando a personas «por honorarios» (como si fueran independientes) aunque en realidad trabajan con horario, bajo instrucciones y de forma permanente. Si existe subordinación, la ley puede considerar que hay una relación de trabajo, con todos sus derechos. Los honorarios son para servicios profesionales independientes, como el contador externo o la diseñadora que trabaja por proyecto.

## El expediente del trabajador
Para cada persona conviene tener un expediente con:
- Contrato firmado.
- Identificación, CURP, RFC, número de seguridad social, comprobante de domicilio.
- Constancia de alta en el IMSS.
- Descripción de puesto.
- Registros de capacitación.
- Recibos de nómina.
- Registros de vacaciones y faltas.
- Evaluaciones.

Además de ordenar el trabajo, el expediente es la mejor defensa ante un conflicto laboral.

## Los primeros días del cocinero
Para el nuevo cocinero, Lupita y la administradora preparan:
- Contrato por tiempo indeterminado con periodo de prueba de 30 días, por escrito.
- Alta en el IMSS el mismo lunes.
- Sueldo por encima del mínimo vigente, pagado por transferencia cada semana con su recibo electrónico.
- Expediente completo.
- Explicación clara de sus prestaciones: aguinaldo, vacaciones, prima vacacional, días festivos.

El cocinero comenta que es la primera vez que un trabajo le explica sus derechos el primer día. Esa confianza también es parte de la cultura.`,
k: `Hay **relación de trabajo** cuando alguien trabaja subordinado a cambio de salario, aunque no haya contrato. Contrato **por escrito** (tiempo indeterminado como regla; periodo de prueba limitado). **Prestaciones mínimas:** salario mínimo vigente, jornada y descanso, **aguinaldo** (al menos 15 días), **vacaciones** (al menos 12 días el primer año desde 2023) y **prima vacacional** (25 %), días festivos, **IMSS desde el primer día**, Infonavit, SAR, PTU y capacitación. Subcontratación de personal **prohibida** desde 2021.`,
ch: `Una tortillería con tres trabajadores los inscribe en el IMSS desde el primer día; cuando uno se lastima la mano, el IMSS lo atiende y le paga la incapacidad, sin que la dueña tenga que cubrir el hospital.`,
gi: `Las grandes empresas tienen áreas de nómina y relaciones laborales que administran miles de contratos, calculan prestaciones, pagan cuotas de seguridad social y, cuando hay sindicato, negocian contratos colectivos de trabajo.`,
e: `La administradora calcula las prestaciones anuales mínimas del cocinero (sueldo diario de 400 pesos, primer año):

| Prestación | Cálculo | Pesos |
|---|---|---|
| Aguinaldo (15 días) | 15 × 400 | 6,000 |
| Vacaciones (12 días, ya incluidas en el sueldo anual) | 12 × 400 | 4,800 |
| Prima vacacional (25 % de las vacaciones) | 4,800 × 25 % | 1,200 |

Además del sueldo de todo el año, el negocio debe prever el aguinaldo y la prima vacacional, más las cuotas de seguridad social (lección M13-5). Son datos ilustrativos: el contador calcula los montos exactos.`,
r: `En abril de 2021 se publicó en México la reforma en materia de subcontratación laboral, que prohibió la subcontratación de personal y estableció un registro (REPSE) para las empresas que prestan servicios especializados. Al año siguiente, en 2023, entró en vigor la reforma que aumentó las vacaciones mínimas a 12 días desde el primer año de trabajo.`,
f: `Diario Oficial de la Federación, reforma en materia de subcontratación (23 de abril de 2021) y reforma a los artículos 76 y 78 de la LFT sobre vacaciones (27 de diciembre de 2022); CONASAMI, salarios mínimos vigentes.`,
err: ["No dar de alta al trabajador en el IMSS desde el primer día.","No tener contrato por escrito.","Contratar «por honorarios» a quien trabaja con horario y bajo instrucciones.","Olvidar prever el aguinaldo y la prima vacacional."],
a: `Arma la lista de verificación de contratación para un nuevo empleado del negocio que observas: documentos, contrato, alta en el IMSS, expediente y explicación de prestaciones. Consulta en el sitio de la CONASAMI el salario mínimo vigente.`,
sol: `Revisa que la lista incluya el registro patronal (si no existe), el alta en el IMSS el primer día y la entrega de una copia del contrato al trabajador.`,
q: [["¿Cuándo debe darse de alta a un trabajador en el IMSS?",["Desde el primer día de trabajo","Después de tres meses","Solo si lo pide"],0,"Es una obligación y una protección."],
["El aguinaldo mínimo en México es de…",["15 días de salario","5 días","Un mes siempre"],0,"Pagado antes del 20 de diciembre."],
["Desde la reforma de 2023, las vacaciones mínimas del primer año son de…",["12 días","6 días","30 días"],0,"Y aumentan con la antigüedad."],
["Desde 2021, en México la subcontratación de personal…",["Está prohibida, salvo servicios especializados registrados","Es obligatoria","No tiene reglas"],0,"Las empresas de servicios especializados deben estar en el REPSE."]],
t: ["Contrato individual de trabajo", "Prestaciones de ley"]
},
"M13-4": {
s: `El primer día, la nueva cajera llega y nadie la esperaba. Le dan un mandil y le dicen «aprende viendo». A la semana renuncia. Lupita se pregunta cuánto talento ha perdido así y decide preparar un buen primer día.`,
o: ["Diseñar un proceso de inducción para nuevos empleados.","Planear la capacitación inicial y continua.","Medir si la capacitación funciona."],
x: `## Los primeros días importan mucho
Los primeros días y semanas de una persona en un trabajo son decisivos: en ese tiempo decide si se queda, aprende cómo se hacen las cosas y se forma una idea de la cultura del negocio. Muchas renuncias ocurren en los primeros meses, a menudo porque la persona no se sintió bienvenida, no entendió qué se esperaba de ella o no recibió la capacitación necesaria.

## La inducción
La **inducción** (o integración, en inglés *onboarding*) es el proceso de recibir a una persona nueva y ayudarle a integrarse al negocio. Tiene tres objetivos:
1. **Que se sienta bienvenida.**
2. **Que entienda el negocio:** su historia, su propósito, sus valores, su forma de trabajar.
3. **Que sepa qué hacer:** su puesto, sus tareas, sus reglas, a quién preguntar.

## Un buen primer día
Lista de lo que debe pasar el primer día:
- **Alguien la espera** y la presenta con el equipo.
- **Recibe su uniforme**, su lugar para guardar sus cosas y lo necesario para trabajar.
- **Conoce el local:** dónde está cada cosa, las salidas de emergencia, el botiquín.
- **Conoce la historia y los valores** del negocio (en 10 minutos, con entusiasmo).
- **Recibe su descripción de puesto** y sus horarios.
- **Conoce las reglas básicas:** puntualidad, uso del celular, higiene, cómo pedir permiso, a quién avisar si falta.
- **Firma su contrato** y entrega sus documentos (lección M13-3).
- **Tiene un «padrino» o «madrina»:** un compañero con experiencia que la acompaña las primeras semanas.
- **Hace algo real**, aunque sea pequeño, para que se sienta útil.
- **Al final del día,** alguien le pregunta cómo le fue.

## El plan de las primeras semanas
| Momento | Qué pasa |
|---|---|
| Día 1 | Bienvenida, recorrido, reglas, padrino, primeras tareas sencillas |
| Semana 1 | Aprende los procedimientos principales de su puesto con su padrino |
| Semana 2 | Hace el trabajo con supervisión cercana |
| Semana 4 | Trabaja sola; conversación con su jefe sobre cómo va |
| Mes 3 | Evaluación del periodo de inducción; se definen siguientes pasos |

## La capacitación
La **capacitación** es el proceso de enseñar a las personas los conocimientos y habilidades que necesitan para hacer bien su trabajo. Además de ser útil para el negocio, en México es un **derecho del trabajador** y una obligación del patrón según la Ley Federal del Trabajo.

Hay dos grandes tipos:
- **Capacitación inicial:** lo que la persona necesita para empezar (recetas, procesos, caja, higiene, atención al cliente).
- **Capacitación continua:** para mejorar, aprender nuevas tareas, adaptarse a cambios o prepararse para crecer (manejo de un sistema nuevo, liderazgo para un futuro encargado).

## Cómo capacitar bien en un negocio pequeño
Un método clásico y muy eficaz para tareas prácticas viene de un programa de entrenamiento usado en Estados Unidos durante la Segunda Guerra Mundial (*Training Within Industry*), y se resume en cuatro pasos:
1. **Preparar:** explicar qué se va a aprender y por qué importa.
2. **Mostrar:** el instructor hace la tarea despacio, explicando cada paso y los puntos clave.
3. **Practicar:** la persona hace la tarea mientras el instructor observa y corrige.
4. **Dar seguimiento:** la persona trabaja sola, y el instructor revisa de vez en cuando y resuelve dudas.

A esto se suma el uso de los **procedimientos escritos** con fotos (lección M9-9): la persona puede consultarlos cuando tenga dudas.

## Qué capacitar en Tortas Lupita
| Tema | Para quién | Cómo |
|---|---|---|
| Recetas y procedimientos | Cocina | Mostrar y practicar con el procedimiento escrito |
| Manejo higiénico de alimentos | Todos los que tocan alimentos | Curso (existen cursos gratuitos o de bajo costo de autoridades sanitarias y cámaras) |
| Caja, cobro y corte | Caja | Práctica con supervisión |
| Atención al cliente y quejas | Todos | Juego de roles con el protocolo (lección M11-7) |
| Seguridad (gas, extintores, primeros auxilios) | Todos | Práctica una vez al año |
| Liderazgo y supervisión | Encargados | Curso externo o lecturas y conversación mensual |

## Medir la capacitación
Para saber si la capacitación funciona, se pueden revisar cuatro niveles (propuestos por Donald Kirkpatrick en los años cincuenta):
1. **Reacción:** ¿a la persona le pareció útil?
2. **Aprendizaje:** ¿aprendió? (una prueba práctica).
3. **Comportamiento:** ¿lo aplica en su trabajo diario? (observación).
4. **Resultados:** ¿mejoró algún indicador? (menos errores, menos tiempo, menos quejas, menos merma).

En un negocio pequeño, basta con comparar indicadores antes y después: tiempo de preparación, errores de caja, quejas.

## La capacitación como inversión
Algunos dueños temen capacitar porque «si los preparo, se van a ir a otro lado». Pero el riesgo contrario es peor: no capacitar y que se queden personas que hacen mal su trabajo. Además, la capacitación es una de las razones por las que las personas se quedan en un empleo: sienten que crecen.

## En las empresas gigantes
Las grandes empresas tienen universidades corporativas y programas de formación para miles de personas. McDonald's, por ejemplo, abrió en 1961 su «Hamburger University», un centro de capacitación para gerentes que con los años se extendió a varios países. Muchas cadenas tienen programas para que un empleado de piso pueda llegar a gerente de tienda. La lógica es la misma que la del padrino de la nueva cajera: enseñar bien desde el primer día.`,
k: `**Inducción:** bienvenida, entender el negocio y saber qué hacer; con **padrino** y plan de las primeras semanas. **Capacitación** inicial y continua (también un **derecho** del trabajador en México). Método de cuatro pasos: **preparar, mostrar, practicar, dar seguimiento**. Mide con los cuatro niveles de Kirkpatrick: reacción, aprendizaje, comportamiento y resultados.`,
ch: `Una ferretería asigna a cada vendedor nuevo un compañero con experiencia durante dos semanas y le da una lista de los 50 productos más vendidos con su ubicación y su precio; los nuevos aprenden en la mitad de tiempo.`,
gi: `McDonald's fundó en 1961 la Hamburger University para capacitar a sus gerentes; con los años abrió campus en varios países y se convirtió en un ejemplo conocido de universidad corporativa.`,
e: `Lupita compara los resultados de la nueva inducción con la anterior:

| Indicador | Sin inducción | Con inducción y padrino |
|---|---|---|
| Personas que se van en el primer mes | 4 de 10 | 1 de 10 |
| Días para trabajar sola en caja | 12 | 5 |
| Errores de caja en el primer mes | 18 | 5 |
| Costo de la inducción (horas del padrino) | 0 | 1,500 por persona |

Con 10 contrataciones al año, evitar 3 salidas tempranas ahorra mucho más que los 15,000 pesos que cuesta la inducción.`,
r: `McDonald's inauguró la Hamburger University en 1961, en un sótano de un restaurante en Elk Grove Village, Illinois. Con el tiempo se convirtió en un centro de formación de gerentes con presencia internacional, y la empresa informa que miles de personas han pasado por sus programas.`,
f: `McDonald's Corporation, información corporativa sobre Hamburger University; Donald Kirkpatrick, «Evaluating Training Programs» (1994).`,
err: ["Recibir a una persona nueva sin que nadie la espere.","Capacitar solo diciendo «aprende viendo».","No dar seguimiento después de la primera semana.","No capacitar por miedo a que la persona se vaya."],
a: `Diseña el primer día y el plan de las primeras cuatro semanas para un puesto del negocio que observas. Escribe cómo enseñarías una tarea clave con los cuatro pasos (preparar, mostrar, practicar, dar seguimiento).`,
sol: `Un buen plan tiene un responsable (padrino), tareas concretas por semana y una conversación al final del primer mes.`,
q: [["La inducción busca que la persona nueva…",["Se sienta bienvenida, entienda el negocio y sepa qué hacer","Firme sin leer","Trabaje sola desde el primer minuto"],0,"Son sus tres objetivos."],
["Un «padrino» en la inducción es…",["Un compañero con experiencia que acompaña al nuevo","El dueño del negocio","Un cliente"],0,"Ayuda a integrarse y aprender."],
["Los cuatro pasos para enseñar una tarea práctica son…",["Preparar, mostrar, practicar, dar seguimiento","Leer, olvidar, repetir, salir","Contratar, pagar, evaluar, despedir"],0,"Método muy eficaz para tareas prácticas."],
["En México, la capacitación es…",["Un derecho del trabajador y una obligación del patrón","Opcional siempre","Prohibida"],0,"Según la Ley Federal del Trabajo."]],
t: ["Inducción", "Capacitación"]
},
"M13-5": {
s: `Lupita le paga al cocinero 9,000 pesos al mes y cree que eso cuesta. Al final del año, entre aguinaldo, vacaciones, cuotas del IMSS y otros pagos, descubre que le costó bastante más. ¿Cuánto cuesta realmente un empleado?`,
o: ["Distinguir sueldo bruto, sueldo neto y costo total para el negocio.","Calcular de forma aproximada el costo real de un empleado.","Entender cómo funciona la nómina."],
x: `## Tres números distintos
Cuando se habla de lo que gana o cuesta un empleado, hay tres números que se confunden:
- **Sueldo bruto:** lo que se acuerda pagar antes de descuentos (por ejemplo, 9,000 pesos al mes).
- **Sueldo neto:** lo que el trabajador recibe en su cuenta después de las **retenciones** (el ISR que le corresponde y su parte de las cuotas del IMSS).
- **Costo total para el negocio:** el sueldo bruto **más** todo lo que el patrón paga adicionalmente: prestaciones (aguinaldo, prima vacacional), cuotas patronales de seguridad social (IMSS, Infonavit, SAR) e impuesto sobre nómina estatal, entre otros.

Para el trabajador, lo importante es el neto. Para el negocio, lo importante es el **costo total**, porque es lo que hay que cubrir con el margen de las ventas.

## Los componentes del costo total
De forma general y aproximada (los porcentajes cambian según el salario, la clase de riesgo de trabajo de la empresa, el año y el estado):
1. **Sueldo** de todo el año (incluye los días de descanso y de vacaciones, que se pagan).
2. **Aguinaldo:** al menos 15 días de salario.
3. **Prima vacacional:** al menos 25 % de los días de vacaciones.
4. **Cuotas patronales al IMSS:** por enfermedades y maternidad, invalidez y vida, riesgos de trabajo, guarderías y prestaciones sociales, entre otros. Su porcentaje depende del salario y del riesgo de la actividad.
5. **Aportaciones al Infonavit** (5 % del salario base de cotización) y al **SAR** (retiro, cesantía y vejez; las aportaciones patronales para cesantía y vejez han ido aumentando gradualmente en los últimos años por una reforma).
6. **Impuesto sobre nómina** del estado (normalmente entre 2 % y 4 % de los salarios).
7. **Otros:** uniformes, capacitación, prestaciones adicionales que el negocio decida dar (vales, bonos), reparto de utilidades si hay utilidades.

Como referencia muy general, para salarios bajos y medios, el costo total para el negocio suele estar varias decenas de puntos porcentuales por encima del sueldo bruto. Por eso la calculadora del curso permite ajustar los porcentajes: es una herramienta educativa, y el cálculo exacto lo hace el contador con el sistema de nómina.

## El ejemplo con la calculadora
Con la calculadora «Costo real de un empleado» y estos datos ilustrativos:
- Sueldo mensual bruto: 9,000 pesos.
- Aguinaldo: 15 días.
- Vacaciones: 12 días; prima vacacional de 25 %.
- Cuotas patronales de IMSS, Infonavit y SAR (aproximación): 25 % del sueldo anual.
- Impuesto sobre nómina: 3 %.

| Concepto | Pesos al año |
|---|---|
| Sueldos (12 meses) | 108,000 |
| Aguinaldo (300 × 15) | 4,500 |
| Prima vacacional (300 × 12 × 25 %) | 900 |
| Cuotas de seguridad social (25 % de 108,000) | 27,000 |
| Impuesto sobre nómina (3 % de 113,400) | 3,402 |
| **Costo total** | **143,802** |
| **Costo mensual promedio** | **11,984** |

El empleado de «9,000 pesos» cuesta, en este ejemplo, unos **12,000 pesos al mes** (alrededor de 33 % más que su sueldo).

## ¿Qué es la nómina?
La **nómina** es el proceso de calcular y pagar los sueldos de los trabajadores en cada periodo (semana, catorcena, quincena o mes). Incluye:
1. Registrar los **días y horas** trabajados (asistencia, faltas, horas extra).
2. Calcular las **percepciones:** sueldo, horas extra, bonos, comisiones, prestaciones.
3. Calcular las **deducciones:** ISR retenido, cuota obrera del IMSS, préstamos (por ejemplo, del Infonavit o de la empresa), pensión alimenticia si un juez la ordenó.
4. Pagar el **neto** (de preferencia por transferencia).
5. Emitir el **recibo de nómina electrónico** (CFDI de nómina).
6. Pagar las **cuotas** y entregar las **retenciones** en sus fechas.

En un negocio pequeño, el contador suele calcular la nómina con un sistema; la administradora reúne la información de asistencia y paga.

## Pagar bien y a tiempo
- **Paga siempre a tiempo:** nada destruye más la confianza que un sueldo atrasado.
- **Explica el recibo:** que cada persona entienda sus percepciones y deducciones.
- **Paga por transferencia:** deja registro y es más seguro que el efectivo.
- **Revisa que el salario de cotización sea el real:** registrar ante el IMSS un salario menor al que se paga es ilegal y deja al trabajador con menos protección (por ejemplo, en incapacidades o pensión).

## Sueldo, productividad y decisiones
Conocer el costo real permite tomar mejores decisiones:
- **¿Conviene contratar?** El margen extra que genera la persona debe ser mayor que su costo total (lección M2-4).
- **¿Tiempo completo o medio tiempo?** Según las horas que realmente se necesitan (lección M13-1).
- **¿Cuánto puedo subir sueldos?** Cada aumento tiene un efecto multiplicado en prestaciones y cuotas.
- **¿Qué precio necesito?** El costo de personal es uno de los grandes gastos de operación (lección M8-2).

## Más allá del sueldo: la compensación total
Las personas no trabajan solo por el sueldo. La **compensación total** incluye también prestaciones adicionales (comida, vales, seguro de gastos médicos), horarios flexibles, capacitación, oportunidades de crecimiento y buen ambiente. Un negocio pequeño que no puede pagar los sueldos más altos puede competir por talento con otras cosas: comida incluida, horarios que permitan estudiar, trato digno y posibilidades de ascenso.

## En las empresas gigantes
Las grandes empresas tienen áreas de **compensaciones** que diseñan tabuladores de sueldos por puesto, comparan sus sueldos con el mercado mediante encuestas salariales, diseñan bonos por resultados y administran prestaciones para miles de personas. En muchas, el costo de personal es uno de los rubros más grandes de su estado de resultados.`,
hr: "empleado",
k: `**Sueldo bruto** (acordado), **neto** (lo que recibe el trabajador tras retenciones) y **costo total** (bruto + aguinaldo + prima vacacional + cuotas IMSS, Infonavit y SAR + impuesto sobre nómina + otros). Ejemplo ilustrativo: 9,000 pesos de sueldo → unos **12,000** de costo mensual. **Nómina:** registrar, calcular percepciones y deducciones, pagar, timbrar el CFDI de nómina y enterar cuotas y retenciones.`,
ch: `Un taller con dos ayudantes descubre con su contador que cada uno le cuesta un tercio más que su sueldo; decide subir un poco el precio de la mano de obra para que el negocio siga siendo rentable.`,
gi: `Las grandes empresas comparan sus sueldos con el mercado mediante encuestas salariales y diseñan tabuladores por puesto; el costo de personal aparece como uno de los gastos principales en sus estados financieros.`,
e: `Lupita usa la calculadora para decidir si contrata a un cocinero más para la hora pico:

| Concepto | Pesos al mes |
|---|---|
| Costo total del cocinero (calculadora) | 11,984 |
| Tortas extra que permite vender en la hora pico | 30 al día × 26 = 780 |
| Margen extra (780 × 24) | 18,720 |
| **Beneficio neto de contratarlo** | **6,736** |

La contratación conviene. Si solo permitiera vender 15 tortas más al día (9,360 de margen), no se pagaría.`,
r: `En México, la reforma a la Ley del Seguro Social publicada en diciembre de 2020 estableció un aumento gradual, entre 2023 y 2030, de las aportaciones patronales para el seguro de cesantía en edad avanzada y vejez, con el objetivo de mejorar las pensiones de los trabajadores. Esto incrementa poco a poco el costo de la nómina para los patrones.`,
f: `Diario Oficial de la Federación, reforma a la Ley del Seguro Social y a la Ley del SAR (16 de diciembre de 2020); IMSS, información para patrones (imss.gob.mx).`,
err: ["Creer que el empleado cuesta lo mismo que su sueldo.","Registrar ante el IMSS un salario menor al real.","Pagar tarde la nómina.","Contratar sin comparar el costo total con el margen que generará la persona."],
a: `Con la calculadora «Costo real de un empleado», calcula el costo total de dos puestos del negocio que observas (con sueldos aproximados). Compáralo con el margen extra que genera cada puesto y escribe una conclusión.`,
sol: `Recuerda que los porcentajes de la calculadora son aproximados y editables; para cifras exactas, pide a un contador un cálculo con el sistema de nómina.`,
q: [["El sueldo neto es…",["Lo que recibe el trabajador después de retenciones","Lo que cuesta al negocio","El sueldo antes de descuentos"],0,"Para el negocio importa el costo total."],
["¿Cuál de estos forma parte del costo total de un empleado para el negocio?",["Cuotas patronales al IMSS e impuesto sobre nómina","El IVA de las ventas","La renta del local"],0,"Además de sueldo y prestaciones."],
["Si el sueldo diario es de 300 pesos, el aguinaldo mínimo es de…",["4,500 pesos","300 pesos","9,000 pesos"],0,"15 días × 300."],
["¿Por qué es un error registrar un salario menor al real ante el IMSS?",["Es ilegal y deja al trabajador con menos protección","Porque se paga más","No es un error"],0,"Afecta incapacidades y pensión."]],
t: ["Sueldo bruto", "Sueldo neto"]
},
"M13-6": {
s: `Rosa, la cajera, es la más rápida y amable, pero gana lo mismo que todos y nadie se lo dice. Un día comenta que está pensando en irse «a donde la valoren». Lupita se da cuenta de que nunca ha hablado con su equipo sobre cómo hacen su trabajo.`,
o: ["Diseñar una evaluación del desempeño sencilla y justa.","Dar retroalimentación útil.","Aplicar ideas sobre motivación al día a día del negocio."],
x: `## ¿Para qué evaluar el desempeño?
La **evaluación del desempeño** es el proceso de revisar, con criterios claros, qué tan bien hace una persona su trabajo. No es un examen para castigar, sino una conversación para:
- **Reconocer** lo que se hace bien.
- **Corregir** lo que no está funcionando.
- **Acordar** metas y apoyos para mejorar.
- **Decidir** con justicia aumentos, bonos, ascensos o, si hace falta, salidas.
- **Desarrollar** a las personas.

Sin evaluación, las decisiones sobre las personas se toman por impresiones, y los mejores empleados sienten que da igual esforzarse.

## Qué evaluar
Una evaluación útil combina dos cosas:
1. **Resultados:** los indicadores del puesto (lección M6-8). Para un cocinero: tiempo de preparación, tortas rehechas, merma de su estación. Para una cajera: errores de caja, tiempo de atención, quejas.
2. **Comportamientos:** cómo hace el trabajo, ligado a los valores del negocio: puntualidad, trabajo en equipo, trato al cliente, limpieza, iniciativa.

Ejemplo de formato para la cajera:

| Criterio | Indicador o ejemplo | Calificación (1 a 5) |
|---|---|---|
| Rapidez | Tiempo promedio de cobro | 5 |
| Exactitud | Diferencias en el corte de caja | 5 |
| Trato al cliente | Comentarios, quejas, observación | 5 |
| Puntualidad | Retardos en el periodo | 4 |
| Trabajo en equipo | Apoya en la hora pico | 5 |
| Iniciativa | Propone mejoras | 4 |

## Cada cuánto
- **Conversaciones breves y frecuentes:** retroalimentación en el momento, cuando algo sale muy bien o muy mal.
- **Conversación uno a uno mensual:** 15 a 20 minutos con cada persona (lección M7-5).
- **Evaluación formal** cada seis meses o cada año, con el formato.

Muchas empresas han descubierto que las evaluaciones una vez al año, sin conversaciones durante el año, sirven poco: la retroalimentación llega demasiado tarde.

## Cómo dar retroalimentación
Una retroalimentación útil es:
- **Específica:** «Hoy atendiste a los 20 clientes de la fila en 15 minutos sin un solo error» en lugar de «buen trabajo».
- **Sobre hechos y comportamientos, no sobre la persona:** «Llegaste 20 minutos tarde tres veces esta semana» en lugar de «eres irresponsable».
- **Oportuna:** cerca del momento.
- **Equilibrada:** reconocer lo bueno con frecuencia, no solo señalar errores.
- **Orientada al futuro:** «¿Qué necesitas para llegar a tiempo?».
- **En privado** cuando es para corregir; puede ser en público cuando es para reconocer.

Una estructura sencilla para corregir es: **situación** (cuándo y dónde), **comportamiento** (qué pasó exactamente), **impacto** (qué efecto tuvo) y **acuerdo** (qué se hará distinto).

## ¿Qué motiva a las personas?
La **motivación** es lo que impulsa a una persona a esforzarse. Hay varias teorías clásicas útiles para un negocio:
- **Jerarquía de necesidades de Abraham Maslow (1943):** las personas buscan satisfacer necesidades en orden aproximado: fisiológicas (salario para vivir), seguridad (estabilidad, prestaciones), pertenencia (buen equipo), reconocimiento y autorrealización (crecer, aprender). Un sueldo justo es la base, pero no basta.
- **Teoría de los dos factores de Frederick Herzberg (1959):** hay **factores de higiene** (sueldo, condiciones, trato del jefe, reglas) que, si faltan, generan insatisfacción, pero que por sí solos no motivan; y **factores motivadores** (logro, reconocimiento, trabajo interesante, responsabilidad, crecimiento) que sí generan motivación. Pagar a tiempo evita la molestia; reconocer y dar responsabilidad motiva.
- **Motivación intrínseca y extrínseca:** la extrínseca viene de recompensas externas (dinero, premios); la intrínseca, del interés por el trabajo mismo, el sentido de propósito, la autonomía y el dominio de una habilidad. Autores como Daniel Pink (en «La sorprendente verdad sobre qué nos motiva», 2009) resumieron investigaciones que sugieren que, en muchos trabajos, la autonomía, el dominio y el propósito pesan mucho.

## Formas prácticas de motivar en un negocio pequeño
- **Pagar justo y a tiempo** (higiene: sin esto, nada funciona).
- **Reconocer** en voz alta y con frecuencia.
- **Dar responsabilidad:** que Rosa entrene a las cajeras nuevas.
- **Escuchar ideas** y aplicarlas (Kaizen, lección M9-7).
- **Mostrar el propósito:** cómo su trabajo ayuda a los clientes y al negocio.
- **Ofrecer crecimiento:** un camino de cajera a encargada de turno.
- **Bonos ligados a resultados claros**, cuando sea posible (por ejemplo, por cero diferencias de caja en el mes).
- **Cuidar el ambiente:** trato respetuoso, reglas claras, equidad.

## Los errores que desmotivan
- Tratar igual a quien se esfuerza y a quien no.
- Prometer y no cumplir.
- Regañar en público.
- Cambiar las reglas sin explicar.
- Ignorar las ideas del equipo.
- Favoritismo con familiares o amigos.

## El caso de Rosa
Lupita tiene su primera conversación formal con Rosa: le reconoce con ejemplos concretos su rapidez y su trato, le pregunta qué le gustaría hacer y le ofrece ser la **capacitadora de las cajeras nuevas** con un aumento y un bono trimestral si las nuevas cajeras cumplen sus indicadores. Rosa se queda, y las cajeras que ella entrena aprenden en la mitad del tiempo.

## Ser justos
La evaluación pierde todo su valor si no es justa: los mismos criterios para todos, incluidos los familiares, y decisiones explicadas.`,
k: `**Evaluación del desempeño:** revisar con criterios claros **resultados** y **comportamientos** para reconocer, corregir, decidir y desarrollar. Retroalimentación **específica, sobre hechos, oportuna, equilibrada y en privado** para corregir (situación, comportamiento, impacto, acuerdo). Motivación: **Maslow**, **Herzberg** (higiene frente a motivadores), intrínseca y extrínseca.`,
ch: `En una papelería, la dueña tiene una conversación mensual de 15 minutos con cada empleado: qué salió bien, qué mejorar y qué necesita. La rotación baja a casi cero.`,
gi: `Varias grandes empresas, como Adobe, Deloitte y Microsoft, anunciaron en la década de 2010 cambios para reemplazar o complementar sus evaluaciones anuales con conversaciones más frecuentes entre jefes y colaboradores.`,
e: `Lupita calcula si conviene el bono de Rosa como capacitadora:

| Concepto | Antes | Con Rosa como capacitadora |
|---|---|---|
| Días para que una cajera nueva trabaje sola | 10 | 5 |
| Errores de caja de cajeras nuevas en su primer mes | 15 | 4 |
| Costo de los errores (promedio 80 pesos c/u) | 1,200 | 320 |
| Bono de Rosa (por trimestre) | — | 1,500 |

Con 4 cajeras nuevas al año, el ahorro en errores (unos 3,500 pesos) y en tiempo de capacitación (5 días menos por cajera) cubre una buena parte de los 6,000 pesos anuales del bono. Y lo más importante: conserva a su mejor cajera, cuyo reemplazo costaría unos 7,000 pesos (lección M13-7), además de su experiencia.`,
r: `Frederick Herzberg publicó en 1959, con Mausner y Snyderman, «The Motivation to Work», basado en entrevistas a ingenieros y contadores, donde distinguió entre factores de higiene y factores motivadores. Décadas después, empresas como Adobe (2012) y Deloitte (2015) anunciaron que reemplazaban sus evaluaciones anuales tradicionales por conversaciones más frecuentes.`,
f: `F. Herzberg, B. Mausner y B. Snyderman, «The Motivation to Work» (1959); A. Maslow, «A Theory of Human Motivation» (1943); Daniel Pink, «Drive» (2009).`,
err: ["Evaluar solo una vez al año y sin conversaciones intermedias.","Dar retroalimentación vaga o sobre la persona en lugar de sobre hechos.","Corregir en público.","Creer que el dinero es lo único que motiva."],
a: `Diseña el formato de evaluación de un puesto del negocio que observas: tres criterios de resultado y tres de comportamiento, con su indicador. Escribe una retroalimentación de reconocimiento y otra de corrección con la estructura situación-comportamiento-impacto-acuerdo.`,
sol: `Revisa que cada criterio tenga un indicador o un ejemplo observable; si no se puede observar, no se puede evaluar con justicia.`,
q: [["La evaluación del desempeño sirve para…",["Reconocer, corregir, decidir con justicia y desarrollar","Castigar","Despedir a todos"],0,"Es una conversación con criterios claros."],
["Una retroalimentación útil es…",["Específica y sobre hechos","Vaga y sobre la persona","Siempre en público"],0,"«Atendiste a 20 clientes en 15 minutos sin errores»."],
["Según Herzberg, el sueldo es un factor…",["De higiene: si falta, genera insatisfacción","Motivador principal","Irrelevante"],0,"Los motivadores son logro, reconocimiento, crecimiento."],
["¿Cuál de estas acciones suele motivar?",["Reconocer en voz alta y dar responsabilidad","Regañar en público","Prometer y no cumplir"],0,"Son factores motivadores."]],
t: ["Evaluación del desempeño", "Retroalimentación"]
},
"M13-7": {
s: `Toño calcula que el año pasado entraron 14 personas y salieron 10, con una plantilla promedio de 9. «Es una puerta giratoria», dice. ¿Cuánto les cuesta que la gente se vaya y qué pueden hacer para que se quede?`,
o: ["Calcular la tasa de rotación y su costo.","Reconocer las causas más comunes de rotación.","Proponer acciones para mejorar el clima laboral y la retención."],
x: `## La rotación de personal
La **rotación de personal** mide qué tanto entran y salen las personas de un negocio. Una forma común de calcularla:

**Rotación anual = número de salidas en el año ÷ número promedio de empleados × 100**

En Tortas Lupita: 10 salidas ÷ 9 empleados en promedio × 100 = **111 %**. Es como si toda la plantilla se hubiera renovado más de una vez en el año.

Algo de rotación es normal y sano (personas que se jubilan, que cambian de ciudad, que encuentran un trabajo mejor relacionado con sus estudios, o que no funcionaban en el puesto). Pero una rotación muy alta es un síntoma de problemas. En restaurantes y comercio, la rotación suele ser mayor que en otros sectores; aun así, conviene compararse con negocios parecidos y, sobre todo, con uno mismo en el tiempo.

## El costo de la rotación
Cada salida cuesta, aunque no aparezca como una línea en el estado de resultados:
- **Reclutamiento y selección:** anuncios, tiempo de entrevistas.
- **Capacitación:** tiempo del padrino y del jefe enseñando.
- **Baja productividad** mientras la persona nueva aprende.
- **Errores** del periodo de aprendizaje (merma, errores de caja, quejas).
- **Sobrecarga** del equipo que cubre el puesto vacante (horas extra, cansancio).
- **Clientes perdidos** por mal servicio.
- **Pagos de salida** (finiquito, y en algunos casos liquidación; lección M13-8).

Estimación de Tortas Lupita por cada salida:

| Concepto | Pesos |
|---|---|
| Reclutamiento y selección (tiempo y anuncios) | 1,200 |
| Capacitación (horas del padrino y del jefe) | 1,500 |
| Productividad reducida del nuevo (primer mes) | 2,500 |
| Errores y merma extra | 800 |
| Horas extra del equipo mientras se cubre el puesto | 1,000 |
| **Costo estimado por salida** | **7,000** |

Con 10 salidas al año: **70,000 pesos**, más los clientes perdidos, que son difíciles de medir.

## ¿Por qué se va la gente?
Las causas más comunes:
1. **El jefe:** trato injusto, gritos, falta de reconocimiento. Una frase muy repetida en RH dice que «la gente no deja empresas, deja jefes».
2. **Sueldo y prestaciones** por debajo del mercado o pagos atrasados.
3. **Horarios** difíciles o cambiantes.
4. **Falta de crecimiento:** no ver un futuro en el negocio.
5. **Mal ambiente:** conflictos, favoritismo, chismes.
6. **Sobrecarga de trabajo** constante.
7. **Mala selección:** la persona no tenía el perfil o no sabía bien en qué consistía el puesto.
8. **Mala inducción:** llegó y nadie la recibió (lección M13-4).
9. **Distancia o transporte** largos y caros.

## Escuchar: la entrevista de salida
Una herramienta sencilla es la **entrevista de salida**: cuando alguien renuncia, preguntarle con respeto por qué se va, qué le gustó y qué cambiaría. Muchas veces las personas son más honestas al irse. Si varias mencionan lo mismo (el jefe del turno de la tarde, los horarios del sábado), ahí está el problema.

También conviene preguntar **antes** de que se vayan: conversaciones uno a uno (lección M13-6) y encuestas breves y anónimas de clima laboral.

## El clima laboral
El **clima laboral** es la percepción que tienen las personas del ambiente en el trabajo: si se sienten respetadas, seguras, escuchadas, reconocidas, si saben qué se espera de ellas, si se llevan bien con sus compañeros. Un buen clima reduce la rotación, mejora el servicio y hace más fácil cualquier cambio.

Una encuesta de clima sencilla puede tener preguntas como (respuesta del 1 al 5):
- Sé claramente qué se espera de mí en mi trabajo.
- Tengo lo que necesito para hacer bien mi trabajo.
- En la última semana recibí reconocimiento por un buen trabajo.
- Mi jefe me trata con respeto.
- Mis opiniones se toman en cuenta.
- Tengo oportunidades de aprender y crecer.
- Recomendaría este lugar a un amigo para trabajar.

La empresa de investigación Gallup popularizó un conjunto de doce preguntas parecidas para medir el **compromiso** de los empleados, y sus estudios han relacionado un mayor compromiso con mejores resultados en productividad, servicio al cliente y menor rotación.

## Los riesgos psicosociales en México
En México, la norma oficial **NOM-035-STPS-2018** obliga a los centros de trabajo a identificar y prevenir los **factores de riesgo psicosocial** (como cargas de trabajo excesivas, jornadas muy largas, violencia laboral o falta de control sobre el trabajo) y a promover un entorno organizacional favorable. Sus obligaciones varían según el número de trabajadores. Para un negocio pequeño, cumplirla empieza por lo básico: una política contra la violencia laboral, mecanismos para recibir quejas y atención a las cargas de trabajo.

## Acciones para retener
| Causa | Acción |
|---|---|
| Mal trato del jefe | Capacitar a los encargados en liderazgo; medir la rotación por jefe |
| Sueldo bajo | Comparar con el mercado; ajustar donde sea posible; bonos por resultados |
| Horarios | Horarios estables publicados con anticipación; turnos que permitan estudiar |
| Falta de crecimiento | Un camino claro: ayudante → cocinero → jefe de cocina → encargado |
| Mala inducción | Proceso de bienvenida y padrino (lección M13-4) |
| Mal ambiente | Reglas claras, cero tolerancia a la violencia, juntas con respeto |
| Sobrecarga | Planear el personal por hora (lección M13-1) |

## El plan de Tortas Lupita
Después de las entrevistas de salida, descubren dos causas principales: el trato del encargado del turno vespertino y los horarios del sábado que cambiaban cada semana. Lupita capacita al encargado (y le pone la rotación como indicador), publica los horarios con dos semanas de anticipación, crea el camino de crecimiento y hace una encuesta de clima cada trimestre. Al año siguiente, la rotación baja de 111 % a 45 %, y el ahorro estimado supera los 40,000 pesos.`,
k: `**Rotación anual = salidas ÷ promedio de empleados × 100.** Cada salida cuesta (reclutar, capacitar, baja productividad, errores, sobrecarga, clientes perdidos). Causas frecuentes: **el jefe**, sueldo, horarios, falta de crecimiento, ambiente, sobrecarga, mala selección e inducción. Escucha con **entrevistas de salida** y **encuestas de clima**. En México, la **NOM-035** pide prevenir riesgos psicosociales.`,
ch: `Una cocina económica descubre en sus entrevistas de salida que las meseras se van por los horarios del domingo; al rotar los domingos de forma justa y publicada, la rotación baja a la mitad.`,
gi: `Gallup ha publicado durante años estudios sobre el compromiso de los empleados en el mundo, basados en preguntas como las de su encuesta Q12, y ha encontrado relación entre el compromiso y la productividad, la satisfacción de los clientes y la rotación.`,
e: `Toño calcula el ahorro por reducir la rotación:

| Concepto | Año anterior | Año siguiente |
|---|---|---|
| Empleados promedio | 9 | 9 |
| Salidas | 10 | 4 |
| Rotación | 111 % | 44 % |
| Costo estimado (7,000 por salida) | 70,000 | 28,000 |
| **Ahorro** | | **42,000** |

Además, las quejas de clientes del turno vespertino bajan a la mitad.`,
r: `Gallup publica su informe «State of the Global Workplace», que estima el nivel de compromiso de los empleados en distintos países y regiones. En México, la Secretaría del Trabajo y Previsión Social emitió la NOM-035-STPS-2018 sobre factores de riesgo psicosocial, cuyas obligaciones entraron en vigor de forma escalonada entre 2019 y 2020.`,
f: `Gallup, «State of the Global Workplace» (gallup.com); Diario Oficial de la Federación, NOM-035-STPS-2018.`,
err: ["Creer que la rotación alta es inevitable y no tiene costo.","No preguntar a las personas por qué se van.","Ignorar el papel de los jefes en la rotación.","Medir el clima y no actuar sobre los resultados."],
a: `Calcula la rotación anual del negocio que observas (o estímala) y el costo de cada salida con la tabla de esta lección. Diseña una encuesta de clima de seis preguntas y propón dos acciones para retener a las personas.`,
sol: `Si no tienes datos exactos, estima: incluso una cifra aproximada del costo por salida ayuda a ver que retener a las personas es una inversión.`,
q: [["Si hubo 6 salidas en el año y el promedio de empleados fue 12, la rotación es…",["50 %","72 %","6 %"],0,"6 ÷ 12 × 100."],
["¿Cuál es una causa muy frecuente de que las personas se vayan?",["El trato del jefe","El color del uniforme","El nombre del negocio"],0,"«La gente no deja empresas, deja jefes»."],
["La entrevista de salida sirve para…",["Entender por qué se va la persona y qué mejorar","Cobrarle","Retenerla a la fuerza"],0,"Las personas suelen ser honestas al irse."],
["En México, la NOM-035 se refiere a…",["Factores de riesgo psicosocial en el trabajo","El IVA","Los precios de los alimentos"],0,"Pide identificarlos y prevenirlos."]],
t: ["Rotación de personal", "Clima laboral"]
},
"M13-8": {
s: `Un repartidor llega tarde por sexta vez y además se salta entregas. Toño, molesto, le dice: «¡Estás despedido, vete ya!». Al día siguiente llega un aviso de un centro de conciliación laboral. Lupita entiende que las salidas también deben hacerse bien.`,
o: ["Distinguir renuncia, despido justificado y despido injustificado.","Conocer, de forma general, la diferencia entre finiquito y liquidación.","Manejar las salidas y los conflictos con orden, legalidad y respeto."],
x: `## Todas las relaciones terminan
Tarde o temprano, toda relación de trabajo termina: por renuncia, por despido, por jubilación, por terminar el contrato o la obra, o por otras causas. Cómo se maneja la salida importa: por respeto a la persona, por el ambiente del equipo que se queda, por la reputación del negocio y por los riesgos legales. Esta lección es una **introducción educativa** a las reglas generales en México; cada caso tiene particularidades y conviene asesorarse con un abogado laboral antes de despedir a alguien.

## Las formas de terminar
1. **Renuncia voluntaria:** el trabajador decide irse. Conviene que la presente **por escrito**, firmada, con fecha. Se le paga su **finiquito**.
2. **Despido justificado (rescisión con causa):** el patrón termina la relación por alguna de las causas que establece la Ley Federal del Trabajo (por ejemplo, ciertas faltas graves: actos de violencia, faltas de probidad u honradez, faltas injustificadas en ciertos supuestos, desobediencia grave, entre otras). Hay requisitos formales: entregar un **aviso escrito** con la causa y la fecha, y documentar los hechos. Si el patrón no puede probar la causa, el despido puede considerarse injustificado.
3. **Despido injustificado:** el patrón termina la relación sin una causa legal (o sin poder probarla). El trabajador puede reclamar su reinstalación o una indemnización, además de otros pagos.
4. **Terminación por mutuo acuerdo:** ambas partes acuerdan terminar, normalmente con un convenio que conviene formalizar ante la autoridad laboral.
5. **Otras:** fin de un contrato por tiempo u obra determinados (cuando legalmente procede), jubilación, incapacidad, muerte del trabajador.

## Finiquito y liquidación
- **Finiquito:** lo que se le debe al trabajador al terminar la relación, por cualquier causa: salarios pendientes, la **parte proporcional del aguinaldo**, las **vacaciones** no disfrutadas y su **prima vacacional**, y otras prestaciones pendientes. En algunos casos incluye la **prima de antigüedad** (doce días de salario por año trabajado, con un tope de salario; aplica, por ejemplo, en despidos y también en renuncias de trabajadores con al menos quince años de antigüedad).
- **Liquidación:** cuando el despido es injustificado, además del finiquito, la ley contempla una **indemnización** (en general, tres meses de salario y, en ciertos supuestos, veinte días de salario por año trabajado), la prima de antigüedad y, si hay juicio, posibles salarios que se dejaron de pagar durante el proceso, con los límites que marca la ley.

Por eso un despido injustificado puede costar mucho más que el finiquito. Y por eso no se debe despedir «en caliente».

## La justicia laboral desde 2019
Con la reforma laboral de 2019, la solución de conflictos laborales en México cambió:
- Antes de ir a juicio, la mayoría de los conflictos deben pasar por una **etapa de conciliación** obligatoria ante los **centros de conciliación** (el Centro Federal de Conciliación y Registro Laboral para asuntos federales y centros locales en cada estado).
- Si no hay acuerdo, el conflicto se resuelve ante **tribunales laborales** del poder judicial.

La conciliación busca que las partes lleguen a un acuerdo justo, más rápido y barato que un juicio. Un negocio que llega a la conciliación con su expediente en orden (contrato, alta en el IMSS, recibos de nómina, registros de asistencia, actas de las faltas) está en una posición mucho mejor que uno sin papeles.

## Cómo manejar los problemas antes de despedir
La mayoría de los despidos se pueden evitar o, al menos, manejar mejor:
1. **Reglas claras desde el inicio:** reglamento o reglas internas conocidas por todos (puntualidad, faltas, uso del celular, higiene).
2. **Retroalimentación temprana:** hablar del problema la primera vez, no la sexta (lección M13-6).
3. **Documentar:** registrar los hechos (retardos, faltas, incidentes) con fecha y, cuando corresponda, levantar un acta con testigos.
4. **Medidas progresivas:** conversación, llamada de atención por escrito y, si la ley y el reglamento lo permiten, otras medidas disciplinarias.
5. **Escuchar la versión de la persona:** a veces hay causas que se pueden resolver (un problema de transporte, de salud o familiar).
6. **Decidir con calma** y asesoría, nunca en caliente.

## Cómo hacer una salida con respeto
Cuando la salida es inevitable:
- **En privado**, con un testigo de confianza si es despido.
- **Con claridad y brevedad:** explicar la decisión y su motivo sin humillar.
- **Con los documentos listos:** aviso escrito (si es rescisión), cálculo del finiquito, recibo para firmar.
- **Pagando lo que corresponde**, en tiempo.
- **Cuidando la dignidad:** no exhibir a la persona frente al equipo ni a los clientes.
- **Comunicando al equipo** lo necesario, sin detalles personales.
- **Dando de baja** al trabajador en el IMSS en el plazo que corresponde.

## Los conflictos entre compañeros
No todos los conflictos son entre el negocio y un trabajador; también hay conflictos entre compañeros (por tareas, horarios, malentendidos o faltas de respeto). Para manejarlos:
- **Intervenir pronto**, antes de que crezcan.
- **Escuchar a ambas partes por separado** y luego juntas.
- **Centrarse en los hechos y en el trabajo**, no en las personalidades.
- **Buscar un acuerdo concreto** y dar seguimiento.
- **Cero tolerancia a la violencia y al acoso:** tener una política clara, un canal para denunciar y actuar de inmediato (lección M13-7).

## El caso del repartidor
Lupita detiene el conflicto: habla con el repartidor, revisa los registros (seis retardos y tres entregas no realizadas, sin actas) y consulta a un abogado laboral. Como no hay documentos de las faltas ni reglamento firmado, un despido «justificado» sería difícil de probar. En la conciliación llegan a un acuerdo de terminación con el pago correspondiente. Desde entonces, Tortas Lupita tiene reglas internas firmadas por cada empleado, registra la asistencia y documenta cada incidente. Toño aprende la lección: **nunca más despedir en caliente**.

## Cierre del módulo
Gestionar personas es una de las tareas más importantes y delicadas de un negocio: planear, atraer, elegir, contratar con legalidad, recibir, capacitar, pagar bien, evaluar, motivar, conservar y, cuando toca, despedir con orden y respeto. Un negocio que cuida a su gente tiene menos rotación, mejor servicio, menos conflictos y más capacidad de crecer.`,
k: `Formas de terminar: **renuncia** (por escrito), **despido justificado** (causa legal, aviso escrito y pruebas), **despido injustificado**, mutuo acuerdo y otras. **Finiquito:** lo que se debe (salarios, aguinaldo y vacaciones proporcionales, prima vacacional y, en ciertos casos, prima de antigüedad). **Liquidación:** finiquito + **indemnización** en despidos injustificados. Desde 2019: **conciliación** obligatoria y **tribunales laborales**. Documenta, escucha y **nunca despidas en caliente**.`,
ch: `Una tienda de abarrotes tiene un reglamento de una hoja firmado por sus dos empleados y una libreta de asistencia; cuando un empleado empieza a faltar, la dueña habla con él, registra cada falta y lo resuelve sin llegar a un conflicto.`,
gi: `Las grandes empresas tienen áreas de relaciones laborales con abogados especializados, políticas disciplinarias detalladas, canales de denuncia y, cuando hay sindicato, contratos colectivos que establecen procedimientos para los conflictos.`,
e: `La administradora calcula un finiquito ilustrativo por renuncia (sueldo diario de 400 pesos; renuncia el 30 de junio; trabajó todo el semestre; le quedan 12 días de vacaciones; última quincena pagada):

| Concepto | Cálculo | Pesos |
|---|---|---|
| Aguinaldo proporcional (15 días × 181/365) | 15 × 181 ÷ 365 × 400 | 2,975 |
| Vacaciones no disfrutadas (12 días) | 12 × 400 | 4,800 |
| Prima vacacional (25 %) | 4,800 × 25 % | 1,200 |
| **Finiquito estimado** | | **8,975** |

Es un cálculo educativo y simplificado; el contador o abogado debe calcular los montos exactos según el caso.`,
r: `La reforma laboral publicada en el Diario Oficial de la Federación el 1 de mayo de 2019 transformó la justicia laboral en México: creó el Centro Federal de Conciliación y Registro Laboral y los centros de conciliación locales, estableció la conciliación prejudicial obligatoria y trasladó los juicios laborales a tribunales del poder judicial.`,
f: `Diario Oficial de la Federación, reforma a la Ley Federal del Trabajo (1 de mayo de 2019); Centro Federal de Conciliación y Registro Laboral (centrolaboral.gob.mx).`,
err: ["Despedir «en caliente» y sin documentos.","No tener reglas internas ni registro de asistencia.","No pagar el finiquito completo y a tiempo.","Humillar a la persona al despedirla."],
a: `Escribe las reglas internas básicas (una hoja) del negocio que observas: puntualidad, faltas, uso del celular, higiene, conducta. Después escribe los pasos que seguirías antes de despedir a alguien por retardos frecuentes.`,
sol: `Los pasos deben incluir: conversación temprana, registro de cada retardo, llamada de atención por escrito, escuchar a la persona y consulta con un asesor antes de decidir.`,
q: [["El finiquito es…",["Lo que se le debe al trabajador al terminar la relación, por cualquier causa","Solo la indemnización por despido","Un impuesto"],0,"Incluye proporcionales de aguinaldo, vacaciones y prima."],
["La liquidación incluye, además del finiquito…",["Una indemnización en caso de despido injustificado","Nada","El IVA"],0,"Por eso un despido injustificado cuesta más."],
["Desde la reforma de 2019, antes de un juicio laboral normalmente hay que pasar por…",["Una etapa de conciliación","La Profeco","El SAT"],0,"Ante los centros de conciliación."],
["¿Qué ayuda más a manejar un conflicto laboral?",["Tener reglas claras y documentar los hechos","Despedir en caliente","No tener contrato"],0,"El expediente en orden es la mejor defensa."]],
t: ["Renuncia", "Despido justificado"]
}
});
// ===== M14. Legal y cumplimiento =====
Object.assign(window.LECC, {
"M14-1": {
s: `En un mismo mes, a Tortas Lupita le llegan tres asuntos legales: el arrendador quiere subir la renta 30 %, una persona dice que se enfermó con una torta y un competidor abrió con un nombre casi igual. Lupita no tiene abogado. ¿Quién se encarga de estos temas en un negocio?`,
o: ["Describir qué hace el área legal de un negocio.","Distinguir entre la prevención y la defensa en temas legales.","Saber cuándo y cómo apoyarse en un abogado."],
x: `## El área legal
El área **legal** (o jurídica) se encarga de que el negocio **cumpla las leyes**, **proteja sus derechos** y **reduzca sus riesgos legales**. En un changarro, el dueño resuelve como puede y busca a un abogado solo cuando ya tiene un problema. En una pyme, se trabaja con un **abogado externo** o un despacho que asesora en contratos, temas laborales y trámites. En una empresa grande hay una **dirección jurídica** encabezada por un director jurídico (en inglés, *general counsel*) con abogados especializados, que además coordina despachos externos para asuntos específicos.

## Los grandes temas legales de un negocio
| Tema | Qué incluye | Lección |
|---|---|---|
| Corporativo (societario) | Constitución de la sociedad, actas de asamblea, poderes, entrada y salida de socios | M3 y M24 |
| Contratos | Arrendamiento, proveedores, clientes, trabajo, socios, confidencialidad | M14-2 |
| Laboral | Contratos, reglamentos, despidos, conciliación | M13 |
| Fiscal | Impuestos, facturación, revisiones del SAT | M3-7 y M8-10 |
| Propiedad intelectual | Marcas, patentes, derechos de autor, secretos industriales | M14-3 |
| Consumidor y datos personales | Profeco, publicidad, garantías, aviso de privacidad | M14-4 |
| Regulatorio | Permisos, licencias, normas sanitarias, Protección Civil, ambientales | M14-5 |
| Cumplimiento | Programas para prevenir riesgos legales y de corrupción | M14-6 |
| Litigio | Defensa cuando hay un conflicto o una demanda | M14-1 |

## Prevenir es más barato que defender
Hay dos formas de trabajar con temas legales:
- **Preventiva:** revisar contratos antes de firmar, registrar la marca antes de que otro lo haga, cumplir los requisitos sanitarios antes de una inspección, documentar las faltas de un empleado antes de un conflicto.
- **Reactiva (de defensa o litigio):** responder cuando ya hay una demanda, una multa o una clausura.

La prevención casi siempre cuesta mucho menos que la defensa. Una consulta de una hora con un abogado para revisar el contrato de renta puede evitar años de problemas. Un juicio, en cambio, puede durar meses o años y costar mucho más en honorarios, tiempo y tranquilidad.

## Los tres asuntos de Lupita
1. **Aumento de renta de 30 %:** lo que diga el **contrato de arrendamiento** es clave: ¿tiene una cláusula de aumento anual (por ejemplo, según la inflación)?, ¿cuánto tiempo falta para que venza?, ¿qué pasa si no se renueva? Si el contrato dice que el aumento anual es según la inflación, el arrendador no puede imponer un 30 % mientras esté vigente. (Lección M14-2).
2. **Posible intoxicación:** hay que atender al cliente con respeto, documentar todo, revisar los registros de higiene y temperatura, y consultar con un abogado. Si el negocio cumple las normas sanitarias y tiene un **seguro de responsabilidad civil**, está mucho mejor protegido. (Lecciones M14-4 y M14-5; también M27-4 sobre crisis).
3. **Competidor con nombre casi igual:** si Tortas Lupita **registró su marca** ante el IMPI, puede defenderla; si no, puede haber un problema serio, incluso que el otro la registre primero. (Lección M14-3).

## Cuándo buscar un abogado
Un negocio pequeño no necesita un abogado todos los días, pero sí en momentos clave:
- **Al crear la sociedad** o al entrar un socio.
- **Antes de firmar** contratos importantes (renta, franquicia, crédito, contratos con clientes grandes).
- **Al registrar la marca.**
- **Antes de despedir** a un trabajador.
- **Cuando llega** un requerimiento de una autoridad, una demanda o una queja formal.
- **Al vender** o comprar un negocio.
- **Al abrir** en otro estado o país.

## Cómo elegir y trabajar con un abogado
- **Especialidad:** no es lo mismo un abogado laboral que uno fiscal o uno de propiedad intelectual. Para temas generales de un negocio, un abogado corporativo o de negocios suele ser un buen punto de partida.
- **Referencias:** pregunta a otros empresarios, a tu cámara empresarial o asociación.
- **Honorarios claros:** por hora, por asunto o una iguala mensual (una cuota fija por un conjunto de servicios). Pide una propuesta por escrito.
- **Explica el contexto completo** y lleva los documentos.
- **Pregunta:** ¿qué riesgos tengo?, ¿qué opciones?, ¿cuánto costaría cada una?
- **Guarda todo por escrito.**

## El dueño también debe saber lo básico
Así como con los impuestos, el dueño no necesita ser abogado, pero sí entender lo básico para detectar riesgos y hacer buenas preguntas: qué dice su contrato de renta, si su marca está registrada, qué permisos necesita, qué derechos tienen sus trabajadores y sus clientes. Este módulo da esa base, siempre con el aviso de que es **contenido educativo** y que cada caso debe revisarse con un profesional y con la norma vigente.

## En las empresas gigantes
En las grandes empresas, el área jurídica participa en casi todas las decisiones importantes: adquisiciones, contratos con proveedores y clientes grandes, entrada a otros países, lanzamientos de productos, relaciones con reguladores, juicios. Muchas también tienen un área de **cumplimiento** (lección M14-6) que vigila que la empresa y sus empleados respeten las leyes y los códigos de ética, incluidas las leyes contra la corrupción.

## Una carpeta legal
Un hábito sencillo ayuda mucho: guardar en una carpeta física y otra digital el acta constitutiva, los poderes, los contratos vigentes, el título de la marca, las licencias y los avisos. Cuando surge un asunto legal, tener todo a la mano ahorra tiempo y honorarios.`,
k: `El área **legal** busca que el negocio **cumpla**, **proteja sus derechos** y **reduzca riesgos**. Temas: corporativo, contratos, laboral, fiscal, **propiedad intelectual**, consumidor y datos, regulatorio, **cumplimiento** y litigio. **Prevenir cuesta menos que defender.** Busca abogado especializado en momentos clave (sociedad, contratos, marca, despidos, requerimientos), con honorarios claros.`,
ch: `Una dueña de estética paga una consulta para revisar su contrato de renta antes de firmarlo y descubre una cláusula que le obligaba a pagar todas las reparaciones del edificio; la negocia y evita un problema caro.`,
gi: `En las empresas que cotizan en bolsa, el director jurídico suele formar parte del equipo directivo y participa en decisiones como adquisiciones, contratos clave y relaciones con autoridades.`,
e: `Lupita compara el costo de prevenir y de defenderse en sus tres asuntos (cifras ilustrativas):

| Asunto | Prevención | Costo | Defensa si no previene | Costo posible |
|---|---|---|---|---|
| Renta | Revisión del contrato antes de firmar | 2,000 | Pagar el aumento o un juicio | 60,000 o más |
| Intoxicación | Seguro de responsabilidad civil y registros de higiene | 6,000 al año | Indemnización y abogado | 100,000 o más |
| Marca | Registro ante el IMPI | Unos miles de pesos | Cambiar de nombre o litigar | 80,000 o más |

En los tres casos, la prevención cuesta una fracción de la defensa.`,
r: `Las sociedades anónimas bursátiles en México suelen incluir entre sus directivos relevantes a un director jurídico, cuya información aparece en sus reportes anuales a la Bolsa Mexicana de Valores.`,
f: `Reportes anuales de emisoras en la Bolsa Mexicana de Valores (bmv.com.mx).`,
err: ["Buscar abogado solo cuando ya hay un problema.","Firmar contratos importantes sin leerlos ni revisarlos.","Contratar a un abogado que no es especialista en el tema.","Creer que lo legal es solo para empresas grandes."],
a: `Haz una lista de los temas legales del negocio que observas usando la tabla de esta lección. Marca cuáles están en orden y cuáles no, y elige el más urgente para revisarlo con un profesional.`,
sol: `Los temas más urgentes suelen ser: contrato de renta, alta de los trabajadores en el IMSS, permisos sanitarios y registro de la marca.`,
q: [["El área legal de un negocio busca…",["Que cumpla las leyes, proteja sus derechos y reduzca sus riesgos","Vender más","Hacer la nómina"],0,"Prevención y defensa."],
["¿Por qué conviene la prevención legal?",["Suele costar mucho menos que defenderse en un juicio","Porque es obligatoria siempre","No conviene"],0,"Una consulta cuesta menos que un litigio."],
["¿Cuándo conviene consultar a un abogado?",["Antes de firmar contratos importantes o despedir a alguien","Nunca","Solo cuando ya se perdió un juicio"],0,"En momentos clave."],
["Una iguala es…",["Una cuota fija mensual por un conjunto de servicios profesionales","Un tipo de contrato de trabajo","Un impuesto"],0,"Es una forma de pagar honorarios."]],
t: ["Área legal (jurídica)", "Prevención legal"]
},
"M14-2": {
s: `El arrendador de Tortas Lupita le pone enfrente un contrato de 12 páginas para la segunda sucursal. «Es el formato de siempre, firme aquí», le dice. Lupita duda. ¿Qué debe revisar en un contrato antes de firmarlo?`,
o: ["Conocer los elementos básicos de un contrato.","Identificar las cláusulas clave de los contratos más comunes de un negocio.","Revisar un contrato antes de firmarlo con una lista de verificación."],
x: `## ¿Qué es un contrato?
Un **contrato** es un acuerdo entre dos o más partes que crea obligaciones y derechos. En general, para que exista, hace falta que las partes estén de acuerdo (consentimiento) sobre algo posible y lícito (objeto). Muchos contratos pueden ser verbales, pero tener los **acuerdos por escrito** permite saber exactamente qué se acordó y probarlo si hay un desacuerdo. Algunos contratos, por ley, deben constar por escrito o cumplir ciertas formalidades (por ejemplo, ante notario en ciertos casos).

En México, los contratos se rigen principalmente por los códigos civiles (federal y de cada estado) y, cuando son entre comerciantes o sobre actos de comercio, también por el Código de Comercio. Los contratos de trabajo tienen sus propias reglas en la Ley Federal del Trabajo.

## Las partes típicas de un contrato
1. **Partes:** quiénes firman, con sus datos completos (y, si es una sociedad, quién la representa y con qué poder).
2. **Antecedentes o declaraciones:** quién es cada parte, qué tiene, para qué quiere el contrato.
3. **Objeto:** qué se acuerda (rentar un local, comprar insumos, prestar un servicio).
4. **Precio o contraprestación:** cuánto se paga, cómo, cuándo y con qué ajustes.
5. **Duración:** cuándo empieza, cuándo termina, si se renueva.
6. **Obligaciones** de cada parte.
7. **Garantías:** depósitos, fianzas, avales.
8. **Penalizaciones:** qué pasa si alguien no cumple.
9. **Terminación anticipada:** cómo y cuándo se puede terminar antes.
10. **Confidencialidad** (si aplica).
11. **Solución de controversias:** qué leyes aplican, qué tribunales o si se usará mediación o arbitraje.
12. **Firmas** y fecha.

## Los contratos más comunes de un negocio
**1. Arrendamiento (renta del local).** Es uno de los contratos más importantes para un negocio físico. Cláusulas clave:
- **Renta y forma de ajuste:** cuánto aumenta cada año y con qué criterio (por ejemplo, según el Índice Nacional de Precios al Consumidor que publica el INEGI).
- **Duración y renovación:** un contrato largo da estabilidad; conviene tener derecho de preferencia para renovar.
- **Depósito en garantía** y cuándo se devuelve.
- **Uso permitido:** que diga expresamente que se puede usar como restaurante (y que el uso de suelo lo permita, lección M3-8).
- **Mantenimiento y reparaciones:** quién paga qué (estructura, instalaciones, mejoras).
- **Mejoras:** qué pasa con la cocina que instales si te vas.
- **Subarrendamiento y traspaso:** si puedes ceder el contrato a un comprador del negocio o a un franquiciatario.
- **Terminación anticipada** y su penalización.
- **Fiador o garantía:** a veces piden un fiador con inmueble o una póliza jurídica.

**2. Contrato con proveedores:** productos y especificaciones, precios y ajustes, entregas, pagos y crédito, devoluciones, duración (lección M10-5).

**3. Contrato con clientes empresa:** productos o servicios, precios, entregas, facturación, plazo de pago, penalizaciones por retraso, confidencialidad.

**4. Contrato individual de trabajo:** lección M13-3.

**5. Convenio entre socios:** cómo se toman las decisiones, cómo se reparten las utilidades, qué pasa si uno quiere vender su parte, si uno muere o se divorcia, qué pasa si no aportan lo prometido, cláusulas de no competencia. Complementa los estatutos de la sociedad (lección M3-5).

**6. Acuerdo de confidencialidad:** para proteger información sensible (recetas, listas de clientes, planes) cuando se comparte con empleados clave, proveedores o posibles socios.

**7. Contrato de franquicia:** lección M21-2.

## Lista de verificación antes de firmar
1. **Lee todo**, incluida la «letra chica».
2. **Verifica quién firma** del otro lado y si tiene poder para hacerlo.
3. **Comprueba que el objeto y el precio** sean exactamente lo acordado.
4. **Revisa los ajustes** de precio y las fechas.
5. **Busca las penalizaciones** y la forma de terminar el contrato.
6. **Revisa las garantías** que te piden (aval, fianza, depósito).
7. **Pregunta por todo lo que no entiendas** y pide que se aclare por escrito.
8. **Negocia:** un «formato de siempre» también se puede modificar.
9. **Para contratos importantes, pide revisión de un abogado.**
10. **Guarda una copia firmada** de todas las hojas.

## La negociación del contrato
Un contrato es el resultado de una negociación (lección M10-4). Muchas personas creen que el «formato» no se puede cambiar, pero casi siempre hay espacio para negociar cláusulas: el porcentaje de aumento, el plazo, el depósito, quién paga el mantenimiento, la posibilidad de traspaso. Lo que no se negocia antes de firmar es muy difícil de cambiar después.

## La firma electrónica
Cada vez más contratos se firman de forma electrónica. En México, la legislación reconoce el valor de los mensajes de datos y de ciertas formas de firma electrónica en actos de comercio, y existen la firma electrónica avanzada (como la e.firma del SAT) y normas para conservar los documentos electrónicos. Para contratos importantes, conviene usar plataformas confiables y conservar las constancias.

## El contrato de la segunda sucursal
Lupita lleva el contrato a una abogada, que encuentra cuatro problemas: no decía expresamente que se permitía usar el local como restaurante; el aumento anual era «el que determine el arrendador»; Lupita debía pagar las reparaciones de la estructura del edificio; y no podía traspasar el contrato si algún día franquiciaba la sucursal. Negocian: uso de restaurante por escrito, aumento anual según la inflación, reparaciones estructurales a cargo del dueño, contrato de cinco años con derecho de renovación y posibilidad de traspaso con aviso. La consulta costó 2,500 pesos.`,
k: `**Contrato:** acuerdo que crea obligaciones y derechos; tenlo **por escrito**. Partes: partes, objeto, precio y ajustes, duración, obligaciones, garantías, penalizaciones, terminación, confidencialidad, solución de controversias y firmas. En el **arrendamiento**, revisa ajuste de renta, duración, uso permitido, mantenimiento, mejoras y traspaso. **Lee todo, negocia y pide revisión** en contratos importantes.`,
ch: `Un taller mecánico firma un contrato con una empresa de flotillas que incluye precios por servicio, plazo de pago de 30 días y una penalización si un auto se entrega tarde; así ambas partes saben qué esperar.`,
gi: `Las grandes empresas tienen áreas jurídicas que redactan y revisan miles de contratos al año con plantillas aprobadas, niveles de autorización según el monto y sistemas para dar seguimiento a vencimientos y renovaciones.`,
e: `Lupita compara el costo de la cláusula de aumento original contra la negociada, en cinco años (renta inicial de 20,000 pesos al mes):

| Año | Aumento «a criterio del arrendador» (supuesto: 12 % al año) | Aumento según inflación (supuesto: 4.5 % al año) |
|---|---|---|
| 1 | 240,000 | 240,000 |
| 2 | 268,800 | 250,800 |
| 3 | 301,056 | 262,086 |
| 4 | 337,183 | 273,880 |
| 5 | 377,645 | 286,205 |
| **Total** | **1,524,684** | **1,312,971** |

Negociar una sola cláusula le ahorra más de 210,000 pesos en cinco años (con estos supuestos).`,
r: `El INEGI publica cada mes el Índice Nacional de Precios al Consumidor (INPC), que mide la inflación en México y que muchos contratos de arrendamiento usan como referencia para el ajuste anual de las rentas.`,
f: `INEGI, Índice Nacional de Precios al Consumidor (inegi.org.mx); Código Civil Federal y códigos civiles estatales; Código de Comercio.`,
err: ["Firmar «el formato de siempre» sin leerlo.","Aceptar aumentos «a criterio» de la otra parte.","No verificar que el contrato permita el uso que se le dará al local.","No guardar una copia firmada."],
a: `Consigue un contrato real (de renta, de un servicio, de un celular) y revísalo con la lista de verificación de esta lección. Anota tres cláusulas que te parezcan riesgosas y cómo las negociarías.`,
sol: `Las cláusulas más riesgosas suelen ser los aumentos sin criterio, las penalizaciones altas por terminación anticipada y las garantías personales (avales) muy amplias.`,
q: [["¿Por qué conviene tener los contratos por escrito?",["Para saber exactamente qué se acordó y poder probarlo","Porque es más bonito","No conviene"],0,"Evita malentendidos."],
["En un contrato de renta, una cláusula clave es…",["Cómo se ajusta la renta cada año","El color de la fachada","El nombre del contador"],0,"Por ejemplo, según la inflación (INPC)."],
["Un «formato de siempre»…",["También se puede negociar antes de firmar","No se puede cambiar nunca","No hay que leerlo"],0,"Lo que no se negocia antes es difícil de cambiar después."],
["El convenio entre socios sirve para…",["Definir cómo deciden, reparten utilidades y qué pasa si uno sale","Contratar empleados","Pagar impuestos"],0,"Complementa los estatutos."]],
t: ["Contrato", "Contrato de arrendamiento"]
},
"M14-3": {
s: `Un día, Toño ve en redes un local nuevo llamado «Tortas La Lupita», con colores parecidos. Va a reclamar y el dueño le muestra un papel del IMPI: registró la marca hace seis meses. Lupita, que lleva diez años con el nombre, nunca la registró.`,
o: ["Explicar qué es la propiedad intelectual y por qué importa.","Conocer cómo se registra una marca en México.","Distinguir marcas, patentes, derechos de autor y secretos industriales."],
x: `## ¿Qué es la propiedad intelectual?
La **propiedad intelectual** protege las creaciones de la mente: nombres y logos de negocios, inventos, diseños, obras artísticas y literarias, programas de cómputo, secretos de fabricación. Para un negocio, estas creaciones son **activos** muy valiosos, a veces más que su equipo o su local. Protegerlas significa tener el derecho de usarlas en exclusiva y de impedir que otros las copien.

En México, la propiedad intelectual se divide en dos grandes ramas:
- **Propiedad industrial:** marcas, avisos comerciales, nombres comerciales, patentes, modelos de utilidad, diseños industriales y secretos industriales. La administra el **Instituto Mexicano de la Propiedad Industrial (IMPI)**, bajo la Ley Federal de Protección a la Propiedad Industrial (vigente desde 2020).
- **Derechos de autor:** obras literarias, musicales, artísticas, fotografías, programas de cómputo, bases de datos. Los administra el **Instituto Nacional del Derecho de Autor (INDAUTOR)**.

## La marca
Una **marca** es cualquier signo que distingue los productos o servicios de un negocio de los de otros: un nombre, un logo, una combinación de ambos, e incluso, en ciertos casos, un sonido, un olor o una forma. Registrarla da el **derecho exclusivo** de usarla para los productos o servicios registrados, en todo México.

Puntos clave del registro de marca en México (en términos generales):
- **Se registra por clases:** existe una clasificación internacional (la Clasificación de Niza) que divide productos y servicios en 45 clases. Por ejemplo, los servicios de restaurante están en una clase y ciertos alimentos preparados o salsas en otras. Tortas Lupita debería registrar su marca en la clase de servicios de restauración y, si vende salsa envasada, en la clase de ese producto.
- **Búsqueda previa:** antes de solicitar, conviene buscar en la base de datos del IMPI si ya existe una marca igual o parecida en la misma clase.
- **Vigencia:** el registro dura **diez años** y se puede renovar.
- **Uso:** la marca debe usarse; una marca registrada que no se usa durante cierto tiempo puede perder su protección.
- **Primero en el tiempo:** en general, en México gana quien **registra primero**, no quien usa primero (aunque el uso anterior puede dar algunos derechos que hay que defender ante la autoridad o en tribunales, con costo e incertidumbre).

## El problema de Lupita
Lupita usó «Tortas Lupita» durante diez años, pero no la registró. El otro negocio registró «Tortas La Lupita», muy parecida, en la misma clase. Ahora Lupita tiene que consultar a un especialista en propiedad intelectual: podría intentar anular el registro del otro alegando que ella usaba la marca antes y que la otra parte actuó de mala fe, pero es un proceso con costo, tiempo e incertidumbre. Si hubiera registrado su marca (con un costo de unos cuantos miles de pesos), estaría protegida y podría impedir el uso de una marca confusa.

## El aviso comercial y el nombre comercial
- **Aviso comercial:** una frase o eslogan que anuncia un negocio o producto («Sabor de casa, en tres minutos»). También se puede registrar.
- **Nombre comercial:** el nombre con el que se conoce un establecimiento. Tiene una protección distinta, ligada a su uso en una zona.

## Patentes, modelos de utilidad y diseños industriales
- **Patente:** protege un **invento** nuevo, con actividad inventiva y aplicación industrial (una máquina, un proceso, una fórmula). Da exclusividad por **20 años** (desde la solicitud), a cambio de publicar cómo funciona. Al terminar, cualquiera puede usarlo.
- **Modelo de utilidad:** protege mejoras prácticas a objetos o herramientas (por ejemplo, un nuevo diseño de plancha que cocina más parejo), por un plazo menor.
- **Diseño industrial:** protege la **forma o apariencia** de un producto (la forma de una botella, el diseño de un empaque).

Para un negocio de comida, las patentes son poco comunes, pero pueden ser importantes para una fábrica o una empresa de tecnología.

## Los derechos de autor
Protegen obras como textos, fotos, música, diseños gráficos, videos y programas de cómputo desde el momento de su creación, aunque registrarlas ante el INDAUTOR ayuda a probar la autoría. Para un negocio, esto importa en dos sentidos:
- **Proteger lo propio:** las fotos de los productos, el diseño del menú, los textos de la página web, un programa hecho a la medida (conviene que el contrato con el diseñador o programador diga que los derechos pasan al negocio).
- **Respetar lo ajeno:** no usar fotos, música o tipografías de otros sin permiso o licencia (por ejemplo, música en el local o en videos de redes).

## El secreto industrial
Un **secreto industrial** es información confidencial que da una ventaja competitiva: una receta, un proceso, una lista de clientes, una fórmula. No se registra: se protege **manteniéndolo en secreto**, con medidas razonables (acceso limitado, acuerdos de confidencialidad con empleados y proveedores). El caso más famoso del mundo es la fórmula de Coca-Cola, que la empresa ha mantenido como secreto durante más de un siglo en lugar de patentarla (una patente habría vencido y obligado a publicarla).

La salsa de Lupita es un buen candidato a secreto industrial: pocas personas conocen la receta completa, se prepara en la cocina central y los empleados que la conocen firman un acuerdo de confidencialidad.

## Lo que todo negocio debería hacer
1. **Buscar** si su nombre está disponible antes de usarlo.
2. **Registrar** su marca (y su logo) en las clases que usa.
3. **Registrar** su dominio de internet y sus nombres en redes.
4. **Firmar acuerdos de confidencialidad** con quienes conocen sus secretos.
5. **Asegurar por contrato** que los diseños y programas que paga sean suyos.
6. **Respetar** la propiedad intelectual de otros.
7. **Vigilar** que nadie use su marca y **renovar** los registros a tiempo.

## En las empresas gigantes
Las grandes empresas registran sus marcas en decenas de países y tienen equipos que vigilan el mercado para detectar copias y falsificaciones. A veces llegan tarde: Burger King no pudo usar su nombre en Australia porque un negocio local ya lo había registrado, y por eso allá opera con otra marca, Hungry Jack's. En México es conocido el caso de la empresa «iFone», que registró su marca años antes de que Apple lanzara el iPhone, lo que llevó a un largo litigio entre ambas.`,
k: `**Propiedad intelectual:** protege creaciones de la mente. **Propiedad industrial** (IMPI): **marcas** (por clases; vigencia de 10 años renovable; en general gana quien **registra primero**), avisos y nombres comerciales, **patentes** (20 años), modelos de utilidad, diseños industriales y **secretos industriales**. **Derechos de autor** (INDAUTOR). Registra tu marca **antes** de que otro lo haga.`,
ch: `Una paletería registra su marca y su logo en el IMPI antes de abrir su segunda tienda; cuando alguien en otra ciudad empieza a usar un nombre igual, puede pedirle que deje de hacerlo.`,
gi: `Burger King opera en Australia con la marca Hungry Jack's porque, cuando llegó al país en los años setenta, el nombre Burger King ya estaba registrado por un negocio local. La fórmula de Coca-Cola es un ejemplo famoso de secreto industrial guardado por más de un siglo.`,
e: `Lupita compara el costo de registrar la marca a tiempo con el de no hacerlo (cifras ilustrativas):

| Escenario | Costo estimado |
|---|---|
| Búsqueda y registro de la marca en 2 clases, por 10 años | Unos miles de pesos (derechos del IMPI y, si se usa, honorarios de un especialista) |
| Litigio para intentar anular el registro de otro | Decenas de miles de pesos, meses o años, resultado incierto |
| Cambiar de nombre (letreros, menús, empaques, redes, pérdida de reconocimiento) | Más de 80,000 pesos |

El registro a tiempo es, con mucho, la opción más barata.`,
r: `Burger King no pudo usar su nombre en Australia porque estaba registrado por un pequeño restaurante local; por eso su franquiciatario australiano abrió en 1971 con el nombre Hungry Jack's. En México, la empresa iFone, que registró su marca en 2003, sostuvo una disputa legal con Apple por el uso del término iPhone.`,
f: `Historia corporativa de Hungry Jack's; notas de prensa sobre el caso iFone contra Apple en México; IMPI, Ley Federal de Protección a la Propiedad Industrial (2020).`,
err: ["Usar un nombre durante años sin registrarlo.","Registrar la marca en una clase que no corresponde al negocio.","No firmar acuerdos de confidencialidad con quienes conocen las recetas o procesos.","Usar fotos o música de otros sin permiso."],
a: `Busca en el sistema de consulta del IMPI (o en su sitio web) si el nombre del negocio que observas o un nombre que te gustaría usar ya está registrado. Identifica en qué clases debería registrarse y qué secretos industriales tiene el negocio.`,
sol: `Si encuentras una marca igual o muy parecida en la misma clase, es probable que no puedas registrar la tuya; conviene elegir otro nombre antes de invertir en letreros y empaques.`,
q: [["En México, las marcas se registran ante…",["El IMPI","El IMSS","La Profeco"],0,"Instituto Mexicano de la Propiedad Industrial."],
["El registro de una marca en México dura…",["Diez años, renovable","Un año","Para siempre sin renovar"],0,"Y debe usarse."],
["Una receta que se protege manteniéndola en secreto es un…",["Secreto industrial","Patente","Derecho de autor"],0,"Ejemplo famoso: la fórmula de Coca-Cola."],
["Una patente protege un invento por…",["Veinte años desde la solicitud","Cinco días","Siempre"],0,"Después cualquiera puede usarlo."]],
t: ["Propiedad intelectual", "Marca registrada"]
},
"M14-4": {
s: `Un cliente reclama porque el precio del menú no incluía el IVA y le cobraron más en la caja. Otro pregunta qué hacen con su número de WhatsApp y su correo. Lupita descubre que los clientes tienen derechos que la ley protege, y que los datos personales también.`,
o: ["Conocer los derechos básicos del consumidor en México.","Cumplir con las reglas de precios, publicidad y garantías.","Proteger los datos personales de los clientes con un aviso de privacidad."],
x: `## Los derechos del consumidor
En México, la **Ley Federal de Protección al Consumidor** protege a las personas que compran productos o servicios. La **Procuraduría Federal del Consumidor (Profeco)** vigila que se cumpla, atiende quejas, concilia entre consumidores y negocios, y puede imponer sanciones. Esta lección resume, de forma educativa, las reglas que más importan a un negocio pequeño; conviene revisar la información vigente de la Profeco.

## Los derechos básicos
- **Información:** el consumidor tiene derecho a información veraz, clara y suficiente sobre los productos y servicios, sus precios, condiciones y riesgos.
- **Precio total visible:** los precios deben exhibirse y deben incluir los impuestos (el IVA). No se puede anunciar un precio y cobrar otro mayor en la caja. Es exactamente el problema del cliente de Lupita.
- **Respeto a lo anunciado:** si se anuncia una promoción, se debe respetar en los términos anunciados.
- **Publicidad veraz:** está prohibida la publicidad engañosa o que induzca a error.
- **No discriminación:** no se puede negar el servicio ni condicionarlo por motivos discriminatorios.
- **Garantía:** los productos deben cumplir lo que prometen; si fallan dentro del periodo de garantía, el consumidor puede pedir reparación, cambio o devolución, según el caso.
- **Cobros correctos:** no se pueden hacer cobros no informados ni obligatorios por servicios no pedidos. La Profeco ha señalado, por ejemplo, que la **propina** en restaurantes es voluntaria: el negocio no puede obligar a pagarla ni agregarla a la cuenta sin el consentimiento del cliente.
- **Comprobante:** el consumidor tiene derecho a recibir un comprobante de su compra.

## Las garantías y devoluciones
Para productos (no tanto para comida preparada), las reglas de garantía y devolución son importantes: el plazo de garantía debe informarse, y si el producto tiene defectos o no corresponde a lo prometido, el consumidor puede reclamar. Para un restaurante, lo equivalente es atender las quejas sobre productos que no cumplen lo prometido (lección M11-7).

## El etiquetado de alimentos y bebidas
Si un negocio vende **alimentos o bebidas preenvasados** (como la salsa de Tortas Lupita en frasco), debe cumplir con la norma de etiquetado vigente (la NOM-051), que establece qué información debe llevar la etiqueta: nombre del producto, ingredientes, contenido neto, datos del fabricante, fecha de caducidad o consumo preferente, información nutrimental y, desde la reforma de 2020, los **sellos de advertencia** frontales (por ejemplo, «exceso de sodio» o «exceso de calorías») cuando el producto supera ciertos límites. Antes de vender un producto envasado, conviene asesorarse para cumplir con esta norma.

## La Profeco y las quejas
Si un consumidor presenta una queja ante la Profeco, normalmente se cita a las partes a una **audiencia de conciliación** para buscar un acuerdo. Un negocio que atiende bien las quejas directamente (lección M11-7) rara vez llega a esta instancia. La Profeco también hace verificaciones (revisa precios exhibidos, básculas, cumplimiento de normas) y publica información útil para comparar precios.

## Los datos personales
Hoy casi todos los negocios recogen **datos personales** de sus clientes: nombre, teléfono, correo, dirección de entrega, datos de facturación, historial de pedidos. En México, la protección de los datos personales en manos de particulares (empresas y personas) está regulada por una ley federal específica, que se actualizó en 2025. En términos generales, quien recoge datos personales debe:
1. **Informar** a la persona, mediante un **aviso de privacidad**, qué datos recoge, para qué los usará, con quién los compartirá y cómo puede ejercer sus derechos.
2. **Usarlos solo** para las finalidades informadas.
3. **Pedir consentimiento** cuando corresponda, y de forma expresa para ciertos datos sensibles.
4. **Protegerlos** con medidas de seguridad razonables (Módulo 15).
5. **Respetar los derechos de las personas** sobre sus datos, conocidos como **derechos ARCO**: Acceso, Rectificación, Cancelación y Oposición.

## El aviso de privacidad
Un **aviso de privacidad** sencillo incluye:
- Quién es el responsable de los datos (el negocio, con su domicilio).
- Qué datos recoge.
- Para qué los usa (por ejemplo, entregar pedidos, facturar, enviar promociones si el cliente acepta).
- Si los comparte con alguien (por ejemplo, con la empresa de reparto o el proveedor del sistema de facturación).
- Cómo puede la persona ejercer sus derechos ARCO o dejar de recibir promociones.
- Dónde se publicarán los cambios al aviso.

Puede estar en la página web, en un letrero en el local o enviarse por WhatsApp al primer contacto. Para un negocio pequeño, conviene usar un modelo y adaptarlo con asesoría.

## Buenas prácticas con los datos de los clientes
- **Pide solo los datos que necesitas.**
- **No compartas** listas de clientes con terceros sin permiso.
- **No envíes promociones** a quien no las aceptó.
- **Protege** las listas y los teléfonos con contraseña (lección M15-6).
- **Borra** los datos que ya no necesitas.
- **Capacita** al equipo: los datos de los clientes no se comentan ni se usan para fines personales.

## Lo que hace Tortas Lupita
Lupita revisa su menú: todos los precios ahora incluyen el IVA y se exhiben en el local y en el catálogo de WhatsApp. Las promociones se anuncian con sus condiciones claras. Agrega un aviso de privacidad breve en su página y en el primer mensaje de WhatsApp, y una opción para dejar de recibir promociones. La propina se deja a criterio del cliente. Antes de vender la salsa en frasco, contrata asesoría para el etiquetado.`,
k: `**Ley Federal de Protección al Consumidor** y **Profeco**: información veraz, **precio total visible con impuestos**, respetar lo anunciado, **publicidad veraz**, garantías, cobros correctos (la **propina es voluntaria**) y comprobante. Alimentos envasados: **NOM-051** con sellos de advertencia. **Datos personales:** **aviso de privacidad**, finalidades informadas, seguridad y **derechos ARCO**.`,
ch: `Una tienda de celulares exhibe sus precios con IVA, entrega una hoja con la garantía de cada equipo y tiene un aviso de privacidad para los datos que pide al vender planes.`,
gi: `Las grandes empresas tienen áreas de protección de datos y de cumplimiento regulatorio que revisan sus avisos de privacidad, sus contratos con proveedores que manejan datos y su publicidad, para cumplir con las leyes de cada país donde operan.`,
e: `Lupita revisa su menú con la regla del precio total visible:

| Producto | Precio que mostraba (sin IVA) | Lo que se cobraba en caja | Precio correcto a exhibir (con IVA) |
|---|---|---|---|
| Torta de jamón | 40 | 46.40 | 46.40 → redondea a 46 |
| Desayuno | 55 | 63.80 | 63.80 → redondea a 63 |
| Agua fresca | 18 | 20.88 | 20.88 → redondea a 21 |

Ahora el cliente paga exactamente lo que ve en el menú. (Si redondea hacia abajo, el negocio absorbe la diferencia; si redondea hacia arriba, sube un poco su precio: es una decisión de precio, lección M5-8).`,
r: `La Profeco ha publicado en distintas ocasiones información para consumidores en la que señala que la propina en restaurantes es voluntaria y que los establecimientos no pueden obligar a los clientes a pagarla. En 2020 se publicó la modificación a la NOM-051 que introdujo en México el etiquetado frontal de advertencia en alimentos y bebidas preenvasados.`,
f: `Profeco (gob.mx/profeco); Ley Federal de Protección al Consumidor; Diario Oficial de la Federación, modificación a la NOM-051-SCFI/SSA1-2010 (27 de marzo de 2020); legislación federal de protección de datos personales en posesión de los particulares.`,
err: ["Exhibir precios sin IVA y cobrar más en la caja.","Anunciar promociones sin condiciones claras o no respetarlas.","Obligar a pagar propina o agregarla sin consentimiento.","Recoger datos de clientes sin aviso de privacidad."],
a: `Revisa el negocio que observas con los derechos del consumidor: ¿los precios incluyen impuestos y están visibles?, ¿las promociones tienen condiciones claras?, ¿hay aviso de privacidad? Redacta un aviso de privacidad breve con los seis elementos de esta lección.`,
sol: `Un aviso de privacidad para un negocio pequeño puede caber en media página; lo importante es decir qué datos se piden, para qué, con quién se comparten y cómo se ejercen los derechos ARCO.`,
q: [["En México, los precios exhibidos al consumidor deben…",["Incluir los impuestos","Excluir el IVA","No mostrarse"],0,"El consumidor debe ver el precio total."],
["Según la Profeco, la propina en restaurantes es…",["Voluntaria","Obligatoria","Un impuesto"],0,"No se puede obligar a pagarla."],
["Los derechos ARCO sobre datos personales son…",["Acceso, rectificación, cancelación y oposición","Ahorro, renta, crédito y oferta","Aviso, registro, contrato y orden"],0,"Son derechos de las personas sobre sus datos."],
["Un aviso de privacidad informa…",["Qué datos se recogen, para qué, con quién se comparten y cómo ejercer derechos","El menú","Los impuestos del mes"],0,"Es obligatorio al recoger datos personales."]],
t: ["Derechos del consumidor", "Profeco"]
},
"M14-5": {
s: `En una sola semana, Tortas Lupita recibe la visita de un verificador sanitario, un aviso de Protección Civil para revisar el gas, un recordatorio del SAT y una carta del IMSS. Lupita se pregunta: ¿cómo llevar el control de tantas obligaciones sin olvidar ninguna?`,
o: ["Identificar las principales obligaciones fiscales, laborales, sanitarias y de seguridad de un negocio.","Organizar un calendario de cumplimiento.","Prepararse para una inspección."],
x: `## Un negocio, muchas reglas
Un negocio formal tiene obligaciones con varias autoridades al mismo tiempo. Cada una vigila un tema distinto: impuestos, trabajo, salud, seguridad, ambiente, uso de suelo. No cumplir puede traer multas, recargos, clausuras temporales o definitivas e incluso problemas mayores. Cumplir, en cambio, da tranquilidad y abre puertas (clientes grandes, crédito, franquicias). Esta lección presenta un mapa general; los detalles dependen del giro, del tamaño, del estado y del municipio, y siempre conviene revisar la norma vigente con asesores.

## Las obligaciones fiscales (SAT y autoridades locales)
- Inscripción en el RFC y actualización de datos (domicilio, actividades).
- Emisión de facturas electrónicas (CFDI).
- Declaraciones y pagos mensuales (IVA, ISR, retenciones) y declaración anual.
- Contabilidad electrónica, si aplica.
- Revisión del buzón tributario.
- Impuestos estatales (impuesto sobre nómina) y municipales (predial, si se es dueño del inmueble; derechos por licencias).
(Lecciones M3-7 y M8-10).

## Las obligaciones laborales y de seguridad social (STPS, IMSS, Infonavit)
- Contratos por escrito y expediente de cada trabajador.
- Alta de los trabajadores en el IMSS desde el primer día y pago de cuotas.
- Aportaciones al Infonavit y al SAR.
- Pago puntual de salarios y prestaciones (aguinaldo, vacaciones, prima vacacional, PTU).
- Capacitación.
- Condiciones de seguridad e higiene en el trabajo (las normas de la Secretaría del Trabajo, por ejemplo sobre prevención de incendios, equipo de protección o riesgos psicosociales, NOM-035).
(Módulo 13).

## Las obligaciones sanitarias (Cofepris y autoridades estatales)
Para negocios que manejan alimentos, bebidas, medicamentos, cosméticos u otros productos relacionados con la salud:
- **Aviso de funcionamiento** o licencia sanitaria, según el giro.
- Cumplir las normas de **buenas prácticas de higiene** en el manejo de alimentos. En México, la norma **NOM-251-SSA1-2009** establece prácticas de higiene para el proceso de alimentos, bebidas o suplementos alimenticios: limpieza de instalaciones, control de temperaturas, manejo de materias primas, control de plagas, higiene del personal, agua potable, manejo de residuos y registros.
- Control de plagas por una empresa autorizada, con constancias.
- Capacitación del personal en manejo higiénico.
- Etiquetado correcto si se venden productos envasados (NOM-051, lección M14-4).

## Protección Civil (autoridad municipal o estatal)
- Programa interno o medidas de Protección Civil según el tamaño y el riesgo del negocio.
- Extintores vigentes y en número suficiente, señalización de rutas de evacuación, botiquín.
- Revisión de las instalaciones de **gas** y eléctricas.
- Capacitación del personal en emergencias.
- En negocios más grandes: simulacros y brigadas.

## Otras obligaciones frecuentes
- **Licencia de funcionamiento** o aviso de apertura y su refrendo (si aplica).
- **Uso de suelo** compatible.
- **Anuncios** y letreros con permiso.
- **Ambientales:** manejo de residuos, trampas de grasa en cocinas, descargas de agua, según la normativa local.
- **Música en el local:** pagos a las sociedades de gestión de derechos de autor cuando se reproduce música con fines comerciales, según las reglas aplicables.
- **Seguros:** no siempre son obligatorios, pero son muy recomendables (daños, responsabilidad civil).

## El calendario de cumplimiento
Para no olvidar nada, conviene un **calendario** con todas las obligaciones, su fecha, su responsable y dónde está el comprobante:

| Obligación | Frecuencia | Fecha | Responsable | Comprobante |
|---|---|---|---|---|
| Declaración y pago de IVA e ISR | Mensual | Día 17 | Contador | Acuse en carpeta digital |
| Cuotas IMSS | Mensual | Según calendario del IMSS | Contador | Comprobante de pago |
| Infonavit y SAR | Bimestral | Según calendario | Contador | Comprobante |
| Impuesto sobre nómina | Mensual | Según el estado | Contador | Comprobante |
| Control de plagas | Mensual | Primer lunes | Toño | Constancia de la empresa |
| Revisión de extintores | Anual | Marzo | Toño | Etiqueta y factura |
| Revisión de gas | Anual | Marzo | Toño | Dictamen del técnico |
| Capacitación en manejo de alimentos | Anual y a cada nuevo empleado | Enero y al contratar | Jefe de cocina | Constancias |
| Refrendo de licencia (si aplica) | Anual | Según el municipio | Administradora | Recibo |
| Aguinaldo | Anual | Antes del 20 de diciembre | Administradora | Recibos de nómina |
| Declaración anual | Anual | Marzo (personas morales) | Contador | Acuse |
| Renovación de la marca | Cada 10 años | Fecha del registro | Lupita | Título del IMPI |

## Prepararse para una inspección
Las inspecciones son normales. Para que una visita sea tranquila:
1. **Ten una carpeta** (física y digital) con todos los documentos: licencias, avisos, constancias de plagas, dictámenes de gas, registros de temperatura, constancias de capacitación, altas en el IMSS.
2. **Pide la identificación** del inspector y la **orden de visita** por escrito; verifica que sea auténtica.
3. **Designa a una persona** que atienda las visitas (y su suplente).
4. **Sé amable y colabora**, pero no firmes nada que no entiendas; lee el acta antes de firmar y anota tus observaciones.
5. **Guarda copia** del acta.
6. **Corrige** lo que te señalen y conserva la prueba.
7. **Consulta a tu asesor** si hay una sanción o algo que no entiendas.
8. **Nunca ofrezcas dinero** o regalos al inspector: es un delito y te expone a problemas mayores (lección M14-6).

## Cumplir como hábito
El cumplimiento no es una tarea de un día, sino un **hábito**: registrar, revisar y renovar. Un negocio que cumple todo el año no tiene que «correr» cuando llega una inspección. En Tortas Lupita, la administradora revisa el calendario cada lunes y Lupita lo revisa en la junta mensual.`,
k: `Obligaciones principales: **fiscales** (SAT: RFC, CFDI, declaraciones), **laborales y de seguridad social** (contratos, IMSS, Infonavit, prestaciones, seguridad e higiene), **sanitarias** (aviso de funcionamiento, **NOM-251** de higiene en alimentos, control de plagas), **Protección Civil** (extintores, gas, rutas de evacuación) y otras (licencias, uso de suelo, anuncios, ambientales). Usa un **calendario de cumplimiento** y una **carpeta** lista para inspecciones.`,
ch: `Una fonda tiene una carpeta en la caja con su aviso de funcionamiento, las constancias de fumigación, el dictamen del gas y las constancias de capacitación de su personal; cuando llega una verificación, la muestra en cinco minutos.`,
gi: `Las cadenas de restaurantes y supermercados tienen áreas de calidad y cumplimiento regulatorio que auditan cada sucursal con listas de verificación basadas en las normas sanitarias y de Protección Civil.`,
e: `Lupita revisa su carpeta de cumplimiento y encuentra lo que falta:

| Documento | ¿Lo tiene? | Acción |
|---|---|---|
| Aviso de funcionamiento sanitario | Sí | — |
| Constancias de control de plagas (12 meses) | 8 de 12 | Pedir copias a la empresa de plagas |
| Dictamen de gas | Vencido | Programar revisión esta semana |
| Constancias de capacitación en manejo de alimentos | 4 de 9 empleados | Inscribir a los 5 faltantes |
| Altas en el IMSS | Todas | — |
| Registros diarios de temperatura | Desde hace 2 meses | Mantener |

En una semana deja todo en orden, antes de la siguiente visita.`,
r: `La norma NOM-251-SSA1-2009, «Prácticas de higiene para el proceso de alimentos, bebidas o suplementos alimenticios», establece en México los requisitos mínimos de higiene que deben cumplir los establecimientos que procesan alimentos, incluidos restaurantes y fondas. La Cofepris y las autoridades sanitarias estatales la usan como referencia en sus verificaciones.`,
f: `Diario Oficial de la Federación, NOM-251-SSA1-2009; Cofepris (gob.mx/cofepris); Secretaría del Trabajo y Previsión Social, normas oficiales mexicanas de seguridad y salud en el trabajo.`,
err: ["Llevar las obligaciones «de memoria».","Dejar vencer dictámenes y constancias.","Firmar un acta de inspección sin leerla.","Ofrecer dinero a un inspector."],
a: `Arma el calendario de cumplimiento del negocio que observas con al menos diez obligaciones: frecuencia, fecha, responsable y comprobante. Revisa qué documentos de la carpeta faltan o están vencidos.`,
sol: `Si no sabes la fecha exacta de alguna obligación, anótala como pendiente y pregúntala al contador o a la autoridad correspondiente; lo importante es que no se olvide.`,
q: [["La NOM-251-SSA1-2009 se refiere a…",["Prácticas de higiene en el proceso de alimentos","El etiquetado de alimentos","Los impuestos"],0,"Es la referencia de higiene para restaurantes y fondas."],
["¿Qué conviene hacer cuando llega un inspector?",["Pedir su identificación y la orden de visita, colaborar y leer el acta antes de firmar","Ofrecerle dinero","Cerrar la puerta"],0,"Y guardar copia del acta."],
["Un calendario de cumplimiento sirve para…",["No olvidar obligaciones, fechas, responsables y comprobantes","Planear vacaciones","Calcular precios"],0,"Convierte el cumplimiento en hábito."],
["La revisión del gas y los extintores es una obligación de…",["Protección Civil","La Profeco","El IMPI"],0,"Autoridad municipal o estatal."]],
t: ["Cumplimiento regulatorio", "NOM-251"]
},
"M14-6": {
s: `Un inspector sugiere a Toño que «todo se puede arreglar» con un pago en efectivo. Al mismo tiempo, un proveedor ofrece a la encargada de compras una comisión «por debajo de la mesa». Lupita se da cuenta de que cumplir la ley no es solo llenar papeles: también es decidir qué no se hace.`,
o: ["Explicar qué es un programa de cumplimiento.","Construir una lista de verificación legal y una matriz de riesgos legales.","Establecer reglas claras contra la corrupción y los conflictos de interés."],
x: `## ¿Qué es el cumplimiento?
El **cumplimiento** (en inglés, *compliance*) es el conjunto de reglas, procesos y controles que un negocio establece para asegurarse de que él y sus personas **respetan las leyes, las normas y sus propios valores**. No es solo reaccionar cuando hay un problema, sino **prevenir** que ocurra: saber qué reglas aplican, asignar responsables, capacitar, vigilar y corregir.

En las empresas grandes hay áreas completas de cumplimiento, con oficiales de cumplimiento, códigos de ética, líneas de denuncia y auditorías. En un negocio pequeño, el cumplimiento puede ser tan sencillo como una lista de verificación, un calendario (lección M14-5), unas cuantas reglas claras y el ejemplo del dueño.

## La lista de verificación legal
Una revisión anual con preguntas sencillas ayuda a detectar huecos:

| Área | Pregunta | Sí / No |
|---|---|---|
| Sociedad | ¿El acta constitutiva y los poderes están actualizados? ¿Hay convenio entre socios? | |
| Fiscal | ¿Estamos al corriente? ¿Tenemos opinión de cumplimiento positiva? | |
| Laboral | ¿Todos tienen contrato y alta en el IMSS desde el primer día? ¿Hay reglas internas firmadas? | |
| Contratos | ¿Los contratos de renta, proveedores y clientes clave están por escrito y vigentes? | |
| Marca | ¿La marca está registrada en las clases correctas y vigente? | |
| Consumidor | ¿Los precios incluyen impuestos y están visibles? ¿Hay aviso de privacidad? | |
| Sanitario | ¿Tenemos aviso de funcionamiento, constancias de plagas y capacitación en higiene? | |
| Protección Civil | ¿Extintores y gas al día? | |
| Seguros | ¿Tenemos seguro de daños y de responsabilidad civil? | |
| Ética | ¿Todos conocen la regla de cero sobornos y cómo reportar un problema? | |

## La matriz de riesgos legales
Otra herramienta útil es una **matriz de riesgos**: para cada riesgo legal, se estima su **probabilidad** (qué tan posible es que ocurra) y su **impacto** (qué tan grave sería), y se define una acción (Módulo 16 profundiza en esta herramienta).

| Riesgo | Probabilidad | Impacto | Acción |
|---|---|---|---|
| Demanda laboral por despido mal hecho | Media | Alto | Reglas internas, documentar, asesoría antes de despedir |
| Intoxicación de un cliente | Baja | Muy alto | NOM-251, registros, seguro de responsabilidad civil |
| Clausura por Protección Civil | Baja | Alto | Revisión anual de gas y extintores |
| Pérdida de la marca | Baja (ya registrada) | Alto | Renovar a tiempo y vigilar |
| Multa del SAT | Media | Medio | Contador, calendario, revisar opinión de cumplimiento |
| Soborno a un inspector o comisión de un proveedor | Media | Muy alto | Política de cero sobornos, capacitación, rotación de compras |

## La corrupción: decir que no
La **corrupción** incluye ofrecer, dar, pedir o aceptar pagos, regalos o favores para obtener un beneficio indebido: evitar una multa, ganar un contrato, acelerar un trámite, que un empleado elija a un proveedor. Es dañina para la sociedad y para el negocio:
- **Es ilegal:** en México, la Ley General de Responsabilidades Administrativas (vigente desde 2017) y el Código Penal sancionan tanto a los servidores públicos como a los particulares y las empresas que participan en actos de corrupción. Las empresas pueden recibir sanciones graves, como multas, inhabilitación para contratar con el gobierno o incluso su disolución en ciertos casos.
- **Crea dependencia:** quien paga una vez, normalmente tiene que seguir pagando.
- **Expone al negocio** a extorsiones y a perder todo lo construido.
- **Daña la cultura:** si el dueño soborna, los empleados aprenden que «así se hacen las cosas».

## Reglas sencillas contra la corrupción
1. **Cero sobornos:** ni a autoridades ni a empleados de clientes. Si un servidor público pide dinero, no se paga; se pide la orden por escrito, se anota su nombre y se consulta a un abogado; existen canales para denunciar.
2. **Regalos con límite:** los empleados no aceptan regalos de proveedores por encima de un valor simbólico, y los reportan.
3. **Conflictos de interés:** si un empleado tiene relación con un proveedor (familiar, socio), debe declararlo y no participar en la decisión.
4. **Compras transparentes:** cotizaciones por escrito, comparación de costos totales y separación de funciones (lección M10-1).
5. **Pagos con comprobante:** todo pago, con factura o recibo; nada «por fuera».
6. **Un canal para reportar:** que cualquier empleado pueda avisar al dueño de algo incorrecto sin miedo a represalias.
7. **El ejemplo del dueño:** sin él, ninguna regla funciona.

## Los seguros como parte del cumplimiento
Los seguros no evitan los problemas, pero reducen su impacto:
- **Seguro de daños:** incendio, inundación, robo, rotura de equipo.
- **Seguro de responsabilidad civil:** si un cliente o un tercero sufre un daño por causa del negocio (una intoxicación, un accidente en el local).
- **Seguro de interrupción de negocio** (en algunos casos): cubre ingresos perdidos si el negocio tiene que cerrar por un siniestro cubierto.

Conviene comparar coberturas y exclusiones con un agente, no solo el precio.

## El cumplimiento en las empresas gigantes
Las grandes empresas que operan en varios países tienen programas de cumplimiento muy estrictos, porque las sanciones por corrupción pueden ser enormes. Uno de los casos más conocidos es el de la empresa alemana Siemens, que en 2008 aceptó pagar en Estados Unidos y Alemania sanciones que sumaron alrededor de 1,600 millones de dólares por pagos indebidos en varios países, y después reconstruyó su programa de cumplimiento. El Módulo 27 profundiza en la ética y la corrupción en las empresas.

## La decisión de Lupita
Lupita establece tres reglas que todos firman: cero sobornos, regalos de proveedores solo de valor simbólico y declarar cualquier relación con proveedores. Toño no paga al inspector: pide la orden por escrito y llama a la abogada; el «problema» resulta inexistente. La encargada de compras rechaza la comisión y lo reporta; Lupita cambia de proveedor. En la siguiente junta, Lupita reconoce públicamente a ambos.

## Cierre del módulo
Lo legal no es un tema solo de abogados: es parte de dirigir bien un negocio. Prevenir con contratos claros, una marca registrada, derechos del consumidor respetados, obligaciones al día y reglas éticas firmes cuesta poco y evita problemas que pueden costar el negocio entero.`,
k: `**Cumplimiento:** reglas, procesos y controles para respetar leyes, normas y valores; **prevenir** más que reaccionar. Herramientas: **lista de verificación legal**, **matriz de riesgos** (probabilidad × impacto), calendario. **Cero sobornos:** en México, la Ley General de Responsabilidades Administrativas sanciona también a particulares y empresas. Reglas sobre regalos, **conflictos de interés**, compras transparentes y un canal para reportar. **Seguros** para reducir el impacto.`,
ch: `Una ferretería establece que ningún empleado puede aceptar regalos de proveedores de más de 300 pesos y que todo se reporta; un vendedor que ofrecía «comisiones» a la encargada de compras deja de ser proveedor.`,
gi: `En 2008, Siemens aceptó pagar sanciones de alrededor de 1,600 millones de dólares en Estados Unidos y Alemania por pagos indebidos en varios países, y después construyó uno de los programas de cumplimiento más conocidos del mundo.`,
e: `Lupita completa su matriz de riesgos legales con una calificación del 1 al 3 (probabilidad × impacto):

| Riesgo | Probabilidad | Impacto | Puntaje | Prioridad |
|---|---|---|---|---|
| Soborno o comisión indebida | 2 | 3 | 6 | Alta |
| Demanda laboral | 2 | 3 | 6 | Alta |
| Intoxicación de un cliente | 1 | 3 | 3 | Media |
| Multa del SAT | 2 | 2 | 4 | Media |
| Clausura por Protección Civil | 1 | 3 | 3 | Media |

Atiende primero los de puntaje 6: reglas anticorrupción y orden en los temas laborales.`,
r: `En diciembre de 2008, Siemens AG acordó pagar alrededor de 800 millones de dólares a autoridades de Estados Unidos y una cantidad similar a autoridades alemanas por violaciones relacionadas con pagos indebidos, en uno de los casos de corrupción corporativa más grandes de su época.`,
f: `Departamento de Justicia y Comisión de Bolsa y Valores de Estados Unidos, comunicados de diciembre de 2008 sobre Siemens AG; Ley General de Responsabilidades Administrativas (México, 2017).`,
err: ["Pagar «para que no haya problemas».","Permitir regalos de proveedores sin límites.","No tener un canal para reportar problemas.","Creer que el cumplimiento es solo papeleo."],
a: `Aplica la lista de verificación legal de esta lección al negocio que observas y arma una matriz de riesgos legales con al menos cinco riesgos. Escribe tres reglas éticas que propondrías para todos en el negocio.`,
sol: `Las reglas más útiles son concretas y fáciles de recordar: «cero sobornos», «regalos de proveedores solo de valor simbólico y reportados», «declara cualquier relación con proveedores».`,
q: [["El cumplimiento (compliance) busca…",["Prevenir que el negocio y sus personas violen leyes, normas y valores","Pagar menos impuestos de forma ilegal","Vender más"],0,"Es prevención con reglas, procesos y controles."],
["En México, ¿pueden ser sancionados los particulares y las empresas por actos de corrupción?",["Sí, por ejemplo con la Ley General de Responsabilidades Administrativas","No, solo los servidores públicos","Solo si son extranjeros"],0,"Vigente desde 2017."],
["Un conflicto de interés ocurre cuando…",["Un empleado tiene una relación con un proveedor y participa en la decisión de compra","Dos empleados discuten","El cliente se queja"],0,"Debe declararse y apartarse de la decisión."],
["Un seguro de responsabilidad civil cubre…",["Daños que el negocio cause a clientes o terceros","Las vacaciones de los empleados","Los impuestos"],0,"Por ejemplo, una intoxicación o un accidente."]],
t: ["Cumplimiento (compliance)", "Matriz de riesgos"]
}
});
// ===== M15. Tecnología y sistemas =====
Object.assign(window.LECC, {
"M15-1": {
s: `En el puesto, a Lupita le bastaba un cuaderno. Con el local, el cuaderno ya no alcanza: hay pedidos por WhatsApp, facturas, inventario, nómina y tres formas de pago. Un vendedor le ofrece «un sistema que hace todo» por 15,000 pesos al mes. ¿Qué tecnología necesita realmente?`,
o: ["Describir cómo evoluciona la tecnología de un negocio según su tamaño.","Elegir herramientas tecnológicas con criterios claros.","Calcular el costo total de una herramienta."],
x: `## La tecnología como herramienta
La tecnología en un negocio no es un fin en sí misma: es una **herramienta** para vender más, controlar mejor, ahorrar tiempo, reducir errores y tomar mejores decisiones. Una herramienta adecuada al tamaño del negocio ayuda mucho; una herramienta demasiado grande o mal implementada puede costar dinero, tiempo y dolores de cabeza.

## Las etapas típicas
| Etapa | Herramientas típicas | Para qué |
|---|---|---|
| Changarro | Cuaderno, calculadora, celular, WhatsApp | Anotar ventas y fiado, comunicarse con clientes y proveedores |
| Microempresa | Hoja de cálculo, terminal de pago, WhatsApp Business, facturación del SAT | Controlar ventas, inventario básico y flujo; cobrar con tarjeta; facturar |
| Pyme | Sistema de punto de venta (con inventario), sistema contable, nómina, CRM sencillo, perfil en mapas y redes | Integrar ventas, inventario y caja; contabilidad formal; seguimiento de clientes |
| Empresa mediana | Sistema administrativo integrado o ERP, comercio electrónico, tableros de indicadores | Unir todas las áreas en un solo sistema; vender en línea; decidir con datos |
| Gran empresa | ERP corporativo, sistemas especializados por área, análisis de datos, automatización e inteligencia artificial, ciberseguridad avanzada | Coordinar miles de personas, sucursales y procesos en tiempo real |

No hay que saltar etapas: un changarro no necesita un ERP, y una cadena de 30 sucursales no puede funcionar con un cuaderno.

## Qué procesos apoyar primero
Para elegir tecnología, conviene empezar por los **procesos** que más duelen o más importan:
1. **Ventas y caja:** cobrar rápido, sin errores, con varias formas de pago, y saber cuánto se vendió (lección M15-2).
2. **Inventario:** saber qué hay, qué falta y cuándo pedir (lecciones M9-5 y M9-6).
3. **Facturación e impuestos:** emitir CFDI y llevar la contabilidad (lección M8-10).
4. **Clientes:** registrar pedidos, datos y preferencias, y dar seguimiento (lección M15-5).
5. **Nómina:** calcular y timbrar recibos (lección M13-5).
6. **Indicadores:** ver los números clave sin tener que armarlos a mano (lección M7-4).

## Criterios para elegir una herramienta
- **¿Resuelve un problema real** y prioritario?
- **¿Es fácil de usar** para el equipo? (La mejor herramienta no sirve si nadie la usa).
- **¿Se adapta al tamaño** del negocio y puede crecer con él?
- **¿Se integra** con otras herramientas (por ejemplo, el punto de venta con la facturación y la contabilidad)?
- **¿Cuánto cuesta en total?** (ver abajo).
- **¿Funciona sin internet** o qué pasa si se cae la conexión?
- **¿Qué soporte** ofrece el proveedor? ¿En español? ¿En qué horario?
- **¿Dónde se guardan los datos** y se pueden exportar si se cambia de proveedor?
- **¿Es seguro?** (contraseñas, permisos por usuario, respaldos; lección M15-6).
- **¿Cumple** con los requisitos fiscales de México (por ejemplo, facturación CFDI 4.0)?

## En la nube o en el local
- **En la nube:** el programa y los datos están en servidores del proveedor; se paga una suscripción mensual; se usa desde cualquier dispositivo con internet; el proveedor se encarga de actualizaciones y respaldos. Es la opción más común hoy para negocios pequeños.
- **En el local (instalado):** el programa se instala en computadoras del negocio; puede requerir un pago inicial más alto; el negocio se encarga de respaldos y mantenimiento; puede funcionar sin internet.

Muchos sistemas modernos combinan ambas cosas: funcionan sin conexión y sincronizan cuando vuelve el internet.

## El costo total de una herramienta
Igual que con el equipo (lección M10-3), hay que calcular el **costo total**, no solo la mensualidad:
- Licencia o suscripción.
- Equipo necesario (computadora, tableta, impresora de tickets, lector de código de barras, cajón de dinero).
- Instalación y configuración.
- Capacitación del equipo.
- Tiempo para cargar la información inicial (productos, precios, clientes).
- Soporte y actualizaciones.
- Comisiones por transacción (en terminales de pago y plataformas).
- Costo de cambiarse después (si los datos no se pueden exportar).

## El error del «sistema que hace todo»
Comprar el sistema más completo y caro no garantiza nada. Muchos negocios pagan por funciones que nunca usan, o no logran implementarlo porque es demasiado complejo para su tamaño. Una regla práctica: **empieza por lo que más te duele, con la herramienta más sencilla que lo resuelva, y crece desde ahí**.

## La decisión de Lupita
Lupita analiza sus problemas principales: errores en la caja, no saber qué tortas se venden más, inventario sin control y facturas hechas a mano. En lugar del sistema de 15,000 pesos al mes, elige:
- Un **sistema de punto de venta en la nube** para restaurantes (unos 800 pesos al mes) con inventario básico, varias formas de pago, reportes por producto y conexión con un servicio de facturación.
- Una **terminal de pago** con comisión por transacción.
- **WhatsApp Business** con catálogo (gratis).
- Una **hoja de cálculo** para el flujo de caja proyectado.
- El **sistema contable y de nómina** del contador.

El costo total del primer año (equipo, suscripciones y capacitación) es de unos 25,000 pesos, y en tres meses los errores de caja bajan casi a cero.

## La tecnología cambia el trabajo
Implementar una herramienta nueva cambia la forma de trabajar: hay que capacitar, ajustar procesos y, a veces, vencer la resistencia de quienes «siempre lo han hecho así». Conviene:
- Explicar **por qué** se cambia.
- Capacitar **antes** de arrancar.
- Empezar con un **periodo de prueba** (en una caja o un turno).
- Tener a una persona **responsable** de la herramienta.
- Revisar después de un mes qué funciona y qué no.

## En las empresas gigantes
Las grandes empresas tienen áreas de tecnología con cientos o miles de personas, dirigidas por un director de tecnología (CTO) o de sistemas (CIO). Invierten en sistemas que conectan todas sus operaciones, en comercio electrónico, en análisis de datos y en ciberseguridad. Para muchas, la tecnología ya no es solo un apoyo, sino una fuente de ventaja competitiva (Módulo 26).`,
k: `La tecnología es una **herramienta**: elige según la **etapa** del negocio y el **proceso** que más duele (caja, inventario, facturación, clientes, nómina, indicadores). Criterios: facilidad de uso, integración, **costo total**, funcionamiento sin internet, soporte, datos exportables, seguridad y cumplimiento fiscal. **En la nube** o **local**. Empieza sencillo y crece.`,
ch: `Una papelería pasa del cuaderno a una hoja de cálculo con sus 300 productos y sus ventas diarias; al año, cuando abre una segunda tienda, adopta un punto de venta con inventario en la nube.`,
gi: `Las grandes empresas tienen directores de tecnología y sistemas que integran ventas, inventarios, logística, finanzas y personas en plataformas que funcionan en tiempo real en miles de puntos.`,
e: `Lupita compara el costo total del primer año de dos opciones:

| Concepto | «Sistema que hace todo» | Opción elegida |
|---|---|---|
| Suscripciones (12 meses) | 180,000 | 9,600 |
| Equipo (tableta, impresora de tickets, cajón) | 15,000 | 8,000 |
| Implementación y capacitación | 30,000 | 4,000 |
| Comisiones de terminal (aprox.) | Iguales en ambas | Iguales en ambas |
| **Total sin comisiones** | **225,000** | **21,600** |

La opción sencilla cuesta una décima parte y resuelve sus cuatro problemas principales.`,
r: `Muchas empresas que cotizan en bolsa incluyen en su equipo directivo a un director de tecnología o de sistemas, y en sus informes anuales describen sus inversiones en plataformas digitales, comercio electrónico y ciberseguridad.`,
f: `Informes anuales de empresas de la Bolsa Mexicana de Valores, secciones sobre tecnología y transformación digital.`,
err: ["Comprar el sistema más completo sin necesitarlo.","Mirar solo la mensualidad y no el costo total.","Implementar sin capacitar ni probar.","Elegir una herramienta de la que no se pueden sacar los datos."],
a: `Lista los cinco procesos más importantes del negocio que observas e indica qué herramienta usa hoy cada uno. Elige el proceso que más duele y compara dos herramientas con los criterios de esta lección.`,
sol: `Si una herramienta no se integra con las demás (por ejemplo, el punto de venta con la facturación), suma el tiempo de capturar los datos dos veces a su costo total.`,
q: [["¿Qué herramienta tecnológica suele necesitar primero un negocio que crece?",["Una que resuelva el proceso que más le duele, como la caja o el inventario","Un ERP corporativo","Inteligencia artificial avanzada"],0,"Empezar sencillo y crecer."],
["El costo total de una herramienta incluye…",["Suscripción, equipo, implementación, capacitación y soporte","Solo la mensualidad","Solo el precio de la tableta"],0,"Como cualquier compra importante."],
["Una ventaja de los sistemas en la nube es…",["Se usan desde cualquier dispositivo y el proveedor hace actualizaciones y respaldos","Nunca necesitan internet","Son siempre gratis"],0,"Son los más comunes hoy en negocios pequeños."],
["Al implementar un sistema nuevo conviene…",["Capacitar antes, probar en pequeño y tener un responsable","Arrancar en todo el negocio sin avisar","No explicar el motivo"],0,"Así se reduce la resistencia y los errores."]],
t: ["Tecnología en el negocio", "Sistema en la nube"]
},
"M15-2": {
s: `Cada noche, el dinero de la caja no cuadra: unas veces sobran 50 pesos, otras faltan 300. Nadie sabe si es error, cambio mal dado o algo peor. Toño decide ordenar la caja con un punto de venta y un corte de caja diario.`,
o: ["Explicar qué es un sistema de punto de venta y qué información da.","Hacer un corte de caja con fondo fijo y arqueo.","Aceptar pagos digitales cuidando comisiones y seguridad."],
x: `## El punto de venta
El **punto de venta** es el lugar y el sistema donde se registra cada venta y se cobra al cliente. Puede ser desde una caja registradora sencilla hasta un **sistema de punto de venta** (en inglés, POS, *point of sale*) en una tableta o computadora, con impresora de tickets, cajón de dinero y terminal para tarjetas.

Un sistema de punto de venta registra cada venta con:
- Fecha y hora.
- Productos vendidos y cantidades.
- Precio, descuentos e impuestos.
- Forma de pago (efectivo, tarjeta, transferencia, vales).
- Quién la registró (cada cajero con su usuario).

## Lo que permite saber
Con esa información, el sistema genera reportes que antes había que armar a mano:
- **Ventas por día, por hora y por producto** (qué torta se vende más y en qué horario).
- **Ticket promedio** y número de tickets (lección M5-2).
- **Ventas por forma de pago.**
- **Ventas por cajero.**
- **Inventario:** si se configura con recetas, descuenta automáticamente los ingredientes de cada torta vendida y avisa cuando algo llega a su punto de reorden.
- **Comparaciones** con días o semanas anteriores.

Esa información alimenta el tablero de indicadores (lección M7-4) y las decisiones de compras, personal y marketing.

## El fondo fijo de caja
El **fondo fijo** (o fondo de cambio) es una cantidad fija de dinero (por ejemplo, 1,000 pesos en billetes y monedas pequeñas) que se deja en la caja al iniciar el día para dar cambio. Al cierre, se separa el fondo fijo y el resto es lo que se vendió en efectivo. Así siempre se empieza con la misma cantidad y se evita confundir el cambio con las ventas.

## El corte de caja
El **corte de caja** es la comparación, al final de un turno o del día, entre lo que **dice el sistema** que se vendió y lo que **realmente hay** en la caja y en los comprobantes. Pasos:
1. **Cerrar el turno** en el sistema y obtener el reporte de ventas por forma de pago.
2. **Contar el efectivo** (arqueo): billetes y monedas.
3. **Separar el fondo fijo.**
4. **Comparar** el efectivo restante con las ventas en efectivo del reporte.
5. **Comparar** los cobros con tarjeta con el reporte de la terminal y las transferencias con el estado de cuenta.
6. **Registrar las diferencias** (faltantes o sobrantes) y su posible causa.
7. **Firmar** el corte quien entrega y quien recibe.
8. **Resguardar o depositar** el efectivo.

Hacer el corte **por turno y por cajero** permite saber dónde está una diferencia. Si hay un solo corte al final del día con tres personas que tocaron la caja, es imposible saber qué pasó.

## Las diferencias de caja
Las diferencias tienen causas comunes:
- **Cambio mal dado** (el error más frecuente).
- **Ventas no registradas** o registradas con el precio equivocado.
- **Gastos pagados de la caja** sin comprobante («saqué 200 para el gas»).
- **Pagos con tarjeta registrados como efectivo**, o al revés.
- **Robo**, que es menos común de lo que se cree, pero hay que prevenirlo.

Reglas útiles:
- **Todo se registra:** no hay ventas «sin ticket».
- **Ningún gasto sale de la caja de ventas sin comprobante**; mejor tener una caja chica separada para gastos menores.
- **Cada cajero con su usuario** y su propio corte.
- **Arqueos sorpresa** de vez en cuando.
- **Revisar las diferencias** cada semana: si un cajero tiene diferencias frecuentes, hay que capacitar o investigar.

## Los pagos digitales
Cada vez más clientes prefieren no pagar en efectivo. Las formas más comunes en México:
- **Tarjeta de débito o crédito** con una terminal. La terminal cobra una **comisión** por transacción (un porcentaje más IVA), y el dinero llega a la cuenta en uno o varios días.
- **Transferencia bancaria (SPEI):** el sistema de pagos del Banco de México permite transferencias entre bancos en segundos, a cualquier hora. Se puede compartir la cuenta (CLABE) del negocio o un código QR del banco.
- **Pagos con código QR** de bancos o de aplicaciones de pago.
- **Vales de despensa o de comida**, si el negocio los acepta.

Ventajas: más ventas (clientes que no traen efectivo), menos riesgo de robo, registro automático. Desventajas: comisiones, el dinero tarda en llegar (en tarjeta), riesgo de fraudes (comprobantes de transferencia falsos).

## Cuidado con los comprobantes falsos
Un fraude común es mostrar en el celular una **captura de pantalla falsa** de una transferencia. Para evitarlo:
- **Verifica en tu propia aplicación bancaria** que el dinero llegó antes de entregar el pedido.
- Usa los servicios del banco que avisan al recibir un pago.
- En pedidos grandes, cobra antes de entregar o usa un medio de pago verificado.

## La seguridad del efectivo
- Mantén poco efectivo en la caja: haz retiros parciales durante el día a una caja fuerte.
- Deposita con frecuencia, en horarios variables.
- Instala cámaras visibles en la zona de caja.
- No cuentes dinero frente a los clientes.

## El resultado en Tortas Lupita
Con el punto de venta, el fondo fijo, el corte por turno y la verificación de transferencias:
- Las diferencias de caja bajan de un promedio de 180 pesos diarios a menos de 15.
- Descubren que el 35 % de las ventas ya se pagan de forma digital.
- Saben por primera vez que la torta de pierna vende el doble los viernes, y ajustan sus compras.`,
k: `**Sistema de punto de venta:** registra cada venta (productos, precio, forma de pago, cajero) y genera reportes de ventas, ticket, productos, horas e inventario. **Fondo fijo** para el cambio. **Corte de caja** por turno y cajero: lo que dice el sistema frente a lo que hay (arqueo). Pagos digitales (tarjeta, **SPEI**, QR): más ventas, pero cuida **comisiones** y **comprobantes falsos**.`,
ch: `Una tienda de abarrotes adopta un punto de venta en una tableta con lector de código de barras; ahora sabe qué productos se venden más, cuándo pedir y si la caja cuadra cada noche.`,
gi: `Las grandes cadenas registran cada venta de cada caja en tiempo real; con esa información ajustan inventarios, precios y personal tienda por tienda.`,
e: `Toño compara las diferencias de caja antes y después:

| Indicador | Antes | Después |
|---|---|---|
| Diferencia promedio diaria | 180 | 12 |
| Diferencia al mes (26 días) | 4,680 | 312 |
| Ventas digitales | Sin registro | 35 % |
| Costo del sistema y equipo (mensual prorrateado) | 0 | 1,500 |

Solo por la caja, el sistema se paga con creces: unos 4,300 pesos menos de diferencias al mes, más la información de ventas.`,
r: `El Banco de México opera el Sistema de Pagos Electrónicos Interbancarios (SPEI), que permite transferencias entre bancos en segundos, a cualquier hora del día y todos los días del año. Banxico también impulsó esquemas de cobro con código QR para facilitar los pagos digitales en comercios.`,
f: `Banco de México, información sobre SPEI y pagos digitales (banxico.org.mx).`,
err: ["Hacer un solo corte de caja al día con varias personas que tocaron la caja.","Pagar gastos de la caja de ventas sin comprobante.","Entregar un pedido con una captura de pantalla sin verificar la transferencia.","Mantener mucho efectivo en la caja."],
a: `Diseña el procedimiento de corte de caja del negocio que observas: fondo fijo, pasos, formato de registro de diferencias y quién firma. Si es posible, revisa qué reportes podría darle un punto de venta que hoy no tiene.`,
sol: `Un buen formato de corte tiene: ventas por forma de pago según el sistema, efectivo contado, fondo fijo, diferencia, causa probable y firmas de quien entrega y quien recibe.`,
q: [["El corte de caja compara…",["Lo que dice el sistema que se vendió con lo que realmente hay","Precios con la competencia","Ventas con impuestos"],0,"Permite detectar diferencias."],
["El fondo fijo de caja sirve para…",["Tener siempre la misma cantidad para dar cambio","Pagar la renta","Invertir"],0,"Se separa al hacer el corte."],
["¿Cómo evitar el fraude de capturas de transferencias falsas?",["Verificando en tu propia aplicación bancaria que el dinero llegó","Confiando en la captura","Pidiendo dos capturas"],0,"Antes de entregar el pedido."],
["¿Por qué conviene un corte por turno y por cajero?",["Para saber dónde está una diferencia","Para trabajar más","Porque lo pide la Profeco"],0,"Con varias personas en una sola caja es imposible saberlo."]],
t: ["Sistema de punto de venta (POS)", "Corte de caja"]
},
"M15-3": {
s: `Toño anota todo en papeles sueltos. Lupita le pide saber cuánto vendieron por mes, cuánta merma hubo y cuánto efectivo tendrán en enero. Toño abre una hoja de cálculo por primera vez y descubre que puede hacer en minutos lo que antes le tomaba una tarde.`,
o: ["Organizar información del negocio en tablas.","Usar fórmulas básicas de una hoja de cálculo.","Armar plantillas sencillas de ventas, inventario y flujo de caja."],
x: `## La herramienta más útil y subestimada
La **hoja de cálculo** (Microsoft Excel, Hojas de cálculo de Google, LibreOffice Calc y otras) es probablemente la herramienta de negocios más usada en el mundo. Sirve para registrar datos, hacer cuentas automáticamente, analizar información y presentar resultados en tablas y gráficas. Para un negocio pequeño, puede ser el primer «sistema» de control; para una empresa grande, sigue siendo la herramienta de análisis del día a día.

La primera hoja de cálculo para computadoras personales, **VisiCalc**, fue creada en 1979 por Dan Bricklin y Bob Frankston, y muchos historiadores de la tecnología la consideran una de las razones por las que las empresas empezaron a comprar computadoras personales: de pronto, un gerente podía cambiar un número y ver al instante el efecto en todo su presupuesto.

## Lo básico
- Una hoja está formada por **celdas** organizadas en **filas** (números) y **columnas** (letras). Cada celda tiene una dirección, como **B3**.
- En una celda se puede escribir un **dato** (texto, número, fecha) o una **fórmula**, que siempre empieza con el signo **=**.
- Las fórmulas pueden hacer operaciones con otras celdas: **=B3*C3** multiplica el contenido de B3 por el de C3. Si cambias B3, el resultado se actualiza solo.

## La regla de oro: datos en forma de tabla
La hoja funciona mejor cuando los datos se organizan como una **tabla**:
- **Una fila por registro** (una venta, un producto, un día).
- **Una columna por dato** (fecha, producto, cantidad, precio).
- **Encabezados** claros en la primera fila.
- **Sin filas vacías ni celdas combinadas** en medio de los datos.
- **Un tipo de dato por columna** (solo fechas en la columna de fecha, solo números en la de cantidad).

## Las fórmulas más útiles
| Fórmula | Qué hace | Ejemplo |
|---|---|---|
| =SUMA(B2:B31) | Suma un rango | Ventas del mes |
| =PROMEDIO(B2:B31) | Promedio | Venta diaria promedio |
| =MAX(B2:B31) y =MIN(B2:B31) | El valor más alto y más bajo | Mejor y peor día |
| =CONTAR(B2:B31) | Cuenta celdas con números | Días con venta registrada |
| =B2*C2 | Multiplica | Cantidad por precio |
| =B2/C2 | Divide | Ticket promedio |
| =SI(B2<C2;"Pedir";"OK") | Decide según una condición | Avisar si el inventario está bajo el punto de reorden |
| =SUMAR.SI(A2:A100;"Pierna";C2:C100) | Suma solo lo que cumple una condición | Ventas de la torta de pierna |
| =BUSCARV(A2;Precios!A:B;2;FALSO) | Busca un dato en otra tabla | Traer el precio de un producto |

(En algunas versiones o idiomas se usa coma en lugar de punto y coma para separar los argumentos, y algunos nombres de funciones cambian ligeramente).

## Referencias relativas y absolutas
Cuando copias una fórmula hacia abajo, sus referencias cambian (B2 se vuelve B3, B4...). Eso es una **referencia relativa**. Si quieres que una referencia no cambie (por ejemplo, la celda con el porcentaje de margen), usas una **referencia absoluta** con signos de pesos: **$F$1**. Este pequeño detalle evita muchos errores.

## Tres plantillas útiles para un negocio
**1. Registro de ventas diarias**
| Fecha | Tickets | Ventas | Ticket promedio | Efectivo | Digital |
|---|---|---|---|---|---|
| 01/03 | 168 | 7,720 | =C2/B2 | 5,020 | 2,700 |
Al final: =SUMA() de ventas, =PROMEDIO() del ticket y una gráfica de ventas por día.

**2. Control de inventario**
| Insumo | Existencia | Consumo diario | Días de entrega | Días de seguridad | Punto de reorden | ¿Pedir? |
|---|---|---|---|---|---|---|
| Bolsas | 1,800 | 250 | 5 | 3 | =C2*D2+C2*E2 | =SI(B2<=F2;"PEDIR";"OK") |

**3. Flujo de caja proyectado**
| Mes | Saldo inicial | Cobros | Pagos | Saldo final |
|---|---|---|---|---|
| Enero | 20,000 | 180,000 | 185,000 | =B2+C2-D2 |
| Febrero | =E2 | 190,000 | 185,000 | =B3+C3-D3 |

La calculadora «Flujo de caja de 6 meses» del curso hace exactamente esto.

## Herramientas que ahorran tiempo
- **Filtros:** mostrar solo ciertas filas (por ejemplo, las ventas de los viernes).
- **Ordenar:** de mayor a menor venta.
- **Formato condicional:** pintar de rojo automáticamente lo que está por debajo de una meta.
- **Tablas dinámicas:** resumir miles de filas en segundos (ventas por producto y por mes).
- **Gráficas:** ver tendencias de un vistazo.
- **Validación de datos:** listas desplegables para evitar errores de captura.

## Buenas prácticas
- **Separa los datos de los cálculos y los reportes** (en pestañas distintas).
- **No escribas números «a mano» dentro de las fórmulas**; ponlos en una celda de supuestos (por ejemplo, el margen o la tasa de IVA) y haz referencia a ella.
- **Revisa las fórmulas** con un caso que conozcas el resultado.
- **Guarda versiones** y respalda el archivo (lección M15-6).
- **Protege** las celdas con fórmulas para que nadie las borre por error.
- **No dependas de una hoja que solo entiende una persona.**

## Cuándo la hoja ya no alcanza
La hoja de cálculo es excelente, pero tiene límites: varias personas capturando al mismo tiempo, miles de productos, varias sucursales, necesidad de facturar o de controlar la caja en tiempo real. Cuando aparecen esos problemas, es momento de un sistema especializado (lecciones M15-2 y M15-4). Aun así, la hoja seguirá siendo útil para analizar y planear.

## El cambio de Toño
Toño arma tres pestañas: ventas diarias (que alimenta el punto de venta con una exportación semanal), inventario de insumos A y flujo de caja de seis meses. En la junta mensual, en lugar de papeles sueltos, presenta una gráfica de ventas, el porcentaje de merma y el saldo esperado en enero.`,
k: `La **hoja de cálculo** registra, calcula y analiza. Organiza los datos como **tabla** (una fila por registro, una columna por dato). Fórmulas clave: **SUMA, PROMEDIO, MAX/MIN, SI, SUMAR.SI, BUSCARV**; referencias **relativas** y **absolutas** ($). Plantillas: **ventas diarias, inventario, flujo de caja**. Separa datos, cálculos y reportes; respalda. Primera hoja para PC: **VisiCalc** (1979).`,
ch: `Una pastelería registra cada pedido en una hoja con fecha, cliente, producto y precio; con un filtro sabe qué pasteles se piden más en mayo y prepara sus compras.`,
gi: `Aun en empresas con grandes sistemas, los analistas de finanzas, ventas y operaciones usan hojas de cálculo todos los días para modelos de presupuesto, análisis de precios y reportes.`,
e: `Toño prueba la fórmula del punto de reorden en su hoja con un caso conocido:

| Insumo | Existencia | Consumo diario | Días de entrega | Días de seguridad | Punto de reorden | ¿Pedir? |
|---|---|---|---|---|---|---|
| Bolsas | 1,800 | 250 | 5 | 3 | 250 × 5 + 250 × 3 = 2,000 | 1,800 ≤ 2,000 → PEDIR |
| Queso (kg) | 50 | 12 | 2 | 1 | 12 × 2 + 12 × 1 = 36 | 50 > 36 → OK |

Los resultados coinciden con la calculadora de la lección M9-6: la fórmula está bien.`,
r: `VisiCalc, creada por Dan Bricklin y Bob Frankston y lanzada en 1979 para la computadora Apple II, fue la primera hoja de cálculo para computadoras personales. Su éxito impulsó la venta de computadoras personales en empresas y abrió el camino a programas como Lotus 1-2-3 y Microsoft Excel.`,
f: `Dan Bricklin, historia de VisiCalc (bricklin.com); Computer History Museum.`,
err: ["Mezclar datos, cálculos y notas en una misma área sin orden.","Escribir números fijos dentro de las fórmulas.","No revisar las fórmulas con un caso conocido.","Tener una sola copia del archivo, sin respaldo."],
a: `Crea en una hoja de cálculo una de las tres plantillas de esta lección para el negocio que observas (o para tus gastos personales). Usa al menos tres fórmulas distintas y una gráfica.`,
sol: `Comprueba cada fórmula con un ejemplo que puedas calcular a mano. Si el resultado no coincide, revisa las referencias de celda.`,
q: [["En una hoja de cálculo, todas las fórmulas empiezan con…",["El signo =","El signo $","La letra F"],0,"Por ejemplo, =SUMA(B2:B31)."],
["La fórmula =SI(B2<C2;\"Pedir\";\"OK\") sirve para…",["Mostrar «Pedir» si la existencia es menor que el punto de reorden","Sumar ventas","Calcular el IVA"],0,"Decide según una condición."],
["Una referencia absoluta como $F$1…",["No cambia al copiar la fórmula","Cambia siempre","Borra la celda"],0,"Útil para supuestos fijos."],
["¿Cuál es una buena práctica?",["Separar datos, cálculos y reportes en pestañas distintas","Escribir números fijos dentro de las fórmulas","No guardar respaldo"],0,"Facilita revisar y evita errores."]],
t: ["Hoja de cálculo", "Fórmula"]
},
"M15-4": {
s: `Con tres sucursales y una cocina central, Tortas Lupita usa cinco herramientas distintas que no se hablan entre sí: la administradora captura las mismas ventas tres veces y nadie sabe el inventario total. Un consultor menciona la palabra «ERP». ¿Qué es y cuándo vale la pena?`,
o: ["Explicar qué es un sistema administrativo integrado o ERP.","Reconocer cuándo un negocio necesita uno.","Conocer los riesgos de implementar un ERP y cómo reducirlos."],
x: `## El problema de las «islas» de información
Cuando un negocio crece, suele ir sumando herramientas: un punto de venta en cada sucursal, una hoja de cálculo para el inventario, un sistema contable del contador, otro para la nómina, el WhatsApp para pedidos. Cada una funciona bien por separado, pero **no se comunican**. Aparecen problemas:
- **Doble captura:** los mismos datos se escriben varias veces, con más trabajo y más errores.
- **Información que no cuadra:** las ventas del punto de venta no coinciden con la contabilidad.
- **Falta de visión completa:** nadie sabe el inventario total o la utilidad por sucursal sin armar un reporte a mano.
- **Lentitud:** cerrar el mes tarda semanas.
- **Dependencia de personas:** solo una persona sabe cómo «cuadrar» todo.

## ¿Qué es un ERP?
Un **ERP** (del inglés *enterprise resource planning*, planeación de recursos empresariales) es un **sistema integrado** que reúne en una sola base de datos la información de las principales áreas del negocio: ventas, compras, inventarios, producción, finanzas, contabilidad, nómina y más. Cuando ocurre algo en un área (una venta), el sistema actualiza automáticamente todo lo relacionado: baja el inventario, registra el ingreso en contabilidad, genera la factura, actualiza los indicadores.

## Los módulos típicos de un ERP
| Módulo | Qué hace |
|---|---|
| Ventas y clientes | Pedidos, cotizaciones, facturación, cuentas por cobrar |
| Compras y proveedores | Órdenes de compra, recepciones, cuentas por pagar |
| Inventarios y almacén | Existencias por ubicación, movimientos, puntos de reorden |
| Producción | Recetas o listas de materiales, órdenes de producción, costos |
| Finanzas y contabilidad | Libro mayor, bancos, estados financieros, impuestos |
| Recursos humanos y nómina | Empleados, asistencia, nómina, recibos |
| Reportes e indicadores | Tableros por área, sucursal y producto |

En México, los ERP deben manejar la facturación electrónica (CFDI), la contabilidad electrónica y otras reglas fiscales locales. Hay ERP de grandes proveedores internacionales y muchos desarrollados para pymes mexicanas.

## Sistemas administrativos para pymes
Entre la hoja de cálculo y un ERP corporativo hay una gama amplia de **sistemas administrativos** para pymes: contabilidad, nómina, facturación, inventarios y punto de venta, a veces del mismo proveedor y conectados entre sí. Para muchas pymes, un conjunto bien integrado de estos sistemas cumple la función de un ERP a un costo mucho menor.

## ¿Cuándo hace falta?
Señales de que un negocio necesita un sistema integrado:
- Varias sucursales, almacenes o una cocina central que hay que coordinar.
- Doble o triple captura de datos.
- Cierres de mes que tardan semanas.
- Errores frecuentes por información que no cuadra.
- Necesidad de saber costos y utilidades por producto o sucursal.
- Crecimiento planeado que las herramientas actuales no soportarán.
- Requisitos de clientes grandes, bancos o inversionistas de información confiable y rápida.

## Los riesgos de implementar un ERP
Implementar un ERP es un proyecto grande, que cambia la forma de trabajar de todo el negocio. Si sale mal, puede ser muy costoso. Algunos riesgos:
- **Costo mayor al esperado:** licencias, consultoría, adaptaciones, equipo, capacitación.
- **Tiempo mayor al esperado.**
- **Adaptaciones excesivas:** querer que el sistema haga todo «como siempre lo hemos hecho» en lugar de aprovechar los procesos que trae.
- **Datos de mala calidad:** cargar al nuevo sistema información desordenada (productos duplicados, precios viejos).
- **Resistencia del personal** y falta de capacitación.
- **Arranque de golpe** sin pruebas suficientes.

Un caso muy citado es el de **Hershey's** en Estados Unidos: en 1999 puso en marcha al mismo tiempo varios sistemas nuevos de gestión (ERP, planeación y relación con clientes) justo antes de su temporada más fuerte. Los problemas de implementación le impidieron surtir a tiempo muchos pedidos de dulces de Halloween, y la empresa informó caídas en sus ventas y utilidades de ese periodo.

## Cómo reducir los riesgos
1. **Define los objetivos** concretos (eliminar la doble captura, cerrar el mes en 5 días, saber el inventario en tiempo real).
2. **Revisa y ordena los procesos** antes de implementar (Módulo 9).
3. **Elige un sistema adecuado al tamaño** y con experiencia en tu giro.
4. **Limpia los datos** antes de cargarlos.
5. **Nombra a un responsable** interno con tiempo y autoridad.
6. **Capacita** a todos los usuarios.
7. **Prueba** con datos reales y en paralelo (el sistema viejo y el nuevo al mismo tiempo durante un periodo).
8. **Arranca por etapas** (una sucursal o un módulo a la vez) y **evita las temporadas fuertes**.
9. **Mide** los resultados después del arranque.

## La decisión de Tortas Lupita
Con tres sucursales y una cocina central, Lupita no compra un ERP corporativo. Elige un **sistema administrativo para restaurantes** que integra punto de venta en cada sucursal, inventario por ubicación (incluida la cocina central), recetas que descuentan ingredientes, órdenes de compra, facturación y exportación a la contabilidad del contador. Lo implementa primero en una sucursal durante un mes, en paralelo con el sistema anterior, en un mes flojo (febrero), y después en las demás. La administradora deja de capturar tres veces lo mismo y el cierre de mes pasa de 12 a 4 días.

## En las empresas gigantes
Las grandes empresas usan ERP corporativos que manejan a miles de usuarios en muchos países, monedas e idiomas, conectados con sistemas de comercio electrónico, logística, análisis de datos y relación con clientes. Sus implementaciones pueden durar años y costar decenas o cientos de millones. Por eso se planean con mucho cuidado: un error puede afectar a toda la cadena de suministro.`,
k: `Las **islas de información** generan doble captura, errores y lentitud. Un **ERP** integra en una base de datos ventas, compras, inventarios, producción, finanzas y nómina. Para pymes hay **sistemas administrativos integrados** más sencillos. Implementarlo es un proyecto con riesgos (costo, tiempo, datos, resistencia): define objetivos, ordena procesos, limpia datos, capacita, **prueba en paralelo** y **arranca por etapas**, fuera de temporada fuerte.`,
ch: `Una distribuidora de abarrotes con dos almacenes adopta un sistema que conecta pedidos, inventario y facturación; ya no vende productos que no tiene ni factura dos veces el mismo pedido.`,
gi: `En 1999, Hershey's implementó al mismo tiempo varios sistemas nuevos de gestión antes de su temporada fuerte de Halloween; los problemas le impidieron surtir a tiempo muchos pedidos, un caso muy citado sobre los riesgos de implementar un ERP.`,
e: `La administradora mide el tiempo que ahorra el sistema integrado:

| Tarea mensual | Antes (horas) | Después (horas) |
|---|---|---|
| Capturar ventas de 3 sucursales en la hoja y en contabilidad | 24 | 2 |
| Conciliar inventarios | 16 | 3 |
| Preparar el estado de resultados por sucursal | 12 | 1 |
| **Total** | **52** | **6** |

Ahorra 46 horas al mes, que ahora dedica a analizar costos y a la cobranza.`,
r: `Hershey Foods puso en marcha en julio de 1999 nuevos sistemas de ERP, planeación de la cadena de suministro y gestión de clientes. Problemas en la implementación afectaron su capacidad para procesar y enviar pedidos en la temporada de Halloween, y la empresa reportó una caída en ventas y utilidades en el tercer trimestre de ese año.`,
f: `Hershey Foods Corporation, comunicados y reportes de 1999; estudios de caso sobre implementaciones de ERP.`,
err: ["Implementar un ERP sin ordenar antes los procesos.","Cargar datos desordenados al sistema nuevo.","Arrancar en todo el negocio a la vez y en temporada fuerte.","Adaptar el sistema para repetir procesos ineficientes."],
a: `Identifica las «islas» de información del negocio que observas: qué herramientas usa, qué datos se capturan más de una vez y qué información no se puede obtener fácilmente. Propón si necesita un sistema integrado y cómo lo implementarías por etapas.`,
sol: `Si el negocio tiene un solo local y pocas herramientas, probablemente basta con conectar el punto de venta con la facturación y la contabilidad; un ERP completo sería excesivo.`,
q: [["Un ERP es…",["Un sistema integrado que reúne la información de las principales áreas del negocio","Un tipo de impuesto","Una hoja de cálculo"],0,"Enterprise resource planning."],
["Una señal de que hace falta un sistema integrado es…",["Capturar los mismos datos varias veces en distintas herramientas","Tener pocos clientes","Vender solo en efectivo"],0,"La doble captura genera errores y trabajo."],
["¿Qué ayuda a reducir el riesgo de implementar un ERP?",["Probar en paralelo y arrancar por etapas, fuera de temporada fuerte","Arrancar todo a la vez en diciembre","No capacitar"],0,"Hershey's es un ejemplo de lo que puede pasar."],
["Antes de implementar un sistema conviene…",["Ordenar los procesos y limpiar los datos","Comprar más equipo","Despedir al personal"],0,"Un sistema no arregla procesos desordenados."]],
t: ["ERP", "Sistema administrativo integrado"]
},
"M15-5": {
s: `Karla lleva los datos de las oficinas en su celular y en notas sueltas. Cuando se enferma una semana, nadie sabe a qué oficinas había que llamar ni qué les prometió. Al mismo tiempo, varios clientes preguntan si pueden pedir tortas en línea y pagar con tarjeta desde su casa.`,
o: ["Explicar qué es un CRM y cómo ayuda a vender y conservar clientes.","Distinguir las opciones de comercio electrónico: tienda propia, mercados en línea y plataformas.","Conocer lo que se necesita para vender en línea."],
x: `## Recordar a cada cliente
En un changarro, el dueño recuerda a sus clientes: qué piden, cómo pagan, cuándo vienen. Cuando el negocio crece, esa memoria ya no alcanza: hay cientos de clientes, varios vendedores y muchos pedidos. Un **CRM** (del inglés *customer relationship management*, gestión de la relación con los clientes) es una herramienta que **guarda en un solo lugar la información de cada cliente y de cada interacción** con él.

## Qué guarda un CRM
- **Datos del cliente:** nombre, empresa, teléfono, correo, dirección, datos de facturación.
- **Historial:** pedidos, montos, fechas, productos preferidos.
- **Interacciones:** llamadas, visitas, mensajes, cotizaciones enviadas, quejas.
- **Oportunidades:** clientes potenciales y en qué etapa del embudo están (lección M11-3).
- **Tareas y recordatorios:** «llamar a la oficina B el lunes», «enviar cotización».
- **Notas:** preferencias y detalles importantes («Mariana pide factura con el nombre completo de la empresa»).

## Para qué sirve
1. **No perder oportunidades:** cada prospecto tiene su seguimiento.
2. **Que el conocimiento no dependa de una persona:** si Karla falta o se va, la información queda en el negocio.
3. **Personalizar la atención:** saber qué prefiere cada cliente.
4. **Detectar clientes en riesgo:** la oficina que bajó sus pedidos (lección M11-8).
5. **Medir ventas:** conversión por etapa, ventas por vendedor, ciclo de venta (lección M11-9).
6. **Coordinar** a ventas, marketing y servicio.

## CRM para todos los tamaños
- **Negocio pequeño:** puede empezar con una hoja de cálculo bien organizada o con las etiquetas de WhatsApp Business.
- **Pyme:** hay CRM en la nube, con versiones gratuitas o de bajo costo, que se usan desde el celular.
- **Gran empresa:** plataformas de CRM muy completas conectadas con el ERP, el centro de llamadas, el comercio electrónico y el marketing. Una de las empresas más conocidas de esta categoría es Salesforce, fundada en 1999 con la idea de ofrecer el CRM como servicio en la nube.

Lo importante no es la herramienta, sino la **disciplina**: registrar cada interacción el mismo día.

## El comercio electrónico
El **comercio electrónico** es la venta de productos o servicios por internet. Para un negocio hay varias opciones:

| Opción | Cómo funciona | Ventajas | Desventajas |
|---|---|---|---|
| Pedidos por WhatsApp con catálogo | El cliente elige y pide por mensaje; paga por transferencia o al recibir | Muy barato, conocido por todos | Manual; depende de quien atiende |
| Tienda en línea propia | Página con catálogo, carrito y pago en línea, con un servicio de tiendas en línea | Control de la marca, los precios y los datos de clientes; sin comisión de terceros por venta | Hay que atraer visitas; costos de la plataforma y de pagos en línea |
| Mercado en línea (marketplace) | Se publican productos en una plataforma con millones de compradores | Muchos clientes desde el inicio, confianza de la plataforma, logística y pagos incluidos | Comisiones por venta; mucha competencia; menos control |
| Plataformas de reparto de comida | El restaurante aparece en una aplicación; la plataforma lleva el pedido | Alcance y repartidores | Comisiones altas; poco control de la experiencia (lección M4-4) |

## Qué se necesita para vender en línea
1. **Catálogo** con fotos de calidad, descripciones claras y precios con impuestos.
2. **Forma de pago en línea** segura (pasarelas de pago, tarjetas, transferencias).
3. **Logística:** cómo se entrega (propia, paquetería, recoger en tienda) y en qué tiempo (lección M9-8).
4. **Atención al cliente:** responder dudas rápido, manejar cambios y devoluciones.
5. **Políticas claras:** envíos, devoluciones, garantías, aviso de privacidad (lección M14-4).
6. **Facturación** de las ventas en línea.
7. **Atraer visitas:** marketing digital (lección M12-6).
8. **Medir:** visitas, conversión, ticket promedio, carritos abandonados.

## Mercados en línea en América Latina
**Mercado Libre**, fundada en Argentina en 1999, se convirtió en el mercado en línea más grande de América Latina. Además del mercado, desarrolló **Mercado Pago** (pagos y servicios financieros) y **Mercado Envíos** (logística), que permiten a millones de pequeños vendedores vender en línea sin tener que construir todo por su cuenta. Amazon también opera en México con un mercado para vendedores externos. Para muchos negocios pequeños, estas plataformas son la forma más rápida de empezar a vender en línea.

## La decisión de Tortas Lupita
- **CRM:** Karla y Toño adoptan un CRM en la nube gratuito: cada oficina tiene su ficha, su historial y sus tareas. Cuando Karla falta, Toño ve en el celular a quién hay que llamar.
- **Comercio electrónico:** para pedidos individuales, mantienen WhatsApp con catálogo y agregan un enlace de pago en línea. Para la salsa envasada (lección M12-4), la publican en un mercado en línea con envíos a todo el país. No abren una tienda en línea propia todavía, porque no tendrían cómo atraer suficientes visitas.
- **Medición:** cada mes revisan pedidos en línea, ticket promedio y opiniones.

## Lo digital no elimina lo básico
Vender en línea exige lo mismo que vender en el mostrador: buen producto, buen precio, cumplir lo prometido, atender bien y cuidar los números (comisiones, empaques, envíos). Muchos negocios descubren que una venta en línea, después de comisiones y envío, deja menos margen que la del mostrador; por eso conviene calcularlo antes (lección M4-4).`,
k: `**CRM:** guarda en un solo lugar los datos, el historial y las interacciones de cada cliente; evita perder oportunidades y que el conocimiento dependa de una persona. **Comercio electrónico:** WhatsApp con catálogo, **tienda propia**, **mercado en línea** (marketplace) o plataformas de reparto. Necesitas catálogo, pago seguro, logística, atención, políticas, facturación, marketing y medición.`,
ch: `Una tienda de artesanías vende en su local y publica sus productos en un mercado en línea; las ventas en línea ya son una tercera parte del total, con envíos a todo el país.`,
gi: `Mercado Libre, fundada en 1999, combina un mercado en línea, servicios de pago (Mercado Pago) y logística (Mercado Envíos) que usan millones de vendedores en América Latina. Salesforce popularizó el CRM en la nube desde su fundación en 1999.`,
e: `Lupita compara el margen de un frasco de salsa vendido en el local y en un mercado en línea:

| Concepto | Local | Mercado en línea |
|---|---|---|
| Precio | 85 | 95 |
| Comisión de la plataforma (aprox. 15 %) | 0 | 14.25 |
| Envío a cargo del vendedor (parte) | 0 | 12 |
| Empaque especial | 0 | 5 |
| Costo de la salsa y el frasco | 28 | 28 |
| **Margen** | **57** | **35.75** |

En línea gana menos por frasco, pero llega a clientes de todo el país que nunca visitarían el local. Conviene si las ventas en línea son adicionales y no le quitan ventas al local.`,
r: `Mercado Libre informa en sus reportes anuales millones de vendedores y compradores activos en América Latina, y describe cómo Mercado Pago y Mercado Envíos se integran con su mercado en línea. Salesforce, fundada en San Francisco en 1999, se convirtió en una de las principales empresas de software de CRM.`,
f: `MercadoLibre, Inc., informe anual (Form 10-K); Salesforce, información corporativa.`,
err: ["Guardar la información de los clientes solo en el celular de un vendedor.","No registrar las interacciones el mismo día.","Abrir una tienda en línea sin plan para atraer visitas.","Vender en línea sin calcular comisiones, envío y empaque."],
a: `Diseña la ficha de cliente de un CRM sencillo para el negocio que observas (qué datos, historial y notas guardarías). Después compara dos opciones de comercio electrónico para uno de sus productos y calcula el margen en cada una.`,
sol: `Si el margen en línea es mucho menor, considera precios distintos para el canal en línea o un pedido mínimo para envío gratis.`,
q: [["Un CRM sirve para…",["Guardar en un solo lugar la información y las interacciones de cada cliente","Pagar la nómina","Calcular impuestos"],0,"Customer relationship management."],
["Una ventaja de vender en un mercado en línea es…",["Acceso a muchos compradores desde el inicio","No pagar comisiones","No tener competencia"],0,"A cambio de comisiones y más competencia."],
["¿Qué empresa latinoamericana combinó un mercado en línea con pagos y logística?",["Mercado Libre","Bimbo","Cemex"],0,"Con Mercado Pago y Mercado Envíos."],
["Antes de vender en línea conviene…",["Calcular el margen después de comisiones, envío y empaque","Bajar todos los precios","No facturar"],0,"La venta en línea puede dejar menos margen."]],
t: ["CRM", "Comercio electrónico"]
},
"M15-6": {
s: `Un lunes, la administradora recibe un WhatsApp del «proveedor de carne» con un número nuevo: «Cambiamos de cuenta, deposita aquí el pago de la semana». Paga 18,000 pesos. Horas después, el proveedor real llama preguntando por su dinero. Fue un fraude. Lupita entiende que la seguridad digital también es parte del negocio.`,
o: ["Reconocer los fraudes y amenazas digitales más comunes para un negocio.","Aplicar medidas básicas de ciberseguridad.","Diseñar un plan de respaldos de la información."],
x: `## Los riesgos digitales también son riesgos del negocio
A medida que un negocio usa más tecnología (WhatsApp, banca en línea, sistemas en la nube, terminales de pago), también se expone a **riesgos digitales**: fraudes, robo de información, pérdida de datos, ataques que bloquean sus sistemas. Los negocios pequeños creen que «nadie se va a fijar en ellos», pero muchas veces son blanco fácil precisamente porque tienen menos protecciones.

## Los fraudes más comunes
1. **Suplantación de proveedores o clientes:** alguien se hace pasar por un proveedor (con un número o correo parecido) y pide que se pague a una cuenta nueva. Es exactamente lo que le pasó a Tortas Lupita. A nivel empresarial se le conoce como fraude por correo comprometido o del «falso proveedor».
2. **Suplantación del banco o de la autoridad (phishing):** mensajes, correos o llamadas que parecen del banco, del SAT o de una paquetería, con un enlace que lleva a una página falsa para robar contraseñas o datos de tarjetas.
3. **Comprobantes de pago falsos:** capturas de pantalla de transferencias que no se hicieron (lección M15-2).
4. **Robo de cuentas de WhatsApp o redes:** alguien pide «el código que te llegó por mensaje» y se queda con la cuenta, desde donde pide dinero a los contactos.
5. **Programas maliciosos y secuestro de datos (ransomware):** un archivo o enlace infecta la computadora y cifra (bloquea) la información; luego piden un rescate para liberarla.
6. **Fraudes con tarjetas** en ventas en línea (compras con tarjetas robadas que luego se desconocen).
7. **Empleados o exempleados** que usan accesos que no se les retiraron.

## Las medidas básicas
No hace falta ser experto para protegerse de la mayoría de estos riesgos. Unas cuantas reglas sencillas reducen mucho el peligro:

**Contra los fraudes de pago**
- **Nunca cambies los datos bancarios** de un proveedor por un mensaje o correo. Confirma siempre **llamando al número que ya tenías registrado** (no al que viene en el mensaje).
- **Doble autorización** para pagos grandes o para cuentas nuevas (una persona prepara, otra autoriza; lección M10-1).
- **Verifica en tu banco** que los pagos de clientes llegaron antes de entregar.

**Contra el robo de cuentas**
- **Contraseñas largas y distintas** para cada servicio importante (banco, correo, sistema, redes). Una frase larga es más segura y más fácil de recordar que una palabra con símbolos.
- **Usa un administrador de contraseñas** si manejas muchas cuentas.
- **Activa la verificación en dos pasos** (un código adicional en el celular) en el banco, el correo, WhatsApp y las redes.
- **Nunca compartas los códigos** que te llegan por mensaje: ningún banco, plataforma o «soporte» los pide.

**Contra los enlaces y archivos maliciosos**
- **Desconfía** de mensajes con urgencia («tu cuenta será bloqueada hoy»), errores de ortografía o remitentes desconocidos.
- **No abras enlaces ni archivos** inesperados; entra directamente a la página oficial escribiendo la dirección.
- **Mantén actualizados** el sistema operativo, el navegador y las aplicaciones: muchas actualizaciones corrigen fallas de seguridad.
- **Usa antivirus** en las computadoras.

**Control de accesos**
- **Un usuario por persona** en el sistema, con los permisos mínimos que necesita.
- **Retira los accesos** el mismo día que alguien deja el negocio y cambia las contraseñas compartidas.
- **Bloquea** las computadoras y celulares con contraseña.

## Los respaldos: la regla 3-2-1
Perder la información del negocio (ventas, clientes, contabilidad) puede ser tan grave como un incendio. Las causas: una computadora descompuesta, un celular robado, un ataque de ransomware, un error humano. La protección principal son los **respaldos** (copias de seguridad). Una regla práctica muy usada es la **3-2-1**:
- **3** copias de la información (la original y dos respaldos).
- En **2** medios distintos (por ejemplo, la computadora y un disco externo).
- **1** copia fuera del negocio (por ejemplo, en la nube o en otra ubicación).

Y lo más importante: **prueba de vez en cuando que puedes recuperar** la información desde el respaldo. Un respaldo que no se puede restaurar no sirve.

Si los sistemas del negocio están en la nube, el proveedor suele hacer respaldos, pero conviene verificar cómo y exportar los datos importantes de vez en cuando.

## Qué hacer si ocurre un fraude o un ataque
1. **Actúa rápido:** llama a tu banco para intentar detener o rastrear la transferencia.
2. **Cambia las contraseñas** de las cuentas afectadas.
3. **Avisa** a tus clientes y proveedores si tu cuenta fue robada, para que no caigan en el mismo engaño.
4. **Denuncia** ante las autoridades (en México, por ejemplo, ante la policía cibernética de tu entidad o la Fiscalía) y, si es un tema bancario, ante tu banco y la **Condusef**.
5. **Guarda las pruebas:** capturas, números, correos.
6. **Revisa qué falló** y corrige el proceso.

## La lección de Tortas Lupita
La transferencia no se pudo recuperar. Lupita establece tres reglas: ningún cambio de cuenta de un proveedor se acepta sin una llamada al número registrado; los pagos de más de 5,000 pesos necesitan la autorización de dos personas; y todos activan la verificación en dos pasos en WhatsApp y el banco. Además, Toño configura un respaldo semanal del sistema y de las hojas de cálculo en un disco externo y en la nube.

## En las empresas gigantes
Las grandes empresas tienen áreas de **ciberseguridad** con especialistas que vigilan sus sistemas las 24 horas, hacen pruebas de ataque, capacitan a los empleados y tienen planes de respuesta. Aun así, sufren ataques: en 2017, un programa de secuestro de datos llamado **WannaCry** afectó a cientos de miles de computadoras en más de cien países, incluidas grandes empresas y servicios de salud, aprovechando una falla de un sistema operativo para el que ya existía una actualización de seguridad. La lección para todos: actualizar y respaldar.`,
k: `Fraudes comunes: **falso proveedor**, **phishing** (suplantación del banco o la autoridad), comprobantes falsos, robo de cuentas, **ransomware**. Defensas: confirmar cambios de cuenta **llamando al número registrado**, **doble autorización** de pagos, contraseñas largas y distintas, **verificación en dos pasos**, nunca compartir códigos, actualizar, un usuario por persona. Respaldos **3-2-1** y prueba de recuperación.`,
ch: `Una estética recibe un mensaje «del banco» pidiendo actualizar sus datos con un enlace; en lugar de abrirlo, la dueña llama al número de su tarjeta y confirma que es un fraude.`,
gi: `En 2017, el ransomware WannaCry afectó a cientos de miles de computadoras en más de cien países, incluidos hospitales del sistema de salud británico y grandes empresas, aprovechando una falla para la que ya existía una actualización de seguridad.`,
e: `Lupita compara el costo de las medidas con el costo del fraude:

| Concepto | Pesos |
|---|---|
| Fraude del falso proveedor (perdido) | 18,000 |
| Disco externo para respaldos | 1,500 (una vez) |
| Respaldo en la nube | 150 al mes |
| Tiempo de configurar verificación en dos pasos y reglas | 2 horas |
| Llamada de confirmación antes de cada cambio de cuenta | 2 minutos |

Las medidas cuestan una fracción de un solo fraude.`,
r: `En mayo de 2017, el ataque de ransomware WannaCry se extendió por todo el mundo y afectó a organizaciones como el Servicio Nacional de Salud del Reino Unido y empresas de telecomunicaciones, transporte y manufactura. Aprovechaba una vulnerabilidad de Windows para la que Microsoft había publicado una actualización semanas antes.`,
f: `Informes de agencias de ciberseguridad y comunicados de Microsoft sobre WannaCry (2017); Condusef, alertas de fraudes financieros (gob.mx/condusef).`,
err: ["Cambiar la cuenta de pago de un proveedor por un mensaje sin llamar para confirmar.","Usar la misma contraseña para todo.","Compartir códigos de verificación.","No tener respaldos o nunca probar que funcionan."],
a: `Haz una revisión de seguridad digital del negocio que observas (o de tu propia vida digital): contraseñas, verificación en dos pasos, respaldos, accesos de exempleados y reglas para pagos. Escribe tres reglas que implementarías esta semana.`,
sol: `Las tres reglas con más impacto suelen ser: confirmar por teléfono cualquier cambio de cuenta, activar la verificación en dos pasos en banco y WhatsApp, y hacer un respaldo semanal en dos lugares.`,
q: [["Si un «proveedor» pide por mensaje pagar a una cuenta nueva, lo correcto es…",["Llamar al número que ya tenías registrado para confirmar","Pagar de inmediato","Responder el mensaje pidiendo confirmación"],0,"Así se evita el fraude del falso proveedor."],
["La verificación en dos pasos consiste en…",["Pedir un código adicional además de la contraseña","Usar dos contraseñas iguales","Tener dos celulares"],0,"Hace mucho más difícil robar una cuenta."],
["La regla de respaldos 3-2-1 significa…",["3 copias, en 2 medios distintos, 1 fuera del negocio","3 contraseñas, 2 usuarios, 1 computadora","3 días, 2 semanas, 1 mes"],0,"Y hay que probar la recuperación."],
["Un banco o una plataforma legítima…",["Nunca pide los códigos que te llegan por mensaje","Siempre los pide","Los pide por WhatsApp"],0,"Compartirlos permite robar la cuenta."]],
t: ["Ciberseguridad", "Phishing"]
},
"M15-7": {
s: `Toño lee que la inteligencia artificial «va a cambiar todos los negocios». Prueba un asistente para escribir publicaciones y responder mensajes, y le sorprende lo rápido que funciona. Pero un día el asistente le dice a un cliente que hay una promoción que no existe. ¿Para qué sirven realmente los datos, la automatización y la IA en un negocio?`,
o: ["Explicar cómo usar los datos del negocio para decidir.","Identificar tareas que conviene automatizar.","Usar herramientas de inteligencia artificial con criterio, conociendo sus límites."],
x: `## Los datos ya están ahí
Cada venta registrada en el punto de venta, cada pedido por WhatsApp, cada factura y cada reseña es un **dato**. Con los sistemas de las lecciones anteriores, Tortas Lupita ya tiene información que hace unos años era imposible de reunir: qué se vende, cuándo, a quién, cuánto deja, qué falla. La pregunta ya no es cómo conseguir datos, sino **cómo usarlos para decidir mejor**.

## Del dato a la decisión
El camino típico es:
1. **Datos:** registros sueltos (ventas por ticket).
2. **Información:** datos organizados (ventas por producto y por hora).
3. **Conocimiento:** patrones e interpretación («los viernes de 13:00 a 14:00 se vende el doble de tortas de pierna»).
4. **Decisión:** una acción («preparar más pierna los viernes y reforzar la cocina en ese horario»).
5. **Medición:** comprobar si funcionó.

Algunas preguntas que los datos de un negocio pequeño pueden responder:
- ¿Qué productos dejan más margen total? (mezcla, lección M5-6).
- ¿Qué horas y días necesitan más personal? (lección M13-1).
- ¿Qué clientes dejaron de comprar? (lección M11-8).
- ¿Cuánto se debe pedir de cada insumo? (lección M9-6).
- ¿Qué promoción funcionó? (lección M12-8).

## La automatización
**Automatizar** es lograr que una tarea repetitiva se haga sola o con mucha menos intervención humana. Conviene automatizar tareas que son:
- **Repetitivas** (se hacen igual muchas veces).
- **Basadas en reglas claras.**
- **Propensas a errores** cuando se hacen a mano.
- **Que consumen tiempo** sin agregar mucho valor.

Ejemplos accesibles para un negocio pequeño:
- El punto de venta que **descuenta inventario** con cada venta.
- **Respuestas automáticas** en WhatsApp Business para preguntas frecuentes y fuera de horario.
- **Recordatorios automáticos** de pago a clientes con crédito.
- **Facturación** automática de las ventas del día.
- **Reportes** que llegan solos cada lunes.
- **Pedidos sugeridos** a proveedores cuando el inventario llega al punto de reorden.

La automatización libera tiempo de las personas para lo que sí requiere criterio: atender a un cliente difícil, negociar con un proveedor, pensar en mejoras.

## La inteligencia artificial
La **inteligencia artificial** (IA) es un conjunto de técnicas que permiten a las computadoras realizar tareas que normalmente requieren inteligencia humana: reconocer patrones, entender y generar texto, reconocer imágenes, hacer pronósticos o recomendaciones. En los últimos años se popularizaron las herramientas de **IA generativa**, que pueden escribir textos, responder preguntas, resumir documentos o crear imágenes a partir de instrucciones en lenguaje común.

## Usos útiles para un negocio pequeño
- **Redactar borradores:** publicaciones para redes, descripciones de productos, correos, anuncios de vacantes, políticas.
- **Resumir y ordenar:** sacar las quejas más frecuentes de un conjunto de reseñas.
- **Apoyar el análisis:** explicar una tendencia en una tabla de ventas o sugerir preguntas para analizarla.
- **Ideas:** nombres de productos, promociones, formatos de capacitación.
- **Traducir** textos para clientes extranjeros.
- **Atención básica:** responder preguntas frecuentes (horarios, menú), siempre con supervisión.

## Los límites de la IA
Usar la IA con criterio significa conocer sus límites:
- **Puede equivocarse con seguridad:** a veces inventa datos, promociones, leyes o cifras que suenan convincentes pero son falsas. Es exactamente lo que le pasó a Toño. **Todo lo que la IA produce debe revisarlo una persona** antes de publicarlo o enviarlo a un cliente.
- **No conoce tu negocio** si no le das la información correcta y actualizada.
- **Datos personales:** no se deben compartir datos personales de clientes o empleados con herramientas externas sin cuidar la ley de protección de datos y las condiciones de uso de la herramienta (lección M14-4).
- **Información confidencial:** las recetas, los precios de los proveedores o los planes del negocio no deberían pegarse sin cuidado en herramientas cuyo manejo de datos no conoces.
- **Sesgos:** la IA puede reproducir prejuicios presentes en los datos con que fue entrenada; no debe usarse sola para decisiones sobre personas (contratar, despedir).
- **Responsabilidad:** si la herramienta promete algo a un cliente, el responsable sigue siendo el negocio.

## Reglas para usar la IA en Tortas Lupita
1. La IA hace **borradores**; una persona revisa y aprueba.
2. Nunca se le dan **datos personales** de clientes o empleados.
3. Las **respuestas automáticas** a clientes solo pueden tratar temas fijos (horario, menú, ubicación); todo lo demás lo atiende una persona.
4. Las **promociones y precios** solo se comunican desde la lista oficial.
5. Se **mide** si la herramienta ahorra tiempo o mejora resultados; si no, se deja.

## La IA en las empresas gigantes
Las grandes empresas usan IA para recomendar productos (las tiendas en línea que sugieren «otros clientes también compraron»), pronosticar la demanda de cada producto en cada tienda, detectar fraudes con tarjetas, optimizar rutas de reparto y atender clientes. Pero también enfrentan sus límites: en 2024, McDonald's anunció que terminaba una prueba de pedidos por voz con IA en cientos de sus autoservicios en Estados Unidos, que había desarrollado con IBM, después de que se difundieran en redes pedidos equivocados; la empresa dijo que seguiría explorando opciones de este tipo. La lección es la misma que aprendió Toño: la tecnología ayuda, pero hay que probarla, supervisarla y medirla.

## Cierre del módulo y del Nivel 2
Con el Módulo 15 termina el recorrido por dentro del negocio: estructura, dirección, finanzas, operaciones, compras, ventas, marketing, personas, legal y tecnología. Tortas Lupita pasó de un puesto que funcionaba «de memoria» a un local formal con áreas, procesos, indicadores y sistemas. En el Nivel 3 aprenderás a tomar decisiones con más método, a controlar con presupuestos e indicadores y a crecer: sucursales, financiamiento, franquicias y expansión.`,
k: `**Datos → información → conocimiento → decisión → medición.** **Automatiza** lo repetitivo, basado en reglas y propenso a errores (inventario, respuestas frecuentes, recordatorios, facturación, reportes). **IA generativa:** útil para borradores, resúmenes, ideas y atención básica, pero **puede equivocarse**: revisa siempre, no compartas datos personales ni confidenciales y no decidas sobre personas solo con ella.`,
ch: `Una papelería usa los datos de su punto de venta para descubrir que en julio se venden el triple de mochilas; compra a tiempo y no se queda sin inventario en el regreso a clases.`,
gi: `Las tiendas en línea usan sistemas de recomendación basados en los datos de compra de millones de clientes. En 2024, McDonald's terminó una prueba de pedidos por voz con inteligencia artificial en autoservicios de Estados Unidos, desarrollada con IBM, tras problemas con pedidos equivocados.`,
e: `Toño mide el tiempo ahorrado con automatización e IA en un mes:

| Tarea | Antes (horas al mes) | Después (horas al mes) | Herramienta |
|---|---|---|---|
| Responder preguntas frecuentes por WhatsApp | 20 | 6 | Respuestas automáticas |
| Escribir publicaciones para redes | 8 | 3 | Borradores con IA, revisados |
| Preparar el reporte semanal de ventas | 6 | 0.5 | Reporte automático del sistema |
| Recordatorios de pago a oficinas | 3 | 0.5 | Mensajes programados |
| **Total** | **37** | **10** | |

Ahorra 27 horas al mes, que dedica a visitar oficinas con Karla.`,
r: `En junio de 2024, McDonald's informó a sus franquiciatarios que terminaría su prueba de pedidos automatizados por voz en más de cien autoservicios de Estados Unidos, desarrollada con IBM, aunque señaló que seguiría evaluando soluciones de pedidos por voz en el futuro.`,
f: `Notas de prensa económica de junio de 2024 sobre el fin de la prueba de pedidos por voz con IA de McDonald's e IBM.`,
err: ["Publicar o enviar a clientes textos de IA sin revisarlos.","Compartir datos personales de clientes con herramientas externas.","Automatizar un proceso desordenado sin mejorarlo antes.","Tener datos y no usarlos para decidir."],
a: `Elige tres tareas repetitivas del negocio que observas y propón cómo automatizar cada una. Después usa una herramienta de IA para redactar una publicación o un anuncio de vacante, y revísalo con ojo crítico: anota qué datos tuviste que corregir.`,
sol: `Revisa especialmente precios, fechas, promociones y cualquier afirmación sobre leyes o salud: son los puntos donde la IA suele equivocarse.`,
q: [["El camino correcto para usar datos es…",["Datos → información → conocimiento → decisión → medición","Decidir y luego buscar datos","Guardar datos sin usarlos"],0,"Los datos solo valen si llevan a decisiones."],
["Conviene automatizar tareas que son…",["Repetitivas, basadas en reglas y propensas a errores","Únicas y que requieren mucho criterio","Ninguna"],0,"Así se libera tiempo para lo importante."],
["¿Cuál es un límite importante de la IA generativa?",["Puede inventar datos que suenan convincentes","Nunca se equivoca","No sabe escribir"],0,"Todo debe revisarlo una persona."],
["¿Qué NO conviene hacer con una herramienta de IA externa?",["Darle datos personales de clientes sin cuidar la ley y las condiciones de uso","Pedirle un borrador de una publicación","Pedirle ideas de promociones"],0,"Hay que proteger los datos personales y confidenciales."]],
t: ["Inteligencia artificial", "IA generativa"]
}
});
